using System.Runtime.Serialization;

namespace NextORM.Core;

/// <summary>
/// Thrown when the SQL text for a command cannot be generated.
/// </summary>
/// <remarks>
/// Derives from <see cref="DataContextException"/> so callers can catch a single library-wide base.
/// </remarks>
[Serializable]
public class BuildSqlCommandException : DataContextException
{
    /// <summary>
    /// Initializes a new instance of the <see cref="BuildSqlCommandException"/> class.
    /// </summary>
    public BuildSqlCommandException()
    {
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="BuildSqlCommandException"/> class with a specified
    /// error message.
    /// </summary>
    /// <param name="message">The message that describes the error.</param>
    public BuildSqlCommandException(string? message) : base(message)
    {
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="BuildSqlCommandException"/> class with a specified
    /// error message and a reference to the inner exception that caused it.
    /// </summary>
    /// <param name="message">The message that describes the error.</param>
    /// <param name="innerException">The exception that is the cause of the current exception, or <see langword="null"/> if none.</param>
    public BuildSqlCommandException(string? message, Exception? innerException) : base(message, innerException)
    {
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="BuildSqlCommandException"/> class from serialized data.
    /// </summary>
    /// <param name="info">The object that holds the serialized object data.</param>
    /// <param name="context">Contextual information about the source or destination of the serialization.</param>
    [Obsolete(DiagnosticId = "SYSLIB0051")]
    protected BuildSqlCommandException(SerializationInfo info, StreamingContext context) : base(info, context)
    {
    }
}

namespace NextORM.Core;

/// <summary>
/// Declares the database collation of a mapped string property. The collation is applied to the
/// column in collation-sensitive operations of generated queries (comparison, <c>LIKE</c>,
/// <c>ORDER BY</c>, <c>GROUP BY</c>), so the column follows the declared collation instead of the
/// database default. Requires a provider that supports a per-expression <c>COLLATE</c> clause (see
/// <see cref="ISqlDialect.SupportsCollation"/>); ClickHouse has none and rejects a collated column.
/// </summary>
/// <remarks>
/// nextorm does not generate DDL, so the attribute declares an existing column's collation rather
/// than creating it (the equivalent of <c>UseCollation</c> in EF Core). The attribute is read by
/// <see cref="IPropertyMetadata"/> (<see cref="IPropertyMetadata.Collation"/>); the equivalent fluent
/// mapping is <see cref="EntityPropertyBuilder{T}.Collation(string)"/>. The in-memory provider has no
/// collations and ignores the value (its comparisons are already ordinal).
/// </remarks>
[AttributeUsage(AttributeTargets.Property, AllowMultiple = false, Inherited = true)]
public sealed class CollationAttribute : Attribute
{
    /// <summary>
    /// Creates an attribute declaring <paramref name="name"/> as the column's collation.
    /// </summary>
    /// <param name="name">The provider-native collation name.</param>
    public CollationAttribute(string name)
    {
        Name = name;
    }

    /// <summary>
    /// The provider-native collation name, for example <c>"C"</c> on PostgreSQL or
    /// <c>"Latin1_General_100_BIN2"</c> on SQL Server.
    /// </summary>
    public string Name { get; set; }
}

using System.Linq.Expressions;

namespace NextORM.Core;

/// <summary>
/// Non-generic identity of a typed self-reference handed to the step callback of the recursive
/// <c>AsRecursiveCte</c> overloads on <c>QueryCommand&lt;TResult&gt;</c>.
/// <para>
/// Creation is non-public: a reference is produced only by the recursive-CTE factory and is bound to
/// the anchor's readable column shape. Identity is the non-public <see cref="Owner"/>
/// token, not the declared <see cref="Name"/> — two references carrying the same name but a different
/// owner are not interchangeable.
/// </para>
/// </summary>
public abstract class CteReference
{
    private protected CteReference(string name, QueryCommand anchorShape, object owner)
    {
        ArgumentException.ThrowIfNullOrEmpty(name);
        ArgumentNullException.ThrowIfNull(anchorShape);
        ArgumentNullException.ThrowIfNull(owner);

        Name = name;
        AnchorShape = anchorShape;
        Owner = owner;
    }

    /// <summary>The name the recursive common table expression is declared under and read from in the step.</summary>
    public string Name { get; }

    /// <summary>The anchor command whose projection describes the readable columns of the self-reference.</summary>
    internal QueryCommand AnchorShape { get; }

    /// <summary>Non-public identity of the recursive definition that owns this reference.</summary>
    internal object Owner { get; }
}

/// <summary>
/// Typed self-reference of a recursive common table expression: the step callback received this
/// instance and reads the anchor's rows through
/// <see cref="DataContextExtensions.From{TResult}(IDataContext, CteReference{TResult})"/>. A self-reference
/// is valid only while the factory is running that definition's step; using it afterwards (a captured
/// or foreign reference) is rejected before any database command is built.
/// </summary>
/// <typeparam name="TResult">The anchor/step row shape, identical to the recursive CTE's projection.</typeparam>
public sealed class CteReference<TResult> : CteReference
{
    internal CteReference(string name, QueryCommand anchorShape, object owner)
        : base(name, anchorShape, owner)
    {
    }
}

/// <summary>
/// An immutable, reference-identified descriptor of a common table expression whose rows carry the
/// projection shape <typeparamref name="TResult"/>.
/// <para>
/// Created from a query with <see cref="QueryCommand{TResult}.AsCte(string)"/> and read with
/// <see cref="DataContextExtensions.From{T}(IDataContext, Cte{T})"/>. The descriptor is a typed
/// projection source, not a mapped entity: typed member reads resolve to the defining query's output
/// columns, so a whole-entity <typeparamref name="TResult"/> does not imply a table mapping.
/// </para>
/// <para>
/// The descriptor holds the defining command and its declaration set internally; identity is by
/// reference, there is no structural or name equality. The defining <see cref="QueryCommand"/> is not
/// snapshotted, matching the existing CTE lifecycle contract.
/// </para>
/// <para>
/// Recursion is not part of this API — it declares an ordinary CTE only. The legacy
/// <c>With</c>/<c>WithRecursive</c>/<c>From(string)</c>/<c>From(CteDefinition)</c> string APIs are
/// unchanged and remain the way to read a CTE by name or to build a recursive CTE.
/// </para>
/// </summary>
/// <typeparam name="TResult">The row shape the CTE's defining <c>SELECT</c> projects.</typeparam>
public sealed class Cte<TResult>
{
    private readonly IReadOnlyList<CteDefinition> _definitions;

    internal Cte(QueryCommand<TResult> query, string name)
    {
        var definition = new CteDefinition(name, query) { TypedProjection = true };

        Query = query;
        Definition = definition;
        _definitions = BuildDefinitions(definition, query);
    }

    private Cte(QueryCommand<TResult> query, CteDefinition definition)
    {
        Query = query;
        Definition = definition;
        _definitions = BuildDefinitions(definition, query);
    }

    /// <summary>
    /// Builds a recursive descriptor: invokes <paramref name="step"/> exactly once under a fresh owner
    /// token, assembles the body as <c>anchor UNION ALL step</c> and stores the recursive declaration.
    /// The callback is never re-invoked by preparation, generation or execution; a null callback throws
    /// <see cref="ArgumentNullException"/> and a null returned query throws
    /// <see cref="InvalidOperationException"/>, both before any database command is built.
    /// </summary>
    internal static Cte<TResult> CreateRecursive(
        QueryCommand<TResult> anchor,
        string name,
        Func<CteReference<TResult>, QueryCommand<TResult>> step,
        int? maxRecursion)
    {
        var owner = new object();
        var reference = new CteReference<TResult>(name, anchor, owner);

        // Marks the anchor command so a member read of the self-reference resolves the CTE's declared
        // output aliases rather than re-rendering the anchor body (a constant anchor would inline `1`
        // and render an unaddressable `t1.1`). See QueryCommand.TypedRecursiveAnchor.
        anchor.TypedRecursiveAnchor = reference;

        QueryCommand<TResult> stepQuery;
        RecursiveCteScope.Enter(owner);
        try
        {
            stepQuery = step(reference);
            if (stepQuery is null)
                throw new InvalidOperationException(
                    $"The recursive common table expression '{name}' step callback returned null; it must return the step query.");

            // Fail fast, before any database command is built: only a self-reference owned by THIS
            // definition may occur in the body. The walk covers the anchor too, so an anchor that
            // (illegally) reads a recursive reference is rejected as construction time as well.
            ValidateRecursiveOwners(name, owner, anchor, stepQuery);
        }
        finally
        {
            RecursiveCteScope.Exit(owner);
        }

        var body = anchor.UnionAll(stepQuery);
        var definition = new CteDefinition(name, body, true, maxRecursion)
        {
            TypedProjection = true,
            RecursiveReference = reference,
        };

        return new Cte<TResult>(body, definition);
    }

    /// <summary>
    /// Walks the whole query graph of a recursive definition's anchor and step and throws when it
    /// encounters a typed recursive self-reference whose owner token is not <paramref name="owner"/>.
    /// A reference from another recursive definition (a foreign/captured reference, even one whose
    /// defining scope is still active in a nested construction) and any reference inside the anchor are
    /// therefore rejected before a database command exists, not at preparation time. Nested recursive
    /// declarations carried by the graph are skipped: each was validated under its own owner when it was
    /// constructed, and its body is not governed by this definition's owner. The walk is fail-fast and
    /// diagnostic: it names the CTE, the branch/position and the offending source.
    /// </summary>
    private static void ValidateRecursiveOwners(string name, object owner, QueryCommand<TResult> anchor, QueryCommand<TResult> step)
    {
        var visited = new HashSet<QueryCommand>(ReferenceEqualityComparer.Instance);
        Walk(anchor, "anchor");
        Walk(step, "step");

        void Walk(QueryCommand cmd, string position)
        {
            if (!visited.Add(cmd))
                return;

            WalkFrom(cmd.From, position);

            if (cmd.Joins is { Length: > 0 } joins)
            {
                for (var i = 0; i < joins.Length; i++)
                    WalkFrom(joins[i].From, $"{position} join {i}");
            }

            if (cmd.UnionQuery is { } union)
                Walk(union, $"{position} set-operation");

            if (cmd.ReferencedQueries is { Count: > 0 } referenced)
            {
                for (var i = 0; i < referenced.Count; i++)
                    Walk(referenced[i], $"{position} subquery {i}");
            }

            if (cmd.Ctes is { Count: > 0 } ctes)
            {
                for (var i = 0; i < ctes.Count; i++)
                {
                    var declaration = ctes[i];
                    if (declaration.RecursiveReference is not null)
                        continue;

                    Walk(declaration.Mutation?.Source ?? declaration.Query, $"{position} declaration '{declaration.Name}'");
                }
            }
        }

        void WalkFrom(FromExpression? from, string position)
        {
            if (from is null)
                return;

            if (from.RecursiveOwner is { } fromOwner && !ReferenceEquals(fromOwner, owner))
                throw new InvalidOperationException(
                    $"The recursive common table expression '{name}' reads the self-reference '{from.Table}' in its {position}, but that reference belongs to a different recursive definition. A self-reference is only valid inside the AsRecursiveCte callback that received it, and never in the anchor.");

            if (from.SubQuery is { } subQuery)
                Walk(subQuery, position);

            if (from.ColumnShape is { } columnShape)
                Walk(columnShape, position);

            if (from.Pivot is { } pivot)
                WalkFrom(pivot.Inner, position);
        }
    }

    /// <summary>The defining command whose projection shape the typed source reads.</summary>
    internal QueryCommand<TResult> Query { get; }

    /// <summary>The single declaration this descriptor wraps.</summary>
    internal CteDefinition Definition { get; }

    /// <summary>
    /// The declaration set to attach to a command reading this CTE: the descriptor's own definition
    /// plus every reachable dependency, already flattened and ordered dependency-before-consumer.
    /// </summary>
    internal IReadOnlyList<CteDefinition> Definitions => _definitions;

    /// <summary>The name the common table expression is declared under and referenced by in <c>from</c>.</summary>
    public string Name => Definition.Name;

    // Seeds the closure with the descriptor's own declaration, then pulls in every declaration the
    // defining command (transitively) references by name. Declarations the defining command carries but
    // never references are omitted. Same-instance dependencies are deduplicated and a distinct
    // declaration under an already-used name is rejected by the hoister, matching the legacy CTE path.
    private static IReadOnlyList<CteDefinition> BuildDefinitions(CteDefinition definition, QueryCommand<TResult> query)
    {
        var candidates = new List<CteDefinition>(2 + (query.Ctes?.Count ?? 0) + (query.UnionQuery?.Ctes?.Count ?? 0)) { definition };
        if (query.Ctes is { Count: > 0 } carried)
            candidates.AddRange(carried);
        // A recursive body is anchor UNION ALL step; declarations carried by the step query are
        // dependencies of the recursive definition, exactly like declarations carried by the anchor.
        if (query.UnionQuery?.Ctes is { Count: > 0 } stepCarried)
            candidates.AddRange(stepCarried);

        return CteHoister.Hoist(CteHoister.Reachable(candidates, definition))!;
    }
}

/// <summary>
/// Ambient owner scope of a recursive typed CTE. It is active only while the definition's step callback
/// runs (so a self-reference can be created) and while that definition's step is prepared (so a
/// captured/foreign reference embedded in the step is rejected). The scope is per-thread: query
/// construction and preparation are synchronous.
/// </summary>
internal static class RecursiveCteScope
{
    [ThreadStatic]
    private static HashSet<object>? _active;

    internal static void Enter(object owner)
        => (_active ??= new HashSet<object>(ReferenceEqualityComparer.Instance)).Add(owner);

    internal static void Exit(object owner)
    {
        if (_active is null)
            return;

        _active.Remove(owner);
        if (_active.Count == 0)
            _active = null;
    }

    internal static bool IsActive(object owner) => _active?.Contains(owner) ?? false;
}

namespace NextORM.Core;

/// <summary>
/// Declares the decimal precision and scale of a mapped <see cref="decimal"/> property. The pair is
/// read by <see cref="IPropertyMetadata"/> (<see cref="IPropertyMetadata.DecimalPrecision"/> and
/// <see cref="IPropertyMetadata.DecimalScale"/>) and used where a provider needs the declared
/// precision/scale, such as the column metadata of a table-valued parameter.
/// <para>
/// The declared domain is provider-neutral and bounded by SQL Server's maximum: precision must be
/// between 1 and 38, and scale between 0 and the precision. A provider without a native decimal
/// precision (for example ClickHouse's <c>Decimal(P, S)</c>) honours the same pair; a provider that
/// does not need it keeps its default. The pair is validated against the type actually bound for the
/// column: a non-<see cref="decimal"/> model mapped through a value converter to decimal is accepted,
/// while a <see cref="decimal"/> model mapped to a non-decimal representation (a converter to
/// <see cref="string"/> or a JSON column) is rejected. An out-of-range pair throws
/// <see cref="ArgumentOutOfRangeException"/>; a pair declared on a non-decimal bound type or a
/// partially declared pair throws <see cref="InvalidOperationException"/>.
/// </para>
/// </summary>
/// <remarks>
/// The equivalent fluent mapping is
/// <see cref="EntityPropertyBuilder{T}.DecimalPrecision(int, int)"/>. The attribute affects only the
/// declared column metadata; nextorm does not generate DDL, so the column must already have a matching
/// precision/scale (the equivalent of <c>HasColumnType("decimal(12,4)")</c> in EF Core).
/// </remarks>
[AttributeUsage(AttributeTargets.Property, AllowMultiple = false, Inherited = true)]
public sealed class DecimalPrecisionAttribute : Attribute
{
    /// <summary>
    /// Creates an attribute declaring <paramref name="precision"/> and <paramref name="scale"/>.
    /// </summary>
    /// <param name="precision">The total number of decimal digits (1 to 38).</param>
    /// <param name="scale">The number of digits to the right of the decimal point (0 to <paramref name="precision"/>).</param>
    public DecimalPrecisionAttribute(int precision, int scale)
    {
        Precision = precision;
        Scale = scale;
    }

    /// <summary>The total number of decimal digits (1 to 38).</summary>
    public int Precision { get; set; }

    /// <summary>The number of digits to the right of the decimal point (0 to <see cref="Precision"/>).</summary>
    public int Scale { get; set; }
}

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace NextORM.Core;

/// <summary>
/// Configures and creates an <see cref="IDataContext"/>.
/// </summary>
/// <remarks>
/// The <c>DataContext</c> prefix is inconsistent with the rest of the library, which otherwise uses
/// <c>DataContext</c> (for example <c>DataContextOptionsBuilderExtensions</c>). Recommended name:
/// <c>DataContextBuilder</c>. See <c>docs/specs/design/API-NAMING-REVIEW.md</c> finding P2-22.
/// </remarks>
public class DataContextBuilder
{
    //private readonly Dictionary<string, object> _props = new();
    private ILoggerFactory? _loggerFactory;
    //private IDataProvider? _dataProvider;
    private bool _logSensitiveData;
    private int? _commandTimeout;
    private Func<DataContextBuilder, IDataContext>? _factory;
    // One ordered list holds every interceptor registration: either an already-created interceptor
    // instance or a Type to resolve from the captured IServiceProvider when a context is created.
    // Registration order is the invocation order in each event pipeline.
    private readonly List<object> _interceptorEntries = [];
    private readonly IServiceProvider? _serviceProvider;
    // Resolved for the current creation only (cleared by CreateDataContext), so a transient service
    // is resolved once per context and never reused across creations.
    private IQueryInterceptor[]? _resolvedQueryInterceptors;
    private IConnectionInterceptor[]? _resolvedConnectionInterceptors;

    /// <summary>
    /// Creates a standalone builder whose interceptors must be supplied as instances.
    /// </summary>
    public DataContextBuilder()
    {
    }

    /// <summary>
    /// Creates a builder backed by <paramref name="serviceProvider"/>, so interceptor service keys
    /// registered with <see cref="AddInterceptor(Type)"/>/<see cref="AddInterceptor{T}()"/> are
    /// resolved from that provider (its scope, not the root) when a context is created.
    /// </summary>
    /// <param name="serviceProvider">The service provider that owns the interceptor services.</param>
    /// <exception cref="ArgumentNullException"><paramref name="serviceProvider"/> is <see langword="null"/>.</exception>
    internal DataContextBuilder(IServiceProvider serviceProvider)
    {
        ArgumentNullException.ThrowIfNull(serviceProvider);
        _serviceProvider = serviceProvider;
    }
    /// <summary>
    /// Whether command parameter values are written to the configured logger. Defaults to
    /// <see langword="false"/>; enable it only for local diagnostics, since parameter values may contain
    /// sensitive data. Set through <see cref="LogSensitiveData"/>.
    /// </summary>
    public bool ShouldLogSensitiveData => _logSensitiveData;
    /// <summary>
    /// Whether physical identifiers (table and column names) are quoted with the provider's delimiter
    /// in generated SQL. Defaults to <c>false</c> (names are emitted verbatim); can be overridden per
    /// command with <c>WithQuotedIdentifiers</c>.
    /// </summary>
    public bool QuoteIdentifiers { get; private set; }

    /// <summary>
    /// Convention applied by default to table and column names that were not declared explicitly
    /// (no attribute/fluent mapping). <see langword="null"/> (the default) emits the CLR names
    /// verbatim; can be overridden per command with <c>WithNamingConvention</c>.
    /// </summary>
    public INamingConvention? NamingConvention { get; private set; }

    /// <summary>
    /// The letter case in which SQL keywords are emitted by default. Defaults to
    /// <see cref="NextORM.Core.KeywordCase.Lower"/> (unchanged historical output); can be overridden per
    /// command with <c>WithKeywordCase</c>. Set through <see cref="UseKeywordCase"/>.
    /// </summary>
    public KeywordCase KeywordCase { get; private set; }

    /// <summary>
    /// Whether a rendered batch places each statement on its own line. Defaults to
    /// <see langword="false"/> (statements joined on one line with <c>"; "</c>). Set through
    /// <see cref="UseMultilineBatchSql"/>; affects the batch SQL produced by <c>BatchQuery.ToSql()</c>
    /// and the joined command text only, not the per-command <c>DbBatch</c> form.
    /// </summary>
    public bool MultilineBatchSql { get; private set; }

    /// <summary>
    /// The command timeout in seconds applied to every command of the contexts this builder creates, or
    /// <see langword="null"/> when no timeout is configured and the provider default applies. Set through
    /// <see cref="UseCommandTimeout"/>; a command can override it with <c>WithCommandTimeout</c>.
    /// </summary>
    public int? CommandTimeout => _commandTimeout;
    //internal IDataProvider? DataProvider => _dataProvider;
    internal ILoggerFactory? LoggerFactory => _loggerFactory;

    /// <summary>
    /// Whether prepared queries may be stored in and reused from the plan cache. Defaults to
    /// <see langword="true"/>; set through <see cref="UseQueryCache"/>. When disabled, every
    /// preparation is built without caching (the equivalent of <c>storeInCache: false</c>) and the
    /// per-command <c>QueryCommand.Cache</c> flag is never mutated.
    /// </summary>
    public bool QueryCacheEnabled { get; private set; } = true;
    // public bool CacheQueryCommand { get; set; } = true;
    // public bool CacheExpressions { get; set; } = true;

    /// <summary>
    /// The context-wide default eager-load strategy applied to <c>LoadWith</c> collections when a query
    /// declares no explicit mode. Defaults to <see cref="EagerLoadMode.SplitQuery"/> (the historical
    /// behavior); set through <see cref="UseEagerLoadMode"/>. A query override
    /// (<c>LoadWith(..., mode)</c>) always wins over this default, and configuring a context never
    /// changes a static/global value.
    /// </summary>
    public EagerLoadMode EagerLoadMode { get; private set; } = EagerLoadMode.SplitQuery;
    /// <summary>
    /// Factory invoked by <see cref="CreateDataContext"/> to materialize the configured context.
    /// <see langword="null"/> until one of the provider extensions (for example
    /// <c>UseInMemoryContext</c>) assigns it; <see cref="CreateDataContext"/> throws
    /// <see cref="InvalidOperationException"/> in that state.
    /// </summary>
    public Func<DataContextBuilder, IDataContext>? Factory { get => _factory; set => _factory = value; }

    //public Dictionary<string, object> Property => _props;
    /// <summary>
    /// Sets the logger factory used for diagnostic logging (SQL text and, when enabled, parameter
    /// values).
    /// </summary>
    /// <param name="loggerFactory">The logger factory to use; must not be <see langword="null"/>.</param>
    /// <returns>This builder, to allow chaining.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="loggerFactory"/> is <see langword="null"/>.</exception>
    public DataContextBuilder UseLoggerFactory(ILoggerFactory loggerFactory)
    {
        ArgumentNullException.ThrowIfNull(loggerFactory);

        _loggerFactory = loggerFactory;
        return this;
    }
    // public DataContextOptionsBuilder UseSqlClient(SqlDataProvider dataProvider)
    // {
    //     ArgumentNullException.ThrowIfNull(dataProvider);

    //     _dataProvider = dataProvider;        
    //     return this;
    // }
    /// <summary>
    /// Enables or disables logging of command parameter values. Disabled by default; only enable it for
    /// local diagnostics, as parameter values may contain sensitive data.
    /// </summary>
    /// <param name="logSensitiveData"><see langword="true"/> to log parameter values; otherwise <see langword="false"/>.</param>
    /// <returns>This builder, to allow chaining.</returns>
    public DataContextBuilder LogSensitiveData(bool logSensitiveData)
    {
        _logSensitiveData = logSensitiveData;
        return this;
    }

    /// <summary>
    /// Enables quoting of physical identifiers (table and column names) in generated SQL, using the
    /// provider's delimiter (<c>"id"</c> on PostgreSQL/SQLite, <c>[id]</c> on SQL Server, `` `id` `` on
    /// MySQL/MariaDB/ClickHouse). A single command can override the setting with
    /// <c>WithQuotedIdentifiers</c>.
    /// </summary>
    public DataContextBuilder UseQuotedIdentifiers(bool value = true)
    {
        QuoteIdentifiers = value;
        return this;
    }

    /// <summary>
    /// Applies a naming convention to auto-derived table and column names; for example
    /// <see cref="SnakeCaseNamingConvention.Instance"/> maps <c>SimpleEntity</c> to
    /// <c>simple_entity</c> and <c>FirstName</c> to <c>first_name</c>. Names declared with
    /// <c>[SqlTable]</c>/<c>[Column]</c> or a fluent mapping are never translated. Pass
    /// <see langword="null"/> to emit CLR names verbatim (the default). A single command can override
    /// the setting with <c>WithNamingConvention</c>.
    /// </summary>
    public DataContextBuilder UseNamingConvention(INamingConvention? convention)
    {
        NamingConvention = convention;
        return this;
    }

    /// <summary>
    /// Sets the letter case in which SQL keywords are emitted. <see cref="KeywordCase.Lower"/> (the
    /// default) emits <c>select ... from ...</c>; <see cref="KeywordCase.Upper"/> emits
    /// <c>SELECT ... FROM ...</c>. Identifiers, string literals, function names, type names and raw SQL
    /// are never affected. A single command can override the setting with <c>WithKeywordCase</c>.
    /// </summary>
    /// <param name="keywordCase">The keyword case to apply.</param>
    /// <returns>This builder, to allow chaining.</returns>
    public DataContextBuilder UseKeywordCase(KeywordCase keywordCase = KeywordCase.Upper)
    {
        KeywordCase = keywordCase;
        return this;
    }

    /// <summary>
    /// Convenience form of <see cref="UseKeywordCase"/>: enables (<paramref name="value"/> is
    /// <see langword="true"/>) or disables upper-case SQL keywords.
    /// </summary>
    /// <param name="value"><see langword="true"/> to emit keywords in upper case; otherwise lower case.</param>
    /// <returns>This builder, to allow chaining.</returns>
    public DataContextBuilder UseUppercaseKeywords(bool value = true)
        => UseKeywordCase(value ? KeywordCase.Upper : KeywordCase.Lower);

    /// <summary>
    /// Enables rendering of batch SQL with one statement per line: each statement is terminated with
    /// <c>;</c> followed by a newline instead of a space. Intended for readable logs and inspection;
    /// the executed SQL is unaffected (providers using <c>DbBatch</c> never run the joined text, and
    /// SQLite/SQL Server accept the newline).
    /// </summary>
    /// <param name="value"><see langword="true"/> to place each batch statement on its own line; otherwise <see langword="false"/>.</param>
    /// <returns>This builder, to allow chaining.</returns>
    public DataContextBuilder UseMultilineBatchSql(bool value = true)
    {
        MultilineBatchSql = value;
        return this;
    }

    /// <summary>
    /// Sets the default command timeout in seconds for every command of the contexts this builder
    /// creates (the ADO.NET <c>DbCommand.CommandTimeout</c>). A value of zero or less means the
    /// provider default (nothing is changed, the zero-cost path); the same applies before the call. A
    /// single command can override the value with <c>WithCommandTimeout</c>. The resolved timeout is
    /// part of the plan-cache key, so contexts with different defaults do not share a cached command.
    /// The in-memory context has no command and ignores it.
    /// </summary>
    /// <param name="seconds">The default command timeout in seconds; zero or less uses the provider default.</param>
    /// <returns>This builder, to allow chaining.</returns>
    public DataContextBuilder UseCommandTimeout(int seconds)
    {
        _commandTimeout = seconds > 0 ? seconds : null;

        return this;
    }

    /// <summary>
    /// Enables (<paramref name="enabled"/> is <see langword="true"/>, the default) or disables the
    /// implicit plan cache for every context this builder creates. Disabled means each terminal builds
    /// its plan again instead of looking it up; the shared <c>AnyCommand</c>'s sticky
    /// <c>QueryCommand.Cache</c> flag is not touched.
    /// </summary>
    /// <param name="enabled"><see langword="true"/> to use the plan cache; otherwise <see langword="false"/>.</param>
    /// <returns>This builder, to allow chaining.</returns>
    public DataContextBuilder UseQueryCache(bool enabled = true)
    {
        QueryCacheEnabled = enabled;
        return this;
    }

    /// <summary>
    /// Sets the context-wide default eager-load strategy used by <c>LoadWith</c> when a query declares
    /// no explicit mode. The default is <see cref="EagerLoadMode.SplitQuery"/> (the historical behavior).
    /// An explicit <c>LoadWith(..., mode)</c> always overrides this setting.
    /// <para>
    /// <see cref="EagerLoadMode.Default"/> is rejected: it is an inheritance sentinel, not a context
    /// setting. <see cref="EagerLoadMode.Correlated"/> is accepted as configuration, but a
    /// <c>LoadWith</c> that resolves to it fails with <see cref="NotSupportedException"/> during
    /// preparation (correlated/per-parent top-N execution is not implemented in this release).
    /// </para>
    /// </summary>
    /// <param name="mode">The context default; one of SplitQuery, SingleQuery, Correlated or Auto.</param>
    /// <returns>This builder, to allow chaining.</returns>
    /// <exception cref="ArgumentOutOfRangeException">
    /// <paramref name="mode"/> is <see cref="EagerLoadMode.Default"/> or an undefined numeric value.
    /// </exception>
    public DataContextBuilder UseEagerLoadMode(EagerLoadMode mode)
    {
        switch (mode)
        {
            case EagerLoadMode.SplitQuery:
            case EagerLoadMode.SingleQuery:
            case EagerLoadMode.Correlated:
            case EagerLoadMode.Auto:
                EagerLoadMode = mode;
                return this;
            case EagerLoadMode.Default:
                throw new ArgumentOutOfRangeException(
                    nameof(mode), mode,
                    "EagerLoadMode.Default is an inheritance sentinel, not a context setting; pass a concrete strategy.");
            default:
                throw new ArgumentOutOfRangeException(
                    nameof(mode), mode,
                    $"'{mode}' is not a defined EagerLoadMode value; use SplitQuery, SingleQuery, Correlated or Auto.");
        }
    }

    /// <summary>
    /// Enables sliding expiration for the process-wide caches: an entry that is not read within
    /// <paramref name="ttl"/> is evicted lazily. Pass <see cref="TimeSpan.Zero"/> to disable it (the
    /// default). The setting is process-wide because the caches are static, so it applies to every
    /// context created afterwards as well.
    /// </summary>
    /// <param name="ttl">The sliding window; <see cref="TimeSpan.Zero"/> disables expiration.</param>
    /// <returns>This builder, to allow chaining.</returns>
    /// <exception cref="ArgumentOutOfRangeException"><paramref name="ttl"/> is negative.</exception>
    public DataContextBuilder UseCacheSlidingExpiration(TimeSpan ttl)
    {
        DataContextCache.CacheSlidingExpiration = ttl;
        return this;
    }

    /// <summary>
    /// Registers a query interceptor that observes the command execution lifecycle of every context
    /// this builder creates. Interceptors are invoked in registration order, after the ones already
    /// registered.
    /// </summary>
    /// <param name="interceptor">The interceptor to register; must not be <see langword="null"/>.</param>
    /// <returns>This builder, to allow chaining.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="interceptor"/> is <see langword="null"/>.</exception>
    /// <remarks>
    /// An instance that also implements <see cref="IConnectionInterceptor"/> is attached to both
    /// event pipelines. Registration is deduplicated by the instance's runtime type: a later
    /// registration of the same type is ignored (first registration wins).
    /// </remarks>
    public DataContextBuilder AddInterceptor(IQueryInterceptor interceptor)
    {
        ArgumentNullException.ThrowIfNull(interceptor);
        AddEntry(interceptor);
        return this;
    }

    /// <summary>
    /// Registers a connection interceptor that observes the connection lifecycle of every context this
    /// builder creates. Interceptors are invoked in registration order, after the ones already
    /// registered.
    /// </summary>
    /// <param name="interceptor">The interceptor to register; must not be <see langword="null"/>.</param>
    /// <returns>This builder, to allow chaining.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="interceptor"/> is <see langword="null"/>.</exception>
    /// <remarks>
    /// An instance that also implements <see cref="IQueryInterceptor"/> is attached to both event
    /// pipelines. Registration is deduplicated by the instance's runtime type: a later registration
    /// of the same type is ignored (first registration wins).
    /// </remarks>
    public DataContextBuilder AddInterceptor(IConnectionInterceptor interceptor)
    {
        ArgumentNullException.ThrowIfNull(interceptor);
        AddEntry(interceptor);
        return this;
    }

    /// <summary>
    /// Registers an interceptor service key to resolve from the provider captured by this builder when
    /// a context is created. The type is validated immediately; the service is resolved once per
    /// <see cref="CreateDataContext"/> call, honouring the DI lifetime and keeping DI ownership of the
    /// resolved instance.
    /// </summary>
    /// <param name="interceptorType">The closed reference type (concrete class, interface or abstract class) to resolve.</param>
    /// <returns>This builder, to allow chaining.</returns>
    /// <exception cref="ArgumentNullException"><paramref name="interceptorType"/> is <see langword="null"/>.</exception>
    /// <exception cref="ArgumentException">
    /// <paramref name="interceptorType"/> is an open generic or value type, or is not assignable to
    /// <see cref="IQueryInterceptor"/> or <see cref="IConnectionInterceptor"/>.
    /// </exception>
    /// <exception cref="InvalidOperationException">
    /// A context is created on a builder without a captured provider (a standalone builder).
    /// </exception>
    /// <remarks>
    /// Registration is deduplicated by the supplied type: a later registration of the same type is
    /// ignored (first registration wins), and a type entry is not merged with an instance of the same
    /// runtime type.
    /// </remarks>
    public DataContextBuilder AddInterceptor(Type interceptorType)
    {
        ArgumentNullException.ThrowIfNull(interceptorType);

        if (!IsValidInterceptorType(interceptorType))
        {
            throw new ArgumentException(
                $"Type '{interceptorType}' must be a closed reference type assignable to IQueryInterceptor or IConnectionInterceptor.",
                nameof(interceptorType));
        }

        AddEntry(interceptorType);
        return this;
    }

    /// <summary>
    /// Registers an interceptor service key to resolve from the provider captured by this builder when
    /// a context is created; see <see cref="AddInterceptor(Type)"/>.
    /// </summary>
    /// <typeparam name="T">A closed reference type assignable to <see cref="IQueryInterceptor"/> or <see cref="IConnectionInterceptor"/>.</typeparam>
    /// <returns>This builder, to allow chaining.</returns>
    /// <exception cref="ArgumentException"><typeparamref name="T"/> is not a valid interceptor type.</exception>
    /// <exception cref="InvalidOperationException">A context is created on a builder without a captured provider.</exception>
    public DataContextBuilder AddInterceptor<T>() where T : class
        => AddInterceptor(typeof(T));

    private void AddEntry(object entry)
    {
        var key = entry is Type type ? type : entry.GetType();
        foreach (var existing in _interceptorEntries)
        {
            var existingKey = existing is Type existingType ? existingType : existing.GetType();
            if (existingKey == key)
                return;
        }

        _interceptorEntries.Add(entry);
    }

    private static bool IsValidInterceptorType(Type interceptorType)
        => !interceptorType.IsValueType
           && !interceptorType.ContainsGenericParameters
           && (typeof(IQueryInterceptor).IsAssignableFrom(interceptorType)
               || typeof(IConnectionInterceptor).IsAssignableFrom(interceptorType));

    /// <summary>
    /// Resolves the interceptor registrations into the two event pipelines, completing the work (and
    /// any missing-service failure) before the context factory runs. The result is cached only for the
    /// duration of one creation; the cached arrays are exposed to the context constructor through
    /// <see cref="QueryInterceptors"/> and <see cref="ConnectionInterceptors"/>.
    /// </summary>
    internal (IQueryInterceptor[] Query, IConnectionInterceptor[] Connection) ResolveInterceptors()
    {
        if (_resolvedQueryInterceptors is not null && _resolvedConnectionInterceptors is not null)
            return (_resolvedQueryInterceptors, _resolvedConnectionInterceptors);

        var query = new List<IQueryInterceptor>();
        var connection = new List<IConnectionInterceptor>();
        foreach (var entry in _interceptorEntries)
        {
            var instance = entry is Type type ? ResolveType(type) : entry;
            if (instance is IQueryInterceptor queryInterceptor)
                query.Add(queryInterceptor);
            if (instance is IConnectionInterceptor connectionInterceptor)
                connection.Add(connectionInterceptor);
        }

        _resolvedQueryInterceptors = [.. query];
        _resolvedConnectionInterceptors = [.. connection];
        return (_resolvedQueryInterceptors, _resolvedConnectionInterceptors);
    }

    private object ResolveType(Type type)
    {
        if (_serviceProvider is null)
            throw new InvalidOperationException($"Interceptor type '{type}' requires a DI-backed DataContextBuilder.");

        return _serviceProvider.GetRequiredService(type);
    }

    internal IQueryInterceptor[] QueryInterceptors => ResolveInterceptors().Query;

    internal IConnectionInterceptor[] ConnectionInterceptors => ResolveInterceptors().Connection;

    /// <summary>
    /// Creates a data context from the current configuration by invoking <see cref="Factory"/>. Any
    /// interceptor service keys are resolved from the captured provider before the factory is invoked,
    /// so a missing registration (or a type entry on a standalone builder) fails before a context is
    /// constructed.
    /// </summary>
    /// <returns>The configured <see cref="IDataContext"/>.</returns>
    /// <exception cref="InvalidOperationException">
    /// No factory has been configured on this builder, the provider does not have an interceptor
    /// registration, or a type entry was registered on a builder without a captured provider.
    /// </exception>
    public IDataContext CreateDataContext()
    {
        if (_factory is null)
            throw new InvalidOperationException("Context is not set");

        // Resolution is scoped to this call so a transient interceptor is resolved per creation and
        // never reused across calls; the factory reads the cached arrays through the two properties.
        _resolvedQueryInterceptors = null;
        _resolvedConnectionInterceptors = null;
        ResolveInterceptors();

        return _factory(this);
    }

    // public DataContextOptionsBuilder UseInMemoryClient()
    // {
    //     _dataProvider = new InMemoryDataProvider();
    //     return this;
    // }
}

using Microsoft.Extensions.DependencyInjection;

namespace NextORM.Core;

/// <summary>
/// Registration helpers for nextorm contexts.
/// <para>
/// Invariants:
/// <list type="bullet">
/// <item>a concrete context type is registered <b>once per scope</b>: resolving the concrete type and
/// <see cref="IDataContext"/> yields the same instance (previously they were two separate instances);</item>
/// <item>the options delegate is mandatory for factory-based registration — a <see cref="DataContextBuilder"/>
/// without options can never produce a context, so a null delegate now fails at registration time instead of
/// at resolution time.</item>
/// </list>
/// </para>
/// </summary>
public static class ServiceCollectionExtensions
{
    /// <summary>
    /// Registers an unkeyed <see cref="IDataContext"/> (and its scoped <see cref="DataContextBuilder"/>)
    /// configured by <paramref name="optionsBuilder"/>, which may resolve services from the provider.
    /// </summary>
    /// <param name="services">The service collection to register into.</param>
    /// <param name="optionsBuilder">Delegate that configures the builder using the current <see cref="IServiceProvider"/>.</param>
    /// <exception cref="ArgumentNullException"><paramref name="services"/> or <paramref name="optionsBuilder"/> is <see langword="null"/>.</exception>
    public static void AddNextOrmContext(this IServiceCollection services, Action<IServiceProvider, DataContextBuilder> optionsBuilder)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(optionsBuilder);

        services.RegisterContextFactory(null, optionsBuilder);
    }

    /// <summary>
    /// Registers a keyed <see cref="IDataContext"/> (and its scoped <see cref="DataContextBuilder"/>)
    /// configured by <paramref name="optionsBuilder"/>, which may resolve services from the provider.
    /// </summary>
    /// <param name="services">The service collection to register into.</param>
    /// <param name="optionsBuilder">Delegate that configures the builder using the current <see cref="IServiceProvider"/>.</param>
    /// <param name="serviceKey">The key under which the context is registered.</param>
    /// <exception cref="ArgumentNullException"><paramref name="services"/> or <paramref name="optionsBuilder"/> is <see langword="null"/>.</exception>
    public static void AddKeyedNextOrmContext(this IServiceCollection services, Action<IServiceProvider, DataContextBuilder> optionsBuilder, object? serviceKey)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(optionsBuilder);

        services.RegisterContextFactory(serviceKey, optionsBuilder);
    }

    /// <summary>
    /// Registers an unkeyed <see cref="IDataContext"/> (and its scoped <see cref="DataContextBuilder"/>)
    /// configured by <paramref name="optionsBuilder"/>.
    /// </summary>
    /// <param name="services">The service collection to register into.</param>
    /// <param name="optionsBuilder">Delegate that configures the builder.</param>
    /// <exception cref="ArgumentNullException"><paramref name="services"/> or <paramref name="optionsBuilder"/> is <see langword="null"/>.</exception>
    public static void AddNextOrmContext(this IServiceCollection services, Action<DataContextBuilder> optionsBuilder)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(optionsBuilder);

        services.RegisterContextFactory(null, (_, builder) => optionsBuilder(builder));
    }

    /// <summary>
    /// Registers a keyed <see cref="IDataContext"/> (and its scoped <see cref="DataContextBuilder"/>)
    /// configured by <paramref name="optionsBuilder"/>.
    /// </summary>
    /// <param name="services">The service collection to register into.</param>
    /// <param name="optionsBuilder">Delegate that configures the builder.</param>
    /// <param name="serviceKey">The key under which the context is registered.</param>
    /// <exception cref="ArgumentNullException"><paramref name="services"/> or <paramref name="optionsBuilder"/> is <see langword="null"/>.</exception>
    public static void AddKeyedNextOrmContext(this IServiceCollection services, Action<DataContextBuilder> optionsBuilder, object? serviceKey)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(optionsBuilder);

        services.RegisterContextFactory(serviceKey, (_, builder) => optionsBuilder(builder));
    }

    /// <summary>
    /// Registers the concrete context type <typeparamref name="T"/> once per scope and forwards
    /// <see cref="IDataContext"/> to it, so both resolve to the same instance.
    /// </summary>
    /// <typeparam name="T">The concrete context type to register.</typeparam>
    /// <param name="services">The service collection to register into.</param>
    /// <exception cref="ArgumentNullException"><paramref name="services"/> is <see langword="null"/>.</exception>
    public static void AddNextOrmContext<T>(this IServiceCollection services)
        where T : class, IDataContext
    {
        ArgumentNullException.ThrowIfNull(services);

        services.RegisterContextType<T>(null);
    }

    /// <summary>
    /// Registers the concrete context type <typeparamref name="T"/> under a key once per scope and
    /// forwards the keyed <see cref="IDataContext"/> to it, so both resolve to the same instance.
    /// </summary>
    /// <typeparam name="T">The concrete context type to register.</typeparam>
    /// <param name="services">The service collection to register into.</param>
    /// <param name="serviceKey">The key under which the context is registered.</param>
    /// <exception cref="ArgumentNullException"><paramref name="services"/> is <see langword="null"/>.</exception>
    public static void AddKeyedNextOrmContext<T>(this IServiceCollection services, object? serviceKey)
        where T : class, IDataContext
    {
        ArgumentNullException.ThrowIfNull(services);

        services.RegisterContextType<T>(serviceKey);
    }

    /// <summary>
    /// Options-driven path: registers a scoped <see cref="DataContextBuilder"/> built by
    /// <paramref name="optionsBuilder"/> plus an <see cref="IDataContext"/> factory that turns it into a
    /// context.
    /// </summary>
    private static void RegisterContextFactory(this IServiceCollection services, object? serviceKey, Action<IServiceProvider, DataContextBuilder> optionsBuilder)
    {
        if (serviceKey is null)
        {
            services.AddScoped(sp =>
            {
                var builder = new DataContextBuilder(sp);
                optionsBuilder(sp, builder);
                return builder;
            });

            services.AddScoped(sp => sp.GetRequiredService<DataContextBuilder>().CreateDataContext());
        }
        else
        {
            services.AddKeyedScoped(serviceKey, (sp, _) =>
            {
                var builder = new DataContextBuilder(sp);
                optionsBuilder(sp, builder);
                return builder;
            });

            services.AddKeyedScoped(serviceKey, (sp, k) => sp.GetRequiredKeyedService<DataContextBuilder>(k).CreateDataContext());
        }
    }

    /// <summary>
    /// Type-driven path: registers the concrete context once per scope and forwards
    /// <see cref="IDataContext"/> to it, so both resolve to the same instance.
    /// </summary>
    private static void RegisterContextType<T>(this IServiceCollection services, object? serviceKey)
        where T : class, IDataContext
    {
        if (serviceKey is null)
        {
            services.AddScoped<T>();
            services.AddScoped<IDataContext>(sp => sp.GetRequiredService<T>());
        }
        else
        {
            services.AddKeyedScoped<T>(serviceKey);
            services.AddKeyedScoped<IDataContext>(serviceKey, (sp, k) => sp.GetRequiredKeyedService<T>(k));
        }
    }
}

namespace NextORM.Core;

/// <summary>
/// Declares how a <see cref="System.TimeSpan"/> property is stored. On a provider with a native
/// duration type (PostgreSQL <c>interval</c>, MySQL/MariaDB <c>TIME</c>) the unit is ignored and the
/// value is stored natively; on a provider without one (SQL Server, SQLite, ClickHouse) the value is
/// stored in an integer column in <see cref="Unit"/>, defaulting to <see cref="DurationUnit.Ticks"/>.
/// </summary>
/// <remarks>
/// The attribute is read by <see cref="IPropertyMetadata"/> (<see cref="IPropertyMetadata.DurationUnit"/>)
/// and by the dialect's <c>MakeDurationType</c> hook. The concrete member is
/// <see cref="System.TimeSpan"/>; the equivalent fluent mapping is
/// <see cref="EntityPropertyBuilder{T}.Duration(DurationUnit, int)"/>.
/// </remarks>
[AttributeUsage(AttributeTargets.Property, AllowMultiple = false, Inherited = true)]
public sealed class DurationAttribute : Attribute
{
    /// <summary>
    /// Creates an attribute that stores the value in <see cref="DurationUnit.Ticks"/>.
    /// </summary>
    public DurationAttribute()
        : this(DurationUnit.Ticks)
    {
    }

    /// <summary>
    /// Creates an attribute that stores the value in <paramref name="unit"/>.
    /// </summary>
    /// <param name="unit">The unit of the stored integer value on providers without a native duration type.</param>
    public DurationAttribute(DurationUnit unit)
    {
        Unit = unit;
    }

    /// <summary>
    /// The unit of the stored integer value on providers without a native duration type.
    /// </summary>
    public DurationUnit Unit { get; set; }

    /// <summary>
    /// The precision of the native duration type (fractional seconds), for example
    /// <c>TIME(3)</c> or <c>interval(3)</c>. Zero means the provider default.
    /// </summary>
    public int Precision { get; set; }
}

namespace NextORM.Core;

/// <summary>
/// Converts between a <see cref="TimeSpan"/> and the integer representation used by a provider
/// without a native duration type. The conversion is lossless only for <see cref="DurationUnit.Ticks"/>;
/// a coarser unit truncates the sub-unit remainder, which is the same behaviour as storing the value
/// in a database column of that unit.
/// </summary>
internal static class DurationStorage
{
    /// <summary>
    /// The unit in which a duration value is stored: <c>null</c> when the provider keeps it natively
    /// (PostgreSQL <c>interval</c>, MySQL/MariaDB <c>TIME</c>), otherwise the declared unit or
    /// <see cref="DurationUnit.Ticks"/> when none is declared.
    /// </summary>
    internal static DurationUnit? ResolveStorageUnit(IPropertyMetadata? property, ISqlDialect dialect)
        => dialect.SupportsNativeDuration ? null : property?.DurationUnit ?? DurationUnit.Ticks;

    /// <summary>
    /// Converts a duration to the stored integer value in <paramref name="unit"/>.
    /// </summary>
    /// <param name="value">The duration to store.</param>
    /// <param name="unit">The storage unit.</param>
    /// <returns>The value expressed in <paramref name="unit"/>, truncated toward zero.</returns>
    internal static long ToStorage(TimeSpan value, DurationUnit unit)
        => value.Ticks / TicksPerUnit(unit);

    /// <summary>
    /// Converts a stored integer value in <paramref name="unit"/> back to a duration.
    /// </summary>
    /// <param name="value">The stored integer value.</param>
    /// <param name="unit">The storage unit.</param>
    /// <returns>The reconstructed duration.</returns>
    internal static TimeSpan FromStorage(long value, DurationUnit unit)
        => new(value * TicksPerUnit(unit));

    private static long TicksPerUnit(DurationUnit unit) => unit switch
    {
        DurationUnit.Ticks => 1L,
        DurationUnit.Microseconds => TimeSpan.TicksPerMicrosecond,
        DurationUnit.Milliseconds => TimeSpan.TicksPerMillisecond,
        DurationUnit.Seconds => TimeSpan.TicksPerSecond,
        DurationUnit.Minutes => TimeSpan.TicksPerMinute,
        DurationUnit.Hours => TimeSpan.TicksPerHour,
        DurationUnit.Days => TimeSpan.TicksPerDay,
        _ => throw new ArgumentOutOfRangeException(nameof(unit), unit, "Unknown duration unit.")
    };

    /// <summary>
    /// Normalizes a write value through the mapped property's converter and, for a provider without a
    /// native duration type, its declared storage unit. This is the single write seam: every mutation
    /// builder (insert, update, merge, bulk, delete keys) routes parameter values through it, so a
    /// converter declared once is applied wherever the property is written. A property with a converter
    /// owns its provider representation; the duration normalization then does not apply.
    /// </summary>
    /// <param name="value">The value being written.</param>
    /// <param name="property">The mapped property the value targets, or <c>null</c>.</param>
    /// <param name="dialect">The dialect rendering the statement.</param>
    /// <returns>The value to pass to the provider parameter.</returns>
    internal static object? ToParameterValue(object? value, IPropertyMetadata? property, ISqlDialect dialect)
    {
        var converter = property?.Converter;
        if (converter is IJsonColumnConverter json)
            converter = json.Resolve(dialect);

        if (converter is not null)
        {
            if (value is null && !converter.ConvertsNulls)
                return null;

            return converter.ConvertToProvider(value);
        }

        if (value is TimeSpan duration && ResolveStorageUnit(property, dialect) is { } unit)
            return ToStorage(duration, unit);

        return value;
    }
}

namespace NextORM.Core;

/// <summary>
/// The unit in which a <see cref="System.TimeSpan"/> property is stored when the provider has no
/// native interval/time-of-day type and the value is kept in an integer column. Providers with a
/// native duration type (PostgreSQL <c>interval</c>, MySQL/MariaDB <c>TIME</c>) ignore the unit and
/// store the value natively; <see cref="Ticks"/> is the unit used when none is declared.
/// </summary>
public enum DurationUnit
{
    /// <summary>100-nanosecond ticks, the <see cref="System.TimeSpan"/> storage unit.</summary>
    Ticks,
    /// <summary>Whole microseconds.</summary>
    Microseconds,
    /// <summary>Whole milliseconds.</summary>
    Milliseconds,
    /// <summary>Whole seconds.</summary>
    Seconds,
    /// <summary>Whole minutes.</summary>
    Minutes,
    /// <summary>Whole hours.</summary>
    Hours,
    /// <summary>Whole days.</summary>
    Days
}

namespace NextORM.Core;

/// <summary>
/// Marks a writable property of an entity as the store that receives the row's columns which are not
/// mapped to a declared member. The property must be assignable from
/// <see cref="Dictionary{TKey,TValue}"/> with <see cref="string"/> keys and <see cref="object"/> values.
/// </summary>
/// <remarks>
/// Read side only: when the entity is queried as a whole (for example
/// <c>context.From&lt;TEntity&gt;()</c>) the generated <c>SELECT</c> appends the source's <c>*</c> after the
/// mapped columns and the store is materialised with every returned column whose name is not one of the
/// mapped columns. Writing the keys back as columns is not implemented; see
/// <c>docs/advanced/limitations.md</c>. The column names are taken from the result set (the database
/// schema), so the store is only populated for a single physical source — a query with joins rejects the
/// store with <see cref="System.NotSupportedException"/>.
/// </remarks>
[AttributeUsage(AttributeTargets.Property, AllowMultiple = false, Inherited = true)]
public sealed class DynamicColumnsAttribute : Attribute
{
}

namespace NextORM.Core;

/// <summary>
/// Selects how the collections declared with <c>LoadWith</c> are loaded. The mode belongs to the whole
/// builder: an explicit value applies to every declared collection, including those declared before it,
/// while <see cref="Default"/> inherits the current choice.
/// </summary>
public enum EagerLoadMode
{
    /// <summary>No explicit choice: inherit the builder's current mode, defaulting to split loading.</summary>
    Default = 0,
    /// <summary>Split loading (the default): the parent command plus one chunked child query per collection.</summary>
    SplitQuery = 1,
    /// <summary>Single-query loading: one denormalized <c>LEFT JOIN</c> command stitched in memory.</summary>
    SingleQuery = 2,
    /// <summary>
    /// Correlated per-parent loading. Recognized but not supported in this release: a query that resolves
    /// to this mode is rejected with <see cref="NotSupportedException"/> before any SQL is generated or
    /// cached. The value is reserved for the correlated/per-parent top-N work tracked separately.
    /// </summary>
    Correlated = 3,
    /// <summary>
    /// Automatic strategy selection. Resolved once during preparation by the conservative E1 rule, which
    /// selects <see cref="SplitQuery"/> for every supported load; it never silently reinterprets a
    /// per-parent top-N or correlated request.
    /// </summary>
    Auto = 4,
}

using System.Collections.Concurrent;
using System.Linq.Expressions;

namespace NextORM.Core;
/// <summary>
/// A concurrent cache keyed by <see cref="ExpressionKey"/>, used to reuse a compiled artifact per
/// structurally equivalent expression.
/// </summary>
/// <typeparam name="T">The cached artifact type.</typeparam>
public class ExpressionCache<T> : ConcurrentDictionary<ExpressionKey, T>
{

}

/// <summary>
/// Equality wrapper around an <see cref="Expression"/> that uses the query registry's
/// <c>ExpressionPlanEqualityComparer</c>, so two expressions that describe the same query plan hash and
/// compare equal even when they are different object instances. The hash is computed once at
/// construction because both inputs are immutable.
/// </summary>
public sealed class ExpressionKey : IEquatable<ExpressionKey>
{
    private readonly Expression _exp;
    private readonly ExpressionPlanEqualityComparer _equalityComparer;
    // Both inputs are readonly, so the hash is stable for the lifetime of the key.
    // Computing it once up front avoids caching it in a mutable field (S2328 false
    // positive) and any lazy-initialization race when the key is shared.
    private readonly int _hash;

    /// <summary>
    /// Initializes a new key for <paramref name="exp"/> using the plan equality comparer obtained from
    /// <paramref name="queryProvider"/>, and precomputes its hash.
    /// </summary>
    /// <param name="exp">The expression to use as the cache key.</param>
    /// <param name="queryProvider">Registry that supplies the plan equality comparer for the expression.</param>
    public ExpressionKey(Expression exp, IQueryRegistry queryProvider)
    {
        _exp = exp;
        _equalityComparer = queryProvider.GetExpressionPlanEqualityComparer();
        _hash = _equalityComparer.GetHashCode(_exp);
    }

    /// <inheritdoc/>
    public override int GetHashCode() => _hash;
    /// <inheritdoc/>
    public override bool Equals(object? obj)
    {
        return Equals(obj as ExpressionKey);
    }
    /// <summary>
    /// Determines whether <paramref name="obj"/> describes the same query plan as this key, using the
    /// registry's plan equality comparer.
    /// </summary>
    /// <param name="obj">The other key to compare with, or <see langword="null"/>.</param>
    /// <returns><see langword="true"/> when both keys hold plan-equivalent expressions.</returns>
    public bool Equals(ExpressionKey? obj)
    {
        if (obj is null) return false;
        return _equalityComparer.Equals(_exp, obj._exp);
    }
    //public static implicit operator ExpressionKey(Expression exp) => new ExpressionKey(exp);
}

