/// <summary>
/// The letter case in which SQL keywords are emitted. Function names, identifiers, string literals,
/// type names and raw SQL are never affected. Configure the context-wide default with
/// <c>DataContextBuilder.UseKeywordCase</c> and override it for a single query with
/// <c>EntityBuilder&lt;TEntity&gt;.WithKeywordCase</c>.
/// </summary>
public enum KeywordCase
{
    /// <summary>Lower case (<c>select ... from ...</c>) — the default, matching the historical output.</summary>
    Lower = 0,
    /// <summary>Upper case (<c>SELECT ... FROM ...</c>).</summary>
    Upper = 1,
}

using System.Collections.Concurrent;
using System.Reflection;

namespace NextORM.Core;
/// <summary>
/// Helpers for resolving a member's column name and for looking up its metadata in the shared entity
/// metadata cache.
/// </summary>
public static class MemberInfoExtensions
{
    // Entity metadata is registered once per type (DataContextCache.Metadata only builds on a miss),
    // so the resolved column name is stable for a given naming convention for the lifetime of the
    // process. Caching it turns the per-member metadata lookup + linear scan into a dictionary read
    // on the SQL-build path.
    private static readonly ConcurrentDictionary<(PropertyInfo, INamingConvention?), string> _columnNames = new();

    /// <summary>
    /// Drops the cached column names, all of them or only those of <paramref name="entityType"/>. Called
    /// when the process-wide metadata cache is cleared and when an already-published mapping is replaced
    /// by a configured one (the many-to-many junction auto-publish), so a column name resolved against
    /// the superseded metadata cannot be served afterwards.
    /// </summary>
    /// <param name="entityType">The owning entity type to invalidate, or <see langword="null"/> for all.</param>
    internal static void ClearColumnNames(Type? entityType = null)
    {
        if (entityType is null)
        {
            _columnNames.Clear();
            return;
        }

        foreach (var key in _columnNames.Keys)
        {
            if (key.Item1.DeclaringType == entityType)
                _columnNames.TryRemove(key, out _);
        }
    }

    /// <summary>
    /// Column name registered for the member in the shared entity metadata cache, or an empty string
    /// when the metadata does not declare it. Auto-derived names are translated through
    /// <paramref name="convention"/>; declared names are returned verbatim.
    /// </summary>
    public static string GetPropertyColumnName(this MemberInfo mi, INamingConvention? convention = null)
    {
        if (mi is PropertyInfo pi)
        {
            var key = (pi, convention);

            if (_columnNames.TryGetValue(key, out var cached))
                return cached;

            if (DataContextCache.Metadata.TryGetValue(pi.DeclaringType!, pi, out var prop))
            {
                var name = prop!.ColumnName;
                if (prop.IsColumnNameAuto && convention is not null)
                    name = convention.ColumnName(name);

                _columnNames.TryAdd(key, name);
                return name;
            }
        }

        return string.Empty;
    }
    /// <summary>
    /// Looks up the metadata for <paramref name="pi"/> in the entity metadata registered for
    /// <paramref name="type"/>. Because the metadata is keyed by type, the property is matched by
    /// scanning that entity's properties rather than by a direct dictionary lookup.
    /// </summary>
    /// <param name="dic">Entity metadata cache keyed by entity type.</param>
    /// <param name="type">The entity type whose metadata should be searched.</param>
    /// <param name="pi">The property to find in the entity's metadata.</param>
    /// <param name="prop">When this method returns <see langword="true"/>, the matching property metadata; otherwise <see langword="null"/>.</param>
    /// <returns><see langword="true"/> when the type and property are both found; otherwise <see langword="false"/>.</returns>
    public static bool TryGetValue(this IDictionary<Type, IEntityMetadata> dic, Type type, PropertyInfo pi, out IPropertyMetadata? prop)
    {
        if (dic.TryGetValue(type, out var entity))
        {
            foreach (var item in entity.Properties)
            {
                if (item.PropertyInfo == pi)
                {
                    prop = item;
                    return true;
                }
            }
        }
        prop = null;
        return false;
    }
}

using System.Reflection;

namespace NextORM.Core;

/// <summary>
/// Marker for a reference to an element of an outer (ancestor) query scope, used while building
/// correlated subqueries. It is only meaningful inside a query expression: the SQL translator rewrites
/// <c>OuterRefMarker&lt;T&gt;(idx).Ref.Member</c> into a reference to the outer alias's column.
/// </summary>
/// <typeparam name="T">The type of the referenced outer element.</typeparam>
/// <param name="i">The zero-based index of the outer element in the correlated query scope.</param>
public class OuterRefMarker<T>(int i)
{
    /// <summary>
    /// The zero-based index of the referenced outer element, as passed to the constructor.
    /// </summary>
    public int I { get; } = i;
    /// <summary>
    /// Sentinel member that the translator looks for to identify an outer reference. It is never
    /// assigned, so at runtime its value is always the default for <typeparamref name="T"/>.
    /// </summary>
    public T? Ref { get; }

}

namespace NextORM.Core;

/// <summary>
/// Name/value pair for a single command parameter.
/// </summary>
/// <remarks>
/// Renamed from <c>Param</c> (<c>Parameter</c> is the full word). See
/// <c>docs/specs/design/API-NAMING-REVIEW.md</c> finding P1-13.
/// </remarks>
public class Parameter(string name, object? value)
{
    /// <summary>
    /// The placeholder name (without the provider's parameter prefix) used to bind
    /// <see cref="Value"/> in the generated SQL.
    /// </summary>
    public string Name { get; set; } = name;
    /// <summary>
    /// The value bound to <see cref="Name"/>, or <see langword="null"/> for a SQL <c>NULL</c>.
    /// </summary>
    public object? Value { get; set; } = value;

    /// <summary>
    /// True when <see cref="Value"/> is fully determined by the query shape (an inline value list or a
    /// constant-folded expression), so a cached plan does not have to copy it into the command on every
    /// execution. A captured collection/variable is not stable: its value can change while the plan key
    /// stays the same. Internal: this is an engine optimization, not part of the public contract.
    /// </summary>
    internal bool Stable { get; set; }

    /// <summary>
    /// The captured expression this parameter was produced from (a closure member access), or
    /// <see langword="null"/> for a parameter that does not bound a captured value. Used to register a
    /// captured local once per rendered statement, so every occurrence reuses the same placeholder.
    /// Internal: an engine bookkeeping detail, not part of the public contract.
    /// </summary>
    internal ExpressionKey? CapturedKey { get; set; }

    /// <summary>
    /// True when <see cref="Value"/> went through a column converter or a duration-storage
    /// normalization while the parameter was built, so re-reading the raw captured value would not
    /// reproduce <see cref="Value"/>. The immutable guarded parameter-refresh recipe refuses such
    /// parameters and routes them to the original extraction path. Internal: an engine bookkeeping
    /// detail, not part of the public contract.
    /// </summary>
    internal bool HasConversion { get; set; }
}

