namespace NextORM.Core;

/// <summary>
/// Central construction-time helper that resolves a keyword token (or a fragment that is pure
/// keywords and separators) to the configured <see cref="KeywordCase"/>. Emitters must pass the
/// exact lower-case token they would have emitted; identifiers, literals and function names are never
/// routed through here, so the case never touches user data. Exposed so provider capability renderers
/// (which live in their own assembly) can case the clauses they emit.
/// </summary>
public static class SqlKeywords
{
    private static readonly ConcurrentDictionary<string, string> UpperCache = new(StringComparer.Ordinal);

    /// <summary>Returns <paramref name="text"/> unchanged for <see cref="KeywordCase.Lower"/> and its invariant upper-case form otherwise.</summary>
    public static string Of(KeywordCase @case, string text)
        => @case == KeywordCase.Upper ? UpperCache.GetOrAdd(text, static t => t.ToUpperInvariant()) : text;
}

namespace NextORM.Core;
/// <summary>
/// Maps a class or interface to a database table, overriding the table name that would otherwise be
/// derived from the CLR type name.
/// </summary>
[AttributeUsage(AttributeTargets.Class | AttributeTargets.Interface, AllowMultiple = false)]
public class SqlTableAttribute : Attribute
{
    /// <summary>
    /// Initializes a new instance of the <see cref="SqlTableAttribute"/> class.
    /// </summary>
    /// <param name="name">The database table name to use for the annotated type.</param>
    public SqlTableAttribute(string name)
    {
        Name=name;
    }

    /// <summary>
    /// The database table name for the annotated type.
    /// </summary>
    public string Name { get; }
}

namespace NextORM.Core;

/// <summary>
/// Where the result-schema of a table function is rendered, when it is derived from the mapped row
/// type (<see cref="SqlTableFunctionAttribute.ResultSchema"/>). The listed providers recognize the
/// corresponding native form; a provider that cannot express it rejects the source with a
/// <see cref="System.NotSupportedException"/>.
/// </summary>
public enum TableFunctionSchema
{
    /// <summary>The schema is not rendered (the default; the function supplies its own result shape).</summary>
    None = 0,
    /// <summary>
    /// A quoted structure string is emitted as the leading call argument, before the arguments declared
    /// on the placeholder method. ClickHouse <c>values('a UInt8, b String', (1,'x'), ...)</c>.
    /// </summary>
    LeadingArgument = 1,
    /// <summary>
    /// A column-definition list is emitted after the source alias, as
    /// <c>as x(col type, ...)</c>. PostgreSQL <c>jsonb_to_record(json) AS x(a int, b text)</c>.
    /// </summary>
    AliasColumnList = 2,
}

/// <summary>
/// Maps a CLR method to a database table-valued function used as a FROM source. Apply it to a
/// placeholder static method that returns <see cref="IQueryable{T}"/> and is only ever referenced
/// inside an expression passed to <see cref="DataContextExtensions.FromTableFunction{T}"/> (its body
/// is never executed, so <c>=&gt; throw new NotSupportedException()</c> or <c>=&gt; default!</c> is
/// enough). Alternatively apply it to the declaring type to map every method by name.
/// <para>
/// The call is translated to <c>[schema.]name(arg1, arg2, ...)</c>. The arguments are rendered through
/// the regular expression visitor, so captured values become parameters exactly like everywhere else.
/// The mapped function must already exist in the target database: nextorm only emits a call to it, it
/// does not create it.
/// </para>
/// </summary>
[AttributeUsage(AttributeTargets.Method | AttributeTargets.Class, AllowMultiple = false, Inherited = false)]
public sealed class SqlTableFunctionAttribute : Attribute
{
    /// <summary>
    /// Initializes a new instance of the <see cref="SqlTableFunctionAttribute"/> class. The SQL function
    /// name defaults to the CLR method name.
    /// </summary>
    public SqlTableFunctionAttribute()
    {
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="SqlTableFunctionAttribute"/> class with an explicit
    /// SQL function name.
    /// </summary>
    /// <param name="name">The SQL table function name to call; must not be <see langword="null"/>.</param>
    public SqlTableFunctionAttribute(string name)
    {
        Name = name;
    }

    /// <summary>
    /// The SQL table function name. Defaults to the CLR method name when it is not provided (or when
    /// the attribute is applied to the declaring type).
    /// </summary>
    public string? Name { get; set; }

    /// <summary>Optional schema/owner prefix, rendered as <c>schema.name</c>.</summary>
    public string? Schema { get; set; }

    /// <summary>
    /// Optional trailing <c>WITH (...)</c> clause body appended to the rendered call, for table
    /// functions that take an explicit schema definition (for example SQL Server
    /// <c>OPENJSON(json) WITH (col type '$.path', ...)</c>). The value is emitted verbatim inside the
    /// parentheses: <c>WithClause = "name nvarchar(50) '$.name'"</c> renders
    /// <c>openjson(@json) with (name nvarchar(50) '$.name')</c>. The mapped row type still supplies the
    /// CLR types used by the projection.
    /// </summary>
    public string? WithClause { get; set; }

    /// <summary>
    /// Optional verbatim SQL appended inside the call parentheses, after the arguments, for table
    /// functions whose schema is part of the call itself (for example MySQL
    /// <c>JSON_TABLE(doc, path COLUMNS(...))</c>). The value is emitted verbatim, so include your own
    /// leading separator; set <c>CallClause = ",'$[*]' columns(id int path '$.id')"</c> to render
    /// <c>json_table(@doc,'$[*]' columns(id int path '$.id'))</c>. The mapped row type still supplies
    /// the CLR types used by the projection. This is developer-authored SQL only — never build it from
    /// user input.
    /// </summary>
    public string? CallClause { get; set; }

    /// <summary>
    /// Indices of the arguments that must be emitted verbatim as SQL identifiers instead of values
    /// (for example the <c>table</c> and <c>column</c> names of SQL Server
    /// <c>CONTAINSTABLE(table, column, search)</c>). Each such argument must be a constant string and
    /// is rendered unquoted; only pass trusted values.
    /// </summary>
    public int[]? VerbatimArguments { get; set; }

    /// <summary>
    /// When not <see cref="TableFunctionSchema.None"/>, the function's result schema is derived from
    /// the mapped row type (the <c>T</c> of the placeholder method's <c>IQueryable&lt;T&gt;</c> return
    /// type) and rendered as a column-definition list. Every readable property must be mapped with
    /// <see cref="System.ComponentModel.DataAnnotations.Schema.ColumnAttribute"/> (or a fluent mapping)
    /// and its CLR type is translated to the
    /// provider's native type. The rows themselves still materialize into that same row type, exactly
    /// like any other table function. The schema is part of the query plan key, so two row shapes never
    /// share a cached plan. See <see cref="TableFunctionSchema"/>.
    /// </summary>
    public TableFunctionSchema ResultSchema { get; set; }
}

using System.Collections;
using System.Collections.Concurrent;

namespace NextORM.Core;

/// <summary>
/// Thread-safe dictionary with optional sliding expiration, used to back the process-wide
/// <see cref="DataContextCache"/> caches. While
/// <see cref="DataContextCache.CacheSlidingExpiration"/> is greater than zero, every read refreshes the
/// entry's timestamp and an entry that has not been read within the window is evicted lazily on the
/// next access or enumeration. <see cref="TimeSpan.Zero"/> (the default) disables expiration and skips
/// the timestamp path entirely.
/// </summary>
/// <typeparam name="TKey">The key type.</typeparam>
/// <typeparam name="TValue">The cached value type.</typeparam>
internal sealed class TimedDictionary<TKey, TValue> : IDictionary<TKey, TValue>
    where TKey : notnull
{
    private sealed class Entry
    {
        internal Entry(TValue value, long stamp, bool timed)
        {
            Value = value;
            Stamp = stamp;
            Timed = timed;
        }

        internal TValue Value { get; }
        internal long Stamp { get; set; }
        internal bool Timed { get; }
    }

    private readonly ConcurrentDictionary<TKey, Entry> _inner = new();

    private static long UtcNowTicks => TimeProvider.System.GetUtcNow().UtcTicks;

    private Entry MakeEntry(TValue value)
    {
        var timed = DataContextCache.CacheSlidingExpiration > TimeSpan.Zero;
        return new Entry(value, timed ? UtcNowTicks : 0, timed);
    }

    private bool TryGetLive(TKey key, out Entry entry)
    {
        if (!_inner.TryGetValue(key, out entry!))
            return false;

        if (!entry.Timed)
            return true;

        var ttl = DataContextCache.CacheSlidingExpiration;
        if (ttl <= TimeSpan.Zero)
            return true;

        var now = UtcNowTicks;
        if (now - entry.Stamp > ttl.Ticks)
        {
            _inner.TryRemove(new KeyValuePair<TKey, Entry>(key, entry));
            entry = null!;
            return false;
        }

        entry.Stamp = now;
        return true;
    }

    private List<KeyValuePair<TKey, TValue>> Snapshot()
    {
        var ttl = DataContextCache.CacheSlidingExpiration;
        var result = new List<KeyValuePair<TKey, TValue>>(_inner.Count);

        foreach (var pair in _inner)
        {
            if (ttl > TimeSpan.Zero && pair.Value.Timed && UtcNowTicks - pair.Value.Stamp > ttl.Ticks)
            {
                _inner.TryRemove(pair);
                continue;
            }

            result.Add(new KeyValuePair<TKey, TValue>(pair.Key, pair.Value.Value));
        }

        return result;
    }

    /// <summary>
    /// Test-only helper that ages every timed entry past the current sliding window without touching the
    /// wall clock, so a test can exercise the real lazy-expiration path deterministically. It only
    /// rewrites the entry timestamp; the next access performs the actual eviction. A non-positive
    /// <see cref="DataContextCache.CacheSlidingExpiration"/> leaves the store untouched.
    /// </summary>
    internal void ExpireEntriesForTesting()
    {
        var ttl = DataContextCache.CacheSlidingExpiration;
        if (ttl <= TimeSpan.Zero)
            return;

        var agedStamp = UtcNowTicks - ttl.Ticks - 1;
        foreach (var pair in _inner)
        {
            if (pair.Value.Timed)
                pair.Value.Stamp = agedStamp;
        }
    }

    /// <summary>Gets or sets the value associated with <paramref name="key"/>.</summary>
    /// <param name="key">The key to look up.</param>
    /// <returns>The live cached value.</returns>
    /// <exception cref="KeyNotFoundException">The key is absent or its entry has expired.</exception>
    public TValue this[TKey key]
    {
        get => TryGetLive(key, out var entry) ? entry.Value : throw new KeyNotFoundException($"Key '{key}' was not found.");
        set => _inner[key] = MakeEntry(value);
    }

    /// <inheritdoc/>
    public ICollection<TKey> Keys => [.. Snapshot().Select(pair => pair.Key)];
    /// <inheritdoc/>
    public ICollection<TValue> Values => [.. Snapshot().Select(pair => pair.Value)];
    /// <inheritdoc/>
    public int Count => Snapshot().Count;
    /// <inheritdoc/>
    public bool IsReadOnly => false;

    /// <inheritdoc/>
    public void Add(TKey key, TValue value)
    {
        if (!_inner.TryAdd(key, MakeEntry(value)))
            throw new ArgumentException($"An item with the same key has already been added. Key: {key}", nameof(key));
    }

    /// <inheritdoc/>
    public bool ContainsKey(TKey key) => TryGetLive(key, out _);

    /// <inheritdoc/>
    public bool Remove(TKey key) => _inner.TryRemove(key, out _);

    /// <inheritdoc/>
    public bool TryGetValue(TKey key, out TValue value)
    {
        if (TryGetLive(key, out var entry))
        {
            value = entry.Value;
            return true;
        }

        value = default!;
        return false;
    }

    /// <inheritdoc/>
    public void Add(KeyValuePair<TKey, TValue> item) => Add(item.Key, item.Value);

    /// <inheritdoc/>
    public void Clear() => _inner.Clear();

    /// <inheritdoc/>
    public bool Contains(KeyValuePair<TKey, TValue> item)
        => TryGetLive(item.Key, out var entry) && EqualityComparer<TValue>.Default.Equals(entry.Value, item.Value);

    /// <inheritdoc/>
    public void CopyTo(KeyValuePair<TKey, TValue>[] array, int arrayIndex)
        => Snapshot().CopyTo(array, arrayIndex);

    /// <inheritdoc/>
    public bool Remove(KeyValuePair<TKey, TValue> item)
        => TryGetLive(item.Key, out var entry)
            && EqualityComparer<TValue>.Default.Equals(entry.Value, item.Value)
            && _inner.TryRemove(item.Key, out _);

    /// <inheritdoc/>
    public IEnumerator<KeyValuePair<TKey, TValue>> GetEnumerator() => Snapshot().GetEnumerator();

    IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
}

using System.Reflection;
using System.Runtime.CompilerServices;

namespace NextORM.Core;

/// <summary>
/// Helpers for classifying runtime types and comparing them while building queries.
/// </summary>
public static class TypeExtensions
{
    /// <summary>
    /// Determines whether the type is a compiler-generated anonymous type (its name starts with
    /// <c>&lt;&gt;f__AnonymousType</c>).
    /// </summary>
    /// <param name="type">The type to test.</param>
    /// <returns><see langword="true"/> for an anonymous type; otherwise <see langword="false"/>.</returns>
    public static bool IsAnonymous(this Type type) => type.IsSealed
        && type.IsGenericType
        && !type.IsVisible
        && Attribute.IsDefined(type, typeof(CompilerGeneratedAttribute), false)
        && type.Name.StartsWith("<>f__AnonymousType", StringComparison.Ordinal);
    /// <summary>
    /// Determines whether the type is a compiler-generated closure (display class) created to hold
    /// variables captured by a lambda.
    /// </summary>
    /// <param name="type">The type to test.</param>
    /// <returns><see langword="true"/> for a closure type; otherwise <see langword="false"/>.</returns>
    public static bool IsClosure(this Type type) => type.IsSealed
        && !type.IsVisible
        && Attribute.IsDefined(type, typeof(CompilerGeneratedAttribute), false)
        && type.Name.StartsWith("<>c__DisplayClass", StringComparison.Ordinal);
    /// <summary>
    /// Determines whether the type is a tuple type, identified by a generic <c>System.Tuple</c> or
    /// <c>System.ValueTuple</c> name.
    /// </summary>
    /// <param name="type">The type to test.</param>
    /// <returns><see langword="true"/> for a tuple type; otherwise <see langword="false"/>.</returns>
    public static bool IsTuple(this Type type) => type.IsGenericType
        && type.Namespace == "System"
        && (type.Name.StartsWith("Tuple`", StringComparison.Ordinal)
            || type.Name.StartsWith("ValueTuple`", StringComparison.Ordinal));

    /// <summary>
    /// Tries to get the number of columns a projection type materializes. A projection is a generic
    /// type implementing <see cref="IProjection"/>; its dimension is its number of generic arguments.
    /// </summary>
    /// <param name="type">The type to inspect.</param>
    /// <param name="dim">When this method returns <see langword="true"/>, the projection's generic arity; otherwise <c>0</c>.</param>
    /// <returns><see langword="true"/> when <paramref name="type"/> is a projection; otherwise <see langword="false"/>.</returns>
    public static bool TryGetProjectionDimension(this Type type, out int dim)
    {
        //const string m = "NextORM.Core.Projection`";
        dim = 0;
        if (type.IsGenericType && type.IsAssignableTo(typeof(IProjection)))
        {
            dim = type.GetGenericArguments().Length;
            return true;
        }
        return false;
    }
    /// <summary>
    /// Determines whether a projection exposes generated lexical alias members (marked with
    /// <see cref="JoinSlotAttribute"/>, for example <c>Buyer</c>/<c>Approver</c>) rather than only the
    /// engine <c>Item1</c>..<c>Item8</c> slots. Such a projection is produced by the source generator
    /// and supported on SQL providers only.
    /// </summary>
    /// <param name="type">The projection type to inspect.</param>
    /// <returns><see langword="true"/> when at least one public property carries a join slot; otherwise <see langword="false"/>.</returns>
    internal static bool HasJoinSlotMembers(this Type type)
    {
        foreach (var property in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
        {
            if (Attribute.IsDefined(property, typeof(JoinSlotAttribute), false))
                return true;
        }

        return false;
    }

    /// <summary>
    /// Determines whether the two types are assignment-compatible in either direction. Equal types and
    /// types assignable to one another match; a nullable type is also compared through its underlying
    /// type.
    /// </summary>
    /// <param name="x">The first type.</param>
    /// <param name="y">The second type.</param>
    /// <returns><see langword="true"/> when the types are considered similar; otherwise <see langword="false"/>.</returns>
    public static bool Similar(this Type x, Type y)
    {
        if (y is null) return false;

        if (x == y
        || x.IsAssignableFrom(y)
        || x.IsAssignableTo(y))
            return true;

        if (x.IsGenericType && x.GetGenericTypeDefinition() == typeof(Nullable<>) && x.GenericTypeArguments[0].Similar(y))
            return true;

        if (y.IsGenericType && y.GetGenericTypeDefinition() == typeof(Nullable<>) && y.GenericTypeArguments[0].Similar(x))
            return true;

        return false;
    }
    /// <summary>
    /// Determines whether the type maps to a single scalar SQL value, i.e. it has a type code other
    /// than <see cref="System.TypeCode.Object"/>.
    /// </summary>
    /// <param name="type">The type to test.</param>
    /// <returns><see langword="true"/> when the type is scalar; otherwise <see langword="false"/>.</returns>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static bool IsScalar(this Type type)
    {
        return Type.GetTypeCode(type) switch
        {
            TypeCode.Object => false,
            _ => true
        };
    }
}

