using System.Data.Common;
using FluentAssertions;
using NextORM.ClickHouse;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Stage A (iteration 15, task #183) characterization of the fresh-fluent cached path that the Stage B
/// equality-scope (B1) and guarded parameter-refresh (B2) changes must preserve: closure-site identity,
/// repeated-capture naming/dedup, null/converter parameters, IN/lookup shape changes, Any/Count shared
/// command interleaving, and the unsupported-shape fallback. These tests build/prepare SQL through the
/// placeholder context (they never open a connection) unless execution is explicitly required.
/// </summary>
/// <remarks>
/// Pinned to the same collection as <c>DataContextCacheClearTests</c>, which clears the process-wide
/// <see cref="DataContextCache"/>: the identity-based "same instance on cache hit" assertions here must
/// never observe a concurrent clear. The assembly already sets <c>ParallelMode.None</c>; this makes the
/// serialization explicit/local as well (W4, checkpoint 1/3).
/// </remarks>
[Collection("DataContextCache clear")]
public class CachedPathCharacterizationTests
{
    private static DbPreparedQueryCommand<T> Prepare<T>(IDataContext ctx, QueryCommand<T> cmd, bool cache = false)
        => (DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, cache, CancellationToken.None);

    // ---------------------------------------------------------------------------------------------
    // Row 1: two closures of the same shape with different captured values.
    // ---------------------------------------------------------------------------------------------

    private static QueryCommand<long> WhereWithCaptured(EntityBuilder<IComplexEntity> e, int captured)
        => e.Where(x => x.Id > captured).Select(x => x.Id);

    // Two textual call sites: each compiles into its own display-class type, which participates in the
    // plan key via ExpressionPlanEqualityComparer.CompareMember (the captured value does not).
    private static QueryCommand<long> WhereAtSiteA(EntityBuilder<IComplexEntity> e)
    {
        var captured = 1;
        return e.Where(x => x.Id > captured).Select(x => x.Id);
    }

    private static QueryCommand<long> WhereAtSiteB(EntityBuilder<IComplexEntity> e)
    {
        var captured = 2;
        return e.Where(x => x.Id > captured).Select(x => x.Id);
    }

    [Fact]
    public void SameClosureSite_DifferentValues_ShouldReusePlanAndRefreshParam()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();

        var first = Prepare(ctx, WhereWithCaptured(e, 1), cache: true);
        first.DbCommandParams[0].Value.Should().Be(1);
        first.NeedsParamRefresh.Should().BeTrue("a captured local is not fixed by the expression shape");

        var second = Prepare(ctx, WhereWithCaptured(e, 2), cache: true);

        ReferenceEquals(first, second).Should().BeTrue("the captured value is not part of the plan key");
        second.DbCommandParams[0].Value.Should().Be(2, "the shared cached command re-binds the second closure's value");
    }

    [Fact]
    public void DistinctClosureSites_SameShape_ShouldNotShareThePlanKey()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();

        var first = Prepare(ctx, WhereAtSiteA(e), cache: true);
        var second = Prepare(ctx, WhereAtSiteB(e), cache: true);

        ReferenceEquals(first, second).Should()
            .BeFalse("each closure site owns a distinct display-class type, which is part of the key");
        first.DbCommandParams[0].Value.Should().Be(1);
        second.DbCommandParams[0].Value.Should().Be(2);
    }

    // ---------------------------------------------------------------------------------------------
    // Row 2: repeated captures in WHERE / JOIN / projection.
    // ---------------------------------------------------------------------------------------------

    [Fact]
    public void RepeatedCapture_AcrossJoinWhereProjection_ShouldBindOnce()
    {
        using var ctx = SqliteTestContext.Create();
        var v = 5;

        var prepared = Prepare(ctx, ctx.From<IComplexEntity>()
            .Join(ctx.From<ISimpleEntity>(), (c, s) => c.Id == s.Id && s.Id > v)
            .Where(p => p.Item1.Int == v)
            .Select(p => new { p.Item1.Id, Captured = v }));

        var parameters = prepared.DbCommandParams.Cast<DbParameter>().ToArray();
        parameters.Should().ContainSingle("one captured local is one parameter no matter how often it repeats");
        parameters[0].ParameterName.Should().Be("v");
        parameters[0].Value.Should().Be(5);
        prepared.DbCommand.CommandText.Should().Contain("$v");
    }

    // ---------------------------------------------------------------------------------------------
    // Row 3: null and converter parameter cases.
    // ---------------------------------------------------------------------------------------------

    [Fact]
    public void NullCaptured_ShouldBindANullValuedParameter()
    {
        using var ctx = SqliteTestContext.Create();
        string? captured = null;

        var prepared = Prepare(ctx, ctx.From<IComplexEntity>().Where(x => x.String == captured).Select(x => x.Id));

        var parameter = prepared.DbCommandParams.Cast<DbParameter>().Should().ContainSingle().Subject;
        (parameter.Value is null || parameter.Value is DBNull).Should()
            .BeTrue("a null capture is bound as a (normalized) null parameter, never inlined");
    }

    [Fact]
    public void ConvertedCapturedEnum_ShouldBindTheProviderValue()
    {
        using var ctx = SqliteTestContext.Create();
        var captured = SqlGenState.Closed;

        var prepared = Prepare(ctx, ctx.From<IConverterEntity>().Where(x => x.State == captured).Select(x => x.Id));

        var parameter = prepared.DbCommandParams.Cast<DbParameter>().Should().ContainSingle().Subject;
        parameter.Value.Should().Be("Closed", "the value converter maps the enum to its provider representation");
    }

    // ---------------------------------------------------------------------------------------------
    // Row 4: IN / lookup form and value change, plus filters / settings.
    // ---------------------------------------------------------------------------------------------

    [Fact]
    public void InCollection_LengthChange_ShouldNotReuseTheStalePlan()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();

        var values = new long[] { 1 };
        var first = Prepare(ctx, e.Where(x => SqlFunctions.Sql.@in(x.Id, values)).Select(x => x.Id), cache: true);
        first.DbCommandParams.Cast<DbParameter>().Select(p => p.ParameterName).Should().Equal("p0");

        values = new long[] { 1, 2 };
        var second = Prepare(ctx, e.Where(x => SqlFunctions.Sql.@in(x.Id, values)).Select(x => x.Id), cache: true);

        ReferenceEquals(first, second).Should()
            .BeFalse("a changed IN cardinality is a different shape and must not reuse the cached plan");
        second.DbCommandParams.Cast<DbParameter>().Select(p => p.ParameterName).Should().Equal("p0", "p1");
    }

    // Same cardinality but a changed value is the same shape: it must hit the cached plan and re-bind the
    // fresh value (the value-list parameter is a runtime pN placeholder, so the recipe declines and the
    // original extraction path refreshes it).
    [Fact]
    public void InCollection_SameLengthValueChange_ShouldReusePlanAndRebind()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();

        var values = new long[] { 1 };
        var first = Prepare(ctx, e.Where(x => SqlFunctions.Sql.@in(x.Id, values)).Select(x => x.Id), cache: true);
        first.DbCommandParams[0].Value.Should().Be(1L);

        ExpressionPlanEqualityComparer.ResetCounters();
        values[0] = 2;
        var second = Prepare(ctx, e.Where(x => SqlFunctions.Sql.@in(x.Id, values)).Select(x => x.Id), cache: true);

        ReferenceEquals(first, second).Should().BeTrue("an unchanged IN cardinality is the same shape");
        second.DbCommandParams[0].Value.Should().Be(2L, "the shared cached command re-binds the current value");
        ParamRefreshRecipe.FastBindHits.Should().Be(0, "a runtime pN placeholder is outside the recipe subset");
        QueryPlanner.FallbackRefreshes.Should().Be(1, "the value-list parameter refreshes through the extraction path");
    }

    // An empty IN is a constant `1 = 0` with no parameters: a rebuilt empty IN must reuse the same
    // parameter-free plan without inventing a recipe or a fallback refresh.
    [Fact]
    public void InCollection_Empty_ShouldReuseParameterFreePlan()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();
        var values = Array.Empty<long>();

        var first = Prepare(ctx, e.Where(x => SqlFunctions.Sql.@in(x.Id, values)).Select(x => x.Id), cache: true);
        first.DbCommandParams.Cast<DbParameter>().Should().BeEmpty("an empty IN renders a constant and binds no parameter");
        first.DbCommand.CommandText.Should().Contain("1 = 0");

        ExpressionPlanEqualityComparer.ResetCounters();
        var second = Prepare(ctx, e.Where(x => SqlFunctions.Sql.@in(x.Id, values)).Select(x => x.Id), cache: true);

        ReferenceEquals(first, second).Should().BeTrue("an empty IN is a stable, parameter-free shape");
        second.DbCommandParams.Cast<DbParameter>().Should().BeEmpty();
        ParamRefreshRecipe.FastBindHits.Should().Be(0);
        QueryPlanner.FallbackRefreshes.Should().Be(0, "a parameter-free plan never enters the refresh path");
    }

    [Fact]
    public void SettingsAndPreWhere_ShouldDistinguishThePlanKey()
    {
        using var ctx = SqliteTestContext.Create();

        // Settings/PREWHERE are not renderable on SQLite, but they are still part of the structural plan
        // identity; prepare-without-render and compare the keys, exactly like PlanKeyUniquenessTests does.
        var plain = ctx.From<IComplexEntity>().Where(x => x.Id > 0).Select(x => x.Id);
        var withSetting = ctx.From<IComplexEntity>().Where(x => x.Id > 0).Settings(("max_threads", "2")).Select(x => x.Id);
        var withPreWhere = ctx.From<IComplexEntity>().Where(x => x.Id > 0).PreWhere(x => x.Id > 5).Select(x => x.Id);

        plain.PrepareCommand(false, TestContext.Current.CancellationToken);
        withSetting.PrepareCommand(false, TestContext.Current.CancellationToken);
        withPreWhere.PrepareCommand(false, TestContext.Current.CancellationToken);

        var comparer = plain.GetQueryPlanEqualityComparer();
        comparer.Equals(plain, withSetting).Should().BeFalse("a setting is part of the plan identity");
        comparer.Equals(plain, withPreWhere).Should().BeFalse("a PREWHERE is part of the plan identity");
    }

    // ---------------------------------------------------------------------------------------------
    // Row 5: Any / Count interleaved with a CTE and a DML source (no sticky cache state).
    // ---------------------------------------------------------------------------------------------

    [Fact]
    public void AnyCountInterleavedWithCteAndDmlSource_ShouldKeepTheSharedCommandCacheable()
    {
        using var ctx = SqliteTestContext.CreateSqlite();
        ctx.PurgeQueryCache();

        // Materialise the context-shared Any command without executing it (the placeholder boundary has
        // no reader). This is the command AGENTS.md warns must never get the sticky Cache=false flag.
        var shared = EntityBuilderExtensions.GetAnyCommand(ctx, ctx.From<IComplexEntity>().ToCommand());
        ctx.AnyCommand!.Value.Should().BeSameAs(shared);
        shared.Cache.Should().BeTrue();

        var cte = ctx.With("c", ctx.From<IComplexEntity>().Where(x => x.Id > 0).Select(x => new { x.Id }))
            .From("c").Select(t => t["id"].AsInt);
        var cteFirst = Prepare(ctx, cte, cache: true);
        var cteSecond = Prepare(ctx, cte, cache: true);
        ReferenceEquals(cteFirst, cteSecond).Should().BeTrue("a rebuilt read CTE must hit the cached plan");

        // Prepare a DML source in between: it must not poison the process/context plan state.
        var delete = ctx.CreateDeleteBuilder<ConverterEntity>().Where(x => x.Id > 0).BuildKeyCommand(new ConverterEntity { Id = 1 });
        delete.Condition!.PrepareCommand(false, TestContext.Current.CancellationToken);
        delete.Condition.Cache.Should().BeTrue("preparing a DML source must not disable its plan cache");

        ctx.AnyCommand!.Value.Should().BeSameAs(shared);
        shared.Cache.Should().BeTrue("the DML interleave must not disable the shared Any command's plan cache");
        ReferenceEquals(Prepare(ctx, cte, cache: true), cteFirst).Should().BeTrue("the read CTE plan survives the DML interleave");
    }

    // ---------------------------------------------------------------------------------------------
    // Row 8: fallback error path and evaluation-once on the refresh path.
    // ---------------------------------------------------------------------------------------------

    [Fact]
    public void UnsupportedLookupOutsideWhere_ShouldThrowAndNotPoisonThePlanCache()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();

        var lookup = new Dictionary<int, DateTime> { [1] = new(2024, 1, 1) };
        var act = () => ctx.GetPreparedQueryCommand(
            ctx.From<IComplexEntity>().Select(x => new { Value = lookup[x.Int!.Value] }), false, true, CancellationToken.None);

        act.Should().Throw<NotSupportedException>().WithMessage("*WHERE*");

        // The failed cacheable preparation must not leave a poisoned entry behind.
        var ok = Prepare(ctx, ctx.From<IComplexEntity>().Select(x => x.Id), cache: true);
        ReferenceEquals(Prepare(ctx, ctx.From<IComplexEntity>().Select(x => x.Id), cache: true), ok).Should().BeTrue();
    }

    private sealed class CountingProbe
    {
        public int Reads;
        public int Value = 5;

        public int Threshold
        {
            get
            {
                Reads++;
                return Value;
            }
        }

        public int Other
        {
            get
            {
                Reads++;
                return Value;
            }
        }
    }

    [Fact]
    public void CapturedProperty_OnCacheHit_ShouldBeEvaluatedExactlyOnce()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();
        var probe = new CountingProbe();

        var first = Prepare(ctx, e.Where(x => x.Id > probe.Threshold).Select(x => x.Id), cache: true);

        probe.Reads = 0; // isolate the cache-hit refresh
        var second = Prepare(ctx, e.Where(x => x.Id > probe.Threshold).Select(x => x.Id), cache: true);

        ReferenceEquals(first, second).Should().BeTrue();
        second.NeedsParamRefresh.Should().BeTrue();
        probe.Reads.Should().Be(1, "a captured parameter refresh must evaluate the captured member exactly once");
    }

    // Same source site, two different probe instances: the closure type and the member chain are part of
    // the plan key while the captured value is not, so the second Prepare is a cache hit with a fresh
    // closure.
    private static QueryCommand<long> WhereProbe(EntityBuilder<IComplexEntity> e, CountingProbe probe)
        => e.Where(x => x.Id > probe.Threshold).Select(x => x.Id);

    [Fact]
    public void SameClosureSite_RepeatedExecution_ShouldNotReuseFirstClosure()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();
        var a = new CountingProbe { Value = 1 };
        var b = new CountingProbe { Value = 2 };

        var first = Prepare(ctx, WhereProbe(e, a), cache: true);
        first.DbCommandParams[0].Value.Should().Be(1);
        first.NeedsParamRefresh.Should().BeTrue();
        first.ParamRecipe.Should().NotBeNull("a simple captured scalar is in the supported recipe subset");

        a.Reads = 0;
        b.Reads = 0;
        var second = Prepare(ctx, WhereProbe(e, b), cache: true);

        ReferenceEquals(first, second).Should().BeTrue("the captured value is not part of the plan key");
        b.Reads.Should().Be(1, "the current closure is evaluated exactly once on the refresh");
        a.Reads.Should().Be(0, "the reusable recipe must not reuse the first closure");
        second.DbCommandParams[0].Value.Should().Be(2, "the shared cached command re-binds the second closure's value");
    }

    // A real cache hit with a supported recipe takes the positional fast path: it reads the CURRENT
    // closure, binds exactly once and never touches the original extraction path.
    [Fact]
    public void CachedHit_FastPath_ShouldBindCurrentValueAndCountOnce()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();
        var probe = new CountingProbe { Value = 1 };

        var first = Prepare(ctx, WhereProbe(e, probe), cache: true);
        first.ParamRecipe.Should().NotBeNull("a simple captured scalar is in the supported recipe subset");
        first.DbCommandParams[0].Value.Should().Be(1);

        probe.Reads = 0;
        probe.Value = 2;
        ExpressionPlanEqualityComparer.ResetCounters();
        var second = Prepare(ctx, WhereProbe(e, probe), cache: true);

        ReferenceEquals(first, second).Should().BeTrue("the captured value is not part of the plan key");
        ParamRefreshRecipe.FastBindHits.Should().Be(1);
        ParamRefreshRecipe.BindRejected.Should().Be(0);
        QueryPlanner.FallbackRefreshes.Should().Be(0);
        second.DbCommandParams[0].Value.Should().Be(2, "the fast path binds the CURRENT closure value");
        probe.Reads.Should().Be(1, "the fast path reads the captured member exactly once");
    }

    // A null capture is still a reproducible scalar: the fast path rebinds the value once the closure
    // changes from null to a non-null string.
    [Fact]
    public void CachedHit_NullCaptureFastPath_ShouldBindCurrentValue()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();

        string? captured = null;
        var first = Prepare(ctx, e.Where(x => x.String == captured).Select(x => x.Id), cache: true);
        first.ParamRecipe.Should().NotBeNull("a null captured scalar still has a reproducible recipe");

        ExpressionPlanEqualityComparer.ResetCounters();
        captured = "x";
        var second = Prepare(ctx, e.Where(x => x.String == captured).Select(x => x.Id), cache: true);

        ReferenceEquals(first, second).Should().BeTrue();
        ParamRefreshRecipe.FastBindHits.Should().Be(1);
        QueryPlanner.FallbackRefreshes.Should().Be(0);
        second.DbCommandParams[0].Value.Should().Be("x", "the null-to-value change is rebound by the fast path");
    }

    // The inverse transition exercises the writer's coalesce branch: a value capture that becomes null on
    // the hit must bind DBNull through the fast path, never the stale miss-time string.
    [Fact]
    public void CachedHit_ValueToNullFastPath_ShouldBindDbNull()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();

        string? captured = "first";
        var first = Prepare(ctx, e.Where(x => x.String == captured).Select(x => x.Id), cache: true);
        first.ParamRecipe.Should().NotBeNull("a captured string scalar is a supported recipe");

        ExpressionPlanEqualityComparer.ResetCounters();
        captured = null;
        var second = Prepare(ctx, e.Where(x => x.String == captured).Select(x => x.Id), cache: true);

        ReferenceEquals(first, second).Should().BeTrue("the captured value is not part of the plan key");
        ParamRefreshRecipe.FastBindHits.Should().Be(1);
        ParamRefreshRecipe.BindRejected.Should().Be(0);
        QueryPlanner.FallbackRefreshes.Should().Be(0);
        second.DbCommandParams[0].Value.Should()
            .Be(DBNull.Value, "the writer's null-coalesce branch normalizes a null capture to DBNull");
    }

    // Converter and raw-SQL shapes are not in the scalar subset, so the plan carries no recipe and no
    // hit takes the fast path. The converter shape still refreshes through the original extraction
    // path (a counted fallback); a raw-SQL override instead reuses its miss-time bound parameters and
    // never enters the generated extraction path, so it is not a fallback refresh.
    [Fact]
    public void CachedHit_UnsupportedShapes_ShouldFallBackWithoutFastPath()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();

        var converter = ctx.From<IConverterEntity>();
        var captured = SqlGenState.Closed;
        var converterFirst = Prepare(ctx, converter.Where(x => x.State == captured).Select(x => x.Id), cache: true);
        converterFirst.ParamRecipe.Should().BeNull("a converter-normalized value is not in the scalar subset");
        ExpressionPlanEqualityComparer.ResetCounters();
        var converterSecond = Prepare(ctx, converter.Where(x => x.State == captured).Select(x => x.Id), cache: true);
        ReferenceEquals(converterFirst, converterSecond).Should().BeTrue();
        ParamRefreshRecipe.FastBindHits.Should().Be(0);
        QueryPlanner.FallbackRefreshes.Should().Be(1);
        converterSecond.DbCommandParams[0].Value.Should().Be("Closed");

        var e = ctx.From<IComplexEntity>();
        const string sql = "select id from complex_entity where id = @id";
        var rawFirst = Prepare(ctx, RawSqlCommand(e, sql, new { id = 1 }), cache: true);
        rawFirst.ParamRecipe.Should().BeNull("a raw-SQL override has no generated captured condition");
        ExpressionPlanEqualityComparer.ResetCounters();
        var rawSecond = Prepare(ctx, RawSqlCommand(e, sql, new { id = 2 }), cache: true);
        ReferenceEquals(rawFirst, rawSecond).Should().BeTrue();
        ParamRefreshRecipe.FastBindHits.Should().Be(0);
        QueryPlanner.FallbackRefreshes.Should().Be(0, "a raw-SQL override bypasses the generated extraction path entirely");
    }

    // The immutable recipe validates parameter count/name/shape before evaluating any closure; an
    // incompatible recipe must fall back to the original ExtractParams path without corrupting the bind.
    [Fact]
    public void CachedPlan_WithIncompatibleRecipe_ShouldFallBackWithoutCorruptingTheBind()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();
        var a = new CountingProbe { Value = 1 };
        var b = new CountingProbe { Value = 2 };

        var target = Prepare(ctx, WhereProbe(e, a), cache: true);
        target.ParamRecipe.Should().NotBeNull();

        // A recipe whose slot count does not match the cached command's parameter count.
        var countMismatch = Prepare(ctx, e.Where(x => x.Id > a.Threshold || x.Id > b.Other).Select(x => x.Id), cache: true);
        countMismatch.ParamRecipe.Should().NotBeNull();
        target.SetParamRecipe(countMismatch.ParamRecipe);

        a.Reads = 0;
        b.Reads = 0;
        ExpressionPlanEqualityComparer.ResetCounters();
        var countHit = Prepare(ctx, WhereProbe(e, b), cache: true);

        ReferenceEquals(target, countHit).Should().BeTrue("the second WhereProbe hits the cached plan");
        QueryPlanner.FallbackRefreshes.Should().Be(1);
        ParamRefreshRecipe.FastBindHits.Should().Be(0);
        ParamRefreshRecipe.BindRejected.Should().Be(1);
        countHit.DbCommandParams[0].Value.Should().Be(2, "the fallback extracts the current closure value");
        b.Reads.Should().Be(1, "the original extraction path evaluates the current closure exactly once");
        a.Reads.Should().Be(0, "the incompatible recipe never evaluates the stale closure");

        // A same-count recipe whose parameter name differs must also be rejected.
        var nameMismatch = Prepare(ctx, e.Where(x => x.Id > a.Other).Select(x => x.Id), cache: true);
        nameMismatch.ParamRecipe.Should().NotBeNull();
        target.SetParamRecipe(nameMismatch.ParamRecipe);

        a.Reads = 0;
        b.Reads = 0;
        ExpressionPlanEqualityComparer.ResetCounters();
        var nameHit = Prepare(ctx, WhereProbe(e, b), cache: true);

        ReferenceEquals(target, nameHit).Should().BeTrue();
        QueryPlanner.FallbackRefreshes.Should().Be(1);
        ParamRefreshRecipe.FastBindHits.Should().Be(0);
        ParamRefreshRecipe.BindRejected.Should().Be(1);
        nameHit.DbCommandParams[0].Value.Should().Be(2);
        b.Reads.Should().Be(1);
        a.Reads.Should().Be(0);
    }

    // ---------------------------------------------------------------------------------------------
    // Row: converter / raw SQL. The converter half is covered by
    // ConvertedCapturedEnum_ShouldBindTheProviderValue above; this is the raw-SQL fallback baseline.
    // A raw-SQL override (WithSql / PrepareFromSql) bypasses the generated-SQL and ExtractParams path
    // (SqlStmt is null on the prepared command), and its plan identity is the injected SQL text:
    // the generated expression shape and the parameter values are not part of the key. This is the
    // documented fallback the B2 guarded refresh must keep (raw SQL is not a supported fastpath shape).
    // ---------------------------------------------------------------------------------------------

    private static QueryCommand<long> RawSqlCommand(EntityBuilder<IComplexEntity> e, string sql, object? @params)
        => e.Select(x => x.Id).WithSql(sql, @params);

    [Fact]
    public void RawSqlOverride_FormAndValueChange_ShouldKeyThePlanBySqlTextOnly()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();
        const string sql = "select id from complex_entity where id = @id";

        var first = Prepare(ctx, RawSqlCommand(e, sql, new { id = 1 }), cache: true);
        first.SqlStmt.Should().BeNull("a raw-SQL override bypasses the generated-SQL and ExtractParams path");

        // Same SQL text, different parameter value: the value is not part of the raw-SQL plan key.
        var sameText = Prepare(ctx, RawSqlCommand(e, sql, new { id = 2 }), cache: true);
        ReferenceEquals(first, sameText).Should()
            .BeTrue("the raw SQL text, not the parameter value, is the raw-SQL plan identity");

        // Different SQL text: a different raw-SQL shape must not reuse the cached plan.
        var otherText = Prepare(ctx, RawSqlCommand(e, "select id from complex_entity where id = @id and id > 0", new { id = 1 }), cache: true);
        ReferenceEquals(first, otherText).Should()
            .BeFalse("a changed raw SQL text must not reuse the cached plan");
    }
}

using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// SQL generation for a collation declared on a mapped column (<see cref="CollationAttribute"/>).
/// No database is touched.
/// </summary>
public class ColumnCollationSqlGenerationTests
{
    [SqlTable("collated_entity")]
    internal interface ICollatedEntity
    {
        [Key]
        [Column("id")]
        long Id { get; set; }
        [Column("name")]
        [Collation("binary")]
        string? Name { get; set; }
    }

    private static string Normalize(string sql) => sql.Replace("\r\n", "\n");

    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd)
        => Normalize(((DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None)).DbCommand.CommandText);

    [Fact]
    public void CollatedColumn_InWhere_ShouldRenderCollate()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<ICollatedEntity>();

        SqlOf(ctx, e.Where(x => x.Name == "a").Select(x => new { x.Id }))
            .Should().Contain("name collate binary = 'a'");
    }

    [Fact]
    public void CollatedColumn_InOrderBy_ShouldRenderCollate()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<ICollatedEntity>();

        SqlOf(ctx, e.OrderBy(x => x.Name).Select(x => new { x.Id }))
            .Should().Contain("order by name collate binary");
    }
}

using System.Data.Common;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;
using NextORM.Sqlite;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Coverage for the per-context (<c>UseCommandTimeout</c>) and per-query (<c>WithCommandTimeout</c>)
/// command timeout. A prepared command is created without opening the connection, so the value baked
/// into its <c>DbCommand.CommandTimeout</c> can be asserted directly; the mutation path runs against a
/// temp file database observed through an interceptor.
/// </summary>
public class CommandTimeoutTests
{
    private static IDataContext Create(int? seconds = null)
    {
        var builder = new DataContextBuilder();
        if (seconds is int value)
            builder = builder.UseCommandTimeout(value);

        var ctx = new SqliteDataContext("Data Source=:memory:", builder);
        ctx.PurgeQueryCache();
        return ctx;
    }

    private static DbCommand Prepare(IDataContext ctx, QueryCommand<int> command)
    {
        var prepared = ctx.GetPreparedQueryCommand(command, false, true, TestContext.Current.CancellationToken);
        return ((DbPreparedQueryCommand<int>)prepared).DbCommand;
    }

    private static int ProviderDefault()
    {
        using var connection = new SqliteConnection("Data Source=:memory:");
        using var command = connection.CreateCommand();
        return command.CommandTimeout;
    }

    [Fact]
    public void ContextTimeout_ShouldApplyToPreparedCommand()
    {
        using var ctx = Create(17);

        Prepare(ctx, ctx.From<ISimpleEntity>().Select(x => x.Id)).CommandTimeout.Should().Be(17);
    }

    [Fact]
    public void NoTimeout_ShouldKeepProviderDefault()
    {
        using var ctx = Create();

        Prepare(ctx, ctx.From<ISimpleEntity>().Select(x => x.Id)).CommandTimeout.Should().Be(ProviderDefault());
    }

    [Fact]
    public void PerQueryTimeout_ShouldOverrideContext()
    {
        using var ctx = Create(17);

        var command = ctx.From<ISimpleEntity>().WithCommandTimeout(5).Select(x => x.Id);
        Prepare(ctx, command).CommandTimeout.Should().Be(5);
    }

    [Fact]
    public void NonGenericBuilder_WithCommandTimeout_ShouldApply()
    {
        using var ctx = Create(17);

        var command = ctx.From("simple_entity").WithCommandTimeout(8).Select(x => x["id"].AsInt);
        Prepare(ctx, command).CommandTimeout.Should().Be(8);
    }

    [Fact]
    public void QueryCommand_WithCommandTimeout_ShouldApply()
    {
        using var ctx = Create(17);

        var command = ctx.From<ISimpleEntity>().Select(x => x.Id).WithCommandTimeout(9);
        Prepare(ctx, command).CommandTimeout.Should().Be(9);
    }

    [Fact]
    public void DifferentPerQueryTimeouts_ShouldNotShareCachedPlanAndShouldNotLeak()
    {
        using var ctx = Create(17);

        var shortCommand = Prepare(ctx, ctx.From<ISimpleEntity>().WithCommandTimeout(11).Select(x => x.Id));
        shortCommand.CommandTimeout.Should().Be(11);

        var longCommand = Prepare(ctx, ctx.From<ISimpleEntity>().WithCommandTimeout(22).Select(x => x.Id));
        longCommand.CommandTimeout.Should().Be(22);
        ReferenceEquals(shortCommand, longCommand).Should().BeFalse("a different timeout must not reuse the cached command");

        var shortAgain = Prepare(ctx, ctx.From<ISimpleEntity>().WithCommandTimeout(11).Select(x => x.Id));
        ReferenceEquals(shortCommand, shortAgain).Should().BeTrue("an equal timeout must reuse the cached plan");
        shortAgain.CommandTimeout.Should().Be(11);
    }

    [Fact]
    public void PerQueryTimeout_ShouldNotLeakToALaterPlainQuery()
    {
        using var ctx = Create(17);

        Prepare(ctx, ctx.From<ISimpleEntity>().WithCommandTimeout(5).Select(x => x.Id)).CommandTimeout.Should().Be(5);

        Prepare(ctx, ctx.From<ISimpleEntity>().Select(x => x.Id)).CommandTimeout.Should().Be(17);
    }

    [Fact]
    public void ContextsWithDifferentTimeouts_ShouldNotShareCachedPlan()
    {
        using var first = Create(17);
        using var second = Create(40);

        Prepare(first, first.From<ISimpleEntity>().Select(x => x.Id)).CommandTimeout.Should().Be(17);
        Prepare(second, second.From<ISimpleEntity>().Select(x => x.Id)).CommandTimeout.Should().Be(40);
    }

    [Fact]
    public void ZeroTimeout_WithoutContextTimeout_ShouldKeepProviderDefault()
    {
        using var ctx = Create();

        var command = ctx.From<ISimpleEntity>().WithCommandTimeout(0).Select(x => x.Id);
        Prepare(ctx, command).CommandTimeout.Should().Be(ProviderDefault());
    }

    [Fact]
    public void ContextTimeout_ShouldApplyToMutationCommand()
    {
        var interceptor = new CapturingInterceptor();
        var path = Path.Combine(Path.GetTempPath(), $"nextorm-timeout-{Guid.NewGuid():N}.db");
        using (var connection = new SqliteConnection($"Data Source={path}"))
        {
            connection.Open();
            using var setup = connection.CreateCommand();
            setup.CommandText = "create table simple_entity (id integer primary key);";
            setup.ExecuteNonQuery();
        }

        try
        {
            using var ctx = new SqliteDataContext(
                $"Data Source={path}",
                new DataContextBuilder().UseCommandTimeout(13).AddInterceptor(interceptor));

            ctx.CreateDeleteBuilder<ISimpleEntity>().All().Delete();

            interceptor.LastCommand.Should().NotBeNull();
            interceptor.LastCommand!.CommandTimeout.Should().Be(13);
        }
        finally
        {
            File.Delete(path);
        }
    }

    private sealed class CapturingInterceptor : IQueryInterceptor
    {
        public DbCommand? LastCommand { get; private set; }

        public void CommandInitialized(CommandEventData eventData, DbCommand command) => LastCommand = command;

        public void CommandExecuting(CommandEventData eventData, DbCommand command) => LastCommand = command;

        public void CommandExecuted(CommandEventData eventData, DbCommand command, TimeSpan elapsed)
        {
        }

        public void CommandFailed(CommandEventData eventData, DbCommand command, Exception exception)
        {
        }
    }
}

using System.Data;
using System.Data.Common;
using System.Runtime.CompilerServices;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Pins the connection contract of <see cref="DataContext"/>: who owns the connection, what
/// <see cref="DataContext.ConnectionString"/> resolves to, and that provider setup runs on every
/// connection the context starts using. The supplied-connection path is not covered by the
/// behavioural suite, so it is verified here.
/// </summary>
public class ConnectionManagementTests
{
    private static SqliteDataContext WithConnectionString(string connectionString = "Data Source=:memory:")
        => new(connectionString, new DataContextBuilder());

    private static SqliteDataContext WithConnection(DbConnection connection)
        => new(connection, new DataContextBuilder());

    [Fact]
    public void GetConnection_WithConnectionString_CreatesProviderConnection()
    {
        using var ctx = WithConnectionString();

        ctx.GetConnection().Should().BeOfType<SqliteConnection>();
    }

    [Fact]
    public void GetConnection_IsStableAcrossCalls()
    {
        using var ctx = WithConnectionString();

        ctx.GetConnection().Should().BeSameAs(ctx.GetConnection());
    }

    [Fact]
    public void GetConnection_WithSuppliedConnection_ReturnsThatInstance()
    {
        using var supplied = new SqliteConnection("Data Source=:memory:");
        using var ctx = WithConnection(supplied);

        ctx.GetConnection().Should().BeSameAs(supplied);
    }

    [Fact]
    public void Dispose_WithSuppliedConnection_LeavesItOpen()
    {
        using var supplied = new SqliteConnection("Data Source=:memory:");
        supplied.Open();

        using (var ctx = WithConnection(supplied))
        {
            ctx.EnsureConnectionOpen();
        }

        supplied.State.Should().Be(ConnectionState.Open);
    }

    [Fact]
    public void Dispose_WithOwnConnection_DisposesIt()
    {
        var ctx = WithConnectionString();
        var conn = ctx.GetConnection();
        ctx.EnsureConnectionOpen();
        conn.State.Should().Be(ConnectionState.Open);

        ctx.Dispose();

        conn.State.Should().Be(ConnectionState.Closed);
    }

    [Fact]
    public void ConnectionString_WithConnectionString_ReturnsIt()
    {
        using var ctx = WithConnectionString("Data Source=:memory:");

        ctx.ConnectionString.Should().Be("Data Source=:memory:");
    }

    [Fact]
    public void ConnectionString_WithSuppliedConnection_ComesFromTheConnection()
    {
        using var supplied = new SqliteConnection("Data Source=:memory:");
        using var ctx = WithConnection(supplied);

        ctx.ConnectionString.Should().Be(supplied.ConnectionString);
    }

    [Fact]
    public void ConnectionManager_ExposesTheSameConnection()
    {
        using var ctx = WithConnectionString();

        ((IConnectionManager)ctx).GetConnection().Should().BeSameAs(ctx.GetConnection());
    }

    [Fact]
    public void SuppliedConnection_GetsProviderFunctionsRegistered()
    {
        using var supplied = new SqliteConnection("Data Source=:memory:");
        using var ctx = WithConnection(supplied);
        ctx.EnsureConnectionOpen();

        using var cmd = supplied.CreateCommand();
        cmd.CommandText = "select stdev(x) from (select 1.0 as x union all select 3.0)";

        var result = cmd.ExecuteScalar();

        result.Should().BeOfType<double>().Which.Should().BeApproximately(1.4142135623730951, 1e-12);
    }

    [Fact]
    public void SuppliedConnection_RunsQueriesAgainstItsOwnDatabase()
    {
        // ':memory:' is per-connection, so the table set up here is visible to the context only
        // because the context reuses this very connection instead of creating one of its own.
        using var supplied = new SqliteConnection("Data Source=:memory:");
        supplied.Open();
        using (var setup = supplied.CreateCommand())
        {
            setup.CommandText = "create table simple_entity (id integer primary key);" +
                                "insert into simple_entity (id) values (42);";
            setup.ExecuteNonQuery();
        }

        using var ctx = WithConnection(supplied);

        ctx.From<ISimpleEntity>().Select(x => x.Id).ToList().Should().Equal(42);
    }

    [Fact]
    public void Dispose_WithSuppliedConnection_UnsubscribesDisposedHandler()
    {
        var supplied = new SqliteConnection("Data Source=:memory:");
        var weak = CreateDisposedContextWithSuppliedConnection(supplied);

        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();

        // The still-alive (caller-owned) connection must not keep the disposed context reachable
        // through its Disposed event.
        weak.IsAlive.Should().BeFalse();
        GC.KeepAlive(supplied);
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static WeakReference CreateDisposedContextWithSuppliedConnection(DbConnection connection)
    {
        var ctx = WithConnection(connection);
        ctx.GetConnection();
        var weak = new WeakReference(ctx);
        ctx.Dispose();
        return weak;
    }
}

using System.Data.Common;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// SQL generation for two engine behaviours that share <c>PredicateTranslator</c> and
/// <c>CorrelatedQueryExpressionVisitor</c>: a captured local repeated in a <c>WHERE</c> over a join
/// projection is registered once, and a correlated <c>EXISTS</c> can be combined with the logical
/// operators <c>||</c>, <c>&amp;&amp;</c> and <c>!</c>. These tests never open a database connection.
/// </summary>
public class CorrelatedParameterSqlGenerationTests
{
    private static string Normalize(string sql) => sql.Replace("\r\n", "\n");

    private static DbPreparedQueryCommand<T> Prepare<T>(IDataContext ctx, QueryCommand<T> cmd)
        => (DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None);

    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd) => Normalize(Prepare(ctx, cmd).DbCommand.CommandText);

    [Fact]
    public void CapturedLocalRepeatedInJoinWhere_ShouldBindOnce()
    {
        using var ctx = SqliteTestContext.Create();
        var v = 5;

        var prepared = Prepare(ctx, ctx.From<IComplexEntity>()
            .Join(ctx.From<ISimpleEntity>(), (c, s) => c.Id == s.Id)
            .Where(p => p.Item1.Int == v && p.Item2.Id != v)
            .Select(p => new { p.Item1.Id }));

        var parameters = prepared.DbCommand.Parameters.Cast<DbParameter>().ToArray();
        parameters.Should().ContainSingle();
        parameters[0].ParameterName.Should().Be("v");
        parameters[0].Value.Should().Be(5);
        Normalize(prepared.DbCommand.CommandText).Should().Contain("$v");
    }

    [Fact]
    public void CorrelatedExistsCombinedWithLogicalOperators_ShouldRenderPredicates()
    {
        using var ctx = SqliteTestContext.Create();
        var inner = ctx.From<ISimpleEntity>();

        var orSql = SqlOf(ctx, ctx.From<IComplexEntity>()
            .Where(c => SqlFunctions.Sql.exists(inner.Where(s => s.Id == c.Int)) || c.Id > 0)
            .Select(c => new { c.Id }));

        orSql.Should().Contain("exists");
        orSql.Should().Contain(" or ");

        var andSql = SqlOf(ctx, ctx.From<IComplexEntity>()
            .Where(c => c.Id > 0 && SqlFunctions.Sql.exists(inner.Where(s => s.Id == c.Int)))
            .Select(c => new { c.Id }));

        andSql.Should().Contain(" and ");
        andSql.Should().Contain("exists");

        var notSql = SqlOf(ctx, ctx.From<IComplexEntity>()
            .Where(c => !SqlFunctions.Sql.exists(inner.Where(s => s.Id == c.Int)))
            .Select(c => new { c.Id }));

        notSql.Should().Contain("not (exists");
    }
}

using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using System.Data.Common;
using FluentAssertions;
using NextORM.Core;
using NextORM.Sqlite;

namespace NextORM.Sqlite.Tests;

[SqlTable("pair_entity")]
public interface IPairEntity
{
    [Key]
    [Column("id")]
    int Id { get; set; }
    [Column("a")]
    int A { get; set; }
    [Column("b")]
    int B { get; set; }
}

[SqlTable("pair_inner")]
public interface IPairInnerEntity
{
    [Key]
    [Column("id")]
    int Id { get; set; }
}

[SqlTable("pair_inner2")]
public interface IPairInner2Entity
{
    [Key]
    [Column("id")]
    int Id { get; set; }
}

/// <summary>
/// SQL generation for correlated subqueries: a subquery that references a column of the enclosing
/// query. These tests never open a database connection, so they run on every build/CI.
/// </summary>
public class CorrelatedQueryTests
{
    private static string Normalize(string sql) => sql.Replace("\r\n", "\n");

    private static DbPreparedQueryCommand<T> Prepare<T>(IDataContext ctx, QueryCommand<T> cmd)
        => (DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None);

    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd) => Normalize(Prepare(ctx, cmd).DbCommand.CommandText);

    [Fact]
    public void CorrelatedScalarInSelect_ShouldReferenceOuterAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            sid = inner.Where(s => s.Id == it.Id).Select(s => s.Id).First()
        }));

        sql.Should().Be("select t1.id, (select t2.id from simple_entity as 't2'\n"
            + " where cast(t2.id as bigint) = t1.id\n"
            + "limit 1) as 'sid' from complex_entity as 't1'");
    }

    [Fact]
    public void CorrelatedScalarInWhere_ShouldReferenceOuterAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer
            .Where(it => it.Id == inner.Where(s => s.Id == it.Id).Select(s => s.Id).First())
            .Select(it => new { it.Id }));

        sql.Should().Be("select t1.id from complex_entity as 't1'\n"
            + " where t1.id = (select t2.id from simple_entity as 't2'\n"
            + " where cast(t2.id as bigint) = t1.id\n"
            + "limit 1)");
    }

    [Fact]
    public void CorrelatedScalarInOrderBy_ShouldReferenceOuterAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer
            .OrderBy(it => inner.Where(s => s.Id == it.Id).Select(s => s.Id).First())
            .Select(it => new { it.Id }));

        sql.Should().Be("select t1.id from complex_entity as 't1'\n"
            + " order by (select t2.id from simple_entity as 't2'\n"
            + " where cast(t2.id as bigint) = t1.id\n"
            + "limit 1)");
    }

    /// <summary>
    /// A correlated subquery may reference a column of a join-projection item
    /// (<c>p.Item1.Id</c>). The marker wraps the projection item, not a plain entity parameter, so
    /// the member has to be resolved through the item's position; before this was handled the
    /// translation evaluated the marker's unset <c>Ref</c> and threw.
    /// </summary>
    [Fact]
    public void CorrelatedScalarOnJoinProjection_ShouldReferenceOuterAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>().Join(ctx.From<ISimpleEntity>(), (c, s) => c.Id == s.Id);
        var inner = ctx.From<IPairInnerEntity>();

        var sql = SqlOf(ctx, outer.Select(p => new
        {
            p.Item1.Id,
            x = inner.Where(i => i.Id == p.Item1.Id).Select(i => i.Id).First()
        }));

        sql.Should().Be("select t1.id, (select t3.id from pair_inner as 't3'\n"
            + " where cast(t3.id as bigint) = t1.id\n"
            + "limit 1) as 'x' from complex_entity as 't1' join simple_entity as 't2' on t1.id = cast(t2.id as bigint)");
    }

    /// <summary>
    /// The projection position of the referenced item selects the table alias: an outer reference to
    /// the second join item must render the second source's alias, not the first one.
    /// </summary>
    [Fact]
    public void CorrelatedExistsOnJoinProjection_ShouldReferenceTheSecondItemAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>().Join(ctx.From<ISimpleEntity>(), (c, s) => c.Id == s.Id);
        var inner = ctx.From<IPairInnerEntity>();

        var sql = SqlOf(ctx, outer.Select(p => new
        {
            p.Item1.Id,
            has = SqlFunctions.Sql.exists(inner.Where(i => i.Id == p.Item2.Id))
        }));

        sql.Should().Contain("t3.id = t2.id");
        sql.Should().Contain("from pair_inner as 't3'");
    }

    /// <summary>
    /// A correlated reference may be wrapped in a function over the outer column (<c>upper(c.String)</c>):
    /// the member translator rewrites the outer column to its marker and the ordinary scalar translator
    /// renders the call around it.
    /// </summary>
    [Fact]
    public void CorrelatedFunctionOverOuterColumn_ShouldRenderAroundOuterAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<IComplexEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            x = inner.Where(s => s.String == it.String!.ToUpper()).Select(s => s.Id).First()
        }));

        sql.Should().Contain("upper(t1.somestring)");
        sql.Should().Contain("t2.somestring");
    }

    [Fact]
    public void CorrelatedExistsInSelect_ShouldReferenceOuterAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            has = SqlFunctions.Sql.exists(inner.Where(s => s.Id == it.Id))
        }));

        sql.Should().Be("select t1.id, exists(select * from simple_entity as 't2'\n"
            + " where cast(t2.id as bigint) = t1.id) from complex_entity as 't1'");
    }

    [Fact]
    public void CorrelatedInInSelect_ShouldReferenceOuterAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            inc = SqlFunctions.Sql.@in((int)it.Id, inner.Where(s => s.Id == it.Id).Select(s => s.Id))
        }));

        sql.Should().Contain(" in (select ");
        sql.Should().Contain("cast(t2.id as bigint) = t1.id");
    }

    [Fact]
    public void CorrelatedExistsInOrderBy_ShouldReferenceOuterAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer
            .OrderBy(it => SqlFunctions.Sql.exists(inner.Where(s => s.Id == it.Id)))
            .Select(it => new { it.Id }));

        sql.Should().Contain("order by exists(");
        sql.Should().Contain("cast(t2.id as bigint) = t1.id");
    }

    /// <summary>
    /// An aggregate terminal inside a correlated subquery is rewritten to the equivalent aggregate
    /// projection, so it renders as a scalar subquery over <c>count(*)</c> instead of being rejected.
    /// </summary>
    [Fact]
    public void AggregateCountInsideSubquery_ShouldRenderAggregateSubquery()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            c = inner.Where(s => s.Id == it.Id).Count()
        }));

        sql.Should().Be("select t1.id, (select count(*) from simple_entity as 't2'\n"
            + " where cast(t2.id as bigint) = t1.id\n"
            + "limit 1) as 'c' from complex_entity as 't1'");
    }

    [Fact]
    public void AggregateOpsInsideSubquery_ShouldRenderAggregateFunctions()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var pairs = ctx.From<IPairEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            s = pairs.Where(p => p.Id == it.Id).Sum(p => p.A),
            mn = pairs.Where(p => p.Id == it.Id).Min(p => p.A),
            mx = pairs.Where(p => p.Id == it.Id).Max(p => p.A),
            av = pairs.Where(p => p.Id == it.Id).Avg(p => p.A)
        }));

        sql.Should().Contain("(select sum(t2.a) from pair_entity as 't2'");
        sql.Should().Contain("(select min(t3.a) from pair_entity as 't3'");
        sql.Should().Contain("(select max(t4.a) from pair_entity as 't4'");
        sql.Should().Contain("(select avg(t5.a) from pair_entity as 't5'");
        sql.Should().Contain("where cast(t2.id as bigint) = t1.id");
    }

    /// <summary>
    /// A non-correlated aggregate terminal in a projection is rewritten the same way and renders as a
    /// plain scalar aggregate subquery.
    /// </summary>
    [Fact]
    public void NonCorrelatedAggregateTerminalInsideSubquery_ShouldRenderAggregateSubquery()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            c = inner.Where(s => s.Id == 1).Count()
        }));

        sql.Should().Contain("(select count(*) from simple_entity");
        sql.Should().Contain("limit 1) as 'c'");
    }

    /// <summary>
    /// SQLite does not enforce scalar-subquery cardinality, so a numeric <c>Single</c> scalar subquery
    /// is rendered with a count guard that raises on a second row instead of returning the first.
    /// </summary>
    [Fact]
    public void SingleScalar_ShouldRenderCardinalityGuard()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            sid = inner.Where(s => s.Id == it.Id).Select(s => s.Id).Single()
        }));

        sql.Should().Contain("case when (count(*) > 1) then cast(abs(-9223372036854775808) as integer) else t2.id end");
    }

    /// <summary>
    /// A fully non-correlated subquery that itself contains a subquery must resolve each referenced
    /// command against the root registry; it used to resolve the wrong (outer) command and recurse.
    /// </summary>
    [Fact]
    public void NestedNonCorrelatedSubquery_ShouldResolveItsOwnInnerCommand()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            x = inner.Where(s => s.Id > 0)
                   .Select(s => inner.Where(s2 => s2.Id == s.Id).Select(s2 => s2.Id).First())
                   .First()
        }));

        sql.Should().Be("select t1.id, (select (select t3.id from simple_entity as 't3'\n"
            + " where t3.id = t2.id\n"
            + "limit 1) from simple_entity as 't2'\n"
            + " where (t2.id > 0)\n"
            + "limit 1) as 'x' from complex_entity as 't1'");
    }

    /// <summary>
    /// Correlation depth greater than one: the innermost subquery references both the middle
    /// subquery's parameter (<c>s.Id</c>) and the outermost one (<c>it.Id</c>). Each outer reference is
    /// resolved to the alias of the scope that registered it.
    /// </summary>
    [Fact]
    public void NestedCorrelationDepth2_ShouldReferenceBothOuterLevels()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var mid = ctx.From<ISimpleEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            x = mid.Where(s => s.Id == it.Id)
                   .Select(s => inner.Where(s2 => s2.Id == s.Id && s2.Id == it.Id).Select(s2 => s2.Id).First())
                   .First()
        }));

        sql.Should().Be("select t1.id, (select (select t3.id from simple_entity as 't3'\n"
            + " where (t3.id = t2.id and cast(t3.id as bigint) = t1.id)\n"
            + "limit 1) from simple_entity as 't2'\n"
            + " where cast(t2.id as bigint) = t1.id\n"
            + "limit 1) as 'x' from complex_entity as 't1'");
    }

    private static string SqlOfCached<T>(SqliteDataContext ctx, QueryCommand<T> cmd)
        => Normalize(((DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None)).DbCommand.CommandText);

    /// <summary>
    /// A subquery in HAVING is prepared through the correlated-query visitor like WHERE, so a
    /// correlated scalar resolves against the grouped outer query instead of emitting a raw
    /// inner-command node (which previously forced an explicit <c>NotSupportedException</c>).
    /// </summary>
    [Fact]
    public void CorrelatedSubqueryInHaving_ShouldReferenceOuterAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer
            .GroupBy(it => new { it.Id })
            .Having(g => g.Id == inner.Where(s => s.Id == g.Id).Select(s => s.Id).First())
            .Select(g => new { g.Id }));

        sql.Should().Contain(" having ");
        sql.Should().Contain("(select t2.id from simple_entity as 't2'");
        sql.Should().Contain("cast(t2.id as bigint) = t1.id");
    }

    /// <summary>
    /// A non-correlated subquery in HAVING is prepared by the same path and renders as a plain scalar
    /// subquery over the inner source.
    /// </summary>
    [Fact]
    public void SubqueryInHaving_ShouldRenderScalarSubquery()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IComplexEntity>();
        var inner = ctx.From<ISimpleEntity>();

        var sql = SqlOf(ctx, outer
            .GroupBy(it => new { it.Id })
            .Having(g => g.Id == inner.Select(s => s.Id).First())
            .Select(g => new { g.Id }));

        sql.Should().Contain(" having ");
        sql.Should().Contain("(select id from simple_entity");
        sql.Should().Contain("limit 1");
    }

    [Fact]
    public void CorrelatedExpressionsCache_ShouldNotReuseMarkerIndex()
    {
        DataContextCache.ExpressionsCache.Clear();
        var ctx = SqliteTestContext.CreateSqlite();
        try
        {
            ctx.EnsureConnectionOpen();
            ctx.PurgeQueryCache();

            // The first command registers two outer references: B -> index 0, A -> index 1, so the
            // cached delegate that builds the "A" subquery bakes OuterRefMarker(1) into its body.
            var sqlZ = SqlOfCached(ctx, ctx.From<IPairEntity>().Select(it => new
            {
                it.Id,
                b = ctx.From<IPairInnerEntity>().Where(s => s.Id == it.B).Select(s => s.Id).First(),
                a = ctx.From<IPairInner2Entity>().Where(s => s.Id == it.A).Select(s => s.Id).First(),
            }));

            // A second command binds A first (index 0). Reusing the cached delegate would resolve
            // marker 1 against this command's single-entry OuterReferences and read the wrong column
            // (or throw). The marker index must never be shared across outer commands.
            var sqlW = SqlOfCached(ctx, ctx.From<IPairEntity>().Select(it => new
            {
                it.Id,
                a = ctx.From<IPairInner2Entity>().Where(s => s.Id == it.A).Select(s => s.Id).First(),
            }));

            sqlZ.Should().Contain("= t1.b");
            sqlZ.Should().Contain("= t1.a");
            sqlW.Should().Contain("= t1.a");
            sqlW.Should().NotContain("t1.b");
        }
        finally
        {
            ctx.Dispose();
        }
    }

    /// <summary>
    /// Regression test for the plan cache: two correlated commands that differ only in the outer
    /// column they reference (both <c>int</c>, so the marker type/index and the referenced-query SQL
    /// are identical) must not share a plan. Before the outer references became part of the plan key
    /// the second command reused the first one's SQL and silently read the wrong column.
    /// </summary>
    [Fact]
    public void CorrelatedPlanCache_ShouldDistinguishOuterColumns()
    {
        var ctx = SqliteTestContext.CreateSqlite();
        try
        {
            ctx.EnsureConnectionOpen();
            ctx.PurgeQueryCache();

            var sqlA = SqlOfCached(ctx, ctx.From<IPairEntity>()
                .Where(it => it.Id == ctx.From<IPairInnerEntity>().Where(s => s.Id == it.A).Select(s => s.Id).First())
                .Select(it => it.Id));
            var sqlB = SqlOfCached(ctx, ctx.From<IPairEntity>()
                .Where(it => it.Id == ctx.From<IPairInnerEntity>().Where(s => s.Id == it.B).Select(s => s.Id).First())
                .Select(it => it.Id));

            sqlA.Should().NotBe(sqlB);
            sqlA.Should().Contain("= t1.a");
            sqlB.Should().Contain("= t1.b");
        }
        finally
        {
            ctx.Dispose();
        }
    }

    /// <summary>
    /// Two correlated subqueries over the same entity type must each resolve to their own table alias.
    /// Before the source scope was introduced the second subquery's columns resolved to the first
    /// subquery's alias (for example <c>from pair_inner as 't3' where t2.id = t1.a</c>), which is
    /// invalid SQL because <c>t2</c> is not in scope there.
    /// </summary>
    [Fact]
    public void CorrelatedSiblingSubqueriesOfSameType_ShouldUseTheirOwnAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IPairEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            b = ctx.From<IPairInnerEntity>().Where(s => s.Id == it.B).Select(s => s.Id).First(),
            a = ctx.From<IPairInnerEntity>().Where(s => s.Id == it.A).Select(s => s.Id).First(),
        }));

        sql.Should().Contain("t2.id = t1.b");
        sql.Should().NotContain("t2.id = t1.a");
        sql.Should().Contain("t3.id = t1.a");
    }

    /// <summary>
    /// Same as <see cref="CorrelatedSiblingSubqueriesOfSameType_ShouldUseTheirOwnAlias"/> for the
    /// pre-existing <c>EXISTS</c> form, which was affected by the same alias-resolution defect.
    /// </summary>
    [Fact]
    public void CorrelatedSiblingExistsOfSameType_ShouldUseTheirOwnAlias()
    {
        using var ctx = SqliteTestContext.Create();
        var outer = ctx.From<IPairEntity>();

        var sql = SqlOf(ctx, outer.Select(it => new
        {
            it.Id,
            eb = SqlFunctions.Sql.exists(ctx.From<IPairInnerEntity>().Where(s => s.Id == it.B)),
            ea = SqlFunctions.Sql.exists(ctx.From<IPairInnerEntity>().Where(s => s.Id == it.A)),
        }));

        sql.Should().Contain("t2.id = t1.b");
        sql.Should().NotContain("t2.id = t1.a");
        sql.Should().Contain("t3.id = t1.a");
    }
}

using FluentAssertions;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// SQL generation of the <c>CREATE TABLE ... AS SELECT</c> terminals on SQLite (no database
/// connection): SQLite has no column list with <c>AS SELECT</c> and neither <c>ON COMMIT</c> nor
/// <c>WITH NO DATA</c>, so those options are rejected.
/// </summary>
public class CreateTableAsSqlGenerationTests
{
    [Fact]
    public void TempTable_ShouldRenderCreateTemporaryTableAsSelect()
    {
        using var ctx = SqliteTestContext.Create();

        ctx.From<ISimpleEntity>()
            .ToTempTableSql("recent_ids")
            .Should().Be("create temporary table recent_ids as select id from simple_entity");
    }

    [Fact]
    public void TempTable_ColumnList_ShouldThrow()
    {
        using var ctx = SqliteTestContext.Create();

        var act = () => ctx.From<ISimpleEntity>()
            .ToTempTableSql("recent_ids", new CreateTableOptions { Columns = ["a"] });

        act.Should().Throw<NotSupportedException>().WithMessage("*column list*");
    }

    [Fact]
    public void TempTable_OnCommit_ShouldThrow()
    {
        using var ctx = SqliteTestContext.Create();

        var act = () => ctx.From<ISimpleEntity>()
            .ToTempTableSql("recent_ids", new CreateTableOptions { OnCommit = TempTableOnCommit.Drop });

        act.Should().Throw<NotSupportedException>().WithMessage("*ON COMMIT*");
    }

    [Fact]
    public void TempTable_WithNoData_ShouldThrow()
    {
        using var ctx = SqliteTestContext.Create();

        var act = () => ctx.From<ISimpleEntity>()
            .ToTempTableSql("recent_ids", new CreateTableOptions { WithData = false });

        act.Should().Throw<NotSupportedException>().WithMessage("*WITH NO DATA*");
    }

    [Fact]
    public void TempTable_WithPredicate_ShouldCarryParametersIntoBody()
    {
        using var ctx = SqliteTestContext.Create();
        var min = 5;

        var sql = ctx.From<ISimpleEntity>()
            .Where(x => x.Id > min)
            .ToTempTableSql("recent_ids");

        sql.Should().Contain("$min");
    }

    [Fact]
    public void Table_DropExisting_ShouldRenderDropThenCreate()
    {
        using var ctx = SqliteTestContext.Create();

        var sql = ctx.From<ISimpleEntity>()
            .ToTableSql("archive", new CreateTableOptions { DropExisting = true });

        sql.Should().Be("drop table if exists archive; create table archive as select id from simple_entity");
    }

    [Fact]
    public void TempTable_DropExisting_ShouldThrow()
    {
        using var ctx = SqliteTestContext.Create();

        var act = () => ctx.From<ISimpleEntity>()
            .ToTempTableSql("recent_ids", new CreateTableOptions { DropExisting = true });

        act.Should().Throw<NotSupportedException>().WithMessage("*persistent*");
    }

    [Fact]
    public void Table_DropExistingWithIfNotExists_ShouldThrow()
    {
        using var ctx = SqliteTestContext.Create();

        var act = () => ctx.From<ISimpleEntity>()
            .ToTableSql("archive", new CreateTableOptions { DropExisting = true, IfNotExists = true });

        act.Should().Throw<ArgumentException>().WithMessage("*mutually exclusive*");
    }

    [Fact]
    public void Table_DropExistingViaBuilder_ShouldRenderDropThenCreate()
    {
        using var ctx = SqliteTestContext.Create();

        var sql = ctx.From<ISimpleEntity>()
            .ToTableSql("archive", o => o.DropExisting());

        sql.Should().Be("drop table if exists archive; create table archive as select id from simple_entity");
    }

    [Fact]
    public void TempTable_OnCommitViaBuilder_ShouldThrow()
    {
        using var ctx = SqliteTestContext.Create();

        var act = () => ctx.From<ISimpleEntity>()
            .ToTempTableSql("recent_ids", o => o.OnCommit(TempTableOnCommit.Drop));

        act.Should().Throw<NotSupportedException>().WithMessage("*ON COMMIT*");
    }

    [Fact]
    public void Dialect_ShouldReportCreateTableAsSelect()
    {
        using var ctx = SqliteTestContext.Create();

        ((DataContext)ctx).Dialect.SupportsCreateTableAsSelect.Should().BeTrue();
        ((DataContext)ctx).Dialect.SupportsCreateTableAsSelectColumnList.Should().BeFalse();
        ((DataContext)ctx).Dialect.SupportsCreateTableAsSelectOnCommit.Should().BeFalse();
        ((DataContext)ctx).Dialect.SupportsCreateTableAsSelectWithNoData.Should().BeFalse();
    }
}

using FluentAssertions;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>SQL generation for the cross-provider scalar functions on SQLite (no database).</summary>
public class CrossProviderScalarSqlGenerationTests
{
    private static string Normalize(string sql) => sql.Replace("\r\n", "\n");

    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd)
        => Normalize(((DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None)).DbCommand.CommandText);

    [Fact]
    public void SupportedScalarFunctions_ShouldEmitNativeSpellings()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var sql = SqlOf(ctx, e.Select(x => new
        {
            L = SqlFunctions.Sql.left(x.String, 3),
            R = SqlFunctions.Sql.right(x.String, 3),
            Cw = SqlFunctions.Sql.concat_ws(",", x.String, x.String),
            Asc = SqlFunctions.Sql.ascii(x.String),
            Ch = SqlFunctions.Sql.@char(65)
        }));

        sql.Should().Contain("substr(somestring, 1, 3)");
        sql.Should().Contain("case when (3) >= length(somestring) then somestring else substr(somestring, length(somestring) - (3) + 1, 3) end");
        sql.Should().Contain("concat_ws(',', somestring, somestring)");
        sql.Should().Contain("unicode(somestring)");
        sql.Should().Contain("char(65)");
    }

    [Fact]
    public void Lpad_ShouldThrowBecauseNotSupported()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        AssertUnsupported(ctx, e.Select(x => new { V = SqlFunctions.Sql.lpad(x.String, 5, "0") }), "lpad");
    }

    [Fact]
    public void Repeat_ShouldThrowBecauseNotSupported()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        AssertUnsupported(ctx, e.Select(x => new { V = SqlFunctions.Sql.repeat(x.String, 2) }), "repeat");
    }

    [Fact]
    public void Reverse_ShouldThrowBecauseNotSupported()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        AssertUnsupported(ctx, e.Select(x => new { V = SqlFunctions.Sql.reverse(x.String) }), "reverse");
    }

    [Fact]
    public void Space_ShouldThrowBecauseNotSupported()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        AssertUnsupported(ctx, e.Select(x => new { V = SqlFunctions.Sql.space(3) }), "space");
    }

    [Fact]
    public void Translate_ShouldThrowBecauseNotSupported()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        AssertUnsupported(ctx, e.Select(x => new { V = SqlFunctions.Sql.translate(x.String, "ab", "xy") }), "translate");
    }

    private static void AssertUnsupported<T>(IDataContext ctx, QueryCommand<T> cmd, string name)
    {
        var act = () => SqlOf(ctx, cmd);
        act.Should().Throw<NotSupportedException>().WithMessage($"*{name}*not supported*");
    }

    [Fact]
    public void NumericAndLengthFunctions_ShouldEmitNativeSpellings()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var sql = SqlOf(ctx, e.Select(x => new
        {
            Bl = SqlFunctions.Sql.bit_length(x.String),
            Ol = SqlFunctions.Sql.octet_length(x.String),
            Deg = SqlFunctions.Sql.degrees(1.5),
            Rad = SqlFunctions.Sql.radians(1.5),
            Pi = SqlFunctions.Sql.pi(),
            Acos = Math.Acos(0.5),
            Atan2 = Math.Atan2(1.5, 2.5)
        }));

        sql.Should().Contain("octet_length(somestring) * 8");
        sql.Should().Contain("octet_length(somestring)");
        sql.Should().Contain("degrees(1.5)");
        sql.Should().Contain("radians(1.5)");
        sql.Should().Contain("pi()");
        sql.Should().Contain("acos(0.5)");
        sql.Should().Contain("atan2(1.5, 2.5)");
    }

    [Fact]
    public void Cot_ShouldThrowBecauseNotSupported()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        AssertUnsupported(ctx, e.Select(x => new { V = SqlFunctions.Sql.cot(1.5) }), "cot");
    }
}

using System.Buffers.Text;
using System.ComponentModel.DataAnnotations.Schema;
using System.Text;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// End-to-end coverage for the <c>WriteCsv</c>/<c>WriteCsvAsync</c> terminals against a real SQLite
/// database: header, escaping, empty results, custom delimiter, parameters, async, cancellation and
/// the box-free streaming guarantee (no <c>TResult</c> per row).
/// </summary>
public class CsvStreamTests
{
    [SqlTable("csv_row")]
    private sealed class CsvRow
    {
        [Column("id")]
        public int Id { get; set; }

        [Column("name")]
        public string? Name { get; set; }

        [Column("note")]
        public string? Note { get; set; }
    }

    /// <summary>A projection whose constructor increments a counter; it proves the terminal never materializes a row.</summary>
    private sealed class CountingRow
    {
        public static int Constructions;

        public CountingRow(int id, string? name)
        {
            Constructions++;
            Id = id;
            Name = name;
        }

        public int Id { get; }

        public string? Name { get; }
    }

    /// <summary>A row whose column is converted only through the object-based bridge.</summary>
    [SqlTable("csv_bridge_probe")]
    private sealed class CsvBridgeRow
    {
        [Column("id")]
        public int Id { get; set; }

        [Column("value")]
        [ValueConverter(typeof(BridgeIntConverter))]
        public int Value { get; set; }
    }

    /// <summary>An <see cref="IPropertyValueConverter"/> implemented directly, so the mapper can only
    /// invoke it through the object-based <c>ConvertFromProvider(object)</c> bridge.</summary>
    private sealed class BridgeIntConverter : IPropertyValueConverter
    {
        public Type ProviderType => typeof(int);

        public bool ConvertsNulls => false;

        public object? ConvertToProvider(object? model) => model;

        public object? ConvertFromProvider(object? provider) => (int)(provider ?? 0);
    }

    /// <summary>A row whose property type has no CSV formatter (the integration-suite regression shape).</summary>
    [SqlTable("csv_unsupported_probe")]
    private sealed class CsvUnsupportedRow
    {
        [Column("id")]
        public int Id { get; set; }

        [Column("state")]
        [ValueConverter(typeof(EnumToStringConverter<CsvProbeState>))]
        public CsvProbeState State { get; set; }
    }

    private enum CsvProbeState
    {
        Unknown,
        Active,
    }

    private static SqliteDataContext CreateDb(out string path)
    {
        path = Path.Combine(Path.GetTempPath(), $"nextorm-csv-{Guid.NewGuid():N}.db");
        using (var connection = new SqliteConnection($"Data Source={path}"))
        {
            connection.Open();
            using (var create = connection.CreateCommand())
            {
                create.CommandText = "create table csv_row (id integer primary key, name text, note text);";
                create.ExecuteNonQuery();
            }

            using var insert = connection.CreateCommand();
            insert.CommandText = "insert into csv_row (id, name, note) values ($id, $name, $note);";
            insert.Parameters.Add(new SqliteParameter("$id", 1));
            insert.Parameters.Add(new SqliteParameter("$name", "alpha"));
            insert.Parameters.Add(new SqliteParameter("$note", "plain"));
            insert.ExecuteNonQuery();

            insert.Parameters["$id"].Value = 2;
            insert.Parameters["$name"].Value = "be,ta";
            insert.Parameters["$note"].Value = "quote\"inside";
            insert.ExecuteNonQuery();

            insert.Parameters["$id"].Value = 3;
            insert.Parameters["$name"].Value = DBNull.Value;
            insert.Parameters["$note"].Value = "line\nbreak";
            insert.ExecuteNonQuery();
        }

        return new SqliteDataContext($"Data Source={path}", new DataContextBuilder());
    }

    private static string Utf8(MemoryStream stream) => Encoding.UTF8.GetString(stream.ToArray());

    [Fact]
    public void WriteCsv_RendersHeaderAndEscapedRows()
    {
        var ctx = CreateDb(out var path);
        try
        {
            using var destination = new MemoryStream();
            ctx.From<CsvRow>().OrderBy(r => r.Id).WriteCsv(destination, null, TestContext.Current.CancellationToken);

            Utf8(destination).Should().Be(
                "Id,Name,Note\r\n" +
                "1,alpha,plain\r\n" +
                "2,\"be,ta\",\"quote\"\"inside\"\r\n" +
                "3,\\N,\"line\nbreak\"\r\n");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public async Task WriteCsvAsync_MatchesSyncOutput()
    {
        var ctx = CreateDb(out var path);
        try
        {
            using var sync = new MemoryStream();
            using var async = new MemoryStream();
            var query = ctx.From<CsvRow>().OrderBy(r => r.Id);

            query.WriteCsv(sync, null, TestContext.Current.CancellationToken);
            await query.WriteCsvAsync(async, null, TestContext.Current.CancellationToken);

            Utf8(async).Should().Be(Utf8(sync));
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void WriteCsv_EmptyResult_WritesHeaderOnly()
    {
        var ctx = CreateDb(out var path);
        try
        {
            using var destination = new MemoryStream();
            ctx.From<CsvRow>().Where(r => r.Id > 100).WriteCsv(destination, null, TestContext.Current.CancellationToken);

            Utf8(destination).Should().Be("Id,Name,Note\r\n");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void WriteCsv_IncludeHeaderFalse_WritesRowsOnly()
    {
        var ctx = CreateDb(out var path);
        try
        {
            using var destination = new MemoryStream();
            ctx.From<CsvRow>().Where(r => r.Id == 1)
                .WriteCsv(destination, new CsvStreamOptions { IncludeHeader = false }, TestContext.Current.CancellationToken);

            Utf8(destination).Should().Be("1,alpha,plain\r\n");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void WriteCsv_CustomDelimiter_QuotesThatDelimiterOnly()
    {
        var ctx = CreateDb(out var path);
        try
        {
            using var destination = new MemoryStream();
            ctx.From<CsvRow>().Where(r => r.Id == 2)
                .WriteCsv(destination, new CsvStreamOptions { Delimiter = ';' }, TestContext.Current.CancellationToken);

            Utf8(destination).Should().Be("Id;Name;Note\r\n2;be,ta;\"quote\"\"inside\"\r\n");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public async Task WriteCsv_WithParameter_BindsPositionally()
    {
        var ctx = CreateDb(out var path);
        try
        {
            using var destination = new MemoryStream();
            var query = ctx.From<CsvRow>()
                .Where(r => r.Id > SqlFunctions.Parameter<int>(0))
                .OrderBy(r => r.Id);

            await query.WriteCsvAsync(destination, null, TestContext.Current.CancellationToken, 1);

            Utf8(destination).Should().Be(
                "Id,Name,Note\r\n" +
                "2,\"be,ta\",\"quote\"\"inside\"\r\n" +
                "3,\\N,\"line\nbreak\"\r\n");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void WriteCsv_DoesNotConstructProjectionType()
    {
        var ctx = CreateDb(out var path);
        try
        {
            CountingRow.Constructions = 0;
            using var destination = new MemoryStream();

            ctx.From<CsvRow>().OrderBy(r => r.Id)
                .Select(r => new CountingRow(r.Id, r.Name))
                .WriteCsv(destination, null, TestContext.Current.CancellationToken);

            CountingRow.Constructions.Should().Be(0, "the CSV terminal must not materialize TResult");
            Utf8(destination).Should().Contain("1,alpha");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void WriteCsv_LeavesDestinationOpen()
    {
        var ctx = CreateDb(out var path);
        try
        {
            var destination = new TrackingStream();
            ctx.From<CsvRow>().OrderBy(r => r.Id).WriteCsv(destination, null, TestContext.Current.CancellationToken);

            destination.WasDisposed.Should().BeFalse();
            destination.CanRead.Should().BeTrue();
            Utf8(destination).Should().Contain("1,alpha");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void WriteCsv_CancelledMidStream_ThrowsAndLeavesPartialOutput()
    {
        var ctx = CreateDb(out var path);
        try
        {
            using var cts = new CancellationTokenSource();
            var destination = new CancellingStream(cts, cancelAfterWrites: 2);

            var act = () => ctx.From<CsvRow>().OrderBy(r => r.Id).WriteCsv(destination, null, cts.Token);

            act.Should().Throw<OperationCanceledException>();
            Utf8(destination).Should().Be("Id,Name,Note\r\n1,alpha,plain\r\n");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public async Task WriteCsvAsync_CancelledMidStream_Throws()
    {
        var ctx = CreateDb(out var path);
        try
        {
            using var cts = new CancellationTokenSource();
            var destination = new CancellingStream(cts, cancelAfterWrites: 2);

            var act = async () => await ctx.From<CsvRow>().OrderBy(r => r.Id).WriteCsvAsync(destination, null, cts.Token);

            await act.Should().ThrowAsync<OperationCanceledException>();
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void WriteCsv_RepeatedOnSameCommand_KeepsCacheAndWritesTwice()
    {
        var ctx = CreateDb(out var path);
        try
        {
            var query = ctx.From<CsvRow>().OrderBy(r => r.Id).ToParentCommand();
            var cacheBefore = query.Cache;
            cacheBefore.Should().BeTrue("a new command caches by default");

            using var first = new MemoryStream();
            query.WriteCsv(first, null, TestContext.Current.CancellationToken);
            query.Cache.Should().BeTrue("the CSV terminal must not mutate the shared command");
            query.Cache.Should().Be(cacheBefore);

            using var second = new MemoryStream();
            query.WriteCsv(second, null, TestContext.Current.CancellationToken);

            query.Cache.Should().Be(cacheBefore);
            Utf8(second).Should().Be(Utf8(first));
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void WriteCsv_DestinationThrows_OriginalExceptionSurfacesAndStreamStaysOpen()
    {
        var ctx = CreateDb(out var path);
        try
        {
            var destination = new ThrowingStream();

            var act = () => ctx.From<CsvRow>().OrderBy(r => r.Id)
                .WriteCsv(destination, null, TestContext.Current.CancellationToken);

            act.Should().ThrowExactly<ThrowingStream.WriteFailure>();
            destination.DisposeCount.Should().Be(0, "the terminal must not dispose a caller-owned stream");
            destination.CanRead.Should().BeTrue();

            // The reader and its command were released, so the same context still runs queries.
            using var after = new MemoryStream();
            ctx.From<CsvRow>().OrderBy(r => r.Id).WriteCsv(after, null, TestContext.Current.CancellationToken);
            Utf8(after).Should().Contain("1,alpha");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public async Task WriteCsvAsync_DestinationThrows_OriginalExceptionSurfaces()
    {
        var ctx = CreateDb(out var path);
        try
        {
            var destination = new ThrowingStream();

            var act = async () => await ctx.From<CsvRow>().OrderBy(r => r.Id)
                .WriteCsvAsync(destination, null, TestContext.Current.CancellationToken);

            await act.Should().ThrowExactlyAsync<ThrowingStream.WriteFailure>();
            destination.DisposeCount.Should().Be(0, "the terminal must not dispose a caller-owned stream");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void WriteCsv_TempTableSource_ThrowsBeforeHeaderInsteadOfRawProviderError()
    {
        using var ctx = SqliteTestContext.Create();
        var source = ctx.From<ISimpleEntity>().Select(x => new { x.Id }).AsTempTable();
