    /// <summary>
    /// Proves the CSV-local locator suppression at the SQL layer: the CSV preparation renders the SQLite
    /// projection without the trailing <c>rowid</c>, while the sibling sequential LOB route (the one
    /// <c>ToStream</c>/<c>ToTextReader</c> use) still appends it.
    /// </summary>
    [Fact]
    public void CsvBinary_SqliteCsvOmitsLocator_ButSequentialLobKeepsIt()
    {
        using var ctx = SqliteTestContext.Create();
        var command = ctx.From<CsvBlobRow>().Select(r => r.Data!);
        var planner = CreatePlanner(ctx, SqliteDialect.Instance);

        var csv = (DbPreparedQueryCommand<byte[]>)planner.GetPreparedQueryCommand(
            command,
            createEnumerator: false,
            storeInCache: false,
            sequentialAccess: true,
            streamingRowsRequested: false,
            suppressLobLocator: true,
            TestContext.Current.CancellationToken);
        NormalizeCommand(csv).Should().Be("select data from csv_blob_row");
        NormalizeCommand(csv).Should().NotContain("rowid");

        var lob = (DbPreparedQueryCommand<byte[]>)planner.GetPreparedQueryCommand(
            command,
            createEnumerator: false,
            storeInCache: false,
            sequentialAccess: true,
            streamingRowsRequested: false,
            suppressLobLocator: false,
            TestContext.Current.CancellationToken);
        NormalizeCommand(lob).Should().Be("select data, rowid from csv_blob_row");
    }

    /// <summary>
    /// REQ-10: on SQLite the CSV preparation requests a sequential reader, and the CSV-only locator
    /// suppression must keep the generated SQL identical to the pre-D167 CSV render (sequential access
    /// off). A DISTINCT, JOIN, aggregate or plain projection must not gain the trailing <c>rowid</c>,
    /// which would change the SQL semantics (an aggregate would even become invalid). The plain binary
    /// projection and its LOB sibling locator behavior are asserted by the neighbouring test.
    /// </summary>
    [Fact]
    public void CsvLocatorSuppression_KeepsDistinctJoinAggregateAndPlainSqlUnchanged()
    {
        using var ctx = SqliteTestContext.Create();
        var planner = CreatePlanner(ctx, SqliteDialect.Instance);

        AssertCsvSqlMatchesPreChange(planner, ctx.From<CsvBlobRow>().Select(r => r.Id));
        AssertCsvSqlMatchesPreChange(planner, ctx.From<CsvBlobRow>().Distinct().Select(r => r.Id));
        AssertCsvSqlMatchesPreChange(planner, ctx.From<CsvBlobRow>()
            .Join(ctx.From<CsvBlobRow>(), (a, b) => a.Id == b.Id)
            .Select(p => p.Item1.Id));
        AssertCsvSqlMatchesPreChange(planner, ctx.From<CsvBlobRow>().Select(r => SqlFunctions.Sql.count()));
    }

    private static void AssertCsvSqlMatchesPreChange<TResult>(QueryPlanner planner, QueryCommand<TResult> command)
    {
        // The pre-D167 CSV behavior: no sequential reader, so no locator is ever appended.
        var preChange = (DbPreparedQueryCommand<TResult>)planner.GetPreparedQueryCommand(
            command,
            createEnumerator: false,
            storeInCache: false,
            sequentialAccess: false,
            streamingRowsRequested: false,
            suppressLobLocator: false,
            TestContext.Current.CancellationToken);

        // The current CSV path: sequential reader with the locator explicitly suppressed.
        var csv = (DbPreparedQueryCommand<TResult>)planner.GetPreparedQueryCommand(
            command,
            createEnumerator: false,
            storeInCache: false,
            sequentialAccess: true,
            streamingRowsRequested: false,
            suppressLobLocator: true,
            TestContext.Current.CancellationToken);

        var csvSql = NormalizeCommand(csv);
        csvSql.Should().NotContain("rowid", "the CSV path must not gain the SQLite locator");
        csvSql.Should().Be(
            NormalizeCommand(preChange),
            "locator suppression must keep the CSV SQL identical to the pre-change sequential-off render");
    }

    private static string NormalizeCommand<TResult>(DbPreparedQueryCommand<TResult> command)
        => command.DbCommand.CommandText.Replace("\r\n", "\n");

    private static QueryPlanner CreatePlanner(IDataContext ctx, ISqlDialect dialect)
        => new(
            ctx,
            () => dialect,
            ctx.GetType(),
            new ProviderHooks(
                (column, param) => param,
                (_, name, value) => new SqliteParameter(name, value ?? DBNull.Value),
                sql => new SqliteCommand(sql)),
            new LoggingOptions(null),
            new InterceptorHooks([], []));

    /// <summary>A <see cref="MemoryStream"/> that records the largest single write, exposing bounded streaming.</summary>
    private sealed class BoundedStream : MemoryStream
    {
        public int MaxWriteLength { get; private set; }

        public override void Write(byte[] buffer, int offset, int count)
        {
            Record(count);
            base.Write(buffer, offset, count);
        }

        public override void Write(ReadOnlySpan<byte> buffer)
        {
            Record(buffer.Length);
            base.Write(buffer);
        }

        public override Task WriteAsync(byte[] buffer, int offset, int count, CancellationToken cancellationToken)
        {
            Record(count);
            return base.WriteAsync(buffer, offset, count, cancellationToken);
        }

        public override ValueTask WriteAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default)
        {
            Record(buffer.Length);
            return base.WriteAsync(buffer, cancellationToken);
        }

        private void Record(int count)
        {
            if (count > MaxWriteLength)
                MaxWriteLength = count;
        }
    }

    /// <summary>Throws on every write and records whether the terminal tried to dispose it.</summary>
    private sealed class ThrowingStream : MemoryStream
    {
        public int DisposeCount { get; private set; }

        public override void Write(ReadOnlySpan<byte> buffer) => throw new WriteFailure();

        public override ValueTask WriteAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default) => throw new WriteFailure();

        protected override void Dispose(bool disposing)
        {
            DisposeCount++;
            base.Dispose(disposing);
        }

        internal sealed class WriteFailure : Exception
        {
        }
    }

    /// <summary>Reveals whether the terminal disposed a destination it was handed.</summary>
    private sealed class TrackingStream : MemoryStream
    {
        public bool WasDisposed { get; private set; }

        protected override void Dispose(bool disposing)
        {
            WasDisposed = true;
            base.Dispose(disposing);
        }
    }

    /// <summary>Cancels its token source once the configured number of buffer writes has completed, so the next loop iteration observes cancellation.</summary>
    private sealed class CancellingStream(CancellationTokenSource source, int cancelAfterWrites) : MemoryStream
    {
        private int _writes;

        public override void Write(ReadOnlySpan<byte> buffer)
        {
            base.Write(buffer);
            CountWrite();
        }

        public override ValueTask WriteAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default)
        {
            var result = base.WriteAsync(buffer, cancellationToken);
            CountWrite();
            return result;
        }

        private void CountWrite()
        {
            if (Interlocked.Increment(ref _writes) == cancelAfterWrites)
                source.Cancel();
        }
    }
}

using System.Data.Common;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;
using NextORM.Sqlite;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// D193 W1 — plan-cache safety of a tuple value-list <c>IN</c>/<c>Contains</c> (#193). Only a tuple list
/// in WHERE/PREWHERE is folded into the plan key (<c>InValuesShapeHash</c>) and stays cacheable. A tuple
/// list in HAVING, a JOIN condition or a SELECT column is not keyed, so the command must be flagged and
/// its call-local cache suppressed instead of reusing a stale plan. These tests drive a real temp-file
/// SQLite database (the placeholder <c>:memory:</c> context cannot execute).
/// </summary>
public class D193TupleInPlanCacheTests
{
    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    private static (IDataContext Ctx, string Path) CreateDb()
    {
        var path = Path.Combine(Path.GetTempPath(), $"nextorm-d193cache-{Guid.NewGuid():N}.db");
        using (var conn = new SqliteConnection($"Data Source={path}"))
        {
            conn.Open();
            using var cmd = conn.CreateCommand();
            cmd.CommandText =
                "create table simple_entity (id integer primary key);" +
                "insert into simple_entity (id) values (1),(2),(3);" +
                "create table complex_entity (id integer primary key, nullableint integer, somestring text);" +
                "insert into complex_entity (id, nullableint, somestring) values (1, 10, 'a'),(2, null, 'b'),(3, 30, 'c');";
            cmd.ExecuteNonQuery();
        }

        var ctx = new SqliteDataContext($"Data Source={path}", new DataContextBuilder());
        ctx.EnsureConnectionOpen();
        return (ctx, path);
    }

    private static DbPreparedQueryCommand<T> Prepare<T>(IDataContext ctx, QueryCommand<T> cmd)
        => (DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, true, Ct);

    private static int ParamCount<T>(DbPreparedQueryCommand<T> command)
        => command.DbCommandParams.Cast<DbParameter>().Count();

    // A field (not a fresh local per call) so the two shapes share the exact same captured member
    // (`this._tuples`): the plan-key comparer keys a captured closure member by its name, so a
    // different local name would itself change the plan key and mask the flag under test.
    private List<(long, int?)> _tuples = [];
    private List<(int, int?)> _joinTuples = [];

    private static QueryCommand<long> WhereTuple(EntityBuilder<IComplexEntity> e, List<(long, int?)> tuples)
        => e.Where(x => tuples.Contains(new ValueTuple<long, int?>(x.Id, x.Int))).Select(x => x.Id);

    private static QueryCommand<long> WhereScalar(EntityBuilder<IComplexEntity> e)
        => e.Where(x => x.Id == 1).Select(x => x.Id);

    private QueryCommand<long> HavingFieldTuple(EntityBuilder<IComplexEntity> e)
        => e.GroupBy(x => x.Id)
            .Having(x => _tuples.Contains(new ValueTuple<long, int?>(x.Id, x.Int)))
            .Select(x => x.Id);

    private QueryCommand<int> JoinFieldTuple(EntityBuilder<ISimpleEntity> simple, EntityBuilder<IComplexEntity> complex)
        => simple.Join<IComplexEntity>(complex, (s, c) => _joinTuples.Contains(new ValueTuple<int, int?>(s.Id, c.Int)))
            .Select(p => p.Item1.Id);

    private QueryCommand<bool> SelectFieldTuple(EntityBuilder<IComplexEntity> e)
        => e.Select(x => _tuples.Contains(new ValueTuple<long, int?>(x.Id, x.Int)));

    private QueryCommand<long> NestedHavingFieldTuple(EntityBuilder<IComplexEntity> e, IDataContext ctx)
        => e.Select(x => ctx.From<IComplexEntity>()
            .GroupBy(c => c.Id)
            .Having(c => _tuples.Contains(new ValueTuple<long, int?>(c.Id, c.Int)))
            .Select(c => c.Id)
            .First());

    private QueryCommand<long> WhereFieldTuple(EntityBuilder<IComplexEntity> e)
        => e.Where(x => _tuples.Contains(new ValueTuple<long, int?>(x.Id, x.Int))).Select(x => x.Id);

    // ------------------------------------------------------------------ unkeyed clauses: must rebuild

    [Fact]
    public void TupleContains_InHaving_DifferentSizes_ShouldRebuildAndReturnCurrentResult()
    {
        var (ctx, path) = CreateDb();
        try
        {
            ctx.PurgeQueryCache();
            var e = ctx.From<IComplexEntity>();

            var twoRows = new List<(long, int?)> { (1, 10), (2, 20) };
            var oneNullRow = new List<(long, int?)> { (2, null) };

            // Both builds capture the SAME field (`this._tuples`), so only the collection shape differs;
            // without the unkeyed-tuple flag the plan key would be identical and the second build could
            // reuse the first SQL.
            _tuples = twoRows;
            var first = Prepare(ctx, HavingFieldTuple(e));
            ParamCount(first).Should().Be(4, "the first HAVING shape has two two-component rows");

            _tuples = oneNullRow;
            var second = Prepare(ctx, HavingFieldTuple(e));

            // A stale plan would have reused the 4-parameter SQL; the null-component row emits a
            // different (smaller) parameter set, so a fresh build has a different parameter count.
            ParamCount(second).Should().Be(1, "the null-component HAVING shape only parameterises the non-null id cell");
            ReferenceEquals(first, second).Should().BeFalse(
                "a tuple IN in HAVING is not folded into the plan key, so it must not be served from the cache");

            ctx.ToList(second).OrderBy(x => x).Should().Equal(2L);
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void TupleContains_InJoinOn_DifferentSizes_ShouldRebuildAndReturnCurrentResult()
    {
        var (ctx, path) = CreateDb();
        try
        {
            ctx.PurgeQueryCache();
            var simple = ctx.From<ISimpleEntity>();
            var complex = ctx.From<IComplexEntity>();

            var twoRows = new List<(int, int?)> { (1, 10), (3, 30) };
            var oneNullRow = new List<(int, int?)> { (2, null) };

            // Same captured field (`this._joinTuples`) for both builds: the JOIN condition is unkeyed, so
            // only the flag can distinguish the two shapes.
            _joinTuples = twoRows;
            var first = Prepare(ctx, JoinFieldTuple(simple, complex));
            ParamCount(first).Should().Be(4);

            _joinTuples = oneNullRow;
            var second = Prepare(ctx, JoinFieldTuple(simple, complex));
            ParamCount(second).Should().Be(1);

            ReferenceEquals(first, second).Should().BeFalse(
                "a tuple IN in a JOIN condition is not folded into the plan key");
            ctx.ToList(second).OrderBy(x => x).Should().Equal(2);
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void TupleContains_InSelectColumn_DifferentSizes_ShouldRebuildAndReturnCurrentResult()
    {
        var (ctx, path) = CreateDb();
        try
        {
            ctx.PurgeQueryCache();
            var e = ctx.From<IComplexEntity>();

            var twoRows = new List<(long, int?)> { (1, 10), (2, 20) };
            var oneNullRow = new List<(long, int?)> { (2, null) };

            // Same captured field for both projections.
            _tuples = twoRows;
            var first = Prepare(ctx, SelectFieldTuple(e));
            ParamCount(first).Should().Be(4);

            _tuples = oneNullRow;
            var second = Prepare(ctx, SelectFieldTuple(e));
