        var command = Prepare(ctx, e
            .Where(x => SqlFunctions.Sql.@in(Tuple.Create(x.Id, x.Code), tuples))
            .Select(x => new { x.Id }));

        command.DbCommand.CommandText.Replace("\r\n", "\n")
            .Should().Contain("(id, code) in (VALUES ($p0, $p1), ($p2, $p3))");
