using System.Data.Common;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Translation of a captured collection indexed from a query (<c>dict[column]</c>): a portable
/// <c>CASE WHEN</c> over the evaluated entries, a parameter fold for a constant key, and an explicit
/// rejection outside the prepared condition. These tests only build SQL; they never open a connection.
/// </summary>
public class DictionaryLookupSqlGenerationTests
{
    private static Dictionary<int, DateTime> CapturedLookup = new()
    {
        [1] = new DateTime(2024, 1, 1),
        [2] = new DateTime(2024, 2, 1),
    };

    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd)
        => ((DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None))
            .DbCommand.CommandText.Replace("\r\n", "\n");

    [Fact]
    public void Dictionary_IndexedByColumn_ShouldEmitCase()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var sql = SqlOf(ctx, e.Where(x => CapturedLookup[x.Int!.Value] < x.Datetime).Select(x => x.Id));

        sql.Should().Be(
            "select id from complex_entity\n where (case when nullableint = $p0 then $p1 when nullableint = $p2 then $p3 end < dt)");
    }

    [Fact]
    public void Dictionary_IndexedByColumn_ShouldBindKeyValueParameters()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var prepared = (DbPreparedQueryCommand<long>)ctx.GetPreparedQueryCommand(
            e.Where(x => CapturedLookup[x.Int!.Value] < x.Datetime).Select(x => x.Id), false, false, CancellationToken.None);

        prepared.DbCommandParams.Cast<DbParameter>().Select(p => p.ParameterName).Should().Equal("p0", "p1", "p2", "p3");
        prepared.DbCommandParams[0].Value.Should().Be(1);
        prepared.DbCommandParams[1].Value.Should().Be(new DateTime(2024, 1, 1));
        prepared.DbCommandParams[2].Value.Should().Be(2);
        prepared.DbCommandParams[3].Value.Should().Be(new DateTime(2024, 2, 1));
    }

    [Fact]
    public void List_IndexedByColumn_ShouldEmitCaseOverIndices()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var lookup = new List<DateTime> { new(2024, 1, 1), new(2024, 2, 1) };
        var sql = SqlOf(ctx, e.Where(x => lookup[x.Int!.Value] < x.Datetime).Select(x => x.Id));

        sql.Should().Be(
            "select id from complex_entity\n where (case when nullableint = $p0 then $p1 when nullableint = $p2 then $p3 end < dt)");
    }

    [Fact]
    public void Dictionary_IndexedByConstant_ShouldFoldToParameter()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var prepared = (DbPreparedQueryCommand<long>)ctx.GetPreparedQueryCommand(
            e.Where(x => CapturedLookup[2] < x.Datetime).Select(x => x.Id), false, false, CancellationToken.None);

        var sql = prepared.DbCommand.CommandText.Replace("\r\n", "\n");
        sql.Should().NotContain("case");
        sql.Should().Be("select id from complex_entity\n where ($p0 < dt)");
        prepared.DbCommandParams[0].Value.Should().Be(new DateTime(2024, 2, 1));
    }

    [Fact]
    public void Dictionary_IndexedOutsideWhere_OnCacheableCommand_ShouldThrow()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var act = () => ctx.GetPreparedQueryCommand(
            e.Select(x => new { Value = CapturedLookup[x.Int!.Value] }), false, true, CancellationToken.None);

        act.Should().Throw<NotSupportedException>().WithMessage("*WHERE*");
    }

    [Fact]
    public void Dictionary_SameShape_ShouldReuseCachedPlan()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();

        var first = ctx.GetPreparedQueryCommand(
            e.Where(x => CapturedLookup[x.Int!.Value] < x.Datetime).Select(x => x.Id), false, true, CancellationToken.None);
        var second = ctx.GetPreparedQueryCommand(
            e.Where(x => CapturedLookup[x.Int!.Value] < x.Datetime).Select(x => x.Id), false, true, CancellationToken.None);

        ReferenceEquals(first, second).Should().BeTrue();
    }

    [Fact]
    public void Dictionary_IndexedByExpressionKey_ShouldKeepParametersAligned()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();
        var lookup = new Dictionary<int, int> { [1] = 10, [2] = 20 };
        var bias = 0;

        var cmd = e.Where(x => lookup[x.Int!.Value + bias] == 20).Select(x => x.Id);
        var first = (DbPreparedQueryCommand<long>)ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None);
        var second = (DbPreparedQueryCommand<long>)ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None);

        // The cache hit re-extracts parameters in parameter mode; the captured `bias` inside the key must
        // be collected there too or every parameter after it shifts (Debug.Assert in QueryPlanner).
        ReferenceEquals(first, second).Should().BeTrue();
        second.DbCommandParams.Cast<DbParameter>().Select(p => p.ParameterName).Should().Equal("bias", "p0", "p1", "p2", "p3");
        second.DbCommandParams[0].Value.Should().Be(0);
        second.DbCommandParams[1].Value.Should().Be(1);
        second.DbCommandParams[2].Value.Should().Be(10);
        second.DbCommandParams[3].Value.Should().Be(2);
        second.DbCommandParams[4].Value.Should().Be(20);
    }

    [Fact]
    public void Dictionary_PreparedWithoutHashThenCached_ShouldTranslate()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();
        var lookup = new Dictionary<int, int> { [1] = 10 };

        var cmd = e.Where(x => lookup[x.Int!.Value] == 10).Select(x => x.Id);

        // First pass without plan-cache hashing (storeInCache:false), then the same command reused through
        // the cache: the shape is folded in on reuse, so the lookup is not mistaken for an out-of-condition one.
        ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None);
        var act = () => ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None);

        act.Should().NotThrow();
    }

    [Fact]
    public void Dictionary_GrownBetweenBuilds_ShouldNotReuseStalePlan()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();
        var e = ctx.From<IComplexEntity>();

        CapturedLookup = new Dictionary<int, DateTime> { [1] = new DateTime(2024, 1, 1) };
        var first = ctx.GetPreparedQueryCommand(
            e.Where(x => CapturedLookup[x.Int!.Value] < x.Datetime).Select(x => x.Id), false, true, CancellationToken.None);

        CapturedLookup = new Dictionary<int, DateTime>
        {
            [1] = new DateTime(2024, 1, 1),
            [2] = new DateTime(2024, 2, 1),
        };
        var second = ctx.GetPreparedQueryCommand(
            e.Where(x => CapturedLookup[x.Int!.Value] < x.Datetime).Select(x => x.Id), false, true, CancellationToken.None);

        ReferenceEquals(first, second).Should().BeFalse();
        ((DbPreparedQueryCommand<long>)second).DbCommandParams.Count.Should().Be(4);
    }

    [Fact]
    public void ReadOnlyList_IndexedByColumn_ShouldEmitCase()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();
        IReadOnlyList<int> lookup = [10, 20, 30];

        var sql = SqlOf(ctx, e.Where(x => lookup[x.Int!.Value] == 20).Select(x => x.Id));

        sql.Should().Contain("case when nullableint = $p0 then $p1 when nullableint = $p2 then $p3 when nullableint = $p4 then $p5 end");
    }

    [Fact]
    public void ReadOnlyList_IndexedByConstant_ShouldFoldToParameter()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();
        IReadOnlyList<int> lookup = [10, 20, 30];

        var prepared = (DbPreparedQueryCommand<long>)ctx.GetPreparedQueryCommand(
            e.Where(x => lookup[0] == 10).Select(x => x.Id), false, false, CancellationToken.None);

        prepared.DbCommand.CommandText.Replace("\r\n", "\n").Should().NotContain("case");
        prepared.DbCommandParams[0].Value.Should().Be(10);
    }
}

using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;
using NextORM.Sqlite;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Round-trip tests for <see cref="TimeSpan"/> columns on a provider without a native duration type
/// (SQLite). The value is stored in an integer column in the unit declared by
/// <see cref="DurationAttribute"/> (ticks by default); reading, writing, nullability and comparison
/// all go through the same conversion.
/// </summary>
public class DurationColumnTests
{
    [SqlTable("duration_entity")]
    public interface IDurationEntity
    {
        [Key]
        [Column("id")]
        int Id { get; set; }

        [Column("ticks")]
        TimeSpan Ticks { get; set; }

        [Column("seconds")]
        [Duration(DurationUnit.Seconds)]
        TimeSpan Seconds { get; set; }

        [Column("nullable_ms")]
        [Duration(DurationUnit.Milliseconds)]
        TimeSpan? Nullable { get; set; }
    }

    public class DurationEntity : IDurationEntity
    {
        public int Id { get; set; }
        public TimeSpan Ticks { get; set; }
        public TimeSpan Seconds { get; set; }
        public TimeSpan? Nullable { get; set; }
    }

    private static SqliteConnection OpenConnection()
    {
        var conn = new SqliteConnection("Data Source=:memory:");
        conn.Open();
        using var setup = conn.CreateCommand();
        setup.CommandText =
            "create table duration_entity (id integer primary key, ticks bigint, seconds bigint, nullable_ms bigint);";
        setup.ExecuteNonQuery();
        return conn;
    }

    private static SqliteDataContext ContextFor(SqliteConnection connection)
        => new(connection, new DataContextBuilder());

    private static long RawLong(SqliteConnection connection, string column)
    {
        using var cmd = connection.CreateCommand();
        cmd.CommandText = $"select {column} from duration_entity where id = 1";
        return Convert.ToInt64(cmd.ExecuteScalar());
    }

    [Fact]
    public void DurationColumn_ShouldRoundTripInDeclaredUnit()
    {
        using var conn = OpenConnection();
        using var ctx = ContextFor(conn);

        var value = new TimeSpan(0, 0, 90);
        ctx.CreateInsertBuilder<IDurationEntity>()
            .Values(new DurationEntity { Id = 1, Ticks = value, Seconds = value, Nullable = TimeSpan.FromMilliseconds(1500) })
            .Insert();

        // The stored integers are the value expressed in the declared unit, not always ticks.
        RawLong(conn, "ticks").Should().Be(value.Ticks);
        RawLong(conn, "seconds").Should().Be(90);
        RawLong(conn, "nullable_ms").Should().Be(1500);

        var row = ctx.From<DurationEntity>().ToList().Single();
        row.Ticks.Should().Be(value);
        row.Seconds.Should().Be(value);
        row.Nullable.Should().Be(TimeSpan.FromMilliseconds(1500));
    }

    [Fact]
    public void DurationColumn_ShouldRoundTripNull()
    {
        using var conn = OpenConnection();
        using var ctx = ContextFor(conn);

        ctx.CreateInsertBuilder<IDurationEntity>()
            .Values(new DurationEntity { Id = 1, Ticks = TimeSpan.Zero, Seconds = TimeSpan.Zero, Nullable = null })
            .Insert();

        using var raw = conn.CreateCommand();
        raw.CommandText = "select nullable_ms from duration_entity where id = 1";
        raw.ExecuteScalar().Should().Be(DBNull.Value);

        ctx.From<DurationEntity>().ToList().Single().Nullable.Should().BeNull();
    }

    [Fact]
    public void DurationColumn_ShouldCompareAgainstConstant()
    {
        using var conn = OpenConnection();
        using var ctx = ContextFor(conn);

        ctx.CreateInsertBuilder<IDurationEntity>()
            .Values([
                new DurationEntity { Id = 1, Ticks = TimeSpan.FromSeconds(30), Seconds = TimeSpan.FromSeconds(30) },
                new DurationEntity { Id = 2, Ticks = TimeSpan.FromSeconds(120), Seconds = TimeSpan.FromSeconds(120) },
            ])
            .Insert();

        ctx.From<IDurationEntity>().Where(x => x.Seconds > TimeSpan.FromSeconds(60)).Select(x => x.Id).ToList()
            .Should().Equal(2);

        // The constant may appear on either side of the comparison.
        ctx.From<IDurationEntity>().Where(x => TimeSpan.FromSeconds(60) < x.Seconds).Select(x => x.Id).ToList()
            .Should().Equal(2);
    }

    [Fact]
    public void DurationColumn_ShouldCompareAgainstCapturedVariable()
    {
        using var conn = OpenConnection();
        using var ctx = ContextFor(conn);

        ctx.CreateInsertBuilder<IDurationEntity>()
            .Values([
                new DurationEntity { Id = 1, Ticks = TimeSpan.FromSeconds(30), Seconds = TimeSpan.FromSeconds(30) },
                new DurationEntity { Id = 2, Ticks = TimeSpan.FromSeconds(120), Seconds = TimeSpan.FromSeconds(120) },
            ])
            .Insert();

        var threshold = TimeSpan.FromSeconds(60);
        ctx.From<IDurationEntity>().Where(x => x.Seconds >= threshold).Select(x => x.Id).ToList()
            .Should().Equal(2);
    }

    [Fact]
    public void DurationColumn_ShouldRoundTripNegativeValue()
    {
        using var conn = OpenConnection();
        using var ctx = ContextFor(conn);

        var value = TimeSpan.FromSeconds(-45);
        ctx.CreateInsertBuilder<IDurationEntity>()
            .Values(new DurationEntity { Id = 1, Ticks = value, Seconds = value })
            .Insert();

        RawLong(conn, "seconds").Should().Be(-45);
        ctx.From<DurationEntity>().ToList().Single().Seconds.Should().Be(value);
    }

    [Fact]
    public void ScalarProjection_ShouldReadInDeclaredUnit()
    {
        using var conn = OpenConnection();
        using var ctx = ContextFor(conn);

        ctx.CreateInsertBuilder<IDurationEntity>()
            .Values(new DurationEntity { Id = 1, Ticks = TimeSpan.FromSeconds(90), Seconds = TimeSpan.FromSeconds(90) })
            .Insert();

        ctx.From<IDurationEntity>().Select(x => x.Seconds).ToList().Single().Should().Be(TimeSpan.FromSeconds(90));
    }
}

using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;
using NextORM.Sqlite;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// A value converter owns its provider representation: a converter to <see cref="TimeSpan"/> is applied
/// as-is, without the integer duration normalization a bare <see cref="TimeSpan"/> property gets. SQLite
/// has no native duration type, so the driver stores the converted value in its own time-of-day form; the
/// round-trip below pins that the converter contract is not silently reduced to a duration unit.
/// </summary>
public sealed class IntToDurationConverter : ValueConverter<int, TimeSpan>
{
    public override TimeSpan ConvertToProvider(int model) => TimeSpan.FromSeconds(model);

    public override int ConvertFromProvider(TimeSpan provider) => (int)provider.TotalSeconds;
}

[SqlTable("converter_duration_entity")]
public interface IConverterDurationEntity
{
    [Key]
    [Column("id")]
    int Id { get; set; }

    [Column("elapsed")]
    [ValueConverter(typeof(IntToDurationConverter))]
    int Elapsed { get; set; }
}

public sealed class ConverterDurationEntity : IConverterDurationEntity
{
    public int Id { get; set; }
    public int Elapsed { get; set; }
}

public class DurationConverterTests
{
    [Fact]
    public void ConverterToTimeSpan_ShouldRoundTripInsertSelectPredicate()
    {
        using var conn = new SqliteConnection("Data Source=:memory:");
        conn.Open();
        using (var setup = conn.CreateCommand())
        {
            setup.CommandText = "create table converter_duration_entity (id integer primary key, elapsed bigint);";
            setup.ExecuteNonQuery();
        }

        using var ctx = new SqliteDataContext(conn, new DataContextBuilder());

        ctx.CreateInsertBuilder<IConverterDurationEntity>()
            .Values(new ConverterDurationEntity { Id = 1, Elapsed = 90 })
            .Insert();
        ctx.CreateInsertBuilder<IConverterDurationEntity>()
            .Values(new ConverterDurationEntity { Id = 2, Elapsed = 30 })
            .Insert();

        var row = ctx.From<ConverterDurationEntity>().Where(x => x.Id == 1).ToList().Single();
        row.Elapsed.Should().Be(90);

        var filtered = ctx.From<ConverterDurationEntity>().Where(x => x.Elapsed >= 60).Select(x => x.Id).ToList();
        filtered.Should().Equal(1);

        var reversed = ctx.From<ConverterDurationEntity>().Where(x => 60 <= x.Elapsed).Select(x => x.Id).ToList();
        reversed.Should().Equal(1);
    }
}

using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.ClickHouse;
using NextORM.Core;
using NextORM.Sqlite;
namespace NextORM.Sqlite.Tests;

/// <summary>
/// Exercises the read side of the dynamic-columns store against a real (temp-file) SQLite database: the
/// generated <c>SELECT</c> appends the source's <c>*</c> and the store receives every column that is not
/// mapped to a declared member.
/// </summary>
public class DynamicColumnsTests
{
    private static (IDataContext Ctx, string Path) CreateDb()
    {
        var path = Path.Combine(Path.GetTempPath(), $"nextorm-dynamic-{Guid.NewGuid():N}.db");
        using (var conn = new SqliteConnection($"Data Source={path}"))
        {
            conn.Open();
            using var cmd = conn.CreateCommand();
            cmd.CommandText = "create table dynamic_entity (id integer primary key, name text, age integer, city text);" +
                              "insert into dynamic_entity (id, name, age, city) values (1, 'Ann', 30, 'NY');" +
                              "insert into dynamic_entity (id, name, age, city) values (2, 'Bob', null, 'LA');" +
                              "create table dynamic_write_entity (id integer primary key, name text, age integer default 99, city text);" +
                              "create table range_dynamic_write_entity (id integer primary key, during_lower integer, during_upper integer, \"During\" integer);";
            cmd.ExecuteNonQuery();
        }

        var ctx = new SqliteDataContext($"Data Source={path}", new DataContextBuilder());
        ctx.EnsureConnectionOpen();
        return (ctx, path);
    }

    [Fact]
    public void ReadEntity_WithDynamicColumnsStore_ShouldCollectUnmappedColumns()
    {
        var (ctx, path) = CreateDb();
        try
        {
            var rows = ctx.From<DynamicColumnsEntity>().ToList();

            rows.Should().HaveCount(2);

            var ann = rows.Single(x => x.Id == 1);
            ann.Name.Should().Be("Ann");
            ann.Extra.Should().ContainKey("age").WhoseValue.Should().Be(30L);
            ann.Extra.Should().ContainKey("city").WhoseValue.Should().Be("NY");
            ann.Extra.Should().NotContainKey("id");
            ann.Extra.Should().NotContainKey("name");

            var bob = rows.Single(x => x.Id == 2);
            bob.Extra.Should().ContainKey("age").WhoseValue.Should().BeNull();
            bob.Extra.Should().ContainKey("city").WhoseValue.Should().Be("LA");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void ReadEntity_WithDynamicColumnsStore_ShouldGenerateStar()
    {
        using var ctx = SqliteTestContext.Create();
        var sql = ((DbPreparedQueryCommand<DynamicColumnsEntity>)ctx.GetPreparedQueryCommand(
            ctx.From<DynamicColumnsEntity>().ToCommand(), false, false, CancellationToken.None)).DbCommand.CommandText;

        sql.Replace("\r\n", "\n").Should().Be("select id, name, * from dynamic_entity");
    }

    [Fact]
    public void OtherDialects_DynamicSql_Unchanged()
    {
        // Regression guard for the MySQL-only qualification: SQLite keeps the bare star and no alias.
        using var ctx = SqliteTestContext.Create();
        var sql = ((DbPreparedQueryCommand<DynamicColumnsEntity>)ctx.GetPreparedQueryCommand(
            ctx.From<DynamicColumnsEntity>().ToCommand(), false, false, CancellationToken.None)).DbCommand.CommandText;

        sql.Replace("\r\n", "\n").Should().Be("select id, name, * from dynamic_entity");
    }

    [Fact]
    public void ReadEntity_WithDynamicColumnsStore_ShouldSupportTerminals()
    {
        var (ctx, path) = CreateDb();
        try
        {
            ctx.From<DynamicColumnsEntity>().Any().Should().BeTrue();
            ctx.From<DynamicColumnsEntity>().Count().Should().Be(2);

            var first = ctx.From<DynamicColumnsEntity>().OrderBy(x => x.Id).First();
            first.Id.Should().Be(1);
            first.Extra.Should().ContainKey("city").WhoseValue.Should().Be("NY");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void ReadEntity_WithDynamicColumnsStore_Quoted_ShouldQuoteMappedColumnsOnly()
    {
        using var ctx = SqliteTestContext.CreateQuoted();
        var sql = ((DbPreparedQueryCommand<DynamicColumnsEntity>)ctx.GetPreparedQueryCommand(
            ctx.From<DynamicColumnsEntity>().ToCommand(), false, false, CancellationToken.None)).DbCommand.CommandText;

        sql.Replace("\r\n", "\n").Should().Be("select \"id\", \"name\", * from \"dynamic_entity\"");
    }

    [Fact]
    public void ReadEntity_WithFluentDynamicColumnsStore_ShouldCollectUnmappedColumns()
    {
        var (ctx, path) = CreateDb();
        try
        {
            var entity = ctx.From<FluentDynamicEntity>((EntityMetadataBuilder<FluentDynamicEntity> b) =>
            {
                b.Property(x => x.Id).Key().HasColumnName("id");
                b.Property(x => x.Extra).DynamicColumnsStore();
            });

            var rows = entity.ToList();

            rows.Should().HaveCount(2);
            var ann = rows.Single(x => x.Id == 1);
            ann.Extra.Should().ContainKey("name").WhoseValue.Should().Be("Ann");
            ann.Extra.Should().ContainKey("age").WhoseValue.Should().Be(30L);
            ann.Extra.Should().NotContainKey("id");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void ReadEntity_WithDynamicColumnsStore_JoinedQueryAfterCachedSelectList_ShouldThrow()
    {
        using var ctx = SqliteTestContext.Create();

        // Warm the whole-entity select list cache for the dynamic-columns entity with a non-join query.
        // The join guard must run before the cache lookup, so the cached (store-bearing) select list is
        // still rejected instead of silently reused for a joined query.
        _ = ctx.GetPreparedQueryCommand(
            ctx.From<DynamicColumnsEntity>().ToCommand(), false, false, CancellationToken.None);

        var joined = ctx.From<DynamicColumnsEntity>()
            .SemiJoin(ctx.From<ISimpleEntity>(), (e, s) => e.Id == s.Id);

        var act = () => ctx.GetPreparedQueryCommand(joined.ToCommand(), false, false, CancellationToken.None);

        act.Should().Throw<NotSupportedException>().WithMessage("*single physical source*");
    }

    [Fact]
    public void WriteEntity_InsertDynamicColumns_ShouldWriteColumnsOrdinalSortedAndReadBack()
    {
        var (ctx, path) = CreateDb();
        try
        {
            var entity = new DynamicWriteEntity { Id = 1, Name = "Ann" };
            // Insert in reverse ordinal order: "city" before "age"; the set is ordinal-sorted to age, city.
            entity.Extra["city"] = "NY";
            entity.Extra["age"] = 30;

            ctx.CreateInsertBuilder<DynamicWriteEntity>()
                .Values(entity)
                .ToSql()
                .Should().Be("insert into dynamic_write_entity (id, name, \"age\", \"city\") values ($p0, $p1, $p2, $p3)");

            ctx.CreateInsertBuilder<DynamicWriteEntity>().Values(entity).Insert().Should().Be(1);

            var read = ctx.From<DynamicWriteEntity>().ToList().Single(x => x.Id == 1);
            read.Name.Should().Be("Ann");
            read.Extra.Should().ContainKey("age").WhoseValue.Should().Be(30L);
            read.Extra.Should().ContainKey("city").WhoseValue.Should().Be("NY");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void WriteEntity_InsertDynamicColumns_PresentNullKeyShouldStoreNull()
