    [Fact]
    public void DirectEntityItem_FirstSlot_ShouldSelectOnlyRequestedEntityColumns()
    {
        var (ctx, path) = CreateDb();
        try
        {
            var sql = SqlOf(ctx, ctx.From<EntityItemParent>()
                .LeftJoin(ctx.From<EntityItemChild>(), (p, c) => p.Id == c.ParentId)
