using System.Data.Common;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;
using NextORM.Sqlite;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Behavioural coverage for the Phase 1 interceptors against a real SQLite database: the command
/// lifecycle events, the bound parameters visible to an interceptor, the failure path and the
/// connection lifecycle.
/// </summary>
public class InterceptorTests
{
    private sealed class RecordingQueryInterceptor : IQueryInterceptor
    {
        public List<string> Events { get; } = [];
        public CommandEventData LastEventData { get; private set; }
        public DbCommand? LastCommand { get; private set; }
        public TimeSpan LastElapsed { get; private set; }
        public Exception? Failure { get; private set; }

        public void CommandInitialized(CommandEventData eventData, DbCommand command)
        {
            Events.Add("initialized");
            LastEventData = eventData;
            LastCommand = command;
        }

        public void CommandExecuting(CommandEventData eventData, DbCommand command)
        {
            Events.Add("executing");
            LastEventData = eventData;
            LastCommand = command;
        }

        public void CommandExecuted(CommandEventData eventData, DbCommand command, TimeSpan elapsed)
        {
            Events.Add("executed");
            LastEventData = eventData;
            LastCommand = command;
            LastElapsed = elapsed;
        }

        public void CommandFailed(CommandEventData eventData, DbCommand command, Exception exception)
        {
            Events.Add("failed");
            LastEventData = eventData;
            LastCommand = command;
            Failure = exception;
        }
    }

    private sealed class RecordingConnectionInterceptor : IConnectionInterceptor
    {
        public List<string> Events { get; } = [];
        public ConnectionEventData LastEventData { get; private set; }

        public void ConnectionOpening(ConnectionEventData eventData)
        {
            Events.Add("opening");
            LastEventData = eventData;
        }

        public void ConnectionOpened(ConnectionEventData eventData)
        {
            Events.Add("opened");
            LastEventData = eventData;
        }
    }

    private sealed class OrderProbe : IQueryInterceptor
    {
        private readonly string _name;
        private readonly List<string> _log;

        public OrderProbe(string name, List<string> log)
        {
            _name = name;
            _log = log;
        }

        public void CommandExecuting(CommandEventData eventData, DbCommand command) => _log.Add(_name);
    }

    // A second, distinct interceptor type: registration is deduplicated by runtime type (#221 A1), so
    // two instances of the same type would collapse to the first one.
    private sealed class OrderProbe2 : IQueryInterceptor
    {
        private readonly string _name;
        private readonly List<string> _log;

        public OrderProbe2(string name, List<string> log)
        {
            _name = name;
            _log = log;
        }

        public void CommandExecuting(CommandEventData eventData, DbCommand command) => _log.Add(_name);
    }

    private static (SqliteDataContext Ctx, string Path) CreateDb(DataContextBuilder? builder = null)
    {
        var path = Path.Combine(Path.GetTempPath(), $"nextorm-interceptors-{Guid.NewGuid():N}.db");
        using (var conn = new SqliteConnection($"Data Source={path}"))
        {
            conn.Open();
            using var cmd = conn.CreateCommand();
            cmd.CommandText = "create table simple_entity (id integer primary key);" +
                              "insert into simple_entity (id) values (42);" +
                              "insert into simple_entity (id) values (43);";
            cmd.ExecuteNonQuery();
        }

        return (new SqliteDataContext($"Data Source={path}", builder ?? new DataContextBuilder()), path);
    }

    [Fact]
    public void BuilderInterceptor_RecordsCommandLifecycleInOrder()
    {
        var interceptor = new RecordingQueryInterceptor();
        var (ctx, path) = CreateDb(new DataContextBuilder().AddInterceptor(interceptor));
        try
        {
            ctx.PurgeQueryCache();

            var ids = ctx.From<ISimpleEntity>().Select(x => x.Id).ToList();

            ids.Should().Equal(42, 43);
            interceptor.Events.Should().Equal("initialized", "executing", "executed");
            interceptor.LastEventData.DataContext.Should().BeSameAs(ctx);
            interceptor.LastEventData.Sql.Should().NotBeNullOrEmpty();
            interceptor.LastCommand.Should().NotBeNull();
            interceptor.LastElapsed.Should().BeGreaterThanOrEqualTo(TimeSpan.Zero);
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void Interceptor_SeesBoundParameters()
    {
        var interceptor = new RecordingQueryInterceptor();
        var (ctx, path) = CreateDb(new DataContextBuilder().AddInterceptor(interceptor));
        try
        {
            ctx.PurgeQueryCache();
            var id = 43;

            var ids = ctx.From<ISimpleEntity>().Where(x => x.Id == id).Select(x => x.Id).ToList();

            ids.Should().Equal(43);
            interceptor.LastCommand!.Parameters.Count.Should().Be(1);
            Convert.ToInt32(interceptor.LastCommand!.Parameters[0].Value).Should().Be(43);
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void Interceptors_AreInvokedInRegistrationOrder()
    {
        var log = new List<string>();
        var builder = new DataContextBuilder()
            .AddInterceptor(new OrderProbe("first", log))
            .AddInterceptor(new OrderProbe2("second", log));
        var (ctx, path) = CreateDb(builder);
        try
        {
            ctx.PurgeQueryCache();

            ctx.From<ISimpleEntity>().Select(x => x.Id).ToList();

            log.Should().Equal("first", "second");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void PerInstanceAddInterceptor_RecordsCommandLifecycle()
    {
        var interceptor = new RecordingQueryInterceptor();
        var (ctx, path) = CreateDb();
        try
        {
            ctx.AddInterceptor(interceptor);
            ctx.PurgeQueryCache();

            ctx.From<ISimpleEntity>().Select(x => x.Id).ToList();

            interceptor.Events.Should().ContainInOrder("initialized", "executing", "executed");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void CommandFailed_IsRaisedOnProviderError()
    {
        var interceptor = new RecordingQueryInterceptor();
        using var supplied = new SqliteConnection("Data Source=:memory:");
        supplied.Open();
        using var ctx = new SqliteDataContext(supplied, new DataContextBuilder().AddInterceptor(interceptor));
        ctx.PurgeQueryCache();

        // The entity is mapped, but the database has no such table: planning succeeds, execution throws.
        var act = () => ctx.From<ISimpleEntity>().Select(x => x.Id).ToList();

        act.Should().Throw<SqliteException>();
        interceptor.Events.Should().Equal("initialized", "executing", "failed");
        interceptor.Failure.Should().BeOfType<SqliteException>();
    }

    [Fact]
    public async Task Streaming_RaisesCommandLifecycleEvents()
    {
        var interceptor = new RecordingQueryInterceptor();
        var (ctx, path) = CreateDb(new DataContextBuilder().AddInterceptor(interceptor));
        try
        {
            ctx.PurgeQueryCache();

            var ids = new List<int>();
            await foreach (var id in ctx.From<ISimpleEntity>().Select(x => x.Id).ToAsyncEnumerable(TestContext.Current.CancellationToken))
                ids.Add(id);

            ids.Should().Equal(42, 43);
            interceptor.Events.Should().Equal("initialized", "executing", "executed");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public async Task AsyncTerminal_RaisesCommandLifecycleEvents()
    {
        var interceptor = new RecordingQueryInterceptor();
        var (ctx, path) = CreateDb(new DataContextBuilder().AddInterceptor(interceptor));
        try
        {
            ctx.PurgeQueryCache();

            var ids = await ctx.From<ISimpleEntity>().Select(x => x.Id).ToListAsync(TestContext.Current.CancellationToken);

            ids.Should().Equal(42, 43);
            interceptor.Events.Should().Equal("initialized", "executing", "executed");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void ConnectionInterceptor_RaisesOpeningAndOpenedOnce()
    {
        var interceptor = new RecordingConnectionInterceptor();
        var (ctx, path) = CreateDb(new DataContextBuilder().AddInterceptor(interceptor));
        try
        {
            ctx.EnsureConnectionOpen();

            interceptor.Events.Should().Equal("opening", "opened");
            interceptor.LastEventData.DataContext.Should().BeSameAs(ctx);
            interceptor.LastEventData.Connection.Should().BeSameAs(ctx.GetConnection());

            ctx.EnsureConnectionOpen();

            interceptor.Events.Should().Equal("opening", "opened");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public async Task ConnectionInterceptor_RaisesOpeningAndOpenedOnAsyncOpen()
    {
        var interceptor = new RecordingConnectionInterceptor();
        var (ctx, path) = CreateDb(new DataContextBuilder().AddInterceptor(interceptor));
        try
        {
            await ctx.EnsureConnectionOpenAsync(TestContext.Current.CancellationToken);

            interceptor.Events.Should().Equal("opening", "opened");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void NoInterceptors_ContextStillExecutes()
    {
        var (ctx, path) = CreateDb();
        try
        {
            ctx.PurgeQueryCache();

            ctx.From<ISimpleEntity>().Select(x => x.Id).ToList().Should().Equal(42, 43);
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }
}

using System.Data.Common;
using FluentAssertions;
using NextORM.Core;
using NextORM.Generated.nextorm_sqlite_tests;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// SQL-generation coverage for the generated join-alias projection on SQLite: every supported
/// operator must forward the matching <see cref="JoinType"/> and render the same SQL as the
/// positional join, a repeated CLR type must resolve to distinct slots, and CROSS/OUTER APPLY must
/// fail closed because SQLite has no lateral source.
/// </summary>
public class JoinAliasSqlGenerationTests
{
    private static string Normalize(string sql) => sql.Replace("\r\n", "\n");

    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd)
        => Normalize(((DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None)).DbCommand.CommandText);

    [Fact]
    public void Inner_alias_join_emits_join_and_matches_positional()
    {
        using var ctx = SqliteTestContext.Create();
        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();

        var positional = SqlOf(ctx, simple.Join(complex, (s, c) => s.Id == c.Id).Select(p => p.Item2.Id));
        var alias = SqlOf(ctx, simple.Join<IComplexEntity>(complex, (s, c) => s.Id == c.Id, Alias.Buyer).Select(p => p.Buyer.Id));

        alias.Should().Be(positional);
        alias.Should().Contain(" join complex_entity");
    }

    [Fact]
    public void Left_alias_join_emits_left_join_and_matches_positional()
    {
        using var ctx = SqliteTestContext.Create();
        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();

        var positional = SqlOf(ctx, simple.LeftJoin(complex, (s, c) => s.Id == c.Id).Select(p => p.Item2.Id));
        var alias = SqlOf(ctx, simple.LeftJoin<IComplexEntity>(complex, (s, c) => s.Id == c.Id, Alias.Buyer).Select(p => p.Buyer.Id));

        alias.Should().Be(positional);
        alias.Should().Contain(" left join complex_entity");
    }

    [Fact]
    public void Right_alias_join_emits_right_join_and_matches_positional()
    {
        using var ctx = SqliteTestContext.Create();
        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();

        var positional = SqlOf(ctx, simple.RightJoin(complex, (s, c) => s.Id == c.Id).Select(p => p.Item2.Id));
        var alias = SqlOf(ctx, simple.RightJoin<IComplexEntity>(complex, (s, c) => s.Id == c.Id, Alias.Buyer).Select(p => p.Buyer.Id));

        alias.Should().Be(positional);
        alias.Should().Contain(" right join complex_entity");
    }

    [Fact]
    public void Full_alias_join_emits_full_join_and_matches_positional()
    {
        using var ctx = SqliteTestContext.Create();
        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();

        var positional = SqlOf(ctx, simple.FullJoin(complex, (s, c) => s.Id == c.Id).Select(p => p.Item2.Id));
        var alias = SqlOf(ctx, simple.FullJoin<IComplexEntity>(complex, (s, c) => s.Id == c.Id, Alias.Buyer).Select(p => p.Buyer.Id));

        alias.Should().Be(positional);
        alias.Should().Contain(" full join complex_entity");
    }

    [Fact]
    public void Cross_alias_join_emits_cross_join_and_matches_positional()
    {
        using var ctx = SqliteTestContext.Create();
        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();

        var positional = SqlOf(ctx, simple.CrossJoin(complex).Select(p => p.Item2.Id));
        var alias = SqlOf(ctx, simple.CrossJoin(complex, Alias.Buyer).Select(p => p.Buyer.Id));

        alias.Should().Be(positional);
        alias.Should().Contain(" cross join complex_entity");
    }

    [Fact]
    public void Repeated_clr_type_resolves_to_distinct_slots()
    {
        using var ctx = SqliteTestContext.Create();
        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();

        var chained = simple
            .Join<IComplexEntity>(complex, (a, b) => a.Id == b.Id, Alias.First)
            .Join<IComplexEntity>(complex, (a, b) => a.Item1.Id == b.Id, Alias.Second);

        var firstSql = SqlOf(ctx, chained.Select(p => p.First.Id));
        var secondSql = SqlOf(ctx, chained.Select(p => p.Second.Id));

        firstSql.Should().Contain("select t2.id");
        secondSql.Should().Contain("select t3.id");
        firstSql.Should().NotBe(secondSql);
    }

    [Fact]
    public void CrossApply_alias_join_fails_closed_because_sqlite_has_no_lateral()
    {
        using var ctx = SqliteTestContext.Create();
        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();

        var act = () => SqlOf(ctx, simple.CrossApply(complex, Alias.Buyer).Select(p => p.Buyer.Id));

        act.Should().Throw<NotSupportedException>().WithMessage("*CrossApply*");
    }

    [Fact]
    public void OuterApply_alias_join_fails_closed_because_sqlite_has_no_lateral()
    {
        using var ctx = SqliteTestContext.Create();
        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();

        var act = () => SqlOf(ctx, simple.OuterApply(complex, Alias.Buyer).Select(p => p.Buyer.Id));

        act.Should().Throw<NotSupportedException>().WithMessage("*OuterApply*");
    }

    // ---------------------------------------------------------------------------------------------
    // #160 root alias: '.WithAlias(Alias.Root)' names slot 1 for every root source and preserves the
    // source state; a later alias join becomes slot 2 (t1/t2 in the join condition).
    // ---------------------------------------------------------------------------------------------

    [Fact]
    public void Root_alias_with_a_join_maps_root_to_t1_and_join_to_t2()
    {
        using var ctx = SqliteTestContext.Create();
        var rooted = ctx.From<ISimpleEntity>().WithAlias(Alias.Root);
        var complex = ctx.From<IComplexEntity>();

        var sql = SqlOf(ctx, rooted.Join<IComplexEntity>(complex, (s, c) => s.Root.Id == c.Id, Alias.Buyer).Select(p => p.Buyer.Id));

        sql.Should().Contain("as 't1'");
        sql.Should().Contain("as 't2'");
        sql.Should().Contain("on cast(t1.id as bigint) = t2.id");
    }

    [Fact]
    public void Root_alias_on_a_fromsql_source_keeps_the_derived_source()
    {
        using var ctx = SqliteTestContext.Create();
        var rooted = ctx.FromSql("select id from simple_entity").WithAlias(Alias.Root);
        var complex = ctx.From<IComplexEntity>();

        var sql = SqlOf(ctx, rooted.Join<IComplexEntity>(complex, (s, c) => s.Root.GetInt64("id") == c.Id, Alias.Buyer).Select(p => p.Buyer.Id));

        sql.Should().Contain("(select id from simple_entity) as 't1'");
        sql.Should().NotContain("simple_entity as 't1'");
    }

    [Fact]
    public void Root_alias_on_a_builder_source_keeps_the_derived_source()
    {
        using var ctx = SqliteTestContext.Create();
        var builder = ctx.From<ISimpleEntity>();
        var rooted = ctx.From(builder).WithAlias(Alias.Root);
        var complex = ctx.From<IComplexEntity>();

        var sql = SqlOf(ctx, rooted.Join<IComplexEntity>(complex, (s, c) => s.Root.Id == c.Id, Alias.Buyer).Select(p => p.Buyer.Id));

        sql.Should().Contain(") as 't1'");
        sql.Should().Contain("from simple_entity");
        sql.Should().NotContain("simple_entity as 't1'");
    }

    [Fact]
    public void Root_alias_on_a_query_command_source_keeps_the_derived_query()
    {
        using var ctx = SqliteTestContext.Create();
        var source = ctx.From<ISimpleEntity>().Where(s => s.Id == 1).ToCommand();
        var rooted = ctx.From(source).WithAlias(Alias.Root);
        var complex = ctx.From<IComplexEntity>();

        var sql = SqlOf(ctx, rooted.Join<IComplexEntity>(complex, (s, c) => s.Root.Id == c.Id, Alias.Buyer).Select(p => p.Buyer.Id));

        sql.Should().Contain("where id = 1");
        sql.Should().Contain(") as 't1'");
        sql.Should().NotContain("simple_entity as 't1'");
    }

    [Fact]
    public void Root_alias_is_rejected_when_the_receiver_already_has_a_join()
    {
        using var ctx = SqliteTestContext.Create();
        var joined = ctx.From<ISimpleEntity>().Join(ctx.From<IComplexEntity>(), (s, c) => s.Id == c.Id);

        Action act = () => joined.AliasRoot<AliasJoin_A1_Root<ISimpleEntity>, AliasProjection_A1_Root<ISimpleEntity>>(
            static dc => new AliasJoin_A1_Root<ISimpleEntity>(dc));

        act.Should().Throw<NotSupportedException>().WithMessage("*before any Join*");
    }
}

using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Regression tests for the SQL execution of <c>JoinInto</c> stitching (#105): the child dedup of a
/// cartesian join must use the entity's composite key, and parent deduplication must use the parent's
/// own identity rather than the first declaration's key.
/// </summary>
public class JoinIntoCartesianDedupTests
{
    private static (SqliteDataContext Ctx, string Path) CreateDb(string schema)
    {
        var path = Path.Combine(Path.GetTempPath(), $"nextorm-joininto-dedup-{Guid.NewGuid():N}.db");
        using (var conn = new SqliteConnection($"Data Source={path}"))
        {
            conn.Open();
            using var cmd = conn.CreateCommand();
            cmd.CommandText = schema;
            cmd.ExecuteNonQuery();
        }

        var ctx = new SqliteDataContext($"Data Source={path}", new DataContextBuilder());
        ctx.EnsureConnectionOpen();
        return (ctx, path);
    }

    [Fact]
    public void CartesianJoin_WithCompositeChildKey_ShouldNotDuplicateChildren()
    {
        var (ctx, path) = CreateDb(
            "create table dedup_parent (id integer primary key, name text);" +
            "create table dedup_child (a integer, b integer, parent_id integer, name text, primary key (a, b));" +
            "create table dedup_note (id integer primary key, parent_id integer, text text);" +
            "insert into dedup_parent (id, name) values (1, 'p1');" +
            "insert into dedup_child (a, b, parent_id, name) values (1, 1, 1, 'c1'), (2, 1, 1, 'c2');" +
            "insert into dedup_note (id, parent_id, text) values (100, 1, 'n1'), (101, 1, 'n2');");
        try
        {
            var parents = ctx.From<DedupParent>(b => b
                    .HasMany(p => p.Children, c => c.ParentId)
                    .HasMany(p => p.Notes, n => n.ParentId))
                .JoinInto(ctx.From<DedupChild>(), (p, c) => p.Id == c.ParentId, p => p.Children)
                .JoinInto(ctx.From<DedupNote>(), (p, n) => p.Id == n.ParentId, p => p.Notes)
                .ToList();

            parents.Should().HaveCount(1);
            parents[0].Children.Select(c => c.A).Should().Equal(new[] { 1, 2 }, "the cartesian join must not repeat composite-keyed children");
            parents[0].Notes.Select(n => n.Id).Should().Equal(100, 101);
        }
        finally { ctx.Dispose(); File.Delete(path); }
    }

    [Fact]
    public void ExplicitKeyJoin_WithNonUniqueSpecKey_ShouldKeepDistinctParents()
    {
        var (ctx, path) = CreateDb(
            "create table parent_dup (id integer primary key, name text);" +
            "create table child_dup (id integer primary key, parent_id integer, name text);" +
            "insert into parent_dup (id, name) values (1, 'dup'), (2, 'dup');" +
            "insert into child_dup (id, parent_id, name) values (10, 1, 'dup');");
        try
        {
            var parents = ctx.From<ParentDup>(b => b.HasMany(p => p.Children, c => c.ParentId))
                .JoinInto(ctx.From<ChildDup>(), (p, c) => p.Name == c.Name, p => p.Children, p => p.Name, c => c.Name)
                .ToList();

            parents.Should().HaveCount(2, "parents are identified by their own key, not by the first declaration's non-unique key");
        }
        finally { ctx.Dispose(); File.Delete(path); }
    }
}

