    private static byte[] PreloadSentinel(out MemoryStream stream)
    {
        stream = new MemoryStream();
        stream.Write([0x53, 0x45, 0x4E, 0x54, 0x49, 0x4E, 0x45, 0x4C]); // "SENTINEL"
        return stream.ToArray();
    }

