            prepared.ToList(ctx).Should().Equal(42);

            var first = prepared.ToList(ctx);
            var second = ctx.From<ISimpleEntity>().Select(x => x.Id).ToList();

            first.Should().Equal(second);
            second.Should().Equal(42);
        }
        finally
        {
