    /// <summary>
    /// The renderable subset used for the end-to-end cache test. Features SQLite cannot render (PIVOT,
    /// xml.nodes, ...) are exercised by the comparer matrix above and by the provider test suites; here
    /// the plan cache itself must never hand one variant the SQL generated for another.
    /// </summary>
    public static IEnumerable<(string Name, Func<IDataContext, QueryCommand> Build)> RenderableVariants()
    {
        yield return ("base", ctx => Row(E(ctx)));
        yield return ("where", ctx => Row(E(ctx).Where(x => x.Id > 0)));
        yield return ("where-other", ctx => Row(E(ctx).Where(x => x.Id > 1)));
        yield return ("distinct", ctx => Row(E(ctx).Distinct()));
        yield return ("orderby", ctx => Row(E(ctx).OrderBy(x => x.Id)));
        yield return ("orderby-desc", ctx => Row(E(ctx).OrderByDescending(x => x.Id)));
        yield return ("paging", ctx => Row(E(ctx).Limit(3).Offset(2)));
        yield return ("group", ctx => Row(E(ctx).GroupBy(x => x.Int)));
        yield return ("having", ctx => Row(E(ctx).GroupBy(x => x.Int).Having(x => SqlFunctions.Sql.count() > 1)));
        yield return ("join", ctx => E(ctx).Join(ctx.From<ISimpleEntity>(), (a, b) => a.Id == b.Id)
            .Select(p => new PKRow { Id = p.Item1.Id, Int = p.Item2.Id }));
        yield return ("join-other", ctx => E(ctx).LeftJoin(ctx.From<ISimpleEntity>(), (a, b) => a.Id == b.Id)
            .Select(p => new PKRow { Id = p.Item1.Id, Int = p.Item2.Id }));
        yield return ("union", ctx => E(ctx).Select(x => new PKRow { Id = x.Id, Int = x.Int }).Union(E(ctx).Select(x => new PKRow { Id = x.Id, Int = x.Int })));
        yield return ("intersect", ctx => E(ctx).Select(x => new PKRow { Id = x.Id, Int = x.Int }).Intersect(E(ctx).Select(x => new PKRow { Id = x.Id, Int = x.Int })));
        yield return ("except", ctx => E(ctx).Select(x => new PKRow { Id = x.Id, Int = x.Int }).Except(E(ctx).Select(x => new PKRow { Id = x.Id, Int = x.Int })));
        yield return ("derived", ctx => ctx.From(E(ctx).Select(x => new PKRow { Id = x.Id, Int = x.Int }))
            .Select(t => new PKRow { Id = t.Id, Int = t.Int }));
        yield return ("cte", ctx => ctx.With("c", E(ctx).Select(x => new PKRow { Id = x.Id, Int = x.Int }))
            .From("c").Select(t => new PKRow { Id = t.GetNullableInt64("Id"), Int = t.GetNullableInt32("Int") }));
        yield return ("window", ctx => Row(E(ctx).Window("w", orderBy: [E(ctx).Asc(x => x.Id)])));
        yield return ("tvf", ctx => ctx.FromTableFunction(() => PkTvf.Rows()).Select(r => new PKRow { Id = r.Id, Int = r.Int }));
    }

    [Fact]
    public void PlanCache_ShouldNeverReturnAnotherVariantsSql()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();

        // First pass: generate each variant's own SQL without touching the cache.
        var ownSql = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var (name, build) in RenderableVariants())
        {
            var prepared = (DbPreparedQueryCommand<PKRow>)ctx.GetPreparedQueryCommand(
                (QueryCommand<PKRow>)build(ctx), false, false, CancellationToken.None);
            ownSql[name] = prepared.DbCommand.CommandText;
        }

        // Second pass: run through the cache. If two variants collided, the second would receive the
        // first's cached command and therefore the first's SQL.
        foreach (var (name, build) in RenderableVariants())
        {
            var prepared = (DbPreparedQueryCommand<PKRow>)ctx.GetPreparedQueryCommand(
                (QueryCommand<PKRow>)build(ctx), false, true, CancellationToken.None);

            prepared.DbCommand.CommandText.Should().Be(
                ownSql[name], $"the cached plan for '{name}' must keep its own SQL");
        }
    }

    /// <summary>
    /// #173: the projection-item member is part of the plan key. Two commands with equal SQL, context
    /// type and every other shape input, differing only in <see cref="ProjectionEntityItem.Member"/>,
    /// must not alias each other in the real <see cref="QueryPlanStore"/>; an equal-member control must
    /// still reuse the stored plan. The member is injected at the test seam because the production
    /// producers only emit the tuple <c>ItemN</c> members.
    /// </summary>
    [Fact]
    public void PlanCache_ShouldSeparateProjectionItemMembers()
    {
        using var ctx = SqliteTestContext.Create();

        var memberId = typeof(PKRow).GetProperty(nameof(PKRow.Id))!;
        var memberInt = typeof(PKRow).GetProperty(nameof(PKRow.Int))!;

        QueryCommand Build()
        {
            var cmd = Row(E(ctx));
            cmd.PrepareCommand(false, CancellationToken.None);
            return cmd;
        }

        var first = Build();
        var second = Build();
        var control = Build();

        first.SelectList![0].ProjectionItem = new ProjectionEntityItem(0, typeof(PKRow), memberId);
        second.SelectList![0].ProjectionItem = new ProjectionEntityItem(0, typeof(PKRow), memberInt);
        control.SelectList![0].ProjectionItem = new ProjectionEntityItem(0, typeof(PKRow), memberId);

        QueryPlanStore.Clear();
        var contextType = typeof(PlanKeyUniquenessTests);
        var holderFirst = new StubCommandHolder();
        var holderSecond = new StubCommandHolder();

        var planFirst = new QueryPlan(first, null);
        var planSecond = new QueryPlan(second, null);
        var planControl = new QueryPlan(control, null);

        planFirst.Equals(planSecond).Should().BeFalse("a projection-item member is part of the plan key");
        planFirst.Equals(planControl).Should().BeTrue("an equal member identity must reuse the plan key");

        QueryPlanStore.Set(contextType, planFirst, holderFirst);
        QueryPlanStore.TryGet(contextType, planSecond, out var missedHolder, out var missedPlan).Should()
            .BeFalse("the member-only variation must not alias the stored plan");
        missedHolder.Should().BeNull();
        missedPlan.Should().BeNull();

        QueryPlanStore.Set(contextType, planSecond, holderSecond);
        QueryPlanStore.TryGet(contextType, planFirst, out var foundFirst, out var storedFirst).Should().BeTrue();
        foundFirst.Should().BeSameAs(holderFirst);
        storedFirst.Should().BeSameAs(planFirst);

        QueryPlanStore.TryGet(contextType, planSecond, out var foundSecond, out var storedSecond).Should().BeTrue();
        foundSecond.Should().BeSameAs(holderSecond);
        storedSecond.Should().BeSameAs(planSecond);

        QueryPlanStore.TryGet(contextType, planControl, out var foundControl, out _).Should()
            .BeTrue("an equal-shape control must reuse the stored plan");
        foundControl.Should().BeSameAs(holderFirst);
    }

    /// <summary>
    /// D190: the direct whole-entity projections of a joined item must never receive another variant's
    /// cached SQL. The same entity type selected through different slots of a self-join has the same
    /// entity type and result type, so the source/slot-binding must separate the real
    /// <see cref="QueryPlanStore"/> entries.
    /// </summary>
    [Fact]
    public void PlanCache_ShouldSeparateDirectEntityItemSlots()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.PurgeQueryCache();

        static string Own<T>((IDataContext Ctx, QueryCommand<T> Cmd) variant)
            => ((DbPreparedQueryCommand<T>)variant.Ctx.GetPreparedQueryCommand(variant.Cmd, false, false, CancellationToken.None)).DbCommand.CommandText;

        static string Cached<T>((IDataContext Ctx, QueryCommand<T> Cmd) variant)
            => ((DbPreparedQueryCommand<T>)variant.Ctx.GetPreparedQueryCommand(variant.Cmd, false, true, CancellationToken.None)).DbCommand.CommandText;

        var parent = (ctx, DirectParentJoin(ctx).Select(p => p.Item1));
        var child = (ctx, DirectParentJoin(ctx).Select(p => p.Item2));
        var selfItem1 = (ctx, DirectSelfJoin(ctx).Select(p => p.Item1));
        var selfItem2 = (ctx, DirectSelfJoin(ctx).Select(p => p.Item2));

        var ownSql = new[] { Own(parent), Own(child), Own(selfItem1), Own(selfItem2) };
        ownSql.Should().OnlyHaveUniqueItems("each direct whole-entity projection has its own SQL shape");

        Cached(parent).Should().Be(ownSql[0], "the parent slot keeps its own cached SQL");
        Cached(child).Should().Be(ownSql[1], "the child slot keeps its own cached SQL");
        Cached(selfItem1).Should().Be(ownSql[2], "the first self-join slot keeps its own cached SQL");
        Cached(selfItem2).Should().Be(ownSql[3], "the second self-join slot keeps its own cached SQL");
    }

    /// <summary>
    /// D190: two independently built but equivalent direct whole-entity projections must share one
    /// plan key and actually hit the stored <see cref="QueryPlanStore"/> entry, so the mapper/SQL is
    /// reused rather than rebuilt per call site.
    /// </summary>
    [Fact]
    public void QueryPlan_ShouldReuseEquivalentDirectEntityProjection()
    {
        using var ctx = SqliteTestContext.Create();

        QueryCommand<EagerChild> Build()
        {
            var cmd = DirectParentJoin(ctx).Select(p => p.Item2);
            cmd.PrepareCommand(false, CancellationToken.None);
            return cmd;
        }

        var first = Build();
        var second = Build();

        var planFirst = new QueryPlan(first, null);
        var planSecond = new QueryPlan(second, null);

        planFirst.Equals(planSecond).Should().BeTrue("an equivalent direct projection must share the plan key");
        planFirst.GetHashCode().Should().Be(planSecond.GetHashCode(), "equal plans must hash alike");

        QueryPlanStore.Clear();
        var contextType = typeof(PlanKeyUniquenessTests);
        var holder = new StubCommandHolder();
        QueryPlanStore.Set(contextType, planFirst, holder);

        QueryPlanStore.TryGet(contextType, planSecond, out var found, out var stored).Should()
            .BeTrue("the equivalent direct projection must hit the cached plan");
        found.Should().BeSameAs(holder);
        stored.Should().BeSameAs(planFirst);
    }

    private sealed class StubCommandHolder : IDbCommandHolder
    {
        public void ResetConnection(DbConnection conn, IDataContext dbContext)
        {
        }
    }
}

using System.Data.Common;
using System.Security.Cryptography;
using System.Text;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// D160 R160-02' oracle (issue #160, cycle N=2). Test-only: it regenerates the frozen positional-only
/// join chain on the current (revised) tree and compares the generated SQL <b>byte-for-byte</b> against
/// the committed baseline corpus captured at HEAD <c>0495ee84</c> under
/// <c>tests/nextorm.sqlite.tests/Baselines/D160/positional/sqlite</c>. It is a genuine baseline&lt;-&gt;revised
/// comparator, not a self-read: a single differing byte fails the test.
///
/// <para>
/// Inputs are env-driven: <c>D160_EVIDENCE_DIR</c> is the revised artifact root (default
/// <c>artifacts/pdca/D160/rv1/N2/revised</c>, so SQL lands in <c>&lt;root&gt;/positional/sqlite</c>) and
/// <c>D160_BASELINE_DIR</c> is the frozen baseline root (default
/// <c>tests/nextorm.sqlite.tests/Baselines/D160/positional</c>). Relative values resolve against the repo root.
/// </para>
/// </summary>
public class PositionalChainSqlInvariantTests
{
    private const string DefaultEvidenceRoot = "artifacts/pdca/D160/rv1/N2/revised";
    // Committed fixture (tracked): the frozen positional SQL corpus captured at HEAD 0495ee84.
    // It must NOT live under artifacts/ (gitignored) — a CI checkout only has tracked files.
    private const string DefaultBaselineRoot = "tests/nextorm.sqlite.tests/Baselines/D160/positional";

    private static readonly string[] Cases =
    [
        "01-inner", "02-left", "03-right", "04-full", "05-cross",
        "06-three-join-chain", "07-where-between-joins", "08-positional-prefix-as",
    ];

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "nextorm.slnx")))
            dir = dir.Parent;
        return dir?.FullName ?? Directory.GetCurrentDirectory();
    }

    private static string ResolveDir(string? envValue, string defaultRelative)
    {
        var value = string.IsNullOrWhiteSpace(envValue) ? defaultRelative : envValue!;
        return Path.IsPathRooted(value) ? value : Path.Combine(RepoRoot(), value);
    }

    private static string EvidenceRoot()
        => ResolveDir(Environment.GetEnvironmentVariable("D160_EVIDENCE_DIR"), DefaultEvidenceRoot);

    private static string BaselineRoot()
        => ResolveDir(Environment.GetEnvironmentVariable("D160_BASELINE_DIR"), DefaultBaselineRoot);

    /// <summary>
    /// Raw, un-normalised <c>CommandText</c>: the corpus is compared byte-for-byte, so aliases and
    /// ordinals must survive exactly as the renderer produced them.
    /// </summary>
    private static string RawSqlOf<T>(IDataContext ctx, QueryCommand<T> cmd)
        => ((DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None))
            .DbCommand.CommandText;

    private static void Capture(string dir, string name, string sql)
    {
        Directory.CreateDirectory(dir);
        var bytes = Encoding.UTF8.GetBytes(sql);
        File.WriteAllBytes(Path.Combine(dir, name + ".sql"), bytes);
        var hash = Convert.ToHexString(SHA256.HashData(bytes));
        File.WriteAllBytes(
            Path.Combine(dir, name + ".sha256"),
            Encoding.UTF8.GetBytes(hash + "  " + name + ".sql" + "\n"));
    }

    /// <summary>
    /// Reads the frozen baseline <c>&lt;name&gt;.sql</c> and asserts the freshly generated revised bytes
    /// are identical (SQL and its recorded SHA-256 sidecar). Any length or byte difference fails.
    /// </summary>
    private static void CompareToBaseline(string baselineDir, string revisedDir, string name)
    {
        var baselineSqlPath = Path.Combine(baselineDir, name + ".sql");
        var revisedSqlPath = Path.Combine(revisedDir, name + ".sql");

        File.Exists(baselineSqlPath)
            .Should().BeTrue($"the frozen baseline positional corpus must exist at '{baselineSqlPath}'");
        File.Exists(revisedSqlPath)
            .Should().BeTrue($"the revised positional corpus must have been regenerated at '{revisedSqlPath}'");

        var baselineBytes = File.ReadAllBytes(baselineSqlPath);
        var revisedBytes = File.ReadAllBytes(revisedSqlPath);
        revisedBytes.Should().Equal(baselineBytes, $"{name}: positional SQL must be byte-identical to the baseline");

        var baselineHash = File.ReadAllBytes(Path.Combine(baselineDir, name + ".sha256"));
        var revisedHash = File.ReadAllBytes(Path.Combine(revisedDir, name + ".sha256"));
        revisedHash.Should().Equal(baselineHash, $"{name}: positional SQL SHA-256 sidecar must match the baseline");
    }

    // -----------------------------------------------------------------------------------------------
    // P2 — regenerate the frozen positional corpus and byte-compare it against the baseline.
    // -----------------------------------------------------------------------------------------------
    [Trait("D160Probe", "P2")]
    [Fact]
    public void Positional_chain_sql_is_byte_identical_to_the_frozen_baseline()
    {
        using var ctx = SqliteTestContext.Create();
        var dir = Path.Combine(EvidenceRoot(), "positional", "sqlite");
        var baselineDir = Path.Combine(BaselineRoot(), "sqlite");

        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();
        var complex2 = ctx.From<IComplexEntity>();

        var inner = RawSqlOf(ctx, simple.Join(complex, (a, b) => a.Id == b.Id).Select(p => p.Item2.Id));
        var left = RawSqlOf(ctx, simple.LeftJoin(complex, (a, b) => a.Id == b.Id).Select(p => p.Item2.Id));
        var right = RawSqlOf(ctx, simple.RightJoin(complex, (a, b) => a.Id == b.Id).Select(p => p.Item2.Id));
        var full = RawSqlOf(ctx, simple.FullJoin(complex, (a, b) => a.Id == b.Id).Select(p => p.Item2.Id));
        var cross = RawSqlOf(ctx, simple.CrossJoin(complex).Select(p => p.Item2.Id));
        var chain = RawSqlOf(ctx, simple
            .Join(complex, (a, b) => a.Id == b.Id)
            .Join(complex2, (p, c) => p.Item1.Id == c.Id)
            .Select(p => p.Item2.Id));
        var whereBetween = RawSqlOf(ctx, simple
            .Where(a => a.Id > 0)
            .Join(complex, (a, b) => a.Id == b.Id)
            .Select(p => p.Item2.Id));
        var prefixAs = RawSqlOf(ctx, simple
            .Join(complex, (a, b) => a.Id == b.Id)
            .As(p => new { p.Item1.Id, p.Item2.String })
            .Select(x => x.Id));

        Capture(dir, "01-inner", inner);
        Capture(dir, "02-left", left);
        Capture(dir, "03-right", right);
        Capture(dir, "04-full", full);
        Capture(dir, "05-cross", cross);
        Capture(dir, "06-three-join-chain", chain);
        Capture(dir, "07-where-between-joins", whereBetween);
        Capture(dir, "08-positional-prefix-as", prefixAs);

        foreach (var name in Cases)
            CompareToBaseline(baselineDir, dir, name);
    }

    // -----------------------------------------------------------------------------------------------
    // P3 — positional CROSS/OUTER APPLY fail closed on SQLite (no lateral source).
    // -----------------------------------------------------------------------------------------------
    [Trait("D160Probe", "P3")]
    [Fact]
    public void Positional_cross_apply_fails_closed_on_sqlite()
    {
        using var ctx = SqliteTestContext.Create();
        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();

        var act = () => RawSqlOf(ctx, simple.CrossApply(complex).Select(p => p.Item2.Id));

        act.Should().Throw<NotSupportedException>().WithMessage("*CrossApply*");
    }

    [Trait("D160Probe", "P3")]
    [Fact]
    public void Positional_outer_apply_fails_closed_on_sqlite()
    {
        using var ctx = SqliteTestContext.Create();
        var simple = ctx.From<ISimpleEntity>();
        var complex = ctx.From<IComplexEntity>();

        var act = () => RawSqlOf(ctx, simple.OuterApply(complex).Select(p => p.Item2.Id));

        act.Should().Throw<NotSupportedException>().WithMessage("*OuterApply*");
    }
}

using FluentAssertions;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>The PostgreSQL-only range surface is rejected by SQLite (no native range type).</summary>
public class PostgresRangeRejectionTests
{
    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd)
        => ((DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None)).DbCommand.CommandText;

    [Fact]
    public void Overlaps_ShouldThrowBecauseNotSupported()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();
        var a = new Range<int>(1, 2);
        var b = new Range<int>(3, 4);

        var act = () => SqlOf(ctx, e.Where(x => SqlFunctions.Postgres.overlaps(a, b)).Select(x => new { x.Id }));

        act.Should().Throw<NotSupportedException>().WithMessage("*range*PostgreSQL*");
    }

    [Fact]
    public void RangeConstructor_ShouldThrowBecauseNotSupported()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var act = () => SqlOf(ctx, e.Select(x => new { R = SqlFunctions.Postgres.int4range(1, 10) }));

        act.Should().Throw<NotSupportedException>().WithMessage("*range*PostgreSQL*");
    }
}

using System.ComponentModel.DataAnnotations.Schema;
using System.Data.Common;
using System.Linq.Expressions;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;
using NextORM.Sqlite;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// SQL generation and plan-cache behaviour for global query filters (#67) on SQLite: the filter
/// predicate reaches the <c>WHERE</c>, the per-context tenant value is bound as a parameter (never
/// inlined) and two contexts with different values share one cached plan. The SQL-only test never
/// opens a database; the two-context test uses a temp file database.
/// </summary>
public class QueryFilterSqlGenerationTests
{
    private const string TenantKey = "tenant";

    [SqlTable("filter_tenant_entity")]
    public sealed class FilterTenantEntity
    {
        [Column("id")]
        public int Id { get; set; }

        [Column("tenant_id")]
        public int TenantId { get; set; }
    }

    [SqlTable("filter_tenant_sql_entity")]
    public sealed class FilterTenantSqlEntity
    {
        [Column("id")]
        public int Id { get; set; }

        [Column("tenant_id")]
        public int TenantId { get; set; }
    }

    [SqlTable("filter_join_left_entity")]
    public sealed class FilterJoinLeftEntity
    {
        [Column("id")]
        public int Id { get; set; }
    }

    [SqlTable("filter_join_right_entity")]
    public sealed class FilterJoinRightEntity
    {
        [Column("id")]
        public int Id { get; set; }

        [Column("tenant_id")]
        public int TenantId { get; set; }
    }

    [SqlTable("filter_selective_entity")]
    public sealed class FilterSelectiveEntity
    {
        [Column("id")]
        public int Id { get; set; }

        [Column("tenant_id")]
        public int TenantId { get; set; }

        [Column("is_deleted")]
        public bool IsDeleted { get; set; }
    }

    [SqlTable("filter_selective_join_left")]
    public sealed class FilterSelectiveJoinLeftEntity
    {
        [Column("id")]
        public int Id { get; set; }
    }

    [SqlTable("filter_selective_join_right")]
    public sealed class FilterSelectiveJoinRightEntity
    {
        [Column("id")]
        public int Id { get; set; }

        [Column("tenant_id")]
        public int TenantId { get; set; }
    }

    private const string SelectiveTenantKey = "tenant_selective";
    private const string SelectiveJoinTenantKey = "tenant_join_selective";

    private const string JoinTenantKey = "tenant_join";

    private static Expression<Func<FilterTenantEntity, IDataContext, bool>> TenantFilter()
        => (e, ctx) => e.TenantId == (int)ctx.Properties[TenantKey];

    private static Expression<Func<FilterJoinRightEntity, IDataContext, bool>> JoinTenantFilter()
        => (e, ctx) => e.TenantId == (int)ctx.Properties[JoinTenantKey];

    private static string Normalize(string sql) => sql.Replace("\r\n", "\n");

    private static int CountOccurrences(string text, string needle)
    {
        var count = 0;
        var index = 0;
        while ((index = text.IndexOf(needle, index, StringComparison.Ordinal)) >= 0)
        {
            count++;
            index += needle.Length;
        }

        return count;
    }

    [Fact]
    public void FilteredEntity_Sql_ShouldContainPredicateAndBoundParameter()
    {
        // A dedicated entity type and property key keep this SQL-shape test independent of the
        // two-context execution test: the context read folds through the process-wide compiled-value
        // cache, whose key does not include the context instance (see the execution test below).
        using var ctx = SqliteTestContext.Create();
        ctx.Properties["tenant_sqlgen"] = 7;
        ctx.From<FilterTenantSqlEntity>(b => b.HasQueryFilter((e, c) => e.TenantId == (int)c.Properties["tenant_sqlgen"]));

        var prepared = (DbPreparedQueryCommand<int>)ctx.GetPreparedQueryCommand(
            ctx.From<FilterTenantSqlEntity>().Select(x => x.Id), false, false, CancellationToken.None);

        var sql = Normalize(prepared.DbCommand.CommandText);
        sql.Should().Contain("tenant_id = $");
        sql.Should().NotContain("= 7");

        var parameters = prepared.DbCommand.Parameters.Cast<DbParameter>().ToArray();
        parameters.Should().ContainSingle();
        parameters[0].Value.Should().Be(7);
    }

    [Fact]
    public void TwoContexts_DifferentTenant_ShouldSharePlanKey_AndScopeDistinguishes()
    {
        using var ctx1 = SqliteTestContext.Create();
        using var ctx2 = SqliteTestContext.Create();
        ctx1.Properties[TenantKey] = 1;
        ctx2.Properties[TenantKey] = 2;
        ctx1.From<FilterTenantEntity>(b => b.HasQueryFilter(TenantFilter()));

        var shared1 = ctx1.From<FilterTenantEntity>().Select(x => x.Id);
        var shared2 = ctx2.From<FilterTenantEntity>().Select(x => x.Id);
        shared1.PrepareCommand(false, TestContext.Current.CancellationToken);
        shared2.PrepareCommand(false, TestContext.Current.CancellationToken);

        shared1.GetOrCreatePlanKey(null).Equals(shared2.GetOrCreatePlanKey(null))
            .Should().BeTrue("two contexts with the same shape share the cached plan regardless of the tenant value");

        var unfiltered = ctx1.From<FilterTenantEntity>().IgnoreFilters().Select(x => x.Id);
        var selective = ctx1.From<FilterTenantEntity>().IgnoreFilters([QueryFilters.AnonymousKey]).Select(x => x.Id);
        unfiltered.PrepareCommand(false, TestContext.Current.CancellationToken);
        selective.PrepareCommand(false, TestContext.Current.CancellationToken);

        shared1.GetOrCreatePlanKey(null).Equals(unfiltered.GetOrCreatePlanKey(null))
            .Should().BeFalse("the all-filters-ignored form injects a different condition");
        shared1.GetOrCreatePlanKey(null).Equals(selective.GetOrCreatePlanKey(null))
            .Should().BeFalse("a selective ignore injects a different condition");
    }

    [Fact]
    public void RePreparedJoin_ShouldNotDoubleInjectFilter()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[JoinTenantKey] = 1;
        ctx.From<FilterJoinRightEntity>(b => b.HasQueryFilter(JoinTenantFilter()));

        var cmd = ctx.From<FilterJoinLeftEntity>()
            .Join(ctx.From<FilterJoinRightEntity>(), (l, r) => l.Id == r.Id)
            .Select(p => p.Item2.TenantId);

        var first = (DbPreparedQueryCommand<int>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None);
        CountOccurrences(Normalize(first.DbCommand.CommandText), "tenant_id = ").Should().Be(1);

        cmd.ResetPreparation();

        var second = (DbPreparedQueryCommand<int>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None);
        CountOccurrences(Normalize(second.DbCommand.CommandText), "tenant_id = ").Should().Be(1);
    }

    [Fact]
    public void DerivedJoin_ShouldApplyFilterOnceInSubquery_NotInOnCondition()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[JoinTenantKey] = 1;
        ctx.From<FilterJoinRightEntity>(b => b.HasQueryFilter(JoinTenantFilter()));

        var right = ctx.From<FilterJoinRightEntity>().ToCommand();
        var cmd = ctx.From<FilterJoinLeftEntity>()
            .Join(right, (l, r) => l.Id == r.Id)
            .Select(p => p.Item2.TenantId);

        var prepared = (DbPreparedQueryCommand<int>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None);
        CountOccurrences(Normalize(prepared.DbCommand.CommandText), "tenant_id = ").Should().Be(1);
    }

    [Fact]
    public void CachedPlanClone_ShouldNotShareJoinInstance()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[JoinTenantKey] = 1;
        ctx.From<FilterJoinRightEntity>(b => b.HasQueryFilter(JoinTenantFilter()));

        var cmd = ctx.From<FilterJoinLeftEntity>()
            .Join(ctx.From<FilterJoinRightEntity>(), (l, r) => l.Id == r.Id)
            .Select(p => p.Item2.TenantId);

        cmd.PrepareCommand(false, TestContext.Current.CancellationToken);

        var clone = cmd.CloneForCache();

        clone.Joins.Should().NotBeSameAs(cmd.Joins);
        clone.Joins![0].Should().NotBeSameAs(cmd.Joins![0]);
    }

    private static void ConfigureSelective(IDataContext ctx)
    {
        ctx.Properties[SelectiveTenantKey] = 1;
        ctx.From<FilterSelectiveEntity>(b => b
            .HasQueryFilter((e, c) => e.Id > 5)
            .HasQueryFilter("tenant", (e, c) => e.TenantId == (int)c.Properties[SelectiveTenantKey]));
    }

    private static string PrepareSelectiveSql(IDataContext ctx, EntityBuilder<FilterSelectiveEntity> builder)
    {
        var prepared = (DbPreparedQueryCommand<int>)ctx.GetPreparedQueryCommand(
            builder.Select(x => x.Id), false, false, CancellationToken.None);
        return Normalize(prepared.DbCommand.CommandText);
    }

    [Fact]
    public void SelectiveIgnore_ByKey_Sql_ShouldDropOnlyNamedPredicate()
    {
        using var ctx = SqliteTestContext.Create();
        ConfigureSelective(ctx);

        var sql = PrepareSelectiveSql(ctx, ctx.From<FilterSelectiveEntity>().IgnoreFilters(["tenant"]));

        sql.Should().Contain("id > 5");
        sql.Should().NotContain("tenant_id = ");
    }

    [Fact]
    public void SelectiveIgnore_ByAnonymousKey_Sql_ShouldDropOnlyAnonymousPredicate()
    {
        using var ctx = SqliteTestContext.Create();
        ConfigureSelective(ctx);

        var sql = PrepareSelectiveSql(ctx, ctx.From<FilterSelectiveEntity>().IgnoreFilters([QueryFilters.AnonymousKey]));

        sql.Should().Contain("tenant_id = $");
        sql.Should().NotContain("id > 5");
    }

    [Fact]
    public void SelectiveIgnore_EmptyKeys_Sql_ShouldKeepEveryPredicate()
    {
        using var ctx = SqliteTestContext.Create();
        ConfigureSelective(ctx);

        var sql = PrepareSelectiveSql(ctx, ctx.From<FilterSelectiveEntity>().IgnoreFilters(Array.Empty<string>()));

        sql.Should().Contain("id > 5");
        sql.Should().Contain("tenant_id = $");
    }

    [Fact]
    public void SelectiveIgnore_ByType_Sql_ShouldDropJoinedTypePredicate()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[SelectiveJoinTenantKey] = 1;
        ctx.From<FilterSelectiveJoinRightEntity>(b => b
            .HasQueryFilter("tenant", (e, c) => e.TenantId == (int)c.Properties[SelectiveJoinTenantKey]));

        var filtered = (DbPreparedQueryCommand<int>)ctx.GetPreparedQueryCommand(
            ctx.From<FilterSelectiveJoinLeftEntity>()
                .Join(ctx.From<FilterSelectiveJoinRightEntity>(), (l, r) => l.Id == r.Id)
                .Select(p => p.Item2.TenantId),
            false, false, CancellationToken.None);
        Normalize(filtered.DbCommand.CommandText).Should().Contain("tenant_id = ");

        var unfiltered = (DbPreparedQueryCommand<int>)ctx.GetPreparedQueryCommand(
            ctx.From<FilterSelectiveJoinLeftEntity>()
                .IgnoreFilters(typeof(FilterSelectiveJoinRightEntity))
                .Join(ctx.From<FilterSelectiveJoinRightEntity>(), (l, r) => l.Id == r.Id)
                .Select(p => p.Item2.TenantId),
            false, false, CancellationToken.None);
        Normalize(unfiltered.DbCommand.CommandText).Should().NotContain("tenant_id = ");
    }

    [Fact]
    public void SharedJoinBuilder_DifferentScopes_ShouldNotLeakFiltersAcrossRenders()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[JoinTenantKey] = 1;
        ctx.From<FilterJoinRightEntity>(b => b.HasQueryFilter(JoinTenantFilter()));

        // One builder lineage: both commands' join arrays hold the same JoinExpression instance, so
        // preparing one must not inject its filter into the other's ON condition.
        var joined = ctx.From<FilterJoinLeftEntity>()
            .Join(ctx.From<FilterJoinRightEntity>(), (l, r) => l.Id == r.Id);
        var joinedUnfiltered = joined.IgnoreFilters();

        string Render(QueryCommand<int> command, bool cache)
        {
            var prepared = (DbPreparedQueryCommand<int>)ctx.GetPreparedQueryCommand(command, false, cache, CancellationToken.None);
            return Normalize(prepared.DbCommand.CommandText);
        }

        // Without the plan cache: render the filtered command first, then its ignore-all sibling.
        var filtered1 = Render(joined.Select(p => p.Item2.TenantId), cache: false);
        var unfiltered1 = Render(joinedUnfiltered.Select(p => p.Item2.TenantId), cache: false);

        filtered1.Should().Contain("tenant_id = ");
        unfiltered1.Should().NotContain("tenant_id = ", "the sibling's injected filter must not leak into the unfiltered ON condition");

        // Re-render the filtered shape after the sibling: identical SQL, not the sibling's mutation.
        Render(joined.Select(p => p.Item2.TenantId), cache: false).Should().Be(filtered1);

        // The same alternation with the plan cache enabled is stable and plans stay distinct.
        var filteredCached = Render(joined.Select(p => p.Item2.TenantId), cache: true);
        var unfilteredCached = Render(joinedUnfiltered.Select(p => p.Item2.TenantId), cache: true);

        filteredCached.Should().Contain("tenant_id = ");
        unfilteredCached.Should().NotContain("tenant_id = ");
        Render(joined.Select(p => p.Item2.TenantId), cache: true).Should().Be(filteredCached);
    }

    [Fact]
    public void ClonedCommand_DifferentScopes_AlternatingPreparation_ShouldNotLeak()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[JoinTenantKey] = 1;
        ctx.From<FilterJoinRightEntity>(b => b.HasQueryFilter(JoinTenantFilter()));

        var source = ctx.From<FilterJoinLeftEntity>()
            .Join(ctx.From<FilterJoinRightEntity>(), (l, r) => l.Id == r.Id)
            .Select(p => p.Item2.TenantId);

        // A Definition-derived clone (the paging clone) used to share the source's `_joins` array, so
        // the source's prepared join was rewritten when the sibling prepared.
        var unfiltered = source.Limit(0);
        unfiltered.IgnoreFilters = true;

        string Render(QueryCommand<int> command, bool cache)
        {
            var prepared = (DbPreparedQueryCommand<int>)ctx.GetPreparedQueryCommand(command, false, cache, CancellationToken.None);
            return Normalize(prepared.DbCommand.CommandText);
        }

        // storeInCache:false re-renders an already-prepared command from its current state, so a shared
        // array is observable as the source's own SQL changing after the sibling prepares.
        var filtered = Render(source, cache: false);
        filtered.Should().Contain("tenant_id = ");
        Render(unfiltered, cache: false).Should().NotContain("tenant_id = ");
        Render(source, cache: false).Should().Be(filtered, "the sibling's preparation must not rewrite the source's join");
        Render(unfiltered, cache: false).Should().NotContain("tenant_id = ");

        // The same alternation with the plan cache enabled stays stable and the plans stay distinct.
        var filteredCached = Render(source, cache: true);
        filteredCached.Should().Contain("tenant_id = ");
        Render(unfiltered, cache: true).Should().NotContain("tenant_id = ");
        Render(source, cache: true).Should().Be(filteredCached);
        Render(source.Limit(0), cache: true).Should().Contain("tenant_id = ", "a fresh sibling re-derived from the source stays filtered");
    }

    [SqlTable("filter_dml_target")]
    public sealed class FilterDmlTargetEntity
    {
        [Column("id")]
        public int Id { get; set; }

        [Column("tenant_id")]
        public int TenantId { get; set; }
    }

    [SqlTable("filter_dml_right")]
    public sealed class FilterDmlRightEntity
    {
        [Column("id")]
        public int Id { get; set; }
    }

    /// <summary>A target with no filter and no test configuring one, so the process-wide metadata cache
    /// cannot leak an active filter into the branchless-On control.</summary>
    [SqlTable("filter_dml_target_plain")]
    public sealed class BranchlessPlainEntity
