using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using FluentAssertions;
using Microsoft.Extensions.Logging;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// D5 task B: the diagnostic lifecycle of a skipped global query filter on a bound raw source.
/// A capturing <see cref="ILoggerProvider"/> asserts the category, level, event name and the five
/// structured fields, that the warning fires once on the cache-miss preparation and never on a cache
/// hit, that the message leaks no SQL text/table name/parameter/captured value, and that a context
/// without a logger factory does not crash.
/// </summary>
public class RawSourceBindingDiagnosticsTests
{
    private const string TenantKey = "rsb_diag_tenant";
    private const int SecretTenant = 424242;

    [SqlTable("rsb_diag_entity")]
    public sealed class DiagEntity
    {
        [Column("id")]
        public int Id { get; set; }

        [Column("tenant_id")]
        public int TenantId { get; set; }
    }

    [SqlTable("rsb_diag_join_main")]
    public sealed class DiagJoinMain
    {
        [Column("id")]
        public int Id { get; set; }
    }

    [SqlTable("rsb_diag_join_plain")]
    public sealed class DiagJoinPlain
    {
        [Column("id")]
        public int Id { get; set; }
    }

    private static void Configure(IDataContext ctx)
        => ctx.From<DiagEntity>(b => b
            .HasQueryFilter("tenant", (e, c) => e.TenantId == (int)c.Properties[TenantKey])
            .HasQueryFilter(e => e.Id > 0));

    private static (IDataContext Ctx, LogSink Sink) CreateWithLogger(bool enabled = true)
    {
        var sink = new LogSink { Enabled = enabled };
        var ctx = new SqliteDataContext(
            "Data Source=:memory:",
            new DataContextBuilder().UseLoggerFactory(LoggerFactory.Create(b => b.AddProvider(sink))));
        return (ctx, sink);
    }

    private static IReadOnlyList<CapturedLog> FilterWarnings(LogSink sink)
        => [.. sink.Logs.Where(static l => l.Message.StartsWith("RawSourceFilterSkipped:", StringComparison.Ordinal))];

    [Fact]
    public void SkippedFilter_ShouldEmitOneWarningWithContractFields()
    {
        var (ctx, sink) = CreateWithLogger();
        using var context = ctx;
        ctx.Properties[TenantKey] = SecretTenant;
        Configure(ctx);

        var cmd = ctx.FromSql("select id from rsb_diag_source")
            .BindEntity<DiagEntity>(["id"])
            .Select(x => x.Id);
        _ = ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None);

        var warning = FilterWarnings(sink).Should().ContainSingle().Subject;
        warning.Category.Should().Be("NextORM.QueryFilters");
        warning.Level.Should().Be(LogLevel.Warning);
        warning.Message.Should().StartWith("RawSourceFilterSkipped: ");
        warning.Fields["EntityType"].Should().Be(nameof(DiagEntity));
        warning.Fields["SourceOrdinal"].Should().Be(0);
        warning.Fields["FilterKey"].Should().Be("tenant");
        warning.Fields["Reason"].Should().Be("MissingColumns");
        warning.Fields["MissingColumns"].Should().Be("tenant_id");
    }

    [Fact]
    public void CacheHit_ShouldNotReemitTheWarning()
    {
        var (ctx, sink) = CreateWithLogger();
        using var context = ctx;
        ctx.Properties[TenantKey] = SecretTenant;
        Configure(ctx);

        var cmd = ctx.FromSql("select id from rsb_diag_cache_source")
            .BindEntity<DiagEntity>(["id"])
            .Select(x => x.Id);

        _ = ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None);
        FilterWarnings(sink).Should().ContainSingle();

        _ = ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None);
        FilterWarnings(sink).Should().ContainSingle("a plan-cache hit must not re-emit the diagnostic");
    }

    [Fact]
    public void Message_ShouldNotLeakSqlTableNamesParametersOrValues()
    {
        var (ctx, sink) = CreateWithLogger();
        using var context = ctx;
        ctx.Properties[TenantKey] = SecretTenant;
        Configure(ctx);

        var cmd = ctx.FromSql("select id from rsb_diag_secret_table")
            .BindEntity<DiagEntity>(["id"])
            .Select(x => x.Id);
        _ = ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None);

        var message = FilterWarnings(sink).Should().ContainSingle().Subject.Message;
        message.Should().NotContain("rsb_diag_secret_table");
        message.Should().NotContain("select");
        message.Should().NotContain(SecretTenant.ToString());
        message.Should().NotContain("p0");
    }

    [Fact]
    public void SourceOrdinal_ShouldCountAllJoins_MainZeroAndJoinJPlusOne()
    {
        var (ctx, sink) = CreateWithLogger();
        using var context = ctx;
        ctx.Properties[TenantKey] = SecretTenant;
        Configure(ctx);

        // The first join is unbound (still ordinal 1); the second bound join is missing the tenant
        // column and is skipped at ordinal 2. The main source's own ordinal 0 is pinned by
        // SkippedFilter_ShouldEmitOneWarningWithContractFields.
        var secondJoin = ctx.FromSql("select id from rsb_diag_join_source").BindEntity<DiagEntity>(["id"]);

        var cmd = ctx.From<DiagJoinMain>()
            .Join(ctx.From<DiagJoinPlain>(), (a, b) => a.Id == b.Id)
            .Join(secondJoin, (p, b) => p.Item2.Id == b.Id)
            .Select(p => p.Item1.Id);
        _ = ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None);

        var warning = FilterWarnings(sink).Should().ContainSingle().Subject;
        warning.Fields["SourceOrdinal"].Should().Be(2, "the unbound first join still occupies ordinal 1");
    }

    [Fact]
    public void DerivedBoundRaw_EmitsSkipWarning()
    {
        var (ctx, sink) = CreateWithLogger();
        using var context = ctx;
        ctx.Properties[TenantKey] = SecretTenant;
        Configure(ctx);

        // A bound raw source nested as a derived table: its skip is collected while the inner command
        // is prepared, so it must be transferred to the owning (outer) preparation.
        var inner = ctx.FromSql("select id from rsb_diag_derived_source")
            .BindEntity<DiagEntity>(["id"])
            .Select(x => x.Id);
        var outer = ctx.From(inner).Select(x => x);

        _ = ctx.GetPreparedQueryCommand(outer, false, true, CancellationToken.None);

        var warning = FilterWarnings(sink).Should().ContainSingle().Subject;
        warning.Category.Should().Be("NextORM.QueryFilters");
        warning.Level.Should().Be(LogLevel.Warning);
        warning.Fields["EntityType"].Should().Be(nameof(DiagEntity));
        warning.Fields["SourceOrdinal"].Should().Be(0);
        warning.Fields["Reason"].Should().Be("MissingColumns");
        warning.Fields["MissingColumns"].Should().Be("tenant_id");
    }

    [Fact]
    public void CteBoundRaw_EmitsSkipWarning()
    {
        var (ctx, sink) = CreateWithLogger();
        using var context = ctx;
        ctx.Properties[TenantKey] = SecretTenant;
        Configure(ctx);

        var body = ctx.FromSql("select id from rsb_diag_cte_source")
            .BindEntity<DiagEntity>(["id"])
            .Select(x => x.Id);
        var cmd = ctx.With("c", body).From("c").Select(t => t["id"].AsInt);

        _ = ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None);

        var warning = FilterWarnings(sink).Should().ContainSingle().Subject;
        warning.Category.Should().Be("NextORM.QueryFilters");
        warning.Level.Should().Be(LogLevel.Warning);
        warning.Fields["EntityType"].Should().Be(nameof(DiagEntity));
        warning.Fields["SourceOrdinal"].Should().Be(0);
        warning.Fields["Reason"].Should().Be("MissingColumns");
        warning.Fields["MissingColumns"].Should().Be("tenant_id");
    }

    [Fact]
    public void NestedBoundRaw_CacheHit_DoesNotRepeatWarning()
    {
        var (ctx, sink) = CreateWithLogger();
        using var context = ctx;
        ctx.Properties[TenantKey] = SecretTenant;
        Configure(ctx);

        var inner = ctx.FromSql("select id from rsb_diag_nested_cache_source")
            .BindEntity<DiagEntity>(["id"])
            .Select(x => x.Id);
        var outer = ctx.From(inner).Select(x => x);

        _ = ctx.GetPreparedQueryCommand(outer, false, true, CancellationToken.None);
        FilterWarnings(sink).Should().ContainSingle("the nested skip is emitted once on the cache miss");

        _ = ctx.GetPreparedQueryCommand(outer, false, true, CancellationToken.None);
        FilterWarnings(sink).Should().ContainSingle("a plan-cache hit must not re-emit the nested diagnostic");
    }

    [Fact]
    public void Lifecycle_EachOwningMissEmitsOnce_HitsNeverReplay()
    {
        var (ctx, sink) = CreateWithLogger();
        using var context = ctx;
        ctx.Properties[TenantKey] = SecretTenant;
        Configure(ctx);

        // Warning-producing miss A: the owning preparation emits exactly one diagnostic.
        var a1 = ctx.From("rsb_diag_life_a").BindEntity<DiagEntity>(["id"]).Select(x => x.Id);
        _ = ctx.GetPreparedQueryCommand(a1, false, true, CancellationToken.None);
        FilterWarnings(sink).Should().ContainSingle().Which.Fields["MissingColumns"].Should().Be("tenant_id");

        // Hit A: a fresh command with the same plan key must not re-emit.
        var a2 = ctx.From("rsb_diag_life_a").BindEntity<DiagEntity>(["id"]).Select(x => x.Id);
        _ = ctx.GetPreparedQueryCommand(a2, false, true, CancellationToken.None);
        FilterWarnings(sink).Should().ContainSingle("a plan-cache hit never re-emits");

        // Unrelated warning-producing miss B: its own preparation emits once more.
        var b1 = ctx.From("rsb_diag_life_b").BindEntity<DiagEntity>(["id"]).Select(x => x.Id);
        _ = ctx.GetPreparedQueryCommand(b1, false, true, CancellationToken.None);
        FilterWarnings(sink).Should().HaveCount(2, "each owning miss emits exactly once");

        // Hit B: again no replay.
        var b2 = ctx.From("rsb_diag_life_b").BindEntity<DiagEntity>(["id"]).Select(x => x.Id);
        _ = ctx.GetPreparedQueryCommand(b2, false, true, CancellationToken.None);
        FilterWarnings(sink).Should().HaveCount(2, "a hit on the second source never re-emits either");
    }

    [Fact]
    public void DisabledMiss_ThenEnabledHitAndUncachedCall_DoesNotReplay()
    {
        var (ctx, sink) = CreateWithLogger(enabled: false);
        using var context = ctx;
        ctx.Properties[TenantKey] = SecretTenant;
        Configure(ctx);

        // Owning miss while logging is disabled: nothing is written and the pending list is consumed.
        var a1 = ctx.From("rsb_diag_life_disabled").BindEntity<DiagEntity>(["id"]).Select(x => x.Id);
        _ = ctx.GetPreparedQueryCommand(a1, false, true, CancellationToken.None);
        FilterWarnings(sink).Should().BeEmpty("logging was disabled at the owning preparation");

        sink.Enabled = true;

        // A hit must not emit retroactively once logging is enabled...
        var a2 = ctx.From("rsb_diag_life_disabled").BindEntity<DiagEntity>(["id"]).Select(x => x.Id);
        _ = ctx.GetPreparedQueryCommand(a2, false, true, CancellationToken.None);
        FilterWarnings(sink).Should().BeEmpty("a cache hit never emits, even once logging is enabled");

        // ...and the hit-collected diagnostic must not survive to a later uncached call.
        _ = ctx.GetPreparedQueryCommand(a2, false, false, CancellationToken.None);
        FilterWarnings(sink).Should().BeEmpty("a diagnostic owned by a hit preparation is discarded, not replayed");
    }

    [Fact]
    public void NoLoggerConfigured_ShouldNotCrash()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[TenantKey] = SecretTenant;
        Configure(ctx);

        var cmd = ctx.FromSql("select id from rsb_diag_nolog_source")
            .BindEntity<DiagEntity>(["id"])
            .Select(x => x.Id);

        var act = () => ctx.GetPreparedQueryCommand(cmd, false, true, CancellationToken.None);

        act.Should().NotThrow("a context without a logger factory must tolerate skipped filters");
    }

    private sealed class LogSink : ILoggerProvider
    {
        private readonly List<CapturedLog> _logs = [];

        public bool Enabled { get; set; } = true;

        public IReadOnlyList<CapturedLog> Logs => _logs;

        public ILogger CreateLogger(string categoryName) => new CaptureLogger(this, categoryName);

        public void Dispose()
        {
        }

        private sealed class CaptureLogger(LogSink owner, string category) : ILogger
        {
            public IDisposable? BeginScope<TState>(TState state)
                where TState : notnull => null;

            public bool IsEnabled(LogLevel logLevel) => owner.Enabled;

            public void Log<TState>(
                LogLevel logLevel,
                EventId eventId,
                TState state,
                Exception? exception,
                Func<TState, Exception?, string> formatter)
            {
                // A single-provider factory can hand the provider's logger straight to the caller, so the
                // caller's LogWarning may not consult IsEnabled; honor the toggle here as well.
                if (!owner.Enabled)
                    return;

                var fields = new Dictionary<string, object?>(StringComparer.Ordinal);
                if (state is IReadOnlyList<KeyValuePair<string, object?>> values)
                {
                    foreach (var pair in values)
                        fields[pair.Key] = pair.Value;
                }

                owner._logs.Add(new CapturedLog(category, logLevel, eventId, formatter(state, exception), fields));
            }
        }
    }

    private sealed record CapturedLog(
        string Category,
        LogLevel Level,
        EventId EventId,
        string Message,
        IReadOnlyDictionary<string, object?> Fields);
}

using System.Data.Common;
using System.Linq.Expressions;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;
using NextORM.Sqlite;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// D5 task A: SQL generation for global query filters injected into a raw `FromSql` source that was
/// explicitly bound with `BindEntity`. Covers the compatible/incompatible decision, empty-column
/// constellations, mapped output names, nullable predicates, raw parameter preservation and a bound
/// joined source (outer join: predicates stay in ON). No connection is opened.
/// </summary>
public class RawSourceBindingSqlGenerationTests
{
    private const string TenantKey = "rsb_sql_tenant";

    [SqlTable("rsb_sql_entity")]
    public sealed class RawSqlEntity
    {
        [System.ComponentModel.DataAnnotations.Schema.Column("id")]
        public int Id { get; set; }

        [System.ComponentModel.DataAnnotations.Schema.Column("tenant_id")]
        public int TenantId { get; set; }

        [System.ComponentModel.DataAnnotations.Schema.Column("is_deleted")]
        public bool IsDeleted { get; set; }

        [System.ComponentModel.DataAnnotations.Schema.Column("nullable_flag")]
        public bool? NullableFlag { get; set; }
    }

    [SqlTable("rsb_sql_alias_entity")]
    public sealed class RawSqlAliasEntity
    {
        [System.ComponentModel.DataAnnotations.Schema.Column("alt_id")]
        public int Id { get; set; }

        [System.ComponentModel.DataAnnotations.Schema.Column("alt_tenant")]
        public int TenantId { get; set; }
    }

    [SqlTable("rsb_sql_constant_entity")]
    public sealed class RawSqlConstantEntity
    {
        [System.ComponentModel.DataAnnotations.Schema.Column("id")]
        public int Id { get; set; }
    }

    [SqlTable("rsb_sql_column_dependent_entity")]
    public sealed class RawSqlColumnDependentEntity
    {
        [System.ComponentModel.DataAnnotations.Schema.Column("id")]
        public int Id { get; set; }
    }

    [SqlTable("rsb_sql_join_main")]
    public sealed class RawSqlJoinMain
    {
        [System.ComponentModel.DataAnnotations.Schema.Column("id")]
        public int Id { get; set; }
    }

    private static void ConfigureScope(IDataContext ctx)
        => ctx.From<RawSqlEntity>(b => b
            .HasQueryFilter("tenant", (e, c) => e.TenantId == (int)c.Properties[TenantKey])
            .HasQueryFilter(e => !e.IsDeleted)
            .HasQueryFilter(e => e.NullableFlag != true)
            .HasQueryFilter(e => e.Id > 0));

    private static void ConfigureAlias(IDataContext ctx)
        => ctx.From<RawSqlAliasEntity>(b => b
            .HasQueryFilter("tenant", (e, c) => e.TenantId == (int)c.Properties[TenantKey]));

    private static void ConfigureConstant(IDataContext ctx)
        => ctx.From<RawSqlConstantEntity>(b => b.HasQueryFilter(e => true));

    private static void ConfigureColumnDependent(IDataContext ctx)
        => ctx.From<RawSqlColumnDependentEntity>(b => b.HasQueryFilter(e => e.Id > 0));

    private static string Normalize(string sql) => sql.Replace("\r\n", "\n");

    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd)
    {
        var prepared = (DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None);
        return Normalize(prepared.DbCommand.CommandText);
    }

    [Fact]
    public void BoundCompatible_ShouldApplyEveryDeclaredFilter()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[TenantKey] = 7;
        ConfigureScope(ctx);

        var sql = SqlOf(ctx, ctx.FromSql("select id, tenant_id, is_deleted, nullable_flag from rsb_sql_table")
            .BindEntity<RawSqlEntity>(["id", "tenant_id", "is_deleted", "nullable_flag"])
            .Select(x => x.Id));

        sql.Should().Contain("from (select id, tenant_id, is_deleted, nullable_flag from rsb_sql_table)");
        sql.Should().Contain("tenant_id = $");
        sql.Should().Contain("not (");
        sql.Should().Contain("is_deleted");
        sql.Should().Contain("nullable_flag !=");
        sql.Should().Contain("id > 0");
    }

    [Fact]
    public void BoundIncompatible_ShouldSkipMissingFilterAndApplyCompatible()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[TenantKey] = 7;
        ConfigureScope(ctx);

        var sql = SqlOf(ctx, ctx.FromSql("select id, tenant_id, is_deleted from rsb_sql_table")
            .BindEntity<RawSqlEntity>(["id", "tenant_id", "is_deleted"])
            .Select(x => x.Id));

        sql.Should().Contain("tenant_id = $");
        sql.Should().Contain("id > 0");
        sql.Should().NotContain("nullable_flag", "the filter whose column is not declared is skipped");
    }

    [Fact]
    public void EmptyColumns_ConstantPredicate_ShouldApply()
    {
        using var ctx = SqliteTestContext.Create();
        ConfigureConstant(ctx);

        var sql = SqlOf(ctx, ctx.FromSql("select id from rsb_sql_table")
            .BindEntity<RawSqlConstantEntity>(Array.Empty<string>())
            .Select(x => x.Id));

        sql.Should().Contain("from (select id from rsb_sql_table)");
        sql.Should().Contain("where", "a proven zero-column filter is still rendered as a predicate");
    }

    [Fact]
    public void EmptyColumns_ColumnDependentPredicate_ShouldSkip()
    {
        using var ctx = SqliteTestContext.Create();
        ConfigureColumnDependent(ctx);

        var sql = SqlOf(ctx, ctx.FromSql("select id from rsb_sql_table")
            .BindEntity<RawSqlColumnDependentEntity>(Array.Empty<string>())
            .Select(x => x.Id));

        sql.Should().Contain("from (select id from rsb_sql_table)");
        sql.Should().NotContain("where", "the column-dependent filter is skipped against an empty declaration");
    }

    [Fact]
    public void MappedOutputNames_ShouldMatchTheDeclaredAlias()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[TenantKey] = 7;
        ConfigureAlias(ctx);

        var applied = SqlOf(ctx, ctx.FromSql("select alt_id, alt_tenant from rsb_sql_table")
            .BindEntity<RawSqlAliasEntity>(["alt_id", "alt_tenant"])
            .Select(x => x.Id));
        applied.Should().Contain("alt_tenant =");
        applied.Should().NotContain("tenant_id", "the filter dependency is the mapped column name");

        var skipped = SqlOf(ctx, ctx.FromSql("select alt_id from rsb_sql_table")
            .BindEntity<RawSqlAliasEntity>(["alt_id"])
            .Select(x => x.Id));
        skipped.Should().NotContain("alt_tenant");
    }

    [Fact]
    public void NullablePredicate_ShouldRenderWhenDeclared()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[TenantKey] = 7;
        ConfigureScope(ctx);

        var sql = SqlOf(ctx, ctx.FromSql("select id, nullable_flag from rsb_sql_table")
            .BindEntity<RawSqlEntity>(["id", "nullable_flag"])
            .Select(x => x.Id));

        sql.Should().Contain("nullable_flag");
        sql.Should().Contain("id > 0");
    }

    [Fact]
    public void RawParameterAndFilterParameter_ShouldBothBePreserved()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[TenantKey] = 7;
        ConfigureScope(ctx);

        var prepared = (DbPreparedQueryCommand<int>)ctx.GetPreparedQueryCommand(
            ctx.FromSql("select id, tenant_id from rsb_sql_table where id > $min", new { min = 3 })
                .BindEntity<RawSqlEntity>(["id", "tenant_id"])
                .Select(x => x.Id),
            false,
            false,
            CancellationToken.None);

        var sql = Normalize(prepared.DbCommand.CommandText);
        sql.Should().Contain("id > $min", "the raw SQL parameter placeholder is preserved verbatim");
        sql.Should().Contain("tenant_id = $");
        var values = prepared.DbCommand.Parameters.Cast<DbParameter>().Select(p => p.Value).ToArray();
        values.Should().Contain(3, "the raw parameter value is bound");
        values.Should().Contain(7, "the filter parameter value is bound");
    }

    [Fact]
    public void JoinedBoundSource_MixedFilters_ShouldApplyCompatibleInOnAndKeepOuterJoin()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[TenantKey] = 7;
        ConfigureScope(ctx);

        var bound = ctx.FromSql("select id, tenant_id, is_deleted from rsb_sql_table")
            .BindEntity<RawSqlEntity>(["id", "tenant_id", "is_deleted"]);

        var sql = SqlOf(ctx, ctx.From<RawSqlJoinMain>()
            .LeftJoin(bound, (a, b) => a.Id == b.Id)
            .Select(p => p.Item1.Id));

        sql.Should().Contain("left join (select id, tenant_id, is_deleted from rsb_sql_table)");
        sql.Should().Contain("t1.id = t2.id");
        sql.Should().Contain("tenant_id =", "the compatible filter is applied to the join alias");
        sql.Should().Contain("is_deleted");
        sql.Should().Contain("not (");
        sql.Should().Contain("id > 0");
        sql.Should().NotContain("nullable_flag", "the incompatible filter is skipped, the compatible ones stay");
        sql.Should().NotContain("where", "an outer-join filter stays in the ON clause");
    }

    [Fact]
    public void MainBoundSource_Joined_ShouldApplyOwnFiltersInWhere()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[TenantKey] = 7;
        ConfigureScope(ctx);

        var main = ctx.FromSql("select id, tenant_id, is_deleted from rsb_sql_table")
            .BindEntity<RawSqlEntity>(["id", "tenant_id", "is_deleted"]);

        var sql = SqlOf(ctx, main
            .Join(ctx.From<RawSqlJoinMain>(), (a, b) => a.Id == b.Id)
            .Select(p => p.Item1.Id));

        sql.Should().Contain("from (select id, tenant_id, is_deleted from rsb_sql_table)");
        sql.Should().Contain("tenant_id =", "the compatible main filter is applied against the main binding");
        sql.Should().Contain("is_deleted");
        sql.Should().Contain("id > 0");
        sql.Should().NotContain("nullable_flag", "an undeclared main dependency is skipped");
        sql.Should().Contain("where", "main-source filters land in WHERE, never in a join ON clause");
    }

    [Fact]
    public void BoundCrossJoin_ShouldApplyFilterInWhereWithoutOn()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[TenantKey] = 7;
        ConfigureScope(ctx);

        var bound = ctx.FromSql("select id, tenant_id, is_deleted from rsb_sql_table")
            .BindEntity<RawSqlEntity>(["id", "tenant_id", "is_deleted"]);

        var sql = SqlOf(ctx, ctx.From<RawSqlJoinMain>()
            .CrossJoin(bound)
            .Select(p => p.Item1.Id));

        sql.Should().Contain(" cross join (select id, tenant_id, is_deleted from rsb_sql_table)");
        sql.Should().NotContain(" on ", "a cross join must not fabricate an ON clause");
        sql.Should().Contain("tenant_id =", "the compatible filter is applied");
        sql.Should().Contain("is_deleted");
        sql.Should().Contain("id > 0");
        sql.Should().NotContain("nullable_flag", "an incompatible filter is skipped");
        sql.Should().Contain("where", "the cross-join filter is placed in WHERE");
    }

    [Fact]
    public void UnboundSource_ShouldRenderWithoutFilters()
    {
        using var ctx = SqliteTestContext.Create();
        ctx.Properties[TenantKey] = 7;
        ConfigureScope(ctx);

        var sql = SqlOf(ctx, ctx.FromSql("select id, tenant_id from rsb_sql_table")
            .Select(x => x["id"].AsInt));

        sql.Should().Contain("from (select id, tenant_id from rsb_sql_table)");
        sql.Should().NotContain("where", "an unbound raw source is never filtered");
        sql.Should().NotContain("tenant_id =");
    }
}

/// <summary>
/// #185 D185: binding a raw source is self-sufficient — it registers the entity mapping through the
/// same path as <c>From&lt;T&gt;()</c>, so a typed member projection works on a genuinely cold
/// <see cref="DataContextCache.Metadata"/> (no prior <c>From&lt;T&gt;</c>). The negative half pins the
/// configured-mapping precedence and that a repeated bind is a registration no-op.
/// <para>
/// Joins the serialized "DataContextCache clear" collection because it clears the process-wide cache.
/// </para>
/// </summary>
[Collection("DataContextCache clear")]
public class RawSourceBindingColdRegistrationTests
{
    [SqlTable("rsb_cold_configured")]
    public sealed class ColdConfiguredEntity
    {
        [System.ComponentModel.DataAnnotations.Schema.Column("attr_name")]
        public string? Name { get; set; }
    }

    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd)
    {
        var prepared = (DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None);
        return prepared.DbCommand.CommandText.Replace("\r\n", "\n");
    }

    // R01/R02: cold interface + typed projection via the raw-SQL entry point.
    [Fact]
    public void ColdInterfaceTypedProjection_FromSql_ShouldRegisterAndRender()
    {
        DataContextCache.Clear();
        using var ctx = SqliteTestContext.Create();

        DataContextCache.Metadata.ContainsKey(typeof(IComplexEntity)).Should().BeFalse("genuinely cold metadata");

        var sql = SqlOf(ctx, ctx.FromSql("select id, somestring from complex_entity")
            .BindEntity<IComplexEntity>(["id", "somestring"])
            .Select(t => t.Id));

        sql.Should().Contain("select id from (select id, somestring from complex_entity)");
        DataContextCache.Metadata.ContainsKey(typeof(IComplexEntity)).Should().BeTrue(
            "binding registers the mapping without a prior From<T>()");
    }

    // R01/R02: the same cold binding through the named-source entry point.
    [Fact]
    public void ColdInterfaceTypedProjection_FromNamedSource_ShouldRegisterAndRender()
    {
        DataContextCache.Clear();
        using var ctx = SqliteTestContext.Create();

        DataContextCache.Metadata.ContainsKey(typeof(IComplexEntity)).Should().BeFalse("genuinely cold metadata");

        var sql = SqlOf(ctx, ctx.From("complex_entity")
            .BindEntity<IComplexEntity>(["id", "somestring"])
            .Select(t => t.Id));

        sql.Should().Contain("from complex_entity");
        sql.Should().Contain("id");
        DataContextCache.Metadata.ContainsKey(typeof(IComplexEntity)).Should().BeTrue();
    }

    // R04: a configured From<T>(cfg) registered before binding keeps its configured column name.
    [Fact]
    public void ColdConfiguredMapping_ShouldWinOverAttributeMapping()
    {
        DataContextCache.Clear();
        using var ctx = SqliteTestContext.Create();
        ctx.From<ColdConfiguredEntity>(cfg => cfg.Property(x => x.Name!).HasColumnName("configured_name"));

        DataContextCache.Metadata[typeof(ColdConfiguredEntity)].Properties
            .Should().ContainSingle(p => p.ColumnName == "configured_name");

        var sql = SqlOf(ctx, ctx.FromSql("select configured_name from rsb_cold_configured")
            .BindEntity<ColdConfiguredEntity>(["configured_name"])
            .Select(x => x.Name));

        sql.Should().Contain("configured_name");
        sql.Should().NotContain("attr_name", "the configured mapping wins over the attribute mapping");
    }

    // R02: a repeated bind does not change the mapping or the generated SQL.
    [Fact]
    public void RepeatedBind_ShouldNotChangeSqlOrMapping()
    {
        DataContextCache.Clear();
        using var ctx = SqliteTestContext.Create();
        var source = ctx.FromSql("select id, somestring from complex_entity");

        var first = source.BindEntity<IComplexEntity>(["id", "somestring"]).Select(t => t.Id);
        var firstMetadata = DataContextCache.Metadata[typeof(IComplexEntity)];
        var second = source.BindEntity<IComplexEntity>(["id", "somestring"]).Select(t => t.Id);

        SqlOf(ctx, first).Should().Be(SqlOf(ctx, second));
        DataContextCache.Metadata[typeof(IComplexEntity)].Should().BeSameAs(firstMetadata,
            "the second bind is a registration no-op");
    }

    // R07: the exact TableAlias guard is unchanged and registers no mapping.
    [Fact]
    public void TableAlias_BindEntity_ShouldStillThrowNotSupported()
    {
        DataContextCache.Clear();
        using var ctx = SqliteTestContext.Create();
        var source = ctx.FromSql("select 1 as Id");

        var act = () => source.BindEntity<TableAlias>(["Id"]);

        act.Should().Throw<NotSupportedException>();
        DataContextCache.Metadata.ContainsKey(typeof(TableAlias)).Should().BeFalse(
            "TableAlias is rejected and has no mapping to register");
    }

    /// <summary>
    /// A class entity unique to the R03 materialization proof: it is never primed through
    /// <c>From&lt;T&gt;()</c>, so the bind's own registration is the only mapping source. It carries a
    /// nullable string and a nullable value type so both a null and a non-null column value are checked.
    /// </summary>
    [SqlTable("rsb_cold_class")]
    public sealed class ColdClassEntity
    {
        [System.ComponentModel.DataAnnotations.Schema.Column("id")]
        public int Id { get; set; }

        [System.ComponentModel.DataAnnotations.Schema.Column("name")]
        public string? Name { get; set; }

        [System.ComponentModel.DataAnnotations.Schema.Column("nullable_flag")]
        public bool? NullableFlag { get; set; }
    }

    // R03 (authoritative): a class entity materializes from a raw source with no prior From<T>(), on a
    // verified-cold Metadata, including a null and a non-null nullable value. Isolated in the serialized
    // cache-clear collection and run in isolation, because the integration smoke test cannot establish
    // coldness across providers in one process (the first provider registers the shared type).
    [Fact]
    public void ColdClassEntity_RawSql_ShouldMaterializeNullAndNonNullValues()
    {
        DataContextCache.Clear();

        var path = Path.Combine(Path.GetTempPath(), $"nextorm-rsb-cold-class-{Guid.NewGuid():N}.db");
        try
        {
            using (var conn = new SqliteConnection($"Data Source={path}"))
            {
                conn.Open();
                using var cmd = conn.CreateCommand();
                cmd.CommandText =
                    "create table rsb_cold_class (id integer primary key, name text null, nullable_flag integer null);" +
                    "insert into rsb_cold_class (id, name, nullable_flag) values (1, 'present', 1);" +
                    "insert into rsb_cold_class (id, name, nullable_flag) values (2, null, null);";
                cmd.ExecuteNonQuery();
            }

            using var ctx = new SqliteDataContext($"Data Source={path}", new DataContextBuilder());

            DataContextCache.Metadata.ContainsKey(typeof(ColdClassEntity)).Should().BeFalse(
                "the configured metadata cache is genuinely cold before the bind");

            // No prior ctx.From<ColdClassEntity>(): the bind itself registers the mapping, and the whole
            // class (not an interface or an identity projection) is materialized by the terminal.
            var rows = ctx.FromSql("select id, name, nullable_flag from rsb_cold_class")
                .BindEntity<ColdClassEntity>(["id", "name", "nullable_flag"])
                .ToList();

            rows.Should().HaveCount(2);

            var present = rows.Single(r => r.Id == 1);
            present.Name.Should().Be("present", "the non-null value round-trips");
            present.NullableFlag.Should().BeTrue("the non-null nullable value round-trips");

            var missing = rows.Single(r => r.Id == 2);
            missing.Name.Should().BeNull("a null column value materializes as null, not a default");
            missing.NullableFlag.Should().BeNull("a null nullable value materializes as null");

            DataContextCache.Metadata.ContainsKey(typeof(ColdClassEntity)).Should().BeTrue(
                "binding registers the class mapping without a prior From<T>()");
        }
        finally
        {
            File.Delete(path);
        }
    }
}

using System.Data.Common;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Coverage for the #112 plain multi-column reader seam (<c>DataContext.OpenResultReader</c>): SQLite
/// used to reject every multi-column reader because the LOB path appends a <c>rowid</c> locator, which
/// the single-column guard then rejects. The plain seam prepares without sequential access, so a
/// multi-column projection must execute end to end on an in-process SQLite database.
/// </summary>
public class ResultReaderTests
{
    [SqlTable("result_reader_row")]
    private sealed class ResultReaderRow
    {
        [System.ComponentModel.DataAnnotations.Schema.Column("id")]
        public int Id { get; set; }

        [System.ComponentModel.DataAnnotations.Schema.Column("name")]
        public string? Name { get; set; }

        [System.ComponentModel.DataAnnotations.Schema.Column("flag")]
        public bool Flag { get; set; }
    }

    private static SqliteDataContext CreateDb(out string path)
    {
        path = Path.Combine(Path.GetTempPath(), $"nextorm-resultreader-{Guid.NewGuid():N}.db");
        using (var connection = new SqliteConnection($"Data Source={path}"))
        {
            connection.Open();
            using var command = connection.CreateCommand();
            command.CommandText =
                "create table result_reader_row (id integer primary key, name text, flag integer);" +
                "insert into result_reader_row (id, name, flag) values (1, 'alpha', 1), (2, null, 0);";
            command.ExecuteNonQuery();
        }

        return new SqliteDataContext($"Data Source={path}", new DataContextBuilder());
    }

    [Fact]
    public void OpenResultReader_Sqlite_MultiColumn_ReadsEveryRowWithoutLocator()
    {
        var ctx = CreateDb(out var path);
        try
        {
            var command = ctx.From<ResultReaderRow>().OrderBy(it => it.Id).ToParentCommand();
            var cacheBefore = command.Cache;

            using var owner = ctx.OpenResultReader(command, ReadOnlySpan<object?>.Empty, CancellationToken.None);

            owner.Reader.FieldCount.Should().Be(3, "the plain seam must not append a locator column");
            owner.Reader.Read().Should().BeTrue();
            owner.Reader.GetInt32(0).Should().Be(1);
            owner.Reader.GetString(1).Should().Be("alpha");
            owner.Reader.GetBoolean(2).Should().BeTrue();
            owner.Reader.Read().Should().BeTrue();
            owner.Reader.GetInt32(0).Should().Be(2);
            owner.Reader.IsDBNull(1).Should().BeTrue();
            owner.Reader.Read().Should().BeFalse();

            command.Cache.Should().Be(cacheBefore, "the seam must not mutate the shared command");
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public async Task OpenResultReaderAsync_Sqlite_MultiColumn_ReadsEveryRow()
    {
        var ctx = CreateDb(out var path);
        try
        {
            var command = ctx.From<ResultReaderRow>().OrderBy(it => it.Id).ToParentCommand();

            var owner = await ctx.OpenResultReaderAsync(command, null, TestContext.Current.CancellationToken);
            await using (owner.ConfigureAwait(false))
            {
                owner.Reader.FieldCount.Should().Be(3);
                (await owner.Reader.ReadAsync(TestContext.Current.CancellationToken)).Should().BeTrue();
                owner.Reader.GetInt32(0).Should().Be(1);
                (await owner.Reader.ReadAsync(TestContext.Current.CancellationToken)).Should().BeTrue();
                owner.Reader.GetInt32(0).Should().Be(2);
                (await owner.Reader.ReadAsync(TestContext.Current.CancellationToken)).Should().BeFalse();
            }
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }
}

using System.Data.Common;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Verifies the per-query source overrides on SQLite: a schema/database qualifier names an attached
/// database and a raw table expression renders as a derived source. No connection is opened.
/// </summary>
public class SourceOverrideSqlGenerationTests
{
    private static string Normalize(string sql) => sql.Replace("\r\n", "\n");

    private static DbPreparedQueryCommand<T> Prepare<T>(IDataContext ctx, QueryCommand<T> cmd)
        => (DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None);

    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd) => Normalize(Prepare(ctx, cmd).DbCommand.CommandText);

    [Fact]
    public void WithSchema_ShouldRenderAttachedDatabaseQualifier()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<ISimpleEntity>();

        SqlOf(ctx, e.WithSchema("main").Select(x => new { x.Id }))
            .Should().Be("select id from main.simple_entity");
    }

    [Fact]
    public void WithDatabase_ShouldRenderAttachedDatabaseQualifier()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<ISimpleEntity>();

        SqlOf(ctx, e.WithDatabase("main").Select(x => new { x.Id }))
            .Should().Be("select id from main.simple_entity");
    }

    [Fact]
    public void WithServer_ShouldThrowBecauseNotSupported()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<ISimpleEntity>();

        var act = () => SqlOf(ctx, e.WithServer("srv").Select(x => new { x.Id }));

        act.Should().Throw<NotSupportedException>();
    }

    [Fact]
    public void WithTableExpression_ShouldRenderDerivedSource()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<ISimpleEntity>();

        SqlOf(ctx, e.WithTableExpression("select id from other").Select(x => new { x.Id }))
            .Should().Be("select id from (select id from other) as 't1'");
    }

    [Fact]
    public void WithoutOverride_ShouldRenderMappedTable()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<ISimpleEntity>();

        SqlOf(ctx, e.Select(x => new { x.Id })).Should().Be("select id from simple_entity");
    }

    [Fact]
    public void NamedTableBuilder_WithSchema_ShouldQualify()
    {
        using var ctx = SqliteTestContext.Create();

        SqlOf(ctx, ctx.From("simple_entity").WithSchema("main").Select(t => new { id = t["id"].AsInt }))
            .Should().Be("select id from main.simple_entity");
    }

    [Fact]
    public void NamedTableBuilder_WithTableExpression_ShouldRenderDerivedSource()
    {
        using var ctx = SqliteTestContext.Create();

        SqlOf(ctx, ctx.From("simple_entity").WithTableExpression("select id from other").Select(t => new { id = t["id"].AsInt }))
            .Should().Be("select t1.id from (select id from other) as 't1'");
    }

    [Fact]
    public void SameOverride_ShouldReuseCachedPlan()
    {
        using var ctx = SqliteTestContext.Create();

        var first = ctx.GetPreparedQueryCommand(
            ctx.From<ISimpleEntity>().WithSchema("main").Select(x => new { x.Id }), false, true, CancellationToken.None);
        var second = ctx.GetPreparedQueryCommand(
            ctx.From<ISimpleEntity>().WithSchema("main").Select(x => new { x.Id }), false, true, CancellationToken.None);

        ReferenceEquals(first, second).Should().BeTrue("an equal source override must reuse the cached plan");
    }

    [Fact]
    public void DifferentOverride_ShouldNotReuseCachedPlan()
    {
        using var ctx = SqliteTestContext.Create();

        var first = ctx.GetPreparedQueryCommand(
            ctx.From<ISimpleEntity>().WithSchema("main").Select(x => new { x.Id }), false, true, CancellationToken.None);
        var second = ctx.GetPreparedQueryCommand(
            ctx.From<ISimpleEntity>().WithSchema("other").Select(x => new { x.Id }), false, true, CancellationToken.None);

        ReferenceEquals(first, second).Should().BeFalse("a different source override must not share a cached plan");
    }
}

