    // ---------------------------------------------------------------------------------------------
    // Input guards (#181, E181-16): the FTS first operand must be a mapped column or a trusted
    // constant token, and a null query must not silently drop the filter.
    // ---------------------------------------------------------------------------------------------

    private sealed class TokenHolder
    {
        public string Value { get; set; } = "q";
    }

    [Fact]
    [Trait("Issue", "181")]
    public void Fts_Match_ShouldRejectNullEmptyComputedAndCapturedFirstOperand()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();
        var holder = new TokenHolder();

        var nullConstant = () => SqlOf(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.Match((string?)null, "q") }));
        var emptyConstant = () => SqlOf(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.Match("", "q") }));
        var computed = () => SqlOf(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.Match(x.Int + 1, "q") }));
        var captured = () => SqlOf(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.Match(holder.Value, "q") }));

        nullConstant.Should().Throw<NotSupportedException>().WithMessage("*mapped column*constant non-empty*");
        emptyConstant.Should().Throw<NotSupportedException>();
        computed.Should().Throw<NotSupportedException>();
        captured.Should().Throw<NotSupportedException>();
    }

    [Fact]
    [Trait("Issue", "181")]
    public void Fts_AuxiliaryAndRank_ShouldRejectNullEmptyAndComputedTableToken()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();
        var holder = new TokenHolder();

        var bm25Null = () => SqlOf(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.FTS5bm25((string?)null) }));
        var bm25Empty = () => SqlOf(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.FTS5bm25("") }));
        var highlightComputed = () => SqlOf(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.Highlight(holder.Value, 0, "[", "]") }));
        var rankNull = () => SqlOf(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.Rank((string?)null) }));

        bm25Null.Should().Throw<NotSupportedException>().WithMessage("*FTS5bm25*constant non-empty*");
        bm25Empty.Should().Throw<NotSupportedException>();
        highlightComputed.Should().Throw<NotSupportedException>();
        rankNull.Should().Throw<NotSupportedException>();
    }

    [Fact]
    [Trait("Issue", "181")]
    public void Fts5_MatchTable_ShouldRejectNullAndEmptyTableToken()
    {
        using var ctx = SqliteTestContext.Create();

        var nullToken = () => SqlOf(ctx, ctx
            .FromTableFunction(() => SqlFunctions.Sqlite.MatchTable<ISimpleEntity>((string?)null, "hello"))
            .Select(r => r.Id));
        var emptyToken = () => SqlOf(ctx, ctx
            .FromTableFunction(() => SqlFunctions.Sqlite.MatchTable<ISimpleEntity>("", "hello"))
            .Select(r => r.Id));

        nullToken.Should().Throw<NotSupportedException>().WithMessage("*verbatim table-function argument*constant string*");
        emptyToken.Should().Throw<NotSupportedException>().WithMessage("*non-empty constant table token*");
    }

    [Fact]
    [Trait("Issue", "181")]
    public void Fts_Match_ShouldPreserveNullQueryPredicate()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var sql = SqlOf(ctx, e
            .Where(x => SqlFunctions.Sqlite.Match(x.String, (string?)null))
            .Select(x => x.Id));

        // A null FTS query is inherited by the native statement (MATCH null), never silently dropped.
        sql.Should().Contain("MATCH null");
    }

    [Fact]
    [Trait("Issue", "181")]
    public void Fts_Match_ShouldKeepTableTokenAndMappedColumnOperandsValid()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var prepared = Prepared(ctx, e.Select(x => new
        {
            Table = SqlFunctions.Sqlite.Match("docs_fts", "hello"),
            Column = SqlFunctions.Sqlite.Match(x.String, "hello")
        }));
        var sql = Normalize(prepared.DbCommand.CommandText);

        sql.Should().Contain("\"docs_fts\" MATCH $p0");
        sql.Should().Contain("somestring MATCH $p1");
        prepared.DbCommand.Parameters.Cast<DbParameter>().Select(p => p.Value).Should().Equal("hello", "hello");
    }

    [Fact]
    [Trait("Issue", "181")]
    public void Fts_Match_AdversarialToken_ShouldBeOneEscapedIdentifierNotRawSql()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var prepared = Prepared(ctx, e.Select(x => new
        {
            V = SqlFunctions.Sqlite.Match("a\"; DROP TABLE sentinel; --", "q")
        }));
        var sql = Normalize(prepared.DbCommand.CommandText);

        sql.Should().Contain("\"a\"\"; DROP TABLE sentinel; --\" MATCH $p0",
            "the whole token must be one escaped identifier");
        sql.Should().NotContain("DROP TABLE sentinel; -- MATCH", "the raw text must not become SQL");
        sql.Should().NotContain("'q'", "the adversarial query must be bound, not inlined");
        prepared.DbCommand.Parameters.Cast<DbParameter>().Select(p => p.Value).Should().Equal("q");
    }

    [Fact]
    [Trait("Issue", "181")]
    public void Fts_ApostropheConstants_ShouldBindNotInlineBrokenLiterals()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        // An apostrophe-bearing search query must be bound; inlining it as a raw literal would both
        // break the statement and let the value escape the literal.
        var match = Prepared(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.Match("docs_fts", "O'Brien") }));
        var matchSql = Normalize(match.DbCommand.CommandText);
        matchSql.Should().Contain("\"docs_fts\" MATCH $p0");
        matchSql.Should().NotContain("'O'Brien'", "the apostrophe-bearing query must be bound, not inlined");
        match.DbCommand.Parameters.Cast<DbParameter>().Select(p => p.Value).Should().Equal("O'Brien");

        // The same holds for the marker/format value positions.
        var marker = Prepared(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.Highlight("docs_fts", 0, "O'Brien", "]") }));
        var markerSql = Normalize(marker.DbCommand.CommandText);
        markerSql.Should().Contain("highlight(\"docs_fts\", 0, $p0, $p1)");
        markerSql.Should().NotContain("'O'Brien'");
        marker.DbCommand.Parameters.Cast<DbParameter>().Select(p => p.Value).Should().Equal("O'Brien", "]");

        var format = Prepared(ctx, e.Select(x => new { V = SqlFunctions.Sqlite.FTS3MatchInfo("docs_fts", "p'cx") }));
        var formatSql = Normalize(format.DbCommand.CommandText);
        formatSql.Should().Contain("matchinfo(\"docs_fts\", $p0)");
        formatSql.Should().NotContain("'p'cx'");
        format.DbCommand.Parameters.Cast<DbParameter>().Select(p => p.Value).Should().Equal("p'cx");
    }

    // ---------------------------------------------------------------------------------------------
    // Branch evidence (#181, E181-19): the reachable outcomes of WrapTableFunction and the renderer
    // fallback are asserted directly (not by coverage hits alone).
    // ---------------------------------------------------------------------------------------------

    [Fact]
    [Trait("Issue", "181")]
    public void WrapTableFunction_Fts5_ShouldQuoteTokenRejectMalformedAndPassThroughOthers()
    {
        var dialect = NextORM.Sqlite.SqliteDialect.Instance;

        // The table token arrives as its own structured argument (never reparsed from the call text):
        // it is echoed as one quoted identifier while the query argument passes through unchanged.
        dialect.WrapTableFunction("fts5", "fts5(docs_fts, $p0)", new[] { "docs_fts", "$p0" })
            .Should().Be("\"docs_fts\"($p0)");
        dialect.WrapTableFunction("fts5", "fts5(ignored, ignored)", new[] { "a\"; DROP TABLE sentinel; --", "$p0" })
            .Should().Be("\"a\"\"; DROP TABLE sentinel; --\"($p0)",
                "the whole adversarial token is one escaped identifier, never reparsed as SQL");
        dialect.WrapTableFunction("json_each", "json_each('[1]')", new[] { "'[1]'" })
            .Should().Be("json_each('[1]')", "non-FTS table functions pass through unchanged");

        var tooFew = () => dialect.WrapTableFunction("fts5", "fts5(x)", new[] { "docs_fts" });
        var emptyTable = () => dialect.WrapTableFunction("fts5", "fts5(x)", new[] { "", "$p0" });

        tooFew.Should().Throw<NotSupportedException>().WithMessage("*requires a table token and a query*");
        emptyTable.Should().Throw<NotSupportedException>().WithMessage("*non-empty constant table token*");
    }

    [Fact]
    [Trait("Issue", "181")]
    public void SqliteFunctionRenderer_UnsupportedName_ShouldThrowInsteadOfEmittingRawSql()
    {
        var functions = NextORM.Sqlite.SqliteDialect.Instance.SqliteFunctions!;

        functions.Supports("bogus").Should().BeFalse();

        var act = () => functions.Render("bogus", Array.Empty<string>());
        act.Should().Throw<NotSupportedException>().WithMessage("*bogus*not supported by SQLite*");
    }
}

using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Behavioural coverage for the raw-SQL LOB guard: a single-column raw SQL override
/// (<c>WithSql</c>) cannot stream on SQLite, because the dialect appends its <c>rowid</c> locator
/// only to generated SQL. The unsafe shape is rejected up front with a clear
/// <see cref="NotSupportedException"/>; every other raw shape keeps the generic
/// <see cref="InvalidOperationException"/> projection-mismatch error. Runs against a real temp-file
/// SQLite database so the <c>FieldCount</c> guard observes the reader the driver actually returns.
/// </summary>
public class SqliteLobGuardTests
{
    private const string ExpectedRawMessage =
        "SQLite LOB streaming with raw SQL (WithSql) is not supported because a rowid locator cannot be added safely.";

    private static (DataContext Context, string Path) CreateDb()
    {
        var path = Path.Combine(Path.GetTempPath(), $"nextorm-lob-guard-{Guid.NewGuid():N}.db");
        using (var connection = new SqliteConnection($"Data Source={path}"))
        {
            connection.Open();
            using var command = connection.CreateCommand();
            command.CommandText =
                "create table lob_probe (id integer primary key, payload blob, body text);" +
                "insert into lob_probe (id, payload, body) values (1, x'0102', 'hi');";
            command.ExecuteNonQuery();
        }

        return (new SqliteDataContext($"Data Source={path}", new DataContextBuilder()), path);
    }

    private static void WithDb(Action<DataContext> test)
    {
        var (ctx, path) = CreateDb();
        try
        {
            test(ctx);
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void RawSqlSingleColumnBinary_ToStream_ShouldThrowNotSupported()
        => WithDb(ctx =>
        {
            var command = ctx.From<ILobProbeEntity>().Select(x => x.Payload!).WithSql("select payload from lob_probe");

            var act = () => command.ToStream();

            act.Should().Throw<NotSupportedException>().WithMessage(ExpectedRawMessage);
        });

    [Fact]
    public async Task RawSqlSingleColumnBinary_ToStreamAsync_ShouldThrowNotSupported()
    {
        var (ctx, path) = CreateDb();
        try
        {
            var command = ctx.From<ILobProbeEntity>().Select(x => x.Payload!).WithSql("select payload from lob_probe");

            var act = async () => await command.ToStreamAsync(TestContext.Current.CancellationToken);

            await act.Should().ThrowAsync<NotSupportedException>().WithMessage(ExpectedRawMessage);
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void RawSqlSingleColumnText_ToTextReader_ShouldThrowNotSupported()
        => WithDb(ctx =>
        {
            var command = ctx.From<ILobProbeEntity>().Select(x => x.Body!).WithSql("select body from lob_probe");

            var act = () => command.ToTextReader();

            act.Should().Throw<NotSupportedException>().WithMessage(ExpectedRawMessage);
        });

    [Fact]
    public async Task RawSqlSingleColumnText_ToTextReaderAsync_ShouldThrowNotSupported()
    {
        var (ctx, path) = CreateDb();
        try
        {
            var command = ctx.From<ILobProbeEntity>().Select(x => x.Body!).WithSql("select body from lob_probe");

            var act = async () => await command.ToTextReaderAsync(TestContext.Current.CancellationToken);

            await act.Should().ThrowAsync<NotSupportedException>().WithMessage(ExpectedRawMessage);
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [Fact]
    public void RawSqlTwoColumnBinary_ToStream_ShouldThrowInvalidOperation()
        => WithDb(ctx =>
        {
            // A multi-column raw projection is not a single-value terminal regardless of the locator.
            var command = ctx.From<ILobProbeEntity>().Select(x => x.Payload!).WithSql("select payload, id from lob_probe");

            var act = () => command.ToStream();

            act.Should().Throw<InvalidOperationException>();
        });

    [Fact]
    public async Task RawSqlTwoColumnText_ToTextReaderAsync_ShouldThrowInvalidOperation()
    {
        var (ctx, path) = CreateDb();
        try
        {
            var command = ctx.From<ILobProbeEntity>().Select(x => x.Body!).WithSql("select body, id from lob_probe");

            var act = async () => await command.ToTextReaderAsync(TestContext.Current.CancellationToken);

            await act.Should().ThrowAsync<InvalidOperationException>();
        }
        finally
        {
            ctx.Dispose();
            File.Delete(path);
        }
    }

    [SqlTable("lob_probe")]
    internal interface ILobProbeEntity
    {
        [Key]
        [Column("id")]
        int Id { get; set; }
        [Column("payload")]
        byte[]? Payload { get; set; }
        [Column("body")]
        string? Body { get; set; }
    }
}

using System.Data;
using Microsoft.Data.Sqlite;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Capability probe (PDCA cycle 2, issue #27): on a real Microsoft.Data.Sqlite 10.0.12 connection,
/// does <see cref="System.Data.Common.DbDataReader.GetStream(int)"/> under
/// <see cref="System.Data.CommandBehavior.SequentialAccess"/> return a memory-bounded
/// <c>SqliteBlob</c> when the query also projects <c>rowid</c>, versus a buffered
/// <see cref="MemoryStream"/> when it does not?
/// <para>
/// The driver is used directly (<see cref="SqliteConnection"/>/<see cref="SqliteCommand"/>), so the
/// nextorm LOB terminals and their <c>FieldCount != 1</c> guard are bypassed (the guard is left
/// untouched). A normal rowid table <c>t(id INTEGER PRIMARY KEY, payload BLOB)</c> is seeded with
/// 1 MiB, 8 MiB and 32 MiB rows; each read uses a fixed 64 KiB buffer and reports the best-of-3
/// <see cref="GC.GetAllocatedBytesForCurrentThread"/> delta plus the peak live-managed delta
/// (<see cref="GC.GetTotalMemory(bool)"/> sampled every buffer iteration, relative to the
/// pre-read baseline). A memory-bounded read has <c>alloc(size) / alloc(1 MiB) ≈ 1</c> and a
/// flat peak; a buffered read shows <c>≈ size / 1 MiB</c> and a peak that grows with the size.
/// Each row is addressed by its explicit <c>id</c>, so the size-to-row mapping never depends on
/// an unordered <c>SELECT</c>'s implicit order.
/// </para>
/// <para>
/// It also documents the fail-closed behavior for a view and a <c>WITHOUT ROWID</c> table, and
/// records the <c>FieldCount</c> of both projections (a trailing <c>rowid</c> makes it 2, which the
/// existing nextorm guard would reject).
/// </para>
/// <para>
/// Out-of-band probe: it only runs when <c>NEXTORM_LOB_SQLITE_PROBE=1</c> is set, so the normal
/// suite does not pay for the multi-megabyte seeds and reads. No containers are required.
/// </para>
/// </summary>
public sealed class SqliteRowIdLobProbeTests
{
    private const int MiB = 1024 * 1024;
    private const int ReadBufferBytes = 64 * 1024;
    private const int Samples = 3;

    private static readonly int[] Sizes = [MiB, 8 * MiB, 32 * MiB];

    // Deterministic byte pattern with period 256: byte(i) = (byte)((i * 131 + 7) & 0xFF).
    private static readonly byte[] Pattern = BuildPattern();

    private static string OutputPath =>
        Environment.GetEnvironmentVariable("NEXTORM_LOB_SQLITE_PROBE_LOG")
        ?? "/tmp/lob-sqlite-rowid-probe.log";

    [Fact]
    public void Sqlite_RowId_Projection_Streams_Lobs_MemoryBounded()
    {
        Assert.SkipUnless(
            Environment.GetEnvironmentVariable("NEXTORM_LOB_SQLITE_PROBE") == "1",
            "Set NEXTORM_LOB_SQLITE_PROBE=1 to run the SQLite rowid LOB capability probe.");

        var databasePath = Path.Combine(Path.GetTempPath(), $"nextorm-lob-rowid-{Guid.NewGuid():N}.db");
        var lines = new List<string>
        {
            $"# SQLite rowid LOB capability probe; driver Microsoft.Data.Sqlite 10.0.12; runtime {Environment.Version}",
            $"# database {databasePath}",
            "# shape | query | size | stream type | bytes | allocated (best of 3) | peak live-delta | ratio vs 1 MiB | correct",
        };

        try
        {
            // Pooling=false: a pooled connection would keep the OS handle open after Dispose and
            // (on Windows) silently defeat the temp-file delete below.
            using var connection = new SqliteConnection($"Data Source={databasePath};Pooling=False");
            connection.Open();

            Seed(connection);

            foreach (var shape in new[] { "baseline", "rowid" })
            {
                // The row is addressed by its explicit id (seeded as size index + 1) so the
                // size -> row mapping never depends on an unordered SELECT's implicit order.
                var projection = shape == "baseline"
                    ? "SELECT payload FROM t WHERE id = $id"
                    : "SELECT payload, rowid FROM t WHERE id = $id";

                var results = new ProbeResult[Sizes.Length];
                for (var sizeIndex = 0; sizeIndex < Sizes.Length; sizeIndex++)
                    results[sizeIndex] = Measure(connection, projection, sizeIndex + 1, Sizes[sizeIndex]);

                var reference = results[0].Allocated;
                for (var i = 0; i < Sizes.Length; i++)
                {
                    var result = results[i];
                    var ratio = i == 0
                        ? "1.00 (ref)"
                        : reference > 0 && result.Allocated > 0
                            ? ((double)result.Allocated / reference).ToString("F2")
                            : "n/a";

                    lines.Add(
                        $"[{shape}] \"{projection}\" | {Sizes[i] / MiB} MiB | {result.StreamType} | {result.Bytes} | " +
                        $"{result.Allocated} | {result.PeakDelta} | {ratio} | {(result.Correct ? "ok" : "FAIL")}" +
                        (result.Error is null ? string.Empty : $" error={result.Error}"));
                }

                lines.Add($"[{shape}] FieldCount={results[0].FieldCount}");
            }

            // Fail-closed documentation: a view and a WITHOUT ROWID table.
            using (var command = connection.CreateCommand())
            {
                command.CommandText = "CREATE VIEW v AS SELECT id, payload FROM t;";
                command.ExecuteNonQuery();
            }

            using (var command = connection.CreateCommand())
            {
                command.CommandText =
                    "CREATE TABLE t2(id INTEGER PRIMARY KEY, payload BLOB) WITHOUT ROWID;" +
                    "INSERT INTO t2 (id, payload) VALUES (1, x'01020304');";
                command.ExecuteNonQuery();
            }

            lines.Add($"[view] \"SELECT payload, rowid FROM v\" -> {ProbeFailure(connection, "SELECT payload, rowid FROM v")}");
            lines.Add($"[without-rowid] \"SELECT payload, rowid FROM t2\" -> {ProbeFailure(connection, "SELECT payload, rowid FROM t2")}");
        }
        finally
        {
            try
            {
                File.Delete(databasePath);
            }
            catch (Exception exception)
            {
                // Do not swallow: record why the temp database could not be removed.
                lines.Add($"[cleanup] File.Delete failed: {exception.GetType().Name}: {exception.Message}");
            }
        }

        File.AppendAllLines(OutputPath, lines);
    }

    private static ProbeResult Measure(
        SqliteConnection connection, string projection, int id, int expectedSize)
    {
        var buffer = new byte[ReadBufferBytes];

        ProbeResult ReadOnce()
        {
            using var command = connection.CreateCommand();
            command.CommandText = projection;
            command.Parameters.AddWithValue("$id", id);
            using var reader = command.ExecuteReader(CommandBehavior.SequentialAccess);

            if (!reader.Read())
                throw new InvalidOperationException($"id {id} was not returned by '{projection}'");

            var fieldCount = reader.FieldCount;

            // Baseline before GetStream: it captures the (potentially whole-value) allocation the
            // buffered path performs inside GetStream.
            var baseLine = GC.GetTotalMemory(forceFullCollection: false);
            using var stream = reader.GetStream(0);
            var streamType = stream.GetType().Name;

            var peak = Math.Max(0, GC.GetTotalMemory(forceFullCollection: false) - baseLine);
            long length = 0;
            var correct = true;
            int read;
            while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
            {
                for (var i = 0; i < read; i++)
                {
                    if (buffer[i] != Pattern[(int)((length + i) & 0xFF)])
                        correct = false;
                }

                length += read;

                var delta = GC.GetTotalMemory(forceFullCollection: false) - baseLine;
                if (delta > peak)
                    peak = delta;
            }

            if (length != expectedSize)
                correct = false;

            return new ProbeResult(streamType, fieldCount, length, 0, peak, correct, null);
        }

        try
        {
            // Warm up JIT and any per-connection state before measuring.
            ReadOnce();
            ReadOnce();

            var best = long.MaxValue;
            var peak = 0L;
            ProbeResult last = default;
            for (var i = 0; i < Samples; i++)
            {
                var before = GC.GetAllocatedBytesForCurrentThread();
                last = ReadOnce();
                var allocated = GC.GetAllocatedBytesForCurrentThread() - before;
                if (allocated < best)
                    best = allocated;
                if (last.PeakDelta > peak)
                    peak = last.PeakDelta;
            }

            return last with { Allocated = best, PeakDelta = peak };
        }
        catch (Exception exception)
        {
            return new ProbeResult("<error>", -1, -1, -1, -1, false, $"{exception.GetType().Name}: {exception.Message}");
        }
    }

    private static string ProbeFailure(SqliteConnection connection, string commandText)
    {
        try
        {
            using var command = connection.CreateCommand();
            command.CommandText = commandText;
            using var reader = command.ExecuteReader(CommandBehavior.SequentialAccess);
            var fieldCount = reader.FieldCount;

            if (!reader.Read())
                return $"no rows (FieldCount={fieldCount})";

            using var stream = reader.GetStream(0);
            var streamType = stream.GetType().Name;
            var buffer = new byte[ReadBufferBytes];
            long total = 0;
            int read;
            while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
                total += read;

            return $"no exception; stream={streamType} FieldCount={fieldCount} bytes={total}";
        }
        catch (Exception exception)
        {
            return $"{exception.GetType().FullName}: {exception.Message}";
        }
    }

    private static void Seed(SqliteConnection connection)
    {
        using (var command = connection.CreateCommand())
        {
            command.CommandText =
                "DROP TABLE IF EXISTS t;" +
                "CREATE TABLE t(id INTEGER PRIMARY KEY, payload BLOB NOT NULL);";
            command.ExecuteNonQuery();
        }

        // One transient deterministic buffer per size; correctness beats avoiding the single
        // largest allocation (SQLite parameters must be contiguous). Ids are sizeIndex + 1 so the
        // probe reads each size back by an explicit id.
        for (var i = 0; i < Sizes.Length; i++)
        {
            var data = new byte[Sizes[i]];
            for (var j = 0; j < data.Length; j++)
                data[j] = Pattern[j & 0xFF];

            using var command = connection.CreateCommand();
            command.CommandText = "INSERT INTO t (id, payload) VALUES ($id, $payload);";
            command.Parameters.AddWithValue("$id", i + 1);
            command.Parameters.Add("$payload", SqliteType.Blob).Value = data;
            command.ExecuteNonQuery();
        }
    }

    private static byte[] BuildPattern()
    {
        var pattern = new byte[256];
        for (var i = 0; i < pattern.Length; i++)
            pattern[i] = (byte)((i * 131 + 7) & 0xFF);
        return pattern;
    }

    private readonly record struct ProbeResult(
        string StreamType, int FieldCount, long Bytes, long Allocated, long PeakDelta, bool Correct, string? Error);
}

