using FluentAssertions;
using NextORM.Core;
using System.Text.RegularExpressions;

namespace NextORM.Sqlite.Tests;

/// <summary>SQL generation for the C# string semantics surface on SQLite.</summary>
public class StringSemanticsSqlGenerationTests
{
    private static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd)
        => ((DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None)).DbCommand.CommandText;

    [Fact]
    public void DateFormat_ShouldUseStrftime()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        SqlOf(ctx, e.Select(x => new { F = x.Datetime!.Value.ToString("yyyy-MM-dd") }))
            .Should().Contain("strftime('%Y-%m-%d', dt)");
    }

    [Fact]
    public void FixedPoint_ShouldUsePrintf()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        SqlOf(ctx, e.Select(x => new { F = string.Format("{0:F2}", x.Id) }))
            .Should().Contain("printf('%.2f', id)");
    }

    [Fact]
    public void Collate_ShouldRenderCollate()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        SqlOf(ctx, e.Select(x => new { F = SqlFunctions.Sql.collate(x.String, "BINARY") }))
            .Should().Contain("somestring collate BINARY");
    }

    [Fact]
    public void CompareOrdinal_ShouldUseBinaryCollation()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        SqlOf(ctx, e.Where(x => string.CompareOrdinal(x.String, "a") > 0).Select(x => new { x.Id }))
            .Should().Contain("somestring collate binary < 'a'");
    }

    [Fact]
    public void GroupedNumber_ShouldThrow()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var act = () => SqlOf(ctx, e.Select(x => new { F = string.Format("{0:N2}", x.Id) }));
        act.Should().Throw<NotSupportedException>().WithMessage("*'N'*");
    }

    [Fact]
    public void ContainsOrdinalCaseSensitive_ShouldThrowBecauseLikeIsCaseInsensitive()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        var act = () => SqlOf(ctx, e.Where(x => x.String!.Contains("X", StringComparison.Ordinal)).Select(x => new { x.Id }));
        act.Should().Throw<NotSupportedException>().WithMessage("*ordinal*");
    }

    [Fact]
    public void ContainsOrdinalIgnoreCase_ShouldRenderLowerLike()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        SqlOf(ctx, e.Where(x => x.String!.Contains("X", StringComparison.OrdinalIgnoreCase)).Select(x => new { x.Id }))
            .Should().Contain("lower(somestring) collate binary like lower('%X%')");
    }

    [Fact]
    public void RegexIsMatch_ShouldUseRegexpOperator()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        SqlOf(ctx, e.Where(x => Regex.IsMatch(x.String!, "^a")).Select(x => new { x.Id }))
            .Should().Contain("somestring regexp '^a'");
    }

    [Fact]
    public void RegexIsMatchIgnoreCase_ShouldPrefixIgnoreCaseFlag()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        SqlOf(ctx, e.Where(x => Regex.IsMatch(x.String!, "^a", RegexOptions.IgnoreCase)).Select(x => new { x.Id }))
            .Should().Contain("somestring regexp '(?i)^a'");
    }

    [Fact]
    public void RegexReplace_ShouldUseRegexpReplace()
    {
        using var ctx = SqliteTestContext.Create();
        var e = ctx.From<IComplexEntity>();

        SqlOf(ctx, e.Select(x => new { F = Regex.Replace(x.String!, "[0-9]+", "#") }))
            .Should().Contain("regexp_replace(somestring, '[0-9]+', '#')");
    }
}

using FluentAssertions;
using NextORM.Core;
using NextORM.Sqlite;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// SQLite emulates a table-valued parameter with a JSON text parameter: scalars are read through
/// <c>json_each(@p)</c>, entities through <c>json_extract(value, '$.col')</c>.
/// </summary>
[Trait("D162", "Conformance")]
public class TableValuedParameterTests
{
    private sealed class TvpRow
    {
        public int Id { get; set; }
        public string? Name { get; set; }
    }

    private static SqliteDataContext CreateContext() => new("Data Source=:memory:", new DataContextBuilder());

    [Fact]
    public void SupportsTableValuedParameters_IsTrue()
    {
        SqliteDialect.Instance.SupportsTableValuedParameters.Should().BeTrue();
    }

    [Fact]
    public void ScalarList_ShouldBeReadThroughJsonEach()
    {
        using var ctx = CreateContext();

        using (var result = ctx.ExecuteRaw(
            "select count(*) as c from json_each(@ids)",
            [ProcedureParameter.Table("ids", new[] { 1, 2, 3 })]))
        {
            result.Read<long>().Should().Equal(3L);
        }

        using (var result = ctx.ExecuteRaw(
            "select sum(value) as s from json_each(@ids)",
            [ProcedureParameter.Table("ids", new[] { 1, 2, 3 })]))
        {
            result.Read<long>().Should().Equal(6L);
        }
    }

    [Fact]
    public void EmptyScalarList_ShouldReadZeroRows()
    {
        using var ctx = CreateContext();

        using var result = ctx.ExecuteRaw(
            "select count(*) as c from json_each(@ids)",
            [ProcedureParameter.Table("ids", Array.Empty<int>())]);

        result.Read<long>().Should().Equal(0L);
    }

    [Fact]
    public void EntityList_ShouldBeReadThroughJsonExtract()
    {
        using var ctx = CreateContext();

        var rows = new[]
        {
            new TvpRow { Id = 1, Name = "alpha" },
            new TvpRow { Id = 2, Name = "beta" },
        };

        using var result = ctx.ExecuteRaw(
            "select json_extract(value, '$.Id') as Id, json_extract(value, '$.Name') as Name from json_each(@rows) order by Id",
            [ProcedureParameter.Table("rows", rows)]);

        var read = result.Read<TvpRow>();

        read.Should().HaveCount(2);
        read[0].Id.Should().Be(1);
        read[0].Name.Should().Be("alpha");
        read[1].Id.Should().Be(2);
        read[1].Name.Should().Be("beta");
    }

    [Fact]
    public void NullableScalarList_WithNullElements_ShouldKeepNulls()
    {
        using var ctx = CreateContext();
        var rows = new int?[] { 1, null, 3 };

        using (var result = ctx.ExecuteRaw("select count(*) as c from json_each(@ids)", [ProcedureParameter.Table("ids", rows)]))
            result.Read<long>().Should().Equal(3L);

        using (var result = ctx.ExecuteRaw("select count(value) as c from json_each(@ids)", [ProcedureParameter.Table("ids", rows)]))
            result.Read<long>().Should().Equal(2L);

        using (var result = ctx.ExecuteRaw("select sum(value) as s from json_each(@ids)", [ProcedureParameter.Table("ids", rows)]))
            result.Read<long>().Should().Equal(4L);
    }

    [Fact]
    public void UnicodeScalarList_ShouldRoundTrip()
    {
        using var ctx = CreateContext();

        using var result = ctx.ExecuteRaw(
            "select value from json_each(@ids) order by value",
            [ProcedureParameter.Table("ids", new[] { "юникод", "a\"b" })]);

        result.Read<string>().Should().Equal("a\"b", "юникод");
    }

    [Fact]
    public void TypeName_OnSqlite_ShouldThrowArgumentException()
    {
        using var ctx = CreateContext();

        var act = () => ctx.ExecuteRaw("select 1", [ProcedureParameter.Table("p", "dbo.MyType", new[] { 1 })]);

        act.Should().Throw<ArgumentException>();
    }
}

using FluentAssertions;
using NextORM.Core;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// SQL generation of the lazy temporary-table source (<c>AsTempTable</c> / <c>From(TempTableSource)</c>)
/// on SQLite (no database connection). Every read materialises the table with a drop-and-recreate in
/// the same batch as the read, so the generated SQL is a single <c>;</c>-joined command.
/// </summary>
public class TempTableSourceSqlGenerationTests
{
    [Fact]
    public void AsTempTable_ShouldNotExecuteAndGenerateAStableName()
    {
        using var ctx = SqliteTestContext.Create();
        var min = 5;

        var source = ctx.From<ISimpleEntity>()
            .Where(x => x.Id > min)
            .Select(x => new { x.Id })
            .AsTempTable();

        source.Name.Should().StartWith("__nextorm_temp_");
        source.Options.Should().NotBeNull();

        var second = ctx.From<ISimpleEntity>().Select(x => new { x.Id }).AsTempTable();
        second.Name.Should().NotBe(source.Name);
    }

    [Fact]
    public void AsTempTable_WithBuilderOptions_ShouldCarryThem()
    {
        using var ctx = SqliteTestContext.Create();

        var source = ctx.From<ISimpleEntity>()
            .Select(x => new { x.Id })
            .AsTempTable(o => o.IfNotExists());

        source.Options.IfNotExists.Should().BeTrue();
    }

    [Fact]
    public void Read_ShouldRenderDropCreateAndSelectAsOneBatch()
    {
        using var ctx = SqliteTestContext.Create();
        var min = 5;
        var readMin = 1;

        var source = ctx.From<ISimpleEntity>()
            .Where(x => x.Id > min)
            .Select(x => new { x.Id })
            .AsTempTable();

        var sql = ctx.From(source)
            .Where(t => t.GetInt32("id") > readMin)
            .Select(t => new { Id = t.GetInt32("id") })
            .ToBatchSql();

        sql.Should().Contain("drop table if exists " + source.Name);
        sql.Should().Contain("create temporary table " + source.Name + " as select id from simple_entity");
        sql.Should().Contain("$b1_min");
        sql.Should().Contain("select id from " + source.Name);
        sql.Should().Contain("$b2_readMin");
    }

    [Fact]
    public void Read_WithQuotedIdentifiers_ShouldQuoteTheTempTableName()
    {
        using var ctx = SqliteTestContext.CreateQuoted();

        var source = ctx.From<ISimpleEntity>().Select(x => new { x.Id }).AsTempTable();

        var sql = ctx.From(source).Select(t => new { Id = t.GetInt32("id") }).ToBatchSql();

        sql.Should().Contain("drop table if exists \"" + source.Name + "\"");
        sql.Should().Contain("create temporary table \"" + source.Name + "\" as select \"id\" from \"simple_entity\"");
    }

    [Fact]
    public void Read_InsideACte_ShouldMaterialiseTheTempTableFirst()
    {
        using var ctx = SqliteTestContext.Create();

        var source = ctx.From<ISimpleEntity>().Select(x => new { x.Id }).AsTempTable();

        var sql = ctx.With("ids", ctx.From(source).Select(t => new { Id = t.GetInt32("id") }))
            .From("ids")
            .Select(t => new { Id = t.GetInt32("id") })
            .ToBatchSql();

        sql.Should().Contain("create temporary table " + source.Name + " as select id from simple_entity");
        sql.Should().Contain("with ids as (select id from " + source.Name + ")");
    }

    [Fact]
    public void NestedTempTables_ShouldBeCreatedInDependencyOrder()
    {
        using var ctx = SqliteTestContext.Create();

        var first = ctx.From<ISimpleEntity>().Select(x => new { x.Id }).AsTempTable();
        var second = ctx.From(first).Select(t => new { Id = t.GetInt32("id") }).AsTempTable();

        var sql = ctx.From(second).Select(t => new { Id = t.GetInt32("id") }).ToBatchSql();

        var firstIndex = sql.IndexOf("create temporary table " + first.Name, StringComparison.Ordinal);
        var secondIndex = sql.IndexOf("create temporary table " + second.Name, StringComparison.Ordinal);

        firstIndex.Should().BeGreaterThanOrEqualTo(0);
        secondIndex.Should().BeGreaterThan(firstIndex);
    }

    [Fact]
    public void Read_WithExtremeRow_ShouldRenderPortableWindowLowering()
    {
        // SQLite has no native extreme-row renderer, so this pins the pre-existing portable policy that a
        // temp-table source relies on: the read materialises the table and then applies the window-rank
        // lowering, never a native LIMIT/DISTINCT ON.
        using var ctx = SqliteTestContext.Create();
        var source = ctx.From<ISimpleEntity>().Select(x => new { x.Id }).AsTempTable();

        var sql = ctx.From(source)
            .SelectWhereMax(t => t.GetInt32("id"), t => new { Id = t.GetInt32("id") })
            .ToBatchSql();

        sql.Should().Contain("create temporary table " + source.Name + " as select id from simple_entity");
        sql.Should().Contain("row_number() over (order by id desc)");
        sql.Should().NotContain("limit 1");
        sql.Should().NotContain("distinct on");
    }

    [Fact]
    public void ToBatchSql_OnAPlainQuery_ShouldThrow()
    {
        using var ctx = SqliteTestContext.Create();

        var act = () => ctx.From<ISimpleEntity>().Select(x => new { x.Id }).ToBatchSql();

        act.Should().Throw<InvalidOperationException>();
    }
}

using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using System.Data;
using System.Data.Common;
using FluentAssertions;
using Microsoft.Data.Sqlite;
using NextORM.Core;
using NextORM.Sqlite;

namespace NextORM.Sqlite.Tests;

/// <summary>
/// Terminal-level coverage for <c>ToDataReader</c>/<c>ToDataReaderAsync</c> on SQLite (issue #134): the
/// locator-free result path emits the projection unchanged, the per-call command never mutates the
/// shared command's cache state, and the lazy temp-table guard names the reader terminal while CSV
/// keeps its own wording.
/// </summary>
public class ToDataReaderSqliteTests
{
    [SqlTable("reader_probe")]
    private sealed class ReaderProbeEntity
    {
        [Key]
        [Column("id")]
        public int Id { get; set; }

        [Column("name")]
        public string? Name { get; set; }

        [Column("data")]
        public byte[]? Data { get; set; }
    }

    private static string Normalize(string sql) => sql.Replace("\r\n", "\n");

    /// <summary>Prepares through the same buffered route the reader terminal uses (no connection opened).</summary>
    private static string BufferedSql<T>(IDataContext ctx, QueryCommand<T> command)
        => Normalize(((DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(command, false, false, CancellationToken.None)).DbCommand.CommandText);

    private sealed class SqlRecordingInterceptor : IQueryInterceptor
    {
        public List<string> Statements { get; } = [];

        /// <summary>The most recently executed command, captured for ownership/disposal assertions.</summary>
        public DbCommand? LastCommand { get; private set; }

        public void CommandExecuting(CommandEventData eventData, DbCommand command)
        {
            Statements.Add(eventData.Sql ?? string.Empty);
            LastCommand = command;
        }
    }

    /// <summary>
    /// Test-only connection hook: the provider mints every command through <see cref="CreateCommand"/>,
    /// so returning a <see cref="TrackingSqliteCommand"/> makes per-call disposal directly observable
    /// (the stock <c>SqliteCommand.Dispose</c> keeps <c>Connection</c> set, so it cannot be probed).
    /// </summary>
    private sealed class TrackingSqliteConnection(string connectionString) : SqliteConnection(connectionString)
    {
        public List<TrackingSqliteCommand> CreatedCommands { get; } = [];

        /// <summary>When set, every command minted by this connection fails on both execution paths.</summary>
        public bool FailExecute { get; set; }

        /// <summary>When set, opening the connection fails instead of opening it.</summary>
        public bool FailOpen { get; set; }

        public override SqliteCommand CreateCommand()
        {
            var command = new TrackingSqliteCommand
            {
                Connection = this,
                CommandTimeout = DefaultTimeout,
                Transaction = Transaction,
                FailExecute = FailExecute,
            };
            CreatedCommands.Add(command);
            return command;
        }

        public override void Open()
        {
            if (FailOpen)
                throw new InvalidOperationException("Simulated connection-open failure.");

            base.Open();
        }

        public override Task OpenAsync(CancellationToken cancellationToken)
            => FailOpen
                ? Task.FromException(new InvalidOperationException("Simulated connection-open failure."))
                : base.OpenAsync(cancellationToken);
    }

    private sealed class TrackingSqliteCommand : SqliteCommand
    {
        public bool WasDisposed { get; private set; }

        /// <summary>When set, the command throws on the sync and the async execution path.</summary>
        public bool FailExecute { get; set; }

        /// <summary>Whether the provider reader is still attached (set by <c>ExecuteReader</c>).</summary>
        public bool HasOpenReader => DataReader is not null;

        protected override void Dispose(bool disposing)
        {
            WasDisposed = true;
            base.Dispose(disposing);
        }

        protected override DbDataReader ExecuteDbDataReader(CommandBehavior behavior)
        {
            if (FailExecute)
                throw new InvalidOperationException("Simulated command-execution failure.");

            return base.ExecuteDbDataReader(behavior);
        }

        protected override Task<DbDataReader> ExecuteDbDataReaderAsync(CommandBehavior behavior, CancellationToken cancellationToken)
            => FailExecute
                ? Task.FromException<DbDataReader>(new InvalidOperationException("Simulated command-execution failure."))
                : base.ExecuteDbDataReaderAsync(behavior, cancellationToken);
    }

    private static SqliteDataContext CreateDb(out string path, SqlRecordingInterceptor? interceptor = null)
    {
        path = Path.Combine(Path.GetTempPath(), $"nextorm-todatareader-{Guid.NewGuid():N}.db");
        using (var connection = new SqliteConnection($"Data Source={path}"))
        {
            connection.Open();
            using var command = connection.CreateCommand();
            command.CommandText =
                "create table reader_probe (id integer primary key, name text, data blob);" +
                "insert into reader_probe (id, name, data) values (1, 'alpha', x'0102'), (2, null, null);";
            command.ExecuteNonQuery();
        }

        var builder = new DataContextBuilder();
        if (interceptor is not null)
            builder = builder.AddInterceptor(interceptor);

        return new SqliteDataContext($"Data Source={path}", builder);
    }

