    private static string WriteSingleString(string? value, CsvStreamOptions options)
    {
        var column = new SelectExpression(typeof(string)) { Index = 0, PropertyName = "V" };
        var plan = CsvStreamWriter.Build([column], Mapper);
        var reader = new ProbeReader(allowGetValue: false, value);

        using var buffer = PolicyBuffer(options);
        CsvStreamWriter.WriteRow(plan, reader, buffer);
        return Encoding.UTF8.GetString(buffer.Written);
    }

    private static string WriteSingleValue<T>(T value, CsvStreamOptions options)
    {
        // Drives the provider-typed formatter (numeric/byte[]) under the call's policy so the Excel
        // guard and marker-collision rules are asserted for non-string columns too.
        var column = new SelectExpression(typeof(T)) { Index = 0, PropertyName = "V" };
        var plan = CsvStreamWriter.Build([column], Mapper);
        var reader = new ProbeReader(allowGetValue: false, value);

        using var buffer = PolicyBuffer(options);
        CsvStreamWriter.WriteRow(plan, reader, buffer);
        return Encoding.UTF8.GetString(buffer.Written);
    }

    private static CsvRowBuffer PolicyBuffer(CsvStreamOptions options)
        => new(new CsvDialect(options.Delimiter), new CsvFieldPolicy(options.NullMarker, options.ExcelMode, options.ValueTransform));

    private static void WriteHeaderTo(SelectExpression column, Stream destination)
    {
        var plan = CsvStreamWriter.Build([column], Mapper);
        using var buffer = new CsvRowBuffer(new CsvDialect(','));
        CsvStreamWriter.WriteHeader(plan, buffer);
        destination.Write(buffer.Written);
    }

    private sealed class NestedProjection
    {
        public int Id { get; set; }
    }

    /// <summary>An <see cref="IUtf8SpanFormattable"/> that never fits, so the scratch-buffer guard fires.</summary>
    private struct OversizedFormattable : IUtf8SpanFormattable
    {
        public bool TryFormat(Span<byte> utf8Destination, out int bytesWritten, ReadOnlySpan<char> format, IFormatProvider? provider)
        {
            bytesWritten = 0;
            return false;
        }
    }

    /// <summary>An <see cref="IPropertyValueConverter"/> implemented directly, so the mapper can only
    /// invoke it through the object-based <c>ConvertFromProvider(object)</c> bridge.</summary>
    private sealed class ObjectBridgeConverter : IPropertyValueConverter
    {
        public Type ProviderType => typeof(int);

        public bool ConvertsNulls => false;

        public object? ConvertToProvider(object? model) => model;

        public object? ConvertFromProvider(object? provider) => (int)(provider ?? 0);
    }

    /// <summary>
    /// A <see cref="DbDataReader"/> whose typed getters record their ordinal and whose
    /// <c>GetValue(int)</c> throws unless explicitly allowed; any object-based fallback on the CSV
    /// write path therefore fails loudly. It is also a <see cref="DbDataReader"/> because the default
    /// column mapper reads <c>uint</c>/<c>ulong</c>/<c>TimeSpan</c>/<c>DateTimeOffset</c> through
    /// <c>GetFieldValue&lt;T&gt;</c>.
    /// </summary>
    private sealed class ProbeReader(bool allowGetValue, params object?[] values) : DbDataReader
    {
        private readonly object?[] _values = values;

        public List<string> Calls { get; } = [];

        /// <summary>Ordinals whose <c>GetFieldType</c> was read, so a test can prove the row loop never reads the schema.</summary>
        public List<int> SchemaCalls { get; } = [];

        /// <summary>Overrides the storage type <c>GetFieldType</c> reports (needed when the probe value is null).</summary>
        public Type[]? FieldTypes { get; init; }

        public override int FieldCount => _values.Length;

        public override int Depth => 0;

        public override bool HasRows => true;

        public override bool IsClosed => false;

        public override int RecordsAffected => 0;

        public override object this[int ordinal] => GetValue(ordinal);

        public override object this[string name] => GetValue(GetOrdinal(name));

        public override bool IsDBNull(int ordinal) => _values[ordinal] is null or DBNull;

        public override object GetValue(int ordinal)
        {
            if (!allowGetValue)
                throw new InvalidOperationException($"GetValue({ordinal}) must not be called on the CSV write path.");

            return _values[ordinal] ?? DBNull.Value;
        }

        public override T GetFieldValue<T>(int ordinal)
        {
            Calls.Add($"GetFieldValue<{typeof(T).Name}>({ordinal})");
            return (T)_values[ordinal]!;
        }

        public override string GetName(int ordinal) => $"c{ordinal}";

        public override int GetOrdinal(string name) => 0;

        public override string GetDataTypeName(int ordinal) => "probe";

        public override Type GetFieldType(int ordinal)
        {
            SchemaCalls.Add(ordinal);
            return FieldTypes is { } types ? types[ordinal] : _values[ordinal]?.GetType() ?? typeof(object);
        }

        public override int GetValues(object[] values)
        {
            var count = Math.Min(values.Length, _values.Length);
            for (var i = 0; i < count; i++)
                values[i] = _values[i] ?? DBNull.Value;

            return count;
        }

        public override IEnumerator GetEnumerator() => _values.GetEnumerator();

        public override bool NextResult() => false;

        public override bool Read() => false;

        public override bool GetBoolean(int ordinal) => Record<bool>(nameof(GetBoolean), ordinal, _values);

        public override byte GetByte(int ordinal) => Record<byte>(nameof(GetByte), ordinal, _values);

        public override long GetBytes(int ordinal, long dataOffset, byte[]? buffer, int bufferOffset, int length) => throw new NotSupportedException();

        public override char GetChar(int ordinal) => throw new NotSupportedException();

        public override long GetChars(int ordinal, long dataOffset, char[]? buffer, int bufferOffset, int length) => throw new NotSupportedException();

        public override DateTime GetDateTime(int ordinal) => Record<DateTime>(nameof(GetDateTime), ordinal, _values);

        public override decimal GetDecimal(int ordinal) => Record<decimal>(nameof(GetDecimal), ordinal, _values);

        public override double GetDouble(int ordinal) => Record<double>(nameof(GetDouble), ordinal, _values);

        public override float GetFloat(int ordinal) => Record<float>(nameof(GetFloat), ordinal, _values);

        public override Guid GetGuid(int ordinal) => Record<Guid>(nameof(GetGuid), ordinal, _values);

        public override short GetInt16(int ordinal) => Record<short>(nameof(GetInt16), ordinal, _values);

        public override int GetInt32(int ordinal) => Record<int>(nameof(GetInt32), ordinal, _values);

        public override long GetInt64(int ordinal) => Record<long>(nameof(GetInt64), ordinal, _values);

        public override string GetString(int ordinal) => Record<string>(nameof(GetString), ordinal, _values);

        private T Record<T>(string getter, int ordinal, object?[] values)
        {
            Calls.Add($"{getter}({ordinal})");
            return (T)values[ordinal]!;
        }
    }
}

using FluentAssertions;

namespace NextORM.Core.Tests;

public class CteQueryTests
{
    [Fact]
    public void WithRecursive_ShouldAppendRecursiveDefinitionAndKeepDeclarations()
    {
        using var ctx = new InMemoryDataContext();
        var e = ctx.From<SimpleEntity>();
        var query = e.Where(x => x.Id > 0).Select(x => new { x.Id });

        var cte = ctx.With("recent", query);
        cte.Ctes.Should().ContainSingle().Which.Name.Should().Be("recent");
        cte.Ctes[0].Recursive.Should().BeFalse();

        var recursive = cte.WithRecursive("nums", query, 50);
        recursive.Ctes.Should().HaveCount(2);
        recursive.Ctes[1].Name.Should().Be("nums");
        recursive.Ctes[1].Recursive.Should().BeTrue();
        recursive.Ctes[1].MaxRecursion.Should().Be(50);
    }

    [Fact]
    public void Join_WithSameCteNameDeclaredOnBothSides_ShouldThrow()
    {
        using var ctx = new InMemoryDataContext();
        var e = ctx.From<SimpleEntity>();
        var left = ctx.With("c", e.Where(x => x.Id > 0).Select(x => new { x.Id }));
        var right = ctx.With("c", e.Where(x => x.Id > 1).Select(x => new { x.Id }));

        var act = () => left.From("c").Join(right.From("c"), (a, b) => a.GetInt64("id") == b.GetInt64("id"));

        act.Should().Throw<InvalidOperationException>().WithMessage("*'c'*both sides of the join*");
    }

    [Fact]
    public void Hoist_AlreadyFlat_ShouldReturnSameListInstance()
    {
        using var ctx = new InMemoryDataContext();
        var query = ctx.From<SimpleEntity>().Select(x => new { x.Id });
        var list = new[] { new CteDefinition("a", query) };

        CteHoister.Hoist(list).Should().BeSameAs(list);
    }

    [Fact]
    public void Hoist_RepeatedReference_ShouldKeepDeclarationOnce()
    {
        using var ctx = new InMemoryDataContext();
        var query = ctx.From<SimpleEntity>().Select(x => new { x.Id });
        var definition = new CteDefinition("a", query);
        var list = new[] { definition, definition };

        var hoisted = CteHoister.Hoist(list);

        hoisted.Should().ContainSingle().Which.Should().BeSameAs(definition);
    }

    [Fact]
    public void Hoist_DifferentDefinitionsUnderSameName_ShouldThrow()
    {
        using var ctx = new InMemoryDataContext();
        var e = ctx.From<SimpleEntity>();
        var list = new[]
        {
            new CteDefinition("a", e.Where(x => x.Id > 0).Select(x => new { x.Id })),
            new CteDefinition("a", e.Where(x => x.Id > 1).Select(x => new { x.Id })),
        };

        var act = () => CteHoister.Hoist(list);

        act.Should().Throw<InvalidOperationException>().WithMessage("*'a'*");
    }

    [Fact]
    public void Hoist_NestedDefinition_ShouldListDependencyBeforeConsumer()
    {
        using var ctx = new InMemoryDataContext();
        var e = ctx.From<SimpleEntity>();

        var inner = ctx.With("i", e.Where(x => x.Id > 0).Select(x => new { x.Id }))
            .From("i")
            .Select(t => new { id = t["id"].AsInt });

        var hoisted = CteHoister.Hoist(new[] { new CteDefinition("o", inner) });

        hoisted!.Select(c => c.Name).Should().Equal("i", "o");
    }

    [Fact]
    public void Hoist_SingleDeclarationWithNestedBody_ShouldFlattenInsteadOfTakingFastPath()
    {
        using var ctx = new InMemoryDataContext();
        var e = ctx.From<SimpleEntity>();

        // Issue #200 L1: a lone declaration whose body carries a nested declaration must not take the
        // single-item fast path, or the nested CTE would survive inside its consumer's WITH.
        var inner = ctx.With("i", e.Where(x => x.Id > 0).Select(x => new { x.Id }))
            .From("i")
            .Select(t => new { id = t["id"].AsInt });
        var list = new[] { new CteDefinition("o", inner) };

        var hoisted = CteHoister.Hoist(list);

        ReferenceEquals(hoisted, list).Should().BeFalse();
        hoisted!.Select(c => c.Name).Should().Equal("i", "o");
    }

    [Fact]
    public void Hoist_SiblingReferencedBeforeItsDeclaration_ShouldListDependencyFirst()
    {
        using var ctx = new InMemoryDataContext();

        // The fluent API builds a body before the CTE it reads is declared, so "b" can reference "a"
        // while "a" is appended to the declaration list only afterwards.
        var a = ctx.From<SimpleEntity>().Where(x => x.Id > 0).Select(x => new { x.Id });
        var b = ctx.From("a").Select(t => new { id = t["id"].AsInt });

        var hoisted = CteHoister.Hoist(
        [
            new CteDefinition("b", b),
            new CteDefinition("a", a),
        ]);

        hoisted!.Select(c => c.Name).Should().Equal("a", "b");
    }

    [Fact]
    public void Hoist_DeclarationCycle_ShouldThrow()
    {
        using var ctx = new InMemoryDataContext();
        var qa = ctx.From<SimpleEntity>().Select(x => new { x.Id });
        var qb = ctx.From<SimpleEntity>().Select(x => new { x.Id });
        var a = new CteDefinition("a", qa);
        var b = new CteDefinition("b", qb);

        // `a`'s body declares `b`, whose body declares `a` again: the declaration tree never terminates,
        // so the hoist must fail instead of recursing forever.
        qa.Ctes = [b];
        qb.Ctes = [a];

        var act = () => CteHoister.Hoist([a]);

        act.Should().Throw<InvalidOperationException>().WithMessage("*cycle*");
    }

    [Fact]
    public void Hoist_NullOrEmpty_ShouldReturnInput()
    {
        // No declarations is not an error: a null list stays null and an empty list stays empty.
        CteHoister.Hoist(null).Should().BeNull();
        CteHoister.Hoist(System.Array.Empty<CteDefinition>()).Should().BeEmpty();
    }

    [Fact]
    public void EnsureNoUnhoistedCtes_NestedDeclarationOutsideHoistedSet_ShouldThrow()
    {
        using var ctx = new InMemoryDataContext();

        // `inner` carries its own declaration `i`; used as a derived-table source it is a nested
        // declaration the top-level WITH cannot reach, so the guard rejects it before rendering.
        var inner = ctx.With("i", ctx.From<SimpleEntity>().Select(x => new { x.Id }))
            .From("i")
            .Select(t => new { id = t["id"].AsInt });
        var root = ctx.From(inner).Select(t => new { t.id });

        var act = () => CteHoister.EnsureNoUnhoistedCtes(root, System.Array.Empty<CteDefinition>());

        act.Should().Throw<InvalidOperationException>().WithMessage("*cannot be hoisted*");
    }
}

using FluentAssertions;

namespace NextORM.Core.Tests;

/// <summary>Plain in-memory row for the D193 tuple membership semantics.</summary>
public class TupleInMemoryEntity
{
    public int Id { get; set; }
    public string? Name { get; set; }
    public int? Score { get; set; }
}

/// <summary>
/// D193.3 — core semantics of the tuple value-list <c>IN</c>/<c>Contains</c> path (#193). In-memory
/// execution proves the C# <c>Contains</c> result (match, mismatch, empty, nullable component,
/// negation); direct <see cref="InValues.PartitionTuple(object?, Type)"/> tests pin the fail-closed
/// shape rules (null collection, arity ≥ 8, nested tuple, malformed arity, null tuple entry) that the
/// SQL translators must reject before rendering.
/// </summary>
public class D193TupleInTests
{
    private readonly InMemoryRepository _sut;

    public D193TupleInTests(InMemoryRepository sut) => _sut = sut;

    private EntityBuilder<TupleInMemoryEntity> Source(params TupleInMemoryEntity[] rows)
    {
        var entity = _sut.DataProvider.From<TupleInMemoryEntity>();
        entity.WithData(rows);
        return entity;
    }

    private static TupleInMemoryEntity[] Seed() =>
    [
        new() { Id = 1, Name = "a", Score = 10 },
        new() { Id = 2, Name = "b", Score = 20 },
        new() { Id = 3, Name = "c", Score = 30 },
        new() { Id = 4, Name = null, Score = null },
    ];

    [Fact]
    public void Contains_ValueTupleList_ShouldMatchBothRows()
    {
        var source = Source(Seed());
        var tuples = new List<(int Id, string? Name)> { (1, "a"), (3, "c") };

        var ids = source.Where(x => tuples.Contains(new ValueTuple<int, string?>(x.Id, x.Name))).Select(x => x.Id).ToList();

        ids.Should().BeEquivalentTo([1, 3]);
    }

    [Fact]
    public void Contains_ValueTupleList_MismatchedComponent_ShouldReturnNoRows()
    {
        var source = Source(Seed());
        var tuples = new List<(int, string?)> { (1, "b"), (2, "zzz") };

        var ids = source.Where(x => tuples.Contains(new ValueTuple<int, string?>(x.Id, x.Name))).Select(x => x.Id).ToList();

        ids.Should().BeEmpty();
