    [Fact]
    public void Write_StoreKeyCollidingWithMappedColumn_ShouldThrow()
    {
        using var ctx = new TestContext();
        const string colliding = "Name";

        var insert = () => ctx.CreateInsertBuilder<DynamicRowEntity>()
            .Values(new DynamicRowEntity { Id = 1, Extra = new() { [colliding] = "x" } })
            .ToSql();
        var update = () => ctx.CreateUpdateBuilder<DynamicRowEntity>()
            .Set(new DynamicRowEntity { Id = 1, Extra = new() { [colliding] = "x" } });
        var merge = () => ctx.CreateMergeBuilder<DynamicRowEntity>()
            .Using(new DynamicRowEntity { Id = 1, Extra = new() { [colliding] = "x" } });

        // A key that names a mapped physical column would silently shadow it; it is rejected and the
        // message names the offending key.
        insert.Should().Throw<InvalidOperationException>().WithMessage($"*{colliding}*");
        update.Should().Throw<InvalidOperationException>().WithMessage($"*{colliding}*");
        merge.Should().Throw<InvalidOperationException>().WithMessage($"*{colliding}*");
    }

    [Fact]
    public void Write_KeyEqualToRangeClrName_ShouldNotCollide()
    {
        using var ctx = new TestContext();
        var entity = new RangeDynamicRowEntity
        {
            Id = 1,
            During = new Range<int>(1, 10),
            // "During" is the range property's CLR name, not either physical bound column
            // (during_lower/during_upper). The read side strips only the physical names, so on write this
            // is an ordinary dynamic key, written as a column, never rejected as a collision.
            Extra = new() { ["During"] = 5 },
        };

        var sql = ctx.CreateInsertBuilder<RangeDynamicRowEntity>().Values(entity).ToSql();

        sql.Should().Contain("(Id, during_lower, during_upper, \"During\")");
        sql.Should().Contain("\"During\"");
    }

    [Fact]
    public void Write_KeyEqualToPhysicalColumnName_ShouldThrow()
    {
        using var ctx = new TestContext();

        // The mapped property's CLR name (Renamed) differs from its physical column (physical_name). A
        // dynamic key naming the physical column would silently shadow the mapped one, so it is rejected
        // and the message names the offending key.
        var insert = () => ctx.CreateInsertBuilder<RenamedDynamicRowEntity>()
            .Values(new RenamedDynamicRowEntity { Id = 1, Renamed = "x", Extra = new() { ["physical_name"] = "y" } })
            .ToSql();

        insert.Should().Throw<InvalidOperationException>().WithMessage("*physical_name*");
    }

    [Fact]
    public void Write_KeyWithEmbeddedIdentifierChar_ShouldEscapeThroughDialect()
    {
        using var ctx = new TestContext();
        var quoted = new DynamicRowEntity { Id = 1, Extra = new() { ["a\"b"] = 1 } };

        var sql = ctx.CreateInsertBuilder<DynamicRowEntity>().Values(quoted).ToSql();

        // The embedded quote is doubled by QuoteIdentifier; the raw "a"b" never reaches the SQL text.
        sql.Should().Contain("\"a\"\"b\"");
        sql.Should().NotContain("\"a\"b\"");

        // Same contract on a bracket-quoting (SQL Server style) dialect: "]" becomes "]]", wrapped in [].
        using var bracketCtx = new BracketContext();
        var bracketed = new DynamicRowEntity { Id = 1, Extra = new() { ["c]d"] = 2 } };

        var bracketSql = bracketCtx.CreateInsertBuilder<DynamicRowEntity>().Values(bracketed).ToSql();

        bracketSql.Should().Contain("[c]]d]");
        bracketSql.Should().NotContain("[c]d]");
    }

    [Fact]
    public void Merge_StoreOnlyEntity_ShouldNotThrowNoSource()
    {
        using var ctx = new TestContext();
        var entity = new StoreOnlyRowEntity { Id = 1, Extra = new() { ["alpha"] = 1 } };

        // The store is the only writable non-key column: the key upsert must not reject the merge for
        // having no mapped column to update, and the dynamic key must reach the SET list.
        var sql = ctx.CreateMergeBuilder<StoreOnlyRowEntity>()
            .Using(entity)
            .OnKeys()
            .WhenMatchedUpdate()
            .WhenNotMatchedInsert()
            .ToSql();

        sql.Should().Contain("(Id, \"alpha\")");
        sql.Should().Contain("\"alpha\" = excluded.\"alpha\"");

        // The full-MERGE branch form hits the same "no mapped selection" guard in AddBranch: the
        // selector-less update branch has no mapped column left (the key is skipped), so the dynamic
        // store must supply it. The dynamic key extends the derived source, the INSERT and the SET,
        // and never the ON match.
        var fullMerge = ctx.CreateMergeBuilder<StoreOnlyRowEntity>()
            .Using(entity)
            .OnKeys()
            .WhenMatched().ThenUpdate()
            .WhenNotMatched().ThenInsert()
            .ToSql();

        fullMerge.Should().Contain("as source (Id, \"alpha\")");
        fullMerge.Should().Contain("then update set target.\"alpha\" = source.\"alpha\"");
        fullMerge.Should().Contain("then insert (Id, \"alpha\") values (source.Id, source.\"alpha\")");

        var onStart = fullMerge.IndexOf(" on ", StringComparison.Ordinal) + 4;
        var whenStart = fullMerge.IndexOf(" when ", StringComparison.Ordinal);
        var on = fullMerge[onStart..whenStart];
        on.Should().Be("target.Id = source.Id");
        on.Should().NotContain("\"alpha\"");
    }

    [Fact]
    public void Merge_StoreOnlyEntity_DatabaseGeneratedKey_ShouldRejectIdentityMatchKey()
    {
        using var ctx = new TestContext();
        var entity = new IdentityStoreOnlyRowEntity { Id = 1, Extra = new() { ["alpha"] = 1 } };

        // A database-generated key cannot be a merge match key: identity columns are excluded from the
        // USING source, so OnKeys rejects it explicitly instead of rendering an ON that references a
        // source column which does not exist. This is a match-key constraint, not the source/selection
        // guard a store-only entity relaxes.
        var act = () => ctx.CreateMergeBuilder<IdentityStoreOnlyRowEntity>()
            .Using(entity)
            .OnKeys();

        act.Should().Throw<NotSupportedException>().WithMessage("*database-generated*");
    }

    [Fact]
    public void Merge_StoreOnlyEntity_OnIdentityKey_ShouldBeRejected()
    {
        using var ctx = new TestContext();
        var entity = new IdentityStoreOnlyRowEntity { Id = 1, Extra = new() { ["alpha"] = 1 } };

        // The On(...) path reaches the same rejection as OnKeys: the identity key is absent from the
        // VALUES-derived source, so matching on it is not expressible. The check now lives in
        // BuildCommand (not in On(...)), because a query source projects the identity column and is valid.
        var onKeys = () => ctx.CreateMergeBuilder<IdentityStoreOnlyRowEntity>().Using(entity).OnKeys();
        onKeys.Should().Throw<NotSupportedException>();

        var on = () => ctx.CreateMergeBuilder<IdentityStoreOnlyRowEntity>()
            .Using(entity)
            .On((t, s) => t.Id == s.Id)
            .WhenMatched().ThenUpdate()
            .WhenNotMatched().ThenInsert()
            .ToSql();

        // The message pins the VALUES-source guard, so the test cannot pass on an unrelated
        // NotSupportedException (for example the dialect's missing conditional-branch capability).
        on.Should().Throw<NotSupportedException>().WithMessage("*is not a column of the VALUES-derived merge source*");
    }

    [Fact]
    public void Merge_StoreOnlyIdentity_OnSourceKey_ShouldThrow()
    {
        using var ctx = new TestContext();

        // The guard belongs to BuildCommand, not On(...), so it catches the store-only identity key
        // whatever the On/Using call order: the source is VALUES-derived either way and never declares
        // the generated Id column.
        var usingFirst = () => ctx.CreateMergeBuilder<IdentityStoreOnlyRowEntity>()
            .Using(new IdentityStoreOnlyRowEntity { Id = 1, Extra = new() { ["alpha"] = 1 } })
            .On((t, s) => t.Id == s.Id)
            .WhenMatched().ThenUpdate()
            .WhenNotMatched().ThenInsert()
            .ToSql();

        usingFirst.Should().Throw<NotSupportedException>().WithMessage("*is not a column of the VALUES-derived merge source*");

        var onFirst = () => ctx.CreateMergeBuilder<IdentityStoreOnlyRowEntity>()
            .On((t, s) => t.Id == s.Id)
            .Using(new IdentityStoreOnlyRowEntity { Id = 1, Extra = new() { ["alpha"] = 1 } })
            .WhenMatched().ThenUpdate()
            .WhenNotMatched().ThenInsert()
            .ToSql();

        onFirst.Should().Throw<NotSupportedException>().WithMessage("*is not a column of the VALUES-derived merge source*");
    }

    [Fact]
    public void Merge_StoreOnlyEntity_EmptyStore_ShouldThrow()
    {
        using var ctx = new TestContext();

        // A store-only entity whose store is empty (or null) supplies no dynamic column, so a key upsert
        // has nothing to update: it must report the missing non-key column, not the misleading
        // "No source rows were specified" guard. The mapped key means the source is not actually absent.
        var emptyStore = () => ctx.CreateMergeBuilder<StoreOnlyRowEntity>()
            .Using(new StoreOnlyRowEntity { Id = 1, Extra = new() })
            .OnKeys()
            .WhenMatchedUpdate()
            .WhenNotMatchedInsert()
            .ToSql();

        var emptyEx = emptyStore.Should().Throw<NotSupportedException>().Which;
        emptyEx.Message.Should().NotContain("No source rows");

        var nullStore = () => ctx.CreateMergeBuilder<StoreOnlyRowEntity>()
            .Using(new StoreOnlyRowEntity { Id = 2, Extra = null! })
            .OnKeys()
            .WhenMatchedUpdate()
            .WhenNotMatchedInsert()
            .ToSql();

        var nullEx = nullStore.Should().Throw<NotSupportedException>().Which;
        nullEx.Message.Should().NotContain("No source rows");
    }

    [Fact]
    public void Merge_StoreOnlyEntity_NonGeneratedKey_OnSourceKey_ShouldRender()
    {
        using var ctx = new TestContext();
        var entity = new StoreOnlyRowEntity { Id = 1, Extra = new() { ["alpha"] = 1 } };

        // The store-only entity's key is not database-generated, so it IS carried by the
        // VALUES-derived source and an explicit On(...) match on it is expressible. The former On(...)
        // guard rejected every store-only entity (the store supplied no mapped selection) even though
        // this match is valid; it has been removed and the guard now lives in BuildCommand, which only
        // rejects source columns absent from the derived source (see the identity case below).
        var sql = ctx.CreateMergeBuilder<StoreOnlyRowEntity>()
            .Using(entity)
            .On((t, s) => t.Id == s.Id)
            .WhenMatched().ThenUpdate()
            .WhenNotMatched().ThenInsert()
            .ToSql();

        // The dynamic key extends the derived source and both write lists...
        sql.Should().Contain("as source (Id, \"alpha\")");
        sql.Should().Contain("then update set target.\"alpha\" = source.\"alpha\"");
        sql.Should().Contain("then insert (Id, \"alpha\") values (source.Id, source.\"alpha\")");

        // ...while the ON match stays on the declared key, never a dynamic key column.
        var onStart = sql.IndexOf(" on ", StringComparison.Ordinal) + 4;
        var whenStart = sql.IndexOf(" when ", StringComparison.Ordinal);
        var on = sql[onStart..whenStart];
        on.Should().Be("target.Id = source.Id");
        on.Should().NotContain("\"alpha\"");
    }

    private static DynamicRowEntity DynamicRow(int id, string name, int alpha, string beta) => new()
    {
        Id = id,
        Name = name,
        // Deliberately beta before alpha: the writer ordinal-sorts the keys.
        Extra = new Dictionary<string, object?> { ["beta"] = beta, ["alpha"] = alpha },
    };
}

using System.Linq.Expressions;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

public class DynamicResultSchemaTests
{
    public interface ILeadingRow
    {
        [System.ComponentModel.DataAnnotations.Schema.Column("a")]
        int A { get; set; }
    }

    public interface IAliasRow
    {
        [System.ComponentModel.DataAnnotations.Schema.Column("a")]
        int A { get; set; }
    }

    private static class LeadingTvf
    {
        [SqlTableFunction("values", ResultSchema = TableFunctionSchema.LeadingArgument)]
        public static IQueryable<ILeadingRow> Values(string tuples) => throw new NotSupportedException();
    }

    private static class AliasTvf
    {
        [SqlTableFunction("jsonb_to_record", ResultSchema = TableFunctionSchema.AliasColumnList)]
        public static IQueryable<IAliasRow> Record(object? json) => throw new NotSupportedException();
    }

    [Fact]
    public void ResultSchema_ShouldDefaultToNone()
    {
        var attribute = new SqlTableFunctionAttribute("tvf");

        attribute.ResultSchema.Should().Be(TableFunctionSchema.None);
    }

    [Fact]
    public void ResultSchema_ShouldBeSettable()
    {
        var attribute = new SqlTableFunctionAttribute("values")
        {
            ResultSchema = TableFunctionSchema.LeadingArgument
        };

        attribute.ResultSchema.Should().Be(TableFunctionSchema.LeadingArgument);
    }

    [Fact]
    public void Create_WithLeadingSchema_ShouldResolveRowTypeAndPlacement()
    {
        var call = (MethodCallExpression)Expression.Call(
            typeof(LeadingTvf).GetMethod(nameof(LeadingTvf.Values))!,
            Expression.Constant("(1)"));

        var function = TableFunctionExpression.Create(call);

        function.ResultType.Should().Be(typeof(ILeadingRow));
        function.ResultSchema.Should().Be(TableFunctionSchema.LeadingArgument);
    }

    [Fact]
    public void Create_WithAliasSchema_ShouldResolveRowTypeAndPlacement()
    {
        var call = (MethodCallExpression)Expression.Call(
            typeof(AliasTvf).GetMethod(nameof(AliasTvf.Record))!,
            Expression.Constant(null, typeof(object)));

        var function = TableFunctionExpression.Create(call);

        function.ResultType.Should().Be(typeof(IAliasRow));
        function.ResultSchema.Should().Be(TableFunctionSchema.AliasColumnList);
    }

    [Fact]
    public void Create_WithoutSchema_ShouldLeaveRowTypeUnset()
    {
        var method = typeof(LeadingTvf).GetMethod(nameof(LeadingTvf.Values))!;
        var call = (MethodCallExpression)Expression.Call(method, Expression.Constant("(1)"));

        var function = new TableFunctionExpression("plain", null, call);

        function.ResultType.Should().BeNull();
        function.ResultSchema.Should().Be(TableFunctionSchema.None);
    }
}

using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// State-machine and API-surface coverage for <see cref="EagerLoadMode"/>: the mode belongs to the whole
/// builder (an explicit choice applies to collections declared earlier too), <c>Default</c> inherits,
/// repeating the same mode is allowed, conflicting explicit modes are rejected, an unknown enum value is
/// rejected, and the old standalone <c>AsSingleQuery</c> API is gone.
/// </summary>
public class EagerLoadingModeTests
{
    public sealed class ModeParent
    {
        public int Id { get; set; }
        public ICollection<ModeChild> Children { get; set; } = new List<ModeChild>();
        public ICollection<ModeNote> Notes { get; set; } = new List<ModeNote>();
    }

    public sealed class ModeChild
    {
        public int Id { get; set; }
        public int ParentId { get; set; }
    }

    public sealed class ModeNote
    {
        public int Id { get; set; }
        public int ParentId { get; set; }
    }

    private static InMemoryDataContext CreateContext()
    {
        var context = new InMemoryDataContext();
        // Declare the relationships once, before any data seeding, so JoinInto can resolve the
        // collection navigation from metadata (LoadWith uses its explicit key selectors regardless).
        context.From<ModeParent>(b => b
            .HasMany(p => p.Children, c => c.ParentId)
            .HasMany(p => p.Notes, n => n.ParentId));
        context.From<ModeChild>().WithData(new[]
        {
            new ModeChild { Id = 10, ParentId = 1 },
            new ModeChild { Id = 11, ParentId = 1 },
            new ModeChild { Id = 12, ParentId = 2 },
        });
        context.From<ModeNote>().WithData(new[]
        {
            new ModeNote { Id = 100, ParentId = 1 },
            new ModeNote { Id = 101, ParentId = 2 },
        });
        context.From<ModeParent>().WithData(new[]
        {
            new ModeParent { Id = 1 },
            new ModeParent { Id = 2 },
        });
        return context;
    }

    [Fact]
    public void Default_ThenSingleQuery_AppliesToTheEarlierCollection()
    {
        using var context = CreateContext();

        var builder = context.From<ModeParent>()
            .LoadWith(p => p.Children, c => c.From<ModeChild>(), p => p.Id, c => c.ParentId)
            .LoadWith(p => p.Notes, c => c.From<ModeNote>(), p => p.Id, n => n.ParentId, EagerLoadMode.SingleQuery);

        builder.SingleQuery.Should().BeTrue("the explicit mode applies to the whole builder");

        var parents = builder.OrderBy(p => p.Id).ToList();
        parents[0].Children.Select(c => c.Id).Should().Equal(10, 11);
        parents[0].Notes.Select(n => n.Id).Should().Equal(100);
        parents[1].Children.Select(c => c.Id).Should().Equal(12);
        parents[1].Notes.Select(n => n.Id).Should().Equal(101);
    }

    [Fact]
    public void SingleQuery_ThenDefault_InheritsTheChoice()
    {
        using var context = CreateContext();

        var builder = context.From<ModeParent>()
            .LoadWith(p => p.Children, c => c.From<ModeChild>(), p => p.Id, c => c.ParentId, EagerLoadMode.SingleQuery)
            .LoadWith(p => p.Notes, c => c.From<ModeNote>(), p => p.Id, n => n.ParentId);

        builder.SingleQuery.Should().BeTrue("Default must inherit the already chosen mode");

        var parents = builder.OrderBy(p => p.Id).ToList();
        parents[0].Children.Select(c => c.Id).Should().Equal(10, 11);
        parents[0].Notes.Select(n => n.Id).Should().Equal(100);
    }

    [Fact]
    public void ExplicitDefault_WithNoChoice_KeepsSplit()
    {
        using var context = CreateContext();

        var builder = context.From<ModeParent>()
            .LoadWith(p => p.Children, c => c.From<ModeChild>(), p => p.Id, c => c.ParentId, EagerLoadMode.Default);

        builder.SingleQuery.Should().BeFalse("Default without an earlier choice keeps split loading");
    }

    [Theory]
    [InlineData(EagerLoadMode.SplitQuery)]
    [InlineData(EagerLoadMode.SingleQuery)]
    public void SameExplicitMode_MayBeRepeated(EagerLoadMode mode)
    {
        using var context = CreateContext();

        var builder = context.From<ModeParent>()
            .LoadWith(p => p.Children, c => c.From<ModeChild>(), p => p.Id, c => c.ParentId, mode)
            .LoadWith(p => p.Notes, c => c.From<ModeNote>(), p => p.Id, n => n.ParentId, mode);

        builder.SingleQuery.Should().Be(mode == EagerLoadMode.SingleQuery);
        builder.LoadSpecs.Should().HaveCount(2);
    }

    [Fact]
    public void Omitted_ExplicitDefault_And_SplitQuery_ProduceIdenticalResultsAndCommandCounts()
    {
        static (string Result, int ChildCommands) Run(int variant)
        {
            using var context = CreateContext();
            var childCommands = 0;
            Func<IDataContext, EntityBuilder<ModeChild>> children = c =>
            {
                childCommands++;
                return c.From<ModeChild>();
            };
            Func<IDataContext, EntityBuilder<ModeNote>> notes = c =>
            {
                childCommands++;
                return c.From<ModeNote>();
            };

            var source = context.From<ModeParent>();
            var builder = variant switch
            {
                0 => source.LoadWith(p => p.Children, children, p => p.Id, c => c.ParentId),
                1 => source.LoadWith(p => p.Children, children, p => p.Id, c => c.ParentId, EagerLoadMode.Default),
                2 => source.LoadWith(p => p.Children, children, p => p.Id, c => c.ParentId, EagerLoadMode.SplitQuery),
                3 => source
                        .LoadWith(p => p.Children, children, p => p.Id, c => c.ParentId, EagerLoadMode.SplitQuery)
                        .LoadWith(p => p.Notes, notes, p => p.Id, n => n.ParentId, EagerLoadMode.Default),
                _ => throw new ArgumentOutOfRangeException(nameof(variant)),
            };

            builder.SingleQuery.Should().BeFalse("every split variant stays split");
            var parents = builder.OrderBy(p => p.Id).ToList();
            var result = string.Join(
                ";",
                parents.Select(p => p.Id + ":" +
                    string.Join("|", p.Children.Select(c => c.Id)) + "/" +
                    string.Join("|", p.Notes.Select(n => n.Id))));
            return (result, childCommands);
        }

        var omitted = Run(0);
        var explicitDefault = Run(1);
        var explicitSplit = Run(2);
        var inheritedSplit = Run(3);

        omitted.Result.Should().Be("1:10|11/;2:12/");
        explicitDefault.Result.Should().Be(omitted.Result, "the explicit Default must behave exactly like the omitted mode");
        explicitSplit.Result.Should().Be(omitted.Result, "the explicit SplitQuery must behave exactly like the omitted mode");

        omitted.ChildCommands.Should().Be(1, "one non-empty chunk issues exactly one child command");
        explicitDefault.ChildCommands.Should().Be(omitted.ChildCommands);
        explicitSplit.ChildCommands.Should().Be(omitted.ChildCommands);

        // SplitQuery -> LoadWith(Default): the later Default inherits the explicit split mode.
        inheritedSplit.Result.Should().Be("1:10|11/100;2:12/101");
        inheritedSplit.ChildCommands.Should().Be(2, "the second collection inherits split and issues its own child command");
    }

    [Fact]
    public void EmptyParentResult_SplitMode_DoesNotExecuteAChildCommand()
    {
        using var context = new InMemoryDataContext();
        context.From<ModeChild>().WithData(Array.Empty<ModeChild>());
        context.From<ModeParent>().WithData(Array.Empty<ModeParent>());

        var childQueryBuilds = 0;
        var parents = context.From<ModeParent>()
            .LoadWith(
                p => p.Children,
                c =>
                {
                    childQueryBuilds++;
                    return c.From<ModeChild>();
                },
                p => p.Id,
                c => c.ParentId)
            .ToList();

        parents.Should().BeEmpty();
        // The child query is built once for the preparation-time per-parent top-N validation, but an
        // empty parent result must not execute a second (child) command.
        childQueryBuilds.Should().Be(1, "the child query is built for pre-SQL validation only, never executed for an empty parent result");
    }

    [Fact]
    public void SingleQueryMode_ThenCloneAndModifier_ThenDefaultInheritsAndExecutes()
    {
        using var context = CreateContext();

        var chosen = context.From<ModeParent>()
            .LoadWith(p => p.Children, c => c.From<ModeChild>(), p => p.Id, c => c.ParentId, EagerLoadMode.SingleQuery);
        var extended = chosen.Clone()
            .Where(p => p.Id == 1)
            .LoadWith(p => p.Notes, c => c.From<ModeNote>(), p => p.Id, n => n.ParentId, EagerLoadMode.Default);

        extended.SingleQuery.Should().BeTrue("the later Default inherits SingleQuery through the copy/modifier");
        extended.LoadSpecs.Should().HaveCount(2);

        var parents = extended.OrderBy(p => p.Id).ToList();
        parents.Should().ContainSingle();
        parents[0].Children.Select(c => c.Id).Should().Equal(10, 11);
        parents[0].Notes.Select(n => n.Id).Should().Equal(100);
    }

    [Fact]
    public void SplitMode_ThenCloneAndModifier_ThenDefaultInheritsAndExecutes()
    {
        using var context = CreateContext();

        var chosen = context.From<ModeParent>()
            .LoadWith(p => p.Children, c => c.From<ModeChild>(), p => p.Id, c => c.ParentId, EagerLoadMode.SplitQuery);
        var extended = chosen.Clone()
            .Where(p => p.Id == 2)
            .LoadWith(p => p.Notes, c => c.From<ModeNote>(), p => p.Id, n => n.ParentId, EagerLoadMode.Default);

        extended.SingleQuery.Should().BeFalse("the later Default inherits SplitQuery through the copy/modifier");
        extended.LoadSpecs.Should().HaveCount(2);

        var parents = extended.OrderBy(p => p.Id).ToList();
        parents.Should().ContainSingle();
        parents[0].Children.Select(c => c.Id).Should().Equal(12);
        parents[0].Notes.Select(n => n.Id).Should().Equal(101);
    }

    [Fact]
    public void SuccessfulBranchUse_LeavesTheOriginalBuilderModeAndLoadSpecsUnchanged()
    {
        using var context = CreateContext();

        var original = context.From<ModeParent>()
            .LoadWith(p => p.Children, c => c.From<ModeChild>(), p => p.Id, c => c.ParentId, EagerLoadMode.SingleQuery);

        var branch = original.Clone()
            .Where(p => p.Id == 1)
            .LoadWith(p => p.Notes, c => c.From<ModeNote>(), p => p.Id, n => n.ParentId, EagerLoadMode.SingleQuery);

        var parents = branch.OrderBy(p => p.Id).ToList();
        parents.Should().ContainSingle();
        parents[0].Children.Select(c => c.Id).Should().Equal(10, 11);
        parents[0].Notes.Select(n => n.Id).Should().Equal(100);

        original.SingleQuery.Should().BeTrue("a successful branch must not change the original builder's mode");
        original.LoadSpecs.Should().HaveCount(1, "the branch's extra LoadWith must not leak into the original builder");
        branch.LoadSpecs.Should().HaveCount(2);
    }

    [Fact]
    public void EagerExecution_DoesNotPoisonThePlanCacheOrStickyCacheFlag()
    {
        using var context = CreateContext();

        EntityBuilder<ModeChild>? childBuilder = null;
        context.From<ModeParent>()
            .LoadWith(
                p => p.Children,
                c =>
                {
                    childBuilder = c.From<ModeChild>();
                    return childBuilder;
                },
                p => p.Id,
                c => c.ParentId,
                EagerLoadMode.SingleQuery)
            .OrderBy(p => p.Id)
            .ToList()
            .Should().HaveCount(2);

        context.From<ModeParent>()
            .LoadWith(p => p.Children, c => c.From<ModeChild>(), p => p.Id, c => c.ParentId, EagerLoadMode.SplitQuery)
            .OrderBy(p => p.Id)
            .ToList()
            .Should().HaveCount(2);

        childBuilder.Should().NotBeNull();
        childBuilder!.ToCommand().Cache.Should().BeTrue(
            "selecting a mode and building the eager joins must not clear the sticky command cache flag");

        var command = context.From<ModeParent>().Select(p => p.Id);
        command.Cache.Should().BeTrue("eager execution must not poison the shared command state");

        var cancellationToken = TestContext.Current.CancellationToken;
        var first = context.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, cancellationToken);
        var second = context.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, cancellationToken);
        second.Should().BeSameAs(first, "the plan cache must still reuse a prepared command after eager execution");
    }

    [Fact]
    public void EagerExecution_DoesNotPoisonTheContextSharedAnyCommand()
    {
        using var context = CreateContext();
        var cancellationToken = TestContext.Current.CancellationToken;

        // (1) Exercise .Any() first so the context allocates and uses its shared AnyCommand.
        context.From<ModeParent>().Where(p => p.Id == 1).Any().Should().BeTrue();
        context.AnyCommand.Should().NotBeNull("the first Any call must allocate the context-shared command");
        var sharedAnyCommand = context.AnyCommand!.Value;

        // (2) Run the eager-loading path with non-empty parents AND children, both modes, on the same context.
        var singleQueryParents = context.From<ModeParent>()
            .LoadWith(p => p.Children, c => c.From<ModeChild>(), p => p.Id, c => c.ParentId, EagerLoadMode.SingleQuery)
            .OrderBy(p => p.Id)
            .ToList();
        singleQueryParents.Should().HaveCount(2);
        singleQueryParents.SelectMany(p => p.Children).Should().NotBeEmpty();

        var splitQueryParents = context.From<ModeParent>()
