            .Join(_sut.SimpleEntity, (t1, t2) => t1.Id == t2.Id + 1)
            .Join(_sut.SimpleEntity, (p, t3) => p.Item2.Id == t3.Id - 1)
            .Join(_sut.SimpleEntity, (p, t4) => p.Item3.Id == t4.Id)
