    public void TestAsThenJoin_ShouldThrow()
    {
        var act = () => _sut.SimpleEntity
            .Join(_sut.SimpleEntity, (t1, t2) => t1.Id == t2.Id)
            .As(p => new { LeftId = p.Item1.Id, RightId = p.Item2.Id })
