using System.Text;
using FluentAssertions;

namespace NextORM.Core.Tests;

/// <summary>
/// D160 reconnaissance probes (issue #160, cycle N=2). Test-only: they characterise the baseline
/// positional join seam on HEAD <c>0495ee84</c> without touching product code.
///
/// <para>
/// The R160-02' oracle is the observation that a positional <c>Join</c> deliberately omits
/// <see cref="EntityBuilder{TEntity}.SourceEntityType"/> and
/// <see cref="EntityBuilder{TEntity}.BindArrayJoinElement"/> when it copies state onto the joined
/// builder, while <c>Clone</c>/<c>CopyTo</c> preserve both. These probes prove that oracle is
/// obtainable on the baseline with <c>InternalsVisibleTo("nextorm.core.tests")</c>.
/// </para>
/// </summary>
public class JoinAliasMixingSeamTests
{
    private const string DefaultEvidenceRoot = "artifacts/pdca/D160/rv1/N2/revised";
    // Committed fixture (tracked): the frozen positional expression corpus captured at HEAD 0495ee84.
    // It must NOT live under artifacts/ (gitignored) — a CI checkout only has tracked files.
    private const string DefaultBaselineRoot = "tests/nextorm.core.tests/Baselines/D160/positional";

    private static readonly string[] Cases =
    [
        "01-inner", "02-left", "03-right", "04-full", "05-cross",
        "06-three-join-chain", "07-where-between-joins", "08-positional-prefix-as",
    ];

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "nextorm.slnx")))
            dir = dir.Parent;
        return dir?.FullName ?? Directory.GetCurrentDirectory();
    }

    private static string ResolveDir(string? envValue, string defaultRelative)
    {
        var value = string.IsNullOrWhiteSpace(envValue) ? defaultRelative : envValue!;
        return Path.IsPathRooted(value) ? value : Path.Combine(RepoRoot(), value);
    }

    private static string EvidenceRoot()
        => ResolveDir(Environment.GetEnvironmentVariable("D160_EVIDENCE_DIR"), DefaultEvidenceRoot);

    private static string BaselineRoot()
        => ResolveDir(Environment.GetEnvironmentVariable("D160_BASELINE_DIR"), DefaultBaselineRoot);

    // -----------------------------------------------------------------------------------------------
    // P1 — the primary oracle: positional Join drops SourceEntityType/BindArrayJoinElement; Clone keeps.
    // -----------------------------------------------------------------------------------------------
    [Trait("D160Probe", "P1")]
    [Fact]
    public void Positional_join_drops_source_entity_type_and_bind_flag_but_clone_preserves()
    {
        using var ctx = new InMemoryDataContext();
        var source = ctx.From<SimpleEntity>();

        // (1) set the internal array-join source seam on the plain From<X>() builder.
        source.SourceEntityType = typeof(SimpleEntity);
        source.BindArrayJoinElement = true;

        // (1b) prove the setup took.
        source.SourceEntityType.Should().Be(typeof(SimpleEntity));
        source.BindArrayJoinElement.Should().BeTrue();

        // (2) call the public positional Join.
        var joined = source.Join(ctx.From<ConventionalEntity>(), (a, b) => a.Id == b.Id);

        // (3) the joined builder must NOT inherit either seam (see ApplyJoinStateTo, which omits them).
        joined.SourceEntityType.Should().BeNull();
        joined.BindArrayJoinElement.Should().BeFalse();

        // (4) control arm: Clone/CopyTo preserves both.
        var clone = source.Clone();
        clone.SourceEntityType.Should().Be(typeof(SimpleEntity));
        clone.BindArrayJoinElement.Should().BeTrue();

        // and the copy is independent of the joined builder.
        joined.SourceEntityType.Should().BeNull();
        joined.BindArrayJoinElement.Should().BeFalse();
    }

    // -----------------------------------------------------------------------------------------------
    // P2 — expression identity of a frozen positional-only corpus (core / in-memory surface).
    // -----------------------------------------------------------------------------------------------
    [Trait("D160Probe", "P2")]
    [Fact]
    public void Positional_chain_expression_identity_is_frozen_and_deterministic()
    {
        using var ctx = new InMemoryDataContext();
        var dir = Path.Combine(EvidenceRoot(), "positional");
        Directory.CreateDirectory(dir);

        var simple = ctx.From<SimpleEntity>();
        var other = ctx.From<ConventionalEntity>();
        var other2 = ctx.From<ConventionalEntity>();

        Capture(dir, "01-inner", simple.Join(other, (a, b) => a.Id == b.Id).Select(p => p.Item2.Id));
        Capture(dir, "02-left", simple.LeftJoin(other, (a, b) => a.Id == b.Id).Select(p => p.Item2.Id));
        Capture(dir, "03-right", simple.RightJoin(other, (a, b) => a.Id == b.Id).Select(p => p.Item2.Id));
        Capture(dir, "04-full", simple.FullJoin(other, (a, b) => a.Id == b.Id).Select(p => p.Item2.Id));
        Capture(dir, "05-cross", simple.CrossJoin(other).Select(p => p.Item2.Id));
        Capture(dir, "06-three-join-chain", simple
            .Join(other, (a, b) => a.Id == b.Id)
            .Join(other2, (p, c) => p.Item1.Id == c.Id)
            .Select(p => p.Item2.Id));
        Capture(dir, "07-where-between-joins", simple
            .Where(a => a.Id > 0)
            .Join(other, (a, b) => a.Id == b.Id)
            .Select(p => p.Item2.Id));
        Capture(dir, "08-positional-prefix-as", simple
            .Join(other, (a, b) => a.Id == b.Id)
            .As(p => new { p.Item1.Id, p.Item2.Name })
            .Select(x => x.Id));

        foreach (var name in Cases)
        {
            var file = Path.Combine(dir, name + ".txt");
            File.Exists(file).Should().BeTrue();
            new FileInfo(file).Length.Should().BeGreaterThan(0);
            CompareToBaseline(BaselineRoot(), dir, name);
        }
    }

    /// <summary>
    /// Reads the frozen baseline expression <c>&lt;name&gt;.txt</c> and asserts the freshly generated
    /// revised bytes are identical. Any length or byte difference fails the test.
    /// </summary>
    private static void CompareToBaseline(string baselineDir, string revisedDir, string name)
    {
        var baselinePath = Path.Combine(baselineDir, name + ".txt");
        var revisedPath = Path.Combine(revisedDir, name + ".txt");

        File.Exists(baselinePath)
            .Should().BeTrue($"the frozen baseline positional expression corpus must exist at '{baselinePath}'");

        var baselineBytes = File.ReadAllBytes(baselinePath);
        var revisedBytes = File.ReadAllBytes(revisedPath);
        revisedBytes.Should().Equal(baselineBytes, $"{name}: positional expression must be byte-identical to the baseline");
    }

    private static void Capture(string dir, string name, QueryCommand command)
    {
        var sb = new StringBuilder();
        sb.Append("case=").Append(name).Append('\n');
        sb.Append("projection=").Append(command.ProjectionExpression?.ToString() ?? "<none>").Append('\n');
        sb.Append("condition=").Append(command.Condition?.ToString() ?? "<none>").Append('\n');
        var joins = command.Joins;
        sb.Append("join_count=").Append(joins?.Length ?? 0).Append('\n');
        if (joins is not null)
        {
            for (var i = 0; i < joins.Length; i++)
            {
                sb.Append("join[").Append(i).Append("]=")
                    .Append(joins[i].JoinType)
                    .Append(";cond=").Append(joins[i].JoinCondition?.ToString() ?? "<none>")
                    .Append('\n');
            }
        }

        File.WriteAllBytes(Path.Combine(dir, name + ".txt"), Encoding.UTF8.GetBytes(sb.ToString()));
    }

    // -----------------------------------------------------------------------------------------------
    // P3 — positional Join returns a core JoinedEntityBuilder and does NOT throw the alias refusal.
    // -----------------------------------------------------------------------------------------------
    [Trait("D160Probe", "P3")]
    [Fact]
    public void Positional_join_returns_core_joined_builder_and_does_not_alias_refuse()
    {
        using var ctx = new InMemoryDataContext();
        var source = ctx.From<SimpleEntity>();

        JoinedEntityBuilder<SimpleEntity, ConventionalEntity> joined = null!;
        var ex = Record.Exception(
            () => joined = source.Join(ctx.From<ConventionalEntity>(), (a, b) => a.Id == b.Id));

        ex.Should().BeNull("a positional Join on a non-projection source must not be refused");
        joined.Should().NotBeNull();
        joined.Should().BeOfType<JoinedEntityBuilder<SimpleEntity, ConventionalEntity>>();
        joined.GetType().Namespace.Should().Be("NextORM.Core");
    }
}

using System.Linq.Expressions;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// Issue #160 (cycle N=2, r=1) mutation-gap tests. They pin the behaviour the first Stryker pass
/// reported as <c>Survived</c>/<c>NoCoverage</c> inside the #160-changed regions, all using the
/// provider-free <see cref="RootProjectionTests.TestContext"/> (fake dialect) so the planner and SQL
/// renderer are exercised without a database.
/// <para>
/// Covered seams: the <c>ProjectionAliasCache.GetItem1Property</c> memoisation; the <c>AliasRoot</c>
/// argument guard; the pre-<c>.WithAlias</c> query-state rebasing on <c>AliasRoot</c> itself and the
/// re-basing performed when an alias join follows (OrderBy/GroupBy/Having/Paging).
/// Runs in the "Query cache controls" collection (parallelization disabled) because the shared
/// process-wide plan cache is read.
/// </para>
/// </summary>
[Collection("Query cache controls")]
public class JoinAliasMutationGapTests
{
    /// <summary>
    /// A root projection type used only by this fixture. <c>ProjectionAliasCache</c> memoizes the
    /// resolved <c>Item1</c> per closed projection type, so the type must not be shared with another
    /// test: otherwise the cache is populated before this test runs and the resolution lambda — the
    /// code under mutation — never executes here.
    /// </summary>
    private sealed class GapRootProjection<T> : Projection<T>
    {
    }

    /// <summary>Parent with a declared collection navigation, used for the eager-load guard.</summary>
    private sealed class GapParent
    {
        [System.ComponentModel.DataAnnotations.Key]
        public int Id { get; set; }

        public ICollection<GapChild> Children { get; } = new List<GapChild>();
    }

    /// <summary>Child of <see cref="GapParent"/>.</summary>
    private sealed class GapChild
    {
        [System.ComponentModel.DataAnnotations.Key]
        public int Id { get; set; }

        public int ParentId { get; set; }
    }

    private static EntityBuilder<RootProjectionTests.RootProjection<RootProjectionTests.Order>> AliasRoot(
        EntityBuilder<RootProjectionTests.Order> source) =>
        source.AliasRoot<
            EntityBuilder<RootProjectionTests.RootProjection<RootProjectionTests.Order>>,
            RootProjectionTests.RootProjection<RootProjectionTests.Order>>(static dc => new(dc));

    // ------------------------------------------------------------------ Item1 memoisation ---------

    [Fact]
    public void GetItem1Property_resolves_public_instance_item1_and_memoizes_the_result()
    {
        var projectionType = typeof(GapRootProjection<RootProjectionTests.Order>);

        var first = ProjectionAliasCache.GetItem1Property(projectionType);
        var second = ProjectionAliasCache.GetItem1Property(projectionType);

        // Resolving must find the inherited public instance Item1 (not a static, not nothing).
        first.Should().NotBeNull();
        first!.Name.Should().Be("Item1");
        first.GetMethod.Should().NotBeNull();
        first.GetMethod!.IsStatic.Should().BeFalse();

        // The same closed projection type must return the same PropertyInfo instance (memoized).
        second.Should().BeSameAs(first);

        // A type without Item1 is a stable null result (AliasRoot turns it into a fail-closed error).
        ProjectionAliasCache.GetItem1Property(typeof(RootProjectionTests.Order)).Should().BeNull();
    }

    // ------------------------------------------------------------------ AliasRoot guards ----------

    [Fact]
    public void AliasRoot_rejects_a_null_factory_before_touching_the_provider()
    {
        using var ctx = new InMemoryDataContext();

        Action act = () => ctx.From<RootProjectionTests.Order>()
            .AliasRoot<
                EntityBuilder<RootProjectionTests.RootProjection<RootProjectionTests.Order>>,
                RootProjectionTests.RootProjection<RootProjectionTests.Order>>(null!);

        act.Should().Throw<ArgumentNullException>();
    }

    [Fact]
    public void AliasRoot_is_refused_after_eager_load_state_is_declared()
    {
        using var ctx = new RootProjectionTests.TestContext();

        var parent = ctx.From<GapParent>(b => b.HasMany(p => p.Children, c => c.ParentId))
            .LoadWith(p => p.Children, c => c.From<GapChild>(), p => p.Id, c => c.ParentId);

        Action act = () => parent.AliasRoot<
            EntityBuilder<RootProjectionTests.RootProjection<GapParent>>,
            RootProjectionTests.RootProjection<GapParent>>(static dc => new(dc));

        act.Should().Throw<NotSupportedException>().WithMessage("*LoadWith*WithAlias*");
    }

    [Fact]
    public void AliasRoot_is_refused_after_a_named_window_is_declared()
    {
        using var ctx = new RootProjectionTests.TestContext();
        var orders = ctx.From<RootProjectionTests.Order>();
        var windowed = orders.Window("w", orderBy: [orders.Asc(o => o.Id)]);

        Action act = () => AliasRoot(windowed);

        // The guard must carry its diagnostic message/context, not an empty or generic exception: the
        // mutation run reported the message string literal as surviving.
        act.Should().Throw<InvalidOperationException>()
            .WithMessage("*Named windows must be declared after joins*Window cannot be combined*");
    }

    // ------------------------------------------------------------------ AliasRoot rebasing --------

    [Fact]
    public void AliasRoot_preserves_order_by_applied_before_it()
    {
        using var ctx = new RootProjectionTests.TestContext();

        var sql = RootProjectionTests.SqlOf(ctx,
            AliasRoot(ctx.From<RootProjectionTests.Order>().OrderBy(o => o.Id)).Select(p => p.Root.Id));

        sql.Should().Contain("order by Id");
    }

    [Fact]
    public void AliasRoot_preserves_group_by_and_having_applied_before_it()
    {
        using var ctx = new RootProjectionTests.TestContext();

        var sql = RootProjectionTests.SqlOf(ctx,
            AliasRoot(ctx.From<RootProjectionTests.Order>()
                .GroupBy(o => o.BuyerId)
                .Having(o => SqlFunctions.Sql.count() > 1))
            .Select(p => p.Root.BuyerId));

        sql.Should().Contain("group by buyer_id");
        sql.Should().Contain("having (count(*) > 1)");
    }

    // ------------------------------------------------------------------ pre-alias seam + join -----

    [Fact]
    public void Alias_join_rebases_order_by_applied_before_the_alias()
    {
        using var ctx = new RootProjectionTests.TestContext();
        var people = ctx.From<RootProjectionTests.Person>();

        var rooted = AliasRoot(ctx.From<RootProjectionTests.Order>().OrderBy(o => o.Id));

        var joined = rooted.JoinAlias<
            EntityBuilder<RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>>,
            RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>,
            RootProjectionTests.Person>(
            static dc => new(dc),
            people,
            (a, b) => a.Root.BuyerId == b.Id);

        var sql = RootProjectionTests.SqlOf(ctx, joined.Select(p => p.Buyer.Id));

        // The pre-alias OrderBy must survive the join, rebased onto the root slot t1; dropping it
        // would silently lose the modifier written before .WithAlias.
        sql.Should().Contain("order by t1.Id");
    }

    [Fact]
    public void Alias_join_rebases_group_by_applied_before_the_alias()
    {
        using var ctx = new RootProjectionTests.TestContext();
        var people = ctx.From<RootProjectionTests.Person>();

        var rooted = AliasRoot(ctx.From<RootProjectionTests.Order>().GroupBy(o => o.BuyerId));

        var joined = rooted.JoinAlias<
            EntityBuilder<RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>>,
            RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>,
            RootProjectionTests.Person>(
            static dc => new(dc),
            people,
            (a, b) => a.Root.BuyerId == b.Id);

        var sql = RootProjectionTests.SqlOf(ctx, joined.Select(p => p.Buyer.Id));

        sql.Should().Contain("group by t1.buyer_id");
    }

    // ------------------------------------------------- descending rebasing (Direction preserved) --

    [Fact]
    public void AliasRoot_preserves_a_descending_order_by_applied_before_it()
    {
        using var ctx = new RootProjectionTests.TestContext();

        var sql = RootProjectionTests.SqlOf(ctx,
            AliasRoot(ctx.From<RootProjectionTests.Order>().OrderByDescending(o => o.Id)).Select(p => p.Root.Id));

        // The rebase must carry the direction, not just the key: a lost Direction defaults to Asc and
        // silently flips the caller's descending order.
        sql.Should().Contain("order by Id desc");
    }

    [Fact]
    public void Alias_join_rebases_a_descending_order_by_applied_before_the_alias()
    {
        using var ctx = new RootProjectionTests.TestContext();
        var people = ctx.From<RootProjectionTests.Person>();

        var rooted = AliasRoot(ctx.From<RootProjectionTests.Order>().OrderByDescending(o => o.Id));

        var joined = rooted.JoinAlias<
            EntityBuilder<RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>>,
            RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>,
            RootProjectionTests.Person>(
            static dc => new(dc),
            people,
            (a, b) => a.Root.BuyerId == b.Id);

        var sql = RootProjectionTests.SqlOf(ctx, joined.Select(p => p.Buyer.Id));

        // As above, but through the alias-join seam: descending must survive the rebase onto t1.
        sql.Should().Contain("order by t1.Id desc");
    }

    // ------------------------------------------------- derived-root rebasing (Query -> From) ------

    [Fact]
    public void AliasRoot_on_a_derived_root_preserves_the_derived_source_and_aliases_it()
    {
        using var ctx = new RootProjectionTests.TestContext();

        // A derived root (From(builder) / From(QueryCommand<T>)) is carried as Query; re-rooting must
        // materialize it as an explicit derived-table FromExpression (and clear Query) so the physical
        // derived source, not the projection type, resolves and is aliased 't1'.
        var derived = ctx.From(ctx.From<RootProjectionTests.Order>().Where(o => o.Id > 0));

        var rooted = derived.AliasRoot<
            EntityBuilder<RootProjectionTests.RootProjection<RootProjectionTests.Order>>,
            RootProjectionTests.RootProjection<RootProjectionTests.Order>>(static dc => new(dc));

        var sql = RootProjectionTests.SqlOf(ctx, rooted.Select(p => p.Root.Id));

        sql.Should().Contain("from (select Id, buyer_id as 'BuyerId' from orders");
        sql.Should().Contain(") as 't1'");
    }

    [Fact]
    public void AliasRoot_on_a_derived_QueryCommand_root_preserves_the_derived_source()
    {
        using var ctx = new RootProjectionTests.TestContext();

        // The QueryCommand overload takes the same derived-root branch as From(builder).
        QueryCommand<int> inner = ctx.From<RootProjectionTests.Order>().Select(o => o.Id);

        var rooted = ctx.From(inner).AliasRoot<
            EntityBuilder<RootProjectionTests.RootProjection<int>>,
            RootProjectionTests.RootProjection<int>>(static dc => new(dc));

        var sql = RootProjectionTests.SqlOf(ctx, rooted.Select(p => p.Root));

        sql.Should().Contain("from (select Id from orders) as 't1'");
    }

    // ------------------------------------------------- having/prewhere-only root rebasing --------

    [Fact]
    public void AliasRoot_having_only_is_rebased_onto_the_root_slot()
    {
        using var ctx = new RootProjectionTests.TestContext();

        // Only Having is set before '.WithAlias' (no GroupBy): the GroupBy is added after re-rooting so
        // the rendered HAVING is observable. ApplyJoinStateTo deliberately does not copy `_having`, so if
        // the root seam skipped the `_having` disjunct the clause would be dropped from the result.
        var rooted = AliasRoot(ctx.From<RootProjectionTests.Order>()
                .Having(o => SqlFunctions.Sql.count() > 1))
            .GroupBy(p => p.Root.BuyerId);

        var sql = RootProjectionTests.SqlOf(ctx, rooted.Select(p => p.Root.BuyerId));

        sql.Should().Contain("group by");
        sql.Should().Contain("having (count(*) > 1)");
    }

    [Fact]
    public void AliasRoot_prewhere_only_is_rebased_onto_the_root_slot()
    {
        using var ctx = new RootProjectionTests.TestContext();

        var source = ctx.From<RootProjectionTests.Order>();
        source.PreWhereCondition = (Expression<Func<RootProjectionTests.Order, bool>>)(o => o.Id > 0);

        var rooted = AliasRoot(source);
        var command = rooted.Select(p => p.Root.Id);

        // PreWhere is copied verbatim by ApplyJoinStateTo, so a skipped rebase is observable in the
        // predicate's type: the seam must retype it over the root projection (Item1).
        command.PreWhere.Should().NotBeNull("the pre-'.WithAlias' PreWhere must survive the re-rooting");
        command.PreWhere!.Parameters[0].Type.Should().Be(
            typeof(RootProjectionTests.RootProjection<RootProjectionTests.Order>));
        command.PreWhere.Body.ToString().Should().Contain("Item1");
    }

    // ------------------------------------------------- rebasing through an alias join -------------

    [Fact]
    public void Alias_join_rebases_having_applied_before_the_alias()
    {
        using var ctx = new RootProjectionTests.TestContext();
        var people = ctx.From<RootProjectionTests.Person>();

        var rooted = AliasRoot(ctx.From<RootProjectionTests.Order>()
                .Having(o => SqlFunctions.Sql.count() > 1))
            .GroupBy(p => p.Root.BuyerId);

        var joined = rooted.JoinAlias<
            EntityBuilder<RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>>,
            RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>,
            RootProjectionTests.Person>(
            static dc => new(dc),
            people,
            (a, b) => a.Root.BuyerId == b.Id);

        var sql = RootProjectionTests.SqlOf(ctx, joined.Select(p => p.Buyer.Id));

        // `_having` is not copied by ApplyJoinStateTo, so the alias-join seam must rebase it onto the
        // extended projection; otherwise the HAVING written before '.WithAlias' is silently dropped.
        sql.Should().Contain("having (count(*) > 1)");
    }

    [Fact]
    public void Alias_join_rebases_prewhere_applied_before_the_alias()
    {
        using var ctx = new RootProjectionTests.TestContext();
        var people = ctx.From<RootProjectionTests.Person>();

        var source = ctx.From<RootProjectionTests.Order>();
        source.PreWhereCondition = (Expression<Func<RootProjectionTests.Order, bool>>)(o => o.Id > 0);

        var joined = AliasRoot(source).JoinAlias<
            EntityBuilder<RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>>,
            RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>,
            RootProjectionTests.Person>(
            static dc => new(dc),
            people,
            (a, b) => a.Root.BuyerId == b.Id);

        var command = joined.Select(p => p.Buyer.Id);

        // The alias-join seam must retype the pre-alias PreWhere over the extended projection, not leave
        // it over the root projection it was copied from.
        command.PreWhere.Should().NotBeNull();
        command.PreWhere!.Parameters[0].Type.Should().Be(
            typeof(RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>));
    }

    // ------------------------------------------------- root-only refusal --------------------------

    [Fact]
    public void AliasRoot_is_refused_when_the_receiver_is_already_aliased_or_joined()
    {
        using var ctx = new RootProjectionTests.TestContext();

        // Applied twice: the receiver is already a root-alias projection (dim-1), not a plain source.
        var rooted = AliasRoot(ctx.From<RootProjectionTests.Order>());
        Action again = () => rooted.AliasRoot<
            EntityBuilder<RootProjectionTests.RootProjection<RootProjectionTests.Order>>,
            RootProjectionTests.RootProjection<RootProjectionTests.Order>>(static dc => new(dc));
        again.Should().Throw<NotSupportedException>();

        // Applied after a join: the receiver already carries a join chain.
        var joined = ctx.From<RootProjectionTests.Order>()
            .Join(ctx.From<RootProjectionTests.Person>(), (o, p) => o.BuyerId == p.Id);
        Action afterJoin = () => joined.AliasRoot<
            EntityBuilder<RootProjectionTests.RootProjection<RootProjectionTests.Order>>,
            RootProjectionTests.RootProjection<RootProjectionTests.Order>>(static dc => new(dc));
        afterJoin.Should().Throw<NotSupportedException>().WithMessage("*before any Join*");
    }

    // ------------------------------------------------- derived-root + alias join -----------------

    [Fact]
    public void Alias_join_after_a_derived_root_alias_keeps_the_derived_source()
    {
        using var ctx = new RootProjectionTests.TestContext();
        var people = ctx.From<RootProjectionTests.Person>();

        // A derived root (From(builder)) is carried as Query; re-rooting materializes it as an explicit
        // derived-table FromExpression and clears Query, so the derived source (not the projection type)
        // resolves and is aliased 't1' even when an alias join follows.
        var derived = ctx.From(ctx.From<RootProjectionTests.Order>().Where(o => o.Id > 0));
        var rooted = derived.AliasRoot<
            EntityBuilder<RootProjectionTests.RootProjection<RootProjectionTests.Order>>,
            RootProjectionTests.RootProjection<RootProjectionTests.Order>>(static dc => new(dc));

        var joined = rooted.JoinAlias<
            EntityBuilder<RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>>,
            RootProjectionTests.RootJoinProjection<RootProjectionTests.Order, RootProjectionTests.Person>,
            RootProjectionTests.Person>(
            static dc => new(dc),
            people,
            (a, b) => a.Root.BuyerId == b.Id);

        var sql = RootProjectionTests.SqlOf(ctx, joined.Select(p => p.Buyer.Id));

        sql.Should().Contain("from (select Id, buyer_id as 'BuyerId' from orders");
        sql.Should().Contain(") as 't1'");
        sql.Should().Contain("join person as 't2'");
        sql.Should().Contain("on t1.BuyerId = t2.Id");
    }
}

using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using FluentAssertions;

namespace NextORM.Core.Tests;

/// <summary>
/// T213 candidate 3 (r=5): the mixed <c>Projection&lt;mappedEntity, scalar&gt;</c> admission introduced at
/// D03 (r=2) was only ever consumed by the composite-junction SQL many-to-many link source, which now
/// fails closed at preparation (#223). No ordinary public query produces that shape as a *working*
/// result: an end-to-end public <c>Join</c> of a mapped entity plus a scalar subquery renders an
/// incomplete column (<c>Item2.</c>) and an unterminated join predicate. The admission is therefore
/// removed and the shape fails closed deterministically instead of emitting broken SQL. These cases pin
/// that fail-closed behavior for the value, reference and nullable scalar items and for the all-columns-
/// NULL entity item; the non-mapped complex item stays rejected as before.
/// </summary>
public class JoinIntoCompositeCarrierSpikeTests
{
    private static IDataContext CreateContext() => new RootProjectionTests.TestContext();

    private static void Prepare<TResult>(IDataContext ctx, EntityBuilder<TResult> builder)
        => ctx.GetPreparedQueryCommand(builder.ToCommand(), createEnumerator: false, storeInCache: false, TestContext.Current.CancellationToken);

    private static void ShouldFailClosed<T>(IDataContext ctx, EntityBuilder<T> joined, string because)
        => ((Action)(() => Prepare(ctx, joined)))
            .Should().Throw<QueryPreparationException>(because);

    [Fact]
    public void MixedProjection_EntityPlusValueScalar_ShouldFailClosed()
    {
        using var ctx = CreateContext();
        var scalarIds = ctx.From<CarrierScalar>().Select(s => s.Id);

        ShouldFailClosed(
            ctx,
            ctx.From<CarrierJunction>().Join(ctx.From(scalarIds), (j, s) => j.Id == s),
            "a scalar item beside a mapped entity is no longer admitted; the shape has no working public terminal");
    }

    [Fact]
    public void MixedProjection_EntityPlusReferenceScalar_ShouldFailClosed()
    {
        using var ctx = CreateContext();
        var scalarNames = ctx.From<CarrierScalar>().Select(s => s.Name);

        ShouldFailClosed(
            ctx,
            ctx.From<CarrierJunction>().Join(ctx.From(scalarNames), (j, s) => j.Id == s!.Length),
            "a reference scalar item beside a mapped entity must fail closed");
    }

    [Fact]
    public void MixedProjection_EntityPlusNullableScalar_ShouldFailClosed()
    {
        using var ctx = CreateContext();
        var scalarValues = ctx.From<CarrierScalar>().Select(s => (int?)s.Value);

        ShouldFailClosed(
            ctx,
            ctx.From<CarrierJunction>().Join(ctx.From(scalarValues), (j, s) => j.Id == s),
            "a nullable scalar item beside a mapped entity must fail closed");
    }

    [Fact]
    public void MixedProjection_UnsupportedComplexItem_ShouldStillFailClosed()
    {
        using var ctx = CreateContext();
        var unmapped = ctx.From<CarrierScalar>().Select(s => new CarrierUnmappedItem { X = s.Id });

        var joined = ctx.From<CarrierJunction>().Join(ctx.From(unmapped), (j, u) => j.Id == u.X);

        ((Action)(() => Prepare(ctx, joined)))
            .Should().Throw<QueryPreparationException>(
                "a non-mapped complex item must not be admitted as an ordinary scalar column");
    }
}

/// <summary>A reference type that is deliberately neither a mapped entity nor a supported scalar.</summary>
public sealed class CarrierUnmappedItem
{
    public int X { get; set; }
}

[SqlTable("carrier_junction")]
public sealed class CarrierJunction
{
    [Key]
    [Column("id")]
    public int Id { get; set; }

    [Column("parent_key1")]
    public int ParentKey1 { get; set; }

    [Column("parent_key2")]
    public int ParentKey2 { get; set; }

    [Column("child_key")]
    public int ChildKey { get; set; }

    [Column("label")]
    public string? Label { get; set; }
}

[SqlTable("carrier_scalar")]
public sealed class CarrierScalar
{
    [Key]
    [Column("id")]
    public int Id { get; set; }

    [Column("value")]
    public int Value { get; set; }

    [Column("name")]
    public string? Name { get; set; }
}

using System.Data;
using System.Data.Common;
using System.Diagnostics.CodeAnalysis;
using System.Reflection;
using System.Text;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// T213 D04-R (r=4, direction D): the composite-junction many-to-many <c>JoinInto</c> SQL link source
/// is rejected explicitly at preparation. The rejection is fail-closed (a <see cref="NotSupportedException"/>
/// from <c>JunctionLinkSourceFactory.BuildSource</c>), carries the follow-up issue number in its message,
/// and must not execute any SQL. The scalar junction path is a control: it is not rejected.
/// <para>
/// Runs in the "Query cache controls" collection because it writes the process-wide
/// <see cref="DataContextCache"/> and must not race other metadata tests.
/// </para>
/// </summary>
[Collection("Query cache controls")]
public class JoinIntoCompositeJunctionRejectionTests
{
    private const string CompositeRejectionMessage = "composite-junction M:N is not supported; see #223";

    public JoinIntoCompositeJunctionRejectionTests()
    {
        DataContextCache.Clear();
    }

    private static IReadOnlyList<IPropertyMetadata> Props<T>()
        => new EntityMetadataBuilder<T>().Build().Properties;

    private static IPropertyMetadata Prop(IReadOnlyList<IPropertyMetadata> properties, string name)
        => properties.First(p => p.PropertyInfo.Name == name);

    public sealed class CompositeJunctionParent
    {
        public int Id { get; set; }
        public ICollection<CompositeJunctionChild> Children { get; set; } = new List<CompositeJunctionChild>();
    }

    public sealed class CompositeJunctionChild
    {
        public int Id { get; set; }
    }

    public sealed class CompositeJunctionLink
    {
        public int ParentId { get; set; }
        public int ParentId2 { get; set; }
        public int ChildId { get; set; }
    }

    private static void RegisterCompositeJunctionParent()
    {
        var parentProps = Props<CompositeJunctionParent>();
        var childProps = Props<CompositeJunctionChild>();
        var linkProps = Props<CompositeJunctionLink>();
        var parentKey = Prop(parentProps, nameof(CompositeJunctionParent.Id)).PropertyInfo;
        var childKey = Prop(childProps, nameof(CompositeJunctionChild.Id)).PropertyInfo;
        var navigation = typeof(CompositeJunctionParent).GetProperty(nameof(CompositeJunctionParent.Children));

        DataContextCache.Metadata[typeof(CompositeJunctionParent)] = new EntityMetadata(
            typeof(CompositeJunctionParent).Name,
            parentProps.Where(p => p.PropertyInfo != navigation).ToList(),
            relationships:
            [
                new RelationshipMetadata(
                    RelationshipKind.ManyToMany,
                    typeof(CompositeJunctionParent),
                    typeof(CompositeJunctionChild),
                    navigation,
                    isCollection: true,
                    childKey,
                    parentKey,
                    typeof(CompositeJunctionChild),
                    typeof(CompositeJunctionParent),
                    new RelationshipJunctionDeclaration
                    {
                        JunctionType = typeof(CompositeJunctionLink),
                        ParentKey = [parentKey],
                        ChildKey = [childKey],
                        JunctionParentForeignKey =
                        [
                            Prop(linkProps, nameof(CompositeJunctionLink.ParentId)).PropertyInfo,
                            Prop(linkProps, nameof(CompositeJunctionLink.ParentId2)).PropertyInfo,
                        ],
                        JunctionChildForeignKey = [Prop(linkProps, nameof(CompositeJunctionLink.ChildId)).PropertyInfo],
                    }),
            ]);
    }

    [Fact]
    public void CompositeJunctionManyToMany_SqlPath_ShouldThrowAtPreparationWithIssueMessage_AndExecuteNoSql()
    {
        RegisterCompositeJunctionParent();
        using var ctx = new TrackingContext();

        // The composite-junction SQL link source cannot be materialized on the entity-item path yet
        // (carried by #223). Building the declaration must fail closed with the explicit message rather
        // than degrade into a broken column mapping or a raw materialization error.
        Action act = () => ctx.From<CompositeJunctionParent>()
            .JoinInto(ctx.From<CompositeJunctionChild>(), (p, c) => true, p => p.Children)
            .ToList();

        act.Should().Throw<NotSupportedException>().WithMessage(CompositeRejectionMessage);
        ctx.ConnectionsRequested.Should().Be(0, "the rejection happens at preparation; no SQL is executed");
    }

    public sealed class ScalarJunctionParent
    {
        public int Id { get; set; }
        public ICollection<ScalarJunctionChild> Children { get; set; } = new List<ScalarJunctionChild>();
    }

    public sealed class ScalarJunctionChild
    {
        public int Id { get; set; }
    }

    public sealed class ScalarJunctionLink
    {
        public int ParentId { get; set; }
        public int ChildId { get; set; }
    }

    [Fact]
    public void ScalarJunctionManyToMany_SqlPath_ShouldNotBeRejected()
    {
        using var ctx = new TrackingContext();
        ctx.From<ScalarJunctionParent>(b => b.HasManyThrough<ScalarJunctionChild, ScalarJunctionLink, int, int>(
            p => p.Children, p => p.Id, l => l.ParentId, c => c.Id, l => l.ChildId));
        ctx.From<ScalarJunctionChild>();

        // The rejection is specific to a composite junction key: a scalar junction still builds its
        // derived row_number() SQL link source.
        Action act = () => ctx.From<ScalarJunctionParent>()
            .JoinInto(ctx.From<ScalarJunctionChild>(), (p, c) => true, p => p.Children);

        act.Should().NotThrow("the scalar junction link source is not rejected");
    }

    [Fact]
    public void CompositeJunctionWhoseForeignKeysDoNotCoverEveryKeyComponent_ShouldThrowDeterministically()
    {
        // AC01 negative: a composite relationship whose junction foreign key covers fewer components than
        // the announced key must fail closed at declaration with the deterministic coverage message,
        // never degrade into a partial-key join. The relationship announces a two-component principal key
        // (the same member twice is a valid multi-component stand-in) while the junction parent FK has one.
        var parentProps = Props<CompositeJunctionParent>();
        var childProps = Props<CompositeJunctionChild>();
        var linkProps = Props<CompositeJunctionLink>();
        var parentKey = Prop(parentProps, nameof(CompositeJunctionParent.Id)).PropertyInfo;
        var childKey = Prop(childProps, nameof(CompositeJunctionChild.Id)).PropertyInfo;
        var navigation = typeof(CompositeJunctionParent).GetProperty(nameof(CompositeJunctionParent.Children));

        DataContextCache.Metadata[typeof(CompositeJunctionParent)] = new EntityMetadata(
            typeof(CompositeJunctionParent).Name,
            parentProps.Where(p => p.PropertyInfo != navigation).ToList(),
            relationships:
            [
                new RelationshipMetadata(
                    RelationshipKind.ManyToMany,
                    typeof(CompositeJunctionParent),
                    typeof(CompositeJunctionChild),
                    navigation,
                    isCollection: true,
                    childKey,
                    parentKey,
                    typeof(CompositeJunctionChild),
                    typeof(CompositeJunctionParent),
                    new RelationshipJunctionDeclaration
                    {
                        JunctionType = typeof(CompositeJunctionLink),
                        ParentKey = [parentKey, parentKey],
                        ChildKey = [childKey],
                        JunctionParentForeignKey = [Prop(linkProps, nameof(CompositeJunctionLink.ParentId)).PropertyInfo],
                        JunctionChildForeignKey = [Prop(linkProps, nameof(CompositeJunctionLink.ChildId)).PropertyInfo],
                    }),
            ]);

        using var ctx = new TrackingContext();

        Action act = () => ctx.From<CompositeJunctionParent>()
            .JoinInto(ctx.From<CompositeJunctionChild>(), (p, c) => true, p => p.Children);

        act.Should().Throw<NotSupportedException>()
            .WithMessage("*do not cover every composite key component*");
        ctx.ConnectionsRequested.Should().Be(0, "a malformed junction key is rejected at declaration; no SQL is executed");
    }

    // ---------------------------------------------------------------------------------------------
    // Provider-free SQL context: a connection request is the observable proof that SQL would execute.
    // ---------------------------------------------------------------------------------------------

    private sealed class TrackingContext : DataContext
    {
        public TrackingContext() : base(new DataContextBuilder())
        {
        }

        public int ConnectionsRequested { get; private set; }

        public override ISqlDialect Dialect => TestDialect.Instance;

        public override DbParameter CreateParam(string name, object? value) => new TrackingParameter(name) { Value = value };

        protected override DbConnection CreateDbConnection(string? connectionString)
        {
            ConnectionsRequested++;
            throw new NotSupportedException("no SQL must be executed for a rejected composite-junction M:N JoinInto");
        }
    }

    private sealed class TestDialect : SqlDialectBase
    {
        internal static readonly TestDialect Instance = new();

        public override string MakeParam(string name) => "@" + name;

        public override bool SupportsRawSqlSource => true;

        public override void MakePage(Paging paging, StringBuilder sqlBuilder, KeywordCase keywordCase = KeywordCase.Lower)
        {
        }
    }

    private sealed class TrackingParameter(string name) : DbParameter
    {
        public override DbType DbType { get; set; }

        public override ParameterDirection Direction { get; set; }

        public override bool IsNullable { get; set; }

        [AllowNull]
        public override string ParameterName { get; set; } = name;

        public override int Size { get; set; }

        [AllowNull]
        public override string SourceColumn { get; set; } = string.Empty;

        public override bool SourceColumnNullMapping { get; set; }

        public override object? Value { get; set; }

        public override void ResetDbType()
        {
        }
    }
}

using System.Reflection;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// D07 (r=5) composite-key NULL / absent-child semantics (#213, variant-closure row
/// "default/nullable values"). A composite relationship key whose component is <c>null</c> is matched
/// in memory (<see cref="JoinIntoKey"/> compares the boxed components with <c>null == null</c>), and a
/// LEFT join with no matching child leaves the one-to-one reference <c>null</c> and the collection
/// empty — never a default-substituted child.
/// <para>
/// Known limitation (documented deliberately, not silently left uncovered): SQL evaluates
/// <c>NULL = NULL</c> as <c>false</c>, so the same composite key with a NULL component would <b>not</b>
/// match a SQL provider. In-memory therefore matches where the SQL path does not; the intent is pinned
/// here and in the provider SQL-generation tests so the divergence is a recorded limitation rather than
/// an unnoticed defect.
/// </para>
/// </summary>
public class JoinIntoCompositeNullSemanticsTests
{
    private static IReadOnlyList<IPropertyMetadata> Props<T>()
        => new EntityMetadataBuilder<T>().Build().Properties;

    private static IPropertyMetadata Prop(IReadOnlyList<IPropertyMetadata> properties, string name)
        => properties.First(p => p.PropertyInfo.Name == name);

    private static void RegisterParent<T>(PropertyInfo? navigation, IRelationshipMetadata relationship)
    {
        var properties = new EntityMetadataBuilder<T>().Build().Properties
            .Where(p => navigation is null || p.PropertyInfo != navigation)
            .ToList();

        DataContextCache.Metadata[typeof(T)] =
            new EntityMetadata(typeof(T).Name, properties, relationships: [relationship]);
    }

    private sealed class InjectedRelationship : IRelationshipMetadata
    {
        public InjectedRelationship(
            RelationshipKind kind,
            Type declaringType,
            Type relatedType,
            PropertyInfo? navigation,
            bool isCollection,
            IReadOnlyList<IPropertyMetadata> foreignKey,
            IReadOnlyList<IPropertyMetadata> principalKey)
        {
            Kind = kind;
            DeclaringType = declaringType;
            RelatedType = relatedType;
            Navigation = navigation;
            IsCollection = isCollection;
            ForeignKey = foreignKey;
            PrincipalKey = principalKey;
        }

        public RelationshipKind Kind { get; }
        public Type DeclaringType { get; }
        public Type RelatedType { get; }
        public PropertyInfo? Navigation { get; }
        public bool IsCollection { get; }
        public IReadOnlyList<IPropertyMetadata> ForeignKey { get; }
        public IReadOnlyList<IPropertyMetadata> PrincipalKey { get; }
        public IRelationshipMetadata? Inverse => null;
    }

    // ---------------------------------------------------------------------------------------------
    // A composite key with a NULL component.
    // ---------------------------------------------------------------------------------------------

    public sealed class NullKeyParent
    {
        public int? TenantId { get; set; }
        public int Id { get; set; }
        public string? Name { get; set; }
        public ICollection<NullKeyChild> Children { get; set; } = new List<NullKeyChild>();
    }

    public sealed class NullKeyChild
    {
        public int Id { get; set; }
        public int? TenantId { get; set; }
        public int ParentId { get; set; }
        public string? Name { get; set; }
    }

    [Fact]
    public void CompositeKey_NullComponent_InMemoryMatchesNullEqualsNull_DivergesFromSql()
    {
        var parentProps = Props<NullKeyParent>();
        var childProps = Props<NullKeyChild>();
        var navigation = typeof(NullKeyParent).GetProperty(nameof(NullKeyParent.Children));
        RegisterParent<NullKeyParent>(navigation, new InjectedRelationship(
            RelationshipKind.OneToMany,
            typeof(NullKeyParent),
            typeof(NullKeyChild),
            navigation,
            isCollection: true,
            foreignKey: [Prop(childProps, nameof(NullKeyChild.TenantId)), Prop(childProps, nameof(NullKeyChild.ParentId))],
            principalKey: [Prop(parentProps, nameof(NullKeyParent.TenantId)), Prop(parentProps, nameof(NullKeyParent.Id))]));

        using var ctx = new InMemoryDataContext();
        ctx.From<NullKeyParent>().WithData([
            new NullKeyParent { TenantId = null, Id = 1, Name = "p" },
        ]);
        ctx.From<NullKeyChild>().WithData([
            // Both components null / equal: in memory null == null is a match.
            new NullKeyChild { TenantId = null, ParentId = 1, Id = 10, Name = "null-match" },
            // A non-null tenant must still be rejected: only the complete composite key matches.
            new NullKeyChild { TenantId = 7, ParentId = 1, Id = 20, Name = "non-null" },
        ]);

        var parents = ctx.From<NullKeyParent>()
            .JoinInto(
                ctx.From<NullKeyChild>(),
                (p, c) => p.TenantId == c.TenantId && p.Id == c.ParentId,
                p => p.Children)
            .ToList();

        parents.Should().ContainSingle();
        // KNOWN LIMITATION: this match is in-memory-only. A SQL provider evaluates NULL = NULL as false,
        // so this row would not be stitched there; the SQL-generation tests document the same divergence.
        parents[0].Children.Select(c => c.Id).Should().Equal(new[] { 10 },
            "in memory a NULL composite component matches NULL (null == null); the SQL path does not");
    }

    // ---------------------------------------------------------------------------------------------
    // An absent LEFT child (all child columns NULL) must be null, never a default-substituted child.
    // ---------------------------------------------------------------------------------------------

    public sealed class AbsentParent
    {
        public int TenantId { get; set; }
        public int Id { get; set; }
        public string? Name { get; set; }
        public AbsentChild? Profile { get; set; }
        public ICollection<AbsentChild> Children { get; set; } = new List<AbsentChild>();
    }

    public sealed class AbsentChild
    {
        public int Id { get; set; }
        public int TenantId { get; set; }
        public int ParentId { get; set; }
        public string? Name { get; set; }
    }

    private static void RegisterAbsentParent(PropertyInfo? navigation, RelationshipKind kind, bool isCollection)
    {
        var parentProps = Props<AbsentParent>();
        var childProps = Props<AbsentChild>();
        RegisterParent<AbsentParent>(navigation, new InjectedRelationship(
            kind,
            typeof(AbsentParent),
            typeof(AbsentChild),
            navigation,
            isCollection,
            foreignKey: [Prop(childProps, nameof(AbsentChild.TenantId)), Prop(childProps, nameof(AbsentChild.ParentId))],
            principalKey: [Prop(parentProps, nameof(AbsentParent.TenantId)), Prop(parentProps, nameof(AbsentParent.Id))]));
    }

    [Fact]
    public void CompositeOneToOne_AbsentLeftChild_ShouldBeNullNotDefault()
    {
        var navigation = typeof(AbsentParent).GetProperty(nameof(AbsentParent.Profile));
        RegisterAbsentParent(navigation, RelationshipKind.OneToOne, isCollection: false);

        using var ctx = new InMemoryDataContext();
        ctx.From<AbsentParent>().WithData([
            new AbsentParent { TenantId = 1, Id = 1, Name = "no-profile" },
        ]);
        // No child rows at all: the LEFT join has nothing to attach.

        var parents = ctx.From<AbsentParent>()
            .JoinInto(
                ctx.From<AbsentChild>(),
                (p, c) => p.TenantId == c.TenantId && p.Id == c.ParentId,
                p => p.Profile)
            .ToList();

        parents.Should().ContainSingle();
        parents[0].Profile.Should().BeNull(
            "an absent LEFT child (all columns NULL) maps to null, not a default child instance");
    }

    [Fact]
    public void CompositeOneToMany_AbsentLeftChild_ShouldBeEmpty()
    {
        var navigation = typeof(AbsentParent).GetProperty(nameof(AbsentParent.Children));
        RegisterAbsentParent(navigation, RelationshipKind.OneToMany, isCollection: true);

        using var ctx = new InMemoryDataContext();
        ctx.From<AbsentParent>().WithData([
            new AbsentParent { TenantId = 1, Id = 1, Name = "no-children" },
        ]);

        var parents = ctx.From<AbsentParent>()
            .JoinInto(
                ctx.From<AbsentChild>(),
                (p, c) => p.TenantId == c.TenantId && p.Id == c.ParentId,
                p => p.Children)
            .ToList();

        parents.Should().ContainSingle();
        parents[0].Children.Should().BeEmpty("an absent LEFT child contributes no element");
    }
}

using System.Reflection;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// D01 (#213) red regressions and scalar controls for the JoinInto remainder: composite 1:N / 1:1 keys
/// (declared/local relationship metadata), composite junction many-to-many, and a many-to-many
/// declaration composed into the SingleQuery dispatcher. The composite / M:N-under-SingleQuery cases are
/// the RED regressions for the still-unsupported shapes (they must throw against the unmodified build);
/// the scalar cases are controls that already pass and must keep passing.
/// </summary>
public class JoinIntoCompositeRemainderTests
{
    public JoinIntoCompositeRemainderTests()
    {
        DataContextCache.Clear();
    }

    private static IReadOnlyList<IPropertyMetadata> Props<T>()
        => new EntityMetadataBuilder<T>().Build().Properties;

    private static IPropertyMetadata Prop(IReadOnlyList<IPropertyMetadata> properties, string name)
        => properties.First(p => p.PropertyInfo.Name == name);

    /// <summary>
    /// Publishes a metadata entry for <typeparamref name="T"/> that carries the injected relationship and
    /// excludes the navigation property from the mapped columns (the declared-relationship builder would
    /// have done that, but the composite key cannot be expressed through the fluent surface).
    /// </summary>
    private static void RegisterParent<T>(PropertyInfo? navigation, IRelationshipMetadata relationship)
    {
        var properties = new EntityMetadataBuilder<T>().Build().Properties
            .Where(p => navigation is null || p.PropertyInfo != navigation)
            .ToList();

        DataContextCache.Metadata[typeof(T)] =
            new EntityMetadata(typeof(T).Name, properties, relationships: [relationship]);
    }

    /// <summary>
    /// A relationship whose foreign/principal keys are supplied as explicit lists, so a composite key can
    /// be injected without the (single-column only) fluent declaration surface.
    /// </summary>
    private sealed class InjectedRelationship : IRelationshipMetadata
    {
        public InjectedRelationship(
            RelationshipKind kind,
            Type declaringType,
            Type relatedType,
            PropertyInfo? navigation,
            bool isCollection,
            IReadOnlyList<IPropertyMetadata> foreignKey,
            IReadOnlyList<IPropertyMetadata> principalKey)
        {
            Kind = kind;
            DeclaringType = declaringType;
            RelatedType = relatedType;
            Navigation = navigation;
            IsCollection = isCollection;
            ForeignKey = foreignKey;
            PrincipalKey = principalKey;
        }

        public RelationshipKind Kind { get; }
        public Type DeclaringType { get; }
        public Type RelatedType { get; }
        public PropertyInfo? Navigation { get; }
        public bool IsCollection { get; }
        public IReadOnlyList<IPropertyMetadata> ForeignKey { get; }
        public IReadOnlyList<IPropertyMetadata> PrincipalKey { get; }
        public IRelationshipMetadata? Inverse => null;
    }

    // ---------------------------------------------------------------------------------------------
    // RED regressions: composite parent/child keys announced as supported but not yet assembled.
    // ---------------------------------------------------------------------------------------------

    public sealed class CompositeOneToManyParent
    {
        public int TenantId { get; set; }
        public int Id { get; set; }
        public string? Name { get; set; }
        public ICollection<CompositeOneToManyChild> Children { get; set; } = new List<CompositeOneToManyChild>();
    }

    public sealed class CompositeOneToManyChild
    {
        public int TenantId { get; set; }
        public int ParentId { get; set; }
        public int Id { get; set; }
        public string? Name { get; set; }
    }

    [Fact]
    public void CompositeOneToMany_ShouldGroupChildrenByFullKey()
    {
        var parentProps = Props<CompositeOneToManyParent>();
        var childProps = Props<CompositeOneToManyChild>();
        var navigation = typeof(CompositeOneToManyParent).GetProperty(nameof(CompositeOneToManyParent.Children));
        RegisterParent<CompositeOneToManyParent>(navigation, new InjectedRelationship(
            RelationshipKind.OneToMany,
            typeof(CompositeOneToManyParent),
            typeof(CompositeOneToManyChild),
            navigation,
            isCollection: true,
            foreignKey: [Prop(childProps, nameof(CompositeOneToManyChild.TenantId)), Prop(childProps, nameof(CompositeOneToManyChild.ParentId))],
            principalKey: [Prop(parentProps, nameof(CompositeOneToManyParent.TenantId)), Prop(parentProps, nameof(CompositeOneToManyParent.Id))]));

        using var ctx = new InMemoryDataContext();
        ctx.From<CompositeOneToManyParent>().WithData([
            new CompositeOneToManyParent { TenantId = 1, Id = 1, Name = "p" },
        ]);
        ctx.From<CompositeOneToManyChild>().WithData([
            new CompositeOneToManyChild { TenantId = 1, ParentId = 1, Id = 10, Name = "match" },
            // Same parent id but a different tenant: the full composite key must reject the cross row.
            new CompositeOneToManyChild { TenantId = 2, ParentId = 1, Id = 20, Name = "cross" },
        ]);

        var parents = ctx.From<CompositeOneToManyParent>()
            .JoinInto(
                ctx.From<CompositeOneToManyChild>(),
                (p, c) => p.TenantId == c.TenantId && p.Id == c.ParentId,
                p => p.Children)
            .ToList();

        parents.Should().ContainSingle();
        parents[0].Children.Select(c => c.Id).Should().Equal(new[] { 10 }, "only the full composite-key match is grouped");
    }

    public sealed class CompositeOneToOneParent
    {
        public int TenantId { get; set; }
        public int Id { get; set; }
        public CompositeOneToOneChild? Profile { get; set; }
    }

    public sealed class CompositeOneToOneChild
    {
        public int TenantId { get; set; }
        public int ParentId { get; set; }
        public int Id { get; set; }
    }

    [Fact]
    public void CompositeOneToOne_ShouldAssignByFullKey()
    {
        var parentProps = Props<CompositeOneToOneParent>();
        var childProps = Props<CompositeOneToOneChild>();
        var navigation = typeof(CompositeOneToOneParent).GetProperty(nameof(CompositeOneToOneParent.Profile));
        RegisterParent<CompositeOneToOneParent>(navigation, new InjectedRelationship(
            RelationshipKind.OneToOne,
            typeof(CompositeOneToOneParent),
            typeof(CompositeOneToOneChild),
            navigation,
            isCollection: false,
            foreignKey: [Prop(childProps, nameof(CompositeOneToOneChild.TenantId)), Prop(childProps, nameof(CompositeOneToOneChild.ParentId))],
            principalKey: [Prop(parentProps, nameof(CompositeOneToOneParent.TenantId)), Prop(parentProps, nameof(CompositeOneToOneParent.Id))]));

        using var ctx = new InMemoryDataContext();
        ctx.From<CompositeOneToOneParent>().WithData([
            new CompositeOneToOneParent { TenantId = 1, Id = 1 },
        ]);
        ctx.From<CompositeOneToOneChild>().WithData([
            new CompositeOneToOneChild { TenantId = 1, ParentId = 1, Id = 50 },
            new CompositeOneToOneChild { TenantId = 2, ParentId = 1, Id = 60 },
        ]);

        var parents = ctx.From<CompositeOneToOneParent>()
            .JoinInto(
                ctx.From<CompositeOneToOneChild>(),
                (p, c) => p.TenantId == c.TenantId && p.Id == c.ParentId,
                p => p.Profile)
            .ToList();

        parents.Should().ContainSingle();
        parents[0].Profile.Should().NotBeNull();
        parents[0].Profile!.Id.Should().Be(50, "the full composite key selects the matching reference");
    }

    public sealed class CompositeJunctionParent
    {
        public int Id { get; set; }
        public ICollection<CompositeJunctionChild> Children { get; set; } = new List<CompositeJunctionChild>();
    }

    public sealed class CompositeJunctionChild
    {
        public int Id { get; set; }
    }

    public sealed class CompositeJunctionLink
    {
        public int ParentId { get; set; }
        public int ParentId2 { get; set; }
        public int ChildId { get; set; }
    }

    [Fact]
    public void CompositeJunctionManyToMany_ShouldStitchByFullJunctionKey()
    {
        var parentProps = Props<CompositeJunctionParent>();
        var childProps = Props<CompositeJunctionChild>();
        var linkProps = Props<CompositeJunctionLink>();
        var parentKey = Prop(parentProps, nameof(CompositeJunctionParent.Id)).PropertyInfo;
        var childKey = Prop(childProps, nameof(CompositeJunctionChild.Id)).PropertyInfo;
        var navigation = typeof(CompositeJunctionParent).GetProperty(nameof(CompositeJunctionParent.Children));

        DataContextCache.Metadata[typeof(CompositeJunctionParent)] = new EntityMetadata(
            typeof(CompositeJunctionParent).Name,
            parentProps.Where(p => p.PropertyInfo != navigation).ToList(),
            relationships:
            [
                new RelationshipMetadata(
                    RelationshipKind.ManyToMany,
                    typeof(CompositeJunctionParent),
                    typeof(CompositeJunctionChild),
                    navigation,
                    isCollection: true,
                    childKey,
                    parentKey,
                    typeof(CompositeJunctionChild),
                    typeof(CompositeJunctionParent),
                    new RelationshipJunctionDeclaration
                    {
                        JunctionType = typeof(CompositeJunctionLink),
                        ParentKey = [parentKey],
                        ChildKey = [childKey],
                        JunctionParentForeignKey = [Prop(linkProps, nameof(CompositeJunctionLink.ParentId)).PropertyInfo, Prop(linkProps, nameof(CompositeJunctionLink.ParentId2)).PropertyInfo],
                        JunctionChildForeignKey = [Prop(linkProps, nameof(CompositeJunctionLink.ChildId)).PropertyInfo],
                    }),
            ]);

        using var ctx = new InMemoryDataContext();
        ctx.From<CompositeJunctionParent>().WithData([new CompositeJunctionParent { Id = 1 }]);
        ctx.From<CompositeJunctionChild>().WithData([new CompositeJunctionChild { Id = 10 }]);
        ctx.From<CompositeJunctionLink>().WithData([new CompositeJunctionLink { ParentId = 1, ParentId2 = 7, ChildId = 10 }]);

        var parents = ctx.From<CompositeJunctionParent>()
            .JoinInto(ctx.From<CompositeJunctionChild>(), (p, c) => true, p => p.Children)
            .ToList();

        parents.Should().ContainSingle();
        parents[0].Children.Select(c => c.Id).Should().Equal(10);
    }

    public sealed class SingleQueryRemainderParent
    {
        public int Id { get; set; }
        public string? Name { get; set; }
        public ICollection<SingleQueryRemainderChild> Children { get; set; } = new List<SingleQueryRemainderChild>();
        public ICollection<SingleQueryRemainderNote> Notes { get; set; } = new List<SingleQueryRemainderNote>();
