using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// Coverage for the single-query (<c>EagerLoadMode.SingleQuery</c>) interaction with a many-to-many <c>JoinInto</c>
/// (#135, #213): the many-to-many declaration is composed into the single-query pairing (a link edge followed by a
/// child edge), a plain <c>JoinInto</c> combined with a single-query <c>LoadWith</c> exercises the pairing path, and an
/// explicit junction mapping drops the column names resolved against the auto-published one.
/// </summary>
public class JoinIntoManyToManySingleQueryTests
{
    public JoinIntoManyToManySingleQueryTests()
    {
        DataContextCache.Clear();
    }

    [Fact]
    public void ManyToManyJoinInto_WithLoadWithAndSingleQuery_ShouldStitchBothCollections()
    {
        // #213: a many-to-many declaration contributes a link edge plus a child edge; the single-query
        // pairing consumes both and stitches the many-to-many collection alongside the LoadWith one.
        using var ctx = new InMemoryDataContext();
        ctx.From<SingleQueryMixedParent>(b => b
                .HasManyThrough<SingleQueryMixedChild, ManyToManyJoinLink, int, int>(
                    p => p.Children, p => p.Id, l => l.ParentId, c => c.Id, l => l.ChildId)
                .HasMany(p => p.Notes, n => n.ParentId))
            .WithData([new SingleQueryMixedParent { Id = 1, Name = "p1" }]);
        ctx.From<SingleQueryMixedChild>().WithData([new SingleQueryMixedChild { Id = 10, Name = "c" }]);
        ctx.From<ManyToManyJoinLink>().WithData([new ManyToManyJoinLink { ParentId = 1, ChildId = 10 }]);
        ctx.From<SingleQueryMixedNote>().WithData([new SingleQueryMixedNote { Id = 20, ParentId = 1, Text = "n" }]);

        var parents = ctx.From<SingleQueryMixedParent>()
            .JoinInto(ctx.From<SingleQueryMixedChild>(), (p, c) => true, p => p.Children)
            .LoadWith(p => p.Notes, n => n.From<SingleQueryMixedNote>(), p => p.Id, n => n.ParentId, EagerLoadMode.SingleQuery)
            .ToList();

        parents.Should().ContainSingle();
        parents[0].Children.Select(c => c.Id).Should().Equal(10);
        parents[0].Notes.Select(n => n.Id).Should().Equal(20);
    }

    public sealed class SingleQueryMixedParent
    {
        public int Id { get; set; }
        public string? Name { get; set; }
        public ICollection<SingleQueryMixedChild> Children { get; set; } = new List<SingleQueryMixedChild>();
        public ICollection<SingleQueryMixedNote> Notes { get; set; } = new List<SingleQueryMixedNote>();
    }

    public sealed class SingleQueryMixedChild
    {
        public int Id { get; set; }
        public int ParentId { get; set; }
        public string? Name { get; set; }
    }

    public sealed class SingleQueryMixedNote
    {
        public int Id { get; set; }
        public int ParentId { get; set; }
        public string? Text { get; set; }
    }

    [Fact]
    public void PlainJoinInto_WithLoadWithAndSingleQuery_ShouldStitchBothCollections()
    {
        using var ctx = new InMemoryDataContext();
        ctx.From<SingleQueryMixedParent>(b => b
                .HasMany(p => p.Children, c => c.ParentId))
            .WithData([new SingleQueryMixedParent { Id = 1, Name = "p1" }]);
        ctx.From<SingleQueryMixedChild>().WithData([new SingleQueryMixedChild { Id = 10, ParentId = 1, Name = "c" }]);
        ctx.From<SingleQueryMixedNote>().WithData([new SingleQueryMixedNote { Id = 20, ParentId = 1, Text = "n" }]);

        // The pre-existing JoinInto declaration and the LoadWith declaration are paired in order: the
        // one-to-one-slot declaration consumes the child edge that carries its child filter scope. The
        // child ignores every filter so the non-empty scope branch of the pairing is exercised.
        var parents = ctx.From<SingleQueryMixedParent>()
            .JoinInto(ctx.From<SingleQueryMixedChild>().IgnoreFilters(), (p, c) => p.Id == c.ParentId, p => p.Children)
            .LoadWith(p => p.Notes, n => n.From<SingleQueryMixedNote>(), p => p.Id, n => n.ParentId, EagerLoadMode.SingleQuery)
            .ToList();

        parents.Should().ContainSingle();
        parents[0].Children.Select(c => c.Id).Should().Equal(10);
        parents[0].Notes.Select(n => n.Id).Should().Equal(20);
    }

    [Fact]
    public void ConfiguredJunctionOverride_ShouldEvictAutoPublishedColumnNames()
    {
        // The junction is deliberately not registered explicitly, so declaring the many-to-many JoinInto
        // reaches the auto-resolution path and marks the junction as auto-published.
        using var ctx = new InMemoryDataContext();
        ctx.From<ManyToManyJoinParent>(b => b
            .HasManyThrough<ManyToManyJoinChild, ManyToManyJoinLink, int, int>(
                p => p.Children, p => p.Id, l => l.ParentId, c => c.Id, l => l.ChildId));
        ctx.From<ManyToManyJoinChild>();

        // Declaring the many-to-many JoinInto auto-publishes the junction mapping so the derived link
        // source can read it.
        _ = ctx.From<ManyToManyJoinParent>()
            .JoinInto(ctx.From<ManyToManyJoinChild>(), (p, c) => true, p => p.Children);

        DataContextCache.AutoPublishedJunctionMetadata.Should().ContainKey(typeof(ManyToManyJoinLink),
            "the many-to-many declaration auto-published the junction mapping");

        // Seed the process-wide per-property column-name cache for the junction, as the SQL build would.
        typeof(ManyToManyJoinLink).GetProperty(nameof(ManyToManyJoinLink.ParentId))!
            .GetPropertyColumnName()
            .Should().NotBeNullOrEmpty();

        // Configuring the junction explicitly must win over the auto-published mapping and drop the
        // column names resolved against it, hitting the per-entity ClearColumnNames eviction loop.
        ctx.From<ManyToManyJoinLink>(_ => { });

        DataContextCache.AutoPublishedJunctionMetadata.Should().NotContainKey(typeof(ManyToManyJoinLink));
        typeof(ManyToManyJoinLink).GetProperty(nameof(ManyToManyJoinLink.ParentId))!
            .GetPropertyColumnName()
            .Should().NotBeNullOrEmpty("the configured mapping resolves the column again");
    }
}

using FluentAssertions;

namespace NextORM.Core.Tests;

/// <summary>
/// In-memory tests for the one-to-one <c>JoinInto</c> overload (#135 slice A): a single child reference
/// is assigned per parent, LEFT leaves the reference null, INNER excludes the childless parent, a parent
/// matching more than one distinct child throws at materialization, and cartesian repeats of one child
/// caused by a neighbouring join are tolerated.
/// </summary>
public class JoinIntoOneToOneTests
{
    private static readonly Guid Gp1 = new("11111111-1111-1111-1111-111111111111");
    private static readonly Guid Gp2 = new("22222222-2222-2222-2222-222222222222");
    private static readonly Guid Gp3 = new("33333333-3333-3333-3333-333333333333");
    private static readonly Guid Gc1 = new("aaaaaaaa-0000-0000-0000-000000000001");
    private static readonly Guid Gc2 = new("aaaaaaaa-0000-0000-0000-000000000002");
    private static readonly Guid Gc3 = new("aaaaaaaa-0000-0000-0000-000000000003");
    private static readonly Guid Gc4 = new("aaaaaaaa-0000-0000-0000-000000000004");

    private static InMemoryDataContext CreateContext()
    {
        var ctx = new InMemoryDataContext();
        ctx.From<OneToOneJoinParent>(b => b
                .HasOneToOne(p => p.Primary, p => p.Id, c => c.ParentId)
                .HasMany(p => p.Notes, n => n.ParentId))
            .WithData([
                new OneToOneJoinParent { Id = 1, Name = "p1" },
                new OneToOneJoinParent { Id = 2, Name = "p2" },
                new OneToOneJoinParent { Id = 3, Name = "p3" },
            ]);
        ctx.From<OneToOneJoinChild>().WithData([
            new OneToOneJoinChild { Id = 10, ParentId = 1, Name = "c1" },
            new OneToOneJoinChild { Id = 11, ParentId = 3, Name = "c2" },
            new OneToOneJoinChild { Id = 12, ParentId = 3, Name = "c3" },
        ]);
        ctx.From<OneToOneJoinNote>().WithData([
            new OneToOneJoinNote { Id = 100, ParentId = 1, Text = "n1" },
            new OneToOneJoinNote { Id = 101, ParentId = 1, Text = "n2" },
        ]);

        return ctx;
    }

    [Fact]
    public void LeftJoinInto_ShouldAssignTheChildOrLeaveTheReferenceNull()
    {
        // case PS / R170-03: one-child LEFT positive — assert child identity and payload, not a bare count.
        using var ctx = CreateContext();

        var parents = ctx.From<OneToOneJoinParent>()
            .Where(p => p.Id == 1 || p.Id == 2)
            .JoinInto(ctx.From<OneToOneJoinChild>(), (p, c) => p.Id == c.ParentId, p => p.Primary)
            .OrderBy(p => p.Id)
            .ToList();

        parents.Select(p => p.Id).Should().Equal(1, 2);
        parents[0].Primary!.Id.Should().Be(10, "the matching child is assigned to the single reference");
        parents[0].Primary!.Name.Should().Be("c1", "the assigned child carries its own payload, not a bare count");
        parents[1].Primary.Should().BeNull("a LEFT join without a matching child leaves the reference null");
    }

    [Fact]
    public void InnerJoinInto_ShouldExcludeTheChildlessParent()
    {
        // case PS / R170-03: one-child INNER positive — excludes the childless parent, keeps identity+payload.
        using var ctx = CreateContext();

        var parents = ctx.From<OneToOneJoinParent>()
            .Where(p => p.Id == 1 || p.Id == 2)
            .JoinInto(ctx.From<OneToOneJoinChild>(), (p, c) => p.Id == c.ParentId, p => p.Primary, JoinType.Inner)
            .ToList();

        parents.Select(p => p.Id).Should().Equal(1);
        parents[0].Primary!.Id.Should().Be(10);
        parents[0].Primary!.Name.Should().Be("c1", "the INNER join assigns the one matching child with its payload");
    }

    [Fact]
    public void MoreThanOneDistinctChild_ShouldThrowAtMaterialization()
    {
        // case DS / R170-03: two distinct non-null child identities for one parent -> throw at materialization.
        using var ctx = CreateContext();

        Action act = () => ctx.From<OneToOneJoinParent>()
            .Where(p => p.Id == 3)
            .JoinInto(ctx.From<OneToOneJoinChild>(), (p, c) => p.Id == c.ParentId, p => p.Primary)
            .ToList();

        act.Should().Throw<InvalidOperationException>()
            .WithMessage("*more than one distinct*");
    }

    [Fact]
    public void CartesianRepeatOfTheSameChild_ShouldNotThrowAndShouldAssignOnce()
    {
        // case RS / R170-03: the same child identity repeated by a neighbouring join is tolerated (one assignment).
        using var ctx = CreateContext();

        var parents = ctx.From<OneToOneJoinParent>()
            .Where(p => p.Id == 1)
            .JoinInto(ctx.From<OneToOneJoinChild>(), (p, c) => p.Id == c.ParentId, p => p.Primary)
            .JoinInto(ctx.From<OneToOneJoinNote>(), (p, n) => p.Id == n.ParentId, p => p.Notes)
            .ToList();

        parents.Should().ContainSingle();
        parents[0].Primary!.Id.Should().Be(10, "the repeated child rows collapse to the one source occurrence");
        parents[0].Notes.Select(n => n.Id).Should().Equal(100, 101);
    }

