        var record = new FakeRecord([1, null, "json"], [typeof(int), typeof(string), typeof(string)]);

        Write(BuildWriter(shape), record).Should().Be("[{\"Id\":1,\"Child\":{\"Name\":null}}]");
    }

    [Fact]
    public void ConditionalConstruction_AbsentSentinelWithPresentMembers_ShouldWriteNull()
    {
        // The sentinel is SQL NULL (null arm) while the visible leaves carry values; presence must not be
        // inferred from the payload, so the object is null.
        var shape = Obj(null,
            [
                Scalar("Id", typeof(int), 0, false),
                Obj("Child", [Scalar("Name", typeof(string), 1, true)], JsonShapePresence.AnyColumnNotNull([2])),
            ],
            JsonShapePresence.Always);
        var record = new FakeRecord([1, "ignored", null], [typeof(int), typeof(string), typeof(string)]);

        Write(BuildWriter(shape), record).Should().Be("[{\"Id\":1,\"Child\":null}]");
    }

    // --- CHECK r2-n2 loopback: W2 provider array DBNull element, T5 boundary edges. ---

    [Fact]
    public void DBNullElementInsideArray_ShouldWriteNull()
    {
        // Some drivers surface a SQL NULL array element as boxed DBNull.Value rather than CLR null; the
        // recursive array writer must treat both as JSON null instead of failing the element cast.
        var shape = Obj(null, [Arr("Names", typeof(string[]), 0, true)], JsonShapePresence.Always);
        var record = new FakeRecord([new object?[] { "a", DBNull.Value, null }], [typeof(string[])]);

        Write(BuildWriter(shape), record).Should().Be("[{\"Names\":[\"a\",null,null]}]");
    }

    [Fact]
    public void DepthExactly64_ShouldBeAllowed()
    {
        JsonShapeNode node = Scalar("Leaf", typeof(int), 0, false);
        for (var i = 0; i < 65; i++)
            node = Obj(i == 64 ? null : $"Level{i}", [node], JsonShapePresence.Always);

        // The root is depth 0 and the innermost object is depth 64, which is the allowed maximum.
        Write(BuildWriter(node), new FakeRecord([7], [typeof(int)])).Should().Contain("\"Leaf\":7");
    }

    [Fact]
    public void Depth65_ShouldThrowBeforeWriting()
    {
        JsonShapeNode node = Scalar("Leaf", typeof(int), 0, false);
        for (var i = 0; i < 66; i++)
            node = Obj(i == 65 ? null : $"Level{i}", [node], JsonShapePresence.Always);

        var act = () => BuildWriter(node);

        act.Should().Throw<NotSupportedException>();
    }

    [Fact]
    public void ZeroMemberObject_ShouldWriteEmptyObject()
    {
        // A member-less nested object is a valid writer shape as long as the enclosing projection still
        // lowers at least one scalar column (a zero-column root is rejected at plan build).
        var shape = Obj(null,
            [
                Scalar("Id", typeof(int), 0, false),
                Obj("Empty", [], JsonShapePresence.Always),
            ],
            JsonShapePresence.Always);

        Write(BuildWriter(shape), new FakeRecord([7], [typeof(int)])).Should().Be("[{\"Id\":7,\"Empty\":{}}]");
    }

    [Fact]
    public void NoSelectedColumns_ShouldThrowProjectionBeforeWriting()
    {
        // W2 (r2/n2): the phase-1 flat path (shape == null) with no selected columns. No public query
        // surface lowers a zero-column projection: EntityBuilder.ToCommand applies the entity projection,
        // and the historical trigger was a construction projection aborted by cancellation during
        // PrepareColumns, which PrepareJsonStream now short-circuits with ThrowIfCancellationRequested.
        // The reachable trigger is therefore this internal entry point — the exact method
        // PrepareJsonStream calls with cmd.SelectList — so the branch is exercised directly, not faked.
        var nullList = () => JsonShapePlan.Build(null, oneColumn: false, new JsonStreamOptions());
        nullList.Should().Throw<NotSupportedException>().WithMessage("*JSON streaming validation [projection]*");

        var emptyList = () => JsonShapePlan.Build([], oneColumn: false, new JsonStreamOptions());
        emptyList.Should().Throw<NotSupportedException>().WithMessage("*JSON streaming validation [projection]*");
    }

    [Fact]
    public void OneElementArray_ShouldWriteSingleElement()
    {
        var shape = Obj(null, [Arr("Values", typeof(int[]), 0, true)], JsonShapePresence.Always);
        var record = new FakeRecord([new[] { 42 }], [typeof(int[])]);

        Write(BuildWriter(shape), record).Should().Be("[{\"Values\":[42]}]");
    }

    [Fact]
    public void ReaderFailure_MidRead_ShouldPropagate()
    {
        var shape = Obj(null, [Scalar("Id", typeof(int), 0, false)], JsonShapePresence.Always);
        var record = new FakeRecord([1], [typeof(int)], throwOnOrdinal: 0);

        var act = () => Write(BuildWriter(shape), record);

        act.Should().Throw<InvalidOperationException>().WithMessage("reader failed mid-read");
    }

    // --- T208 (PDCA=T208): a projected SqlFunctions.Parameter<T> is a non-TableAlias/TableColumn
    // method call, so the shape plan must admit it as a direct pass-through number scalar and the
    // managed writer must emit its value under the exact projected member name (the native FOR JSON
    // eligibility depends on that name being a simple alias). ---

    [Fact]
    public void ProjectedParameter_ShouldStreamValueUnderMemberName()
    {
        var call = Expression.Call(
            typeof(SqlFunctions).GetMethod(nameof(SqlFunctions.Parameter))!.MakeGenericMethod(typeof(int)),
            Expression.Constant(0));
        var column = new SelectExpression(typeof(int)) { Index = 0, PropertyName = "Param", Expression = call };

        var plan = JsonShapePlan.Build([column], oneColumn: false, new JsonStreamOptions());

        plan.Columns[0].Name.Should().Be("Param");
        plan.Columns[0].Kind.Should().Be(JsonWriteKind.Number);
        plan.Columns[0].ValueType.Should().Be(typeof(int));
        plan.Columns[0].IsDirectPassThrough.Should().BeTrue(
            "a projected Parameter<T> is a non-TableAlias/TableColumn method call admitted as a direct pass-through");

        Write(JsonRowWriterFactory.Build(plan), new FakeRecord([42], [typeof(int)]))
            .Should().Be("[{\"Param\":42}]");
    }

    private static SelectExpression ProjectedParameterColumn(int index, string name, Type parameterType)
    {
        var call = Expression.Call(
            typeof(SqlFunctions).GetMethod(nameof(SqlFunctions.Parameter))!.MakeGenericMethod(parameterType),
            Expression.Constant(index));
        return new SelectExpression(parameterType) { Index = index, PropertyName = name, Expression = call };
    }

    // T208 (PDCA=T208) row 2: a projected SqlFunctions.Parameter<T> inside a recursive (nested/grouped)
    // shape is never served by the database FOR JSON transport -- the recursive writer reconstructs the
    // shape with managed presence/alias logic -- and the managed writer emits its value under the exact
    // member names. This is the "test + guard" closure for the array/root/nested/grouped shape row.
    [Fact]
    public void ProjectedParameter_InsideNestedAndArrayShape_ShouldRejectNativeAndStreamManaged()
    {
        var columns = new[]
        {
            ProjectedParameterColumn(0, "Param", typeof(int)),
            ProjectedParameterColumn(1, "Values", typeof(int[])),
        };

        var shape = Obj(null,
        [
            Scalar("Param", typeof(int), 0, nullable: false),
            Obj("Child", [Scalar("Param", typeof(int), 0, nullable: false)], JsonShapePresence.Always),
            Arr("Values", typeof(int[]), 1, nullable: true),
        ], JsonShapePresence.Always);

        var plan = JsonShapePlan.Build(columns, oneColumn: false, new JsonStreamOptions(), shape);

        plan.Shape.Should().NotBeNull("a captured recursive shape is not a flat phase-1 plan");
        JsonNativeStream.IsEligible(plan, plan.Options).Should().BeFalse(
            "a recursive shape must be reconstructed by the managed writer, never by the database FOR JSON transport");

        Write(JsonRowWriterFactory.Build(plan), new FakeRecord([42, new[] { 1, 2, 3 }], [typeof(int), typeof(int[])]))
            .Should().Be("[{\"Param\":42,\"Child\":{\"Param\":42},\"Values\":[1,2,3]}]");
    }

    // T208 (PDCA=T208) row 2 (root shape): a projected Parameter<int[]> inside a root array shape has no
    // FOR JSON object mapping, so native is rejected and the managed recursive writer handles it.
    [Fact]
    public void ProjectedParameter_RootArrayShape_ShouldRejectNativeAndStreamManaged()
    {
        var columns = new[] { ProjectedParameterColumn(0, "Values", typeof(int[])) };
        var shape = Arr(null, typeof(int[]), 0, nullable: true);

        var plan = JsonShapePlan.Build(columns, oneColumn: false, new JsonStreamOptions(), shape);

        plan.Shape.Should().NotBeNull();
        JsonNativeStream.IsEligible(plan, plan.Options).Should().BeFalse(
            "a root array shape has no FOR JSON object mapping and stays managed");
        Write(JsonRowWriterFactory.Build(plan), new FakeRecord([new[] { 7, 8 }], [typeof(int[])]))
            .Should().Be("[[7,8]]");
    }
}

using System.Data;
using System.Text;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// D179 managed-seam fault coverage for the internal JSON stream writer: the writer owns the container
/// framing and flushes each row into a caller-owned destination. These tests drive it with a controlled
/// <see cref="IDataRecord"/> and a recording/throwing destination to pin the route-independent, fail-stop
/// policy — the original error propagates, no recovery/rollback tail is written, the destination stays
/// open and the library never adds a <c>Stream.Flush</c>. The public SQLite-terminal cells live in
/// <c>JsonStreamingTests</c> and the SQL Server native cells in <c>JsonNativeStreamTests</c>.
/// </summary>
public class JsonStreamWriterTests
{
    private sealed class FakeRecord : IDataRecord
    {
        private readonly object?[] _values;
        private readonly Type[] _types;
        private readonly int _throwOnOrdinal;

        public FakeRecord(object?[] values, Type[] types, int throwOnOrdinal = -1)
        {
            _values = values;
            _types = types;
            _throwOnOrdinal = throwOnOrdinal;
        }

        public int FieldCount => _values.Length;
        public object this[int i] => GetValue(i);
        public object this[string name] => throw new NotSupportedException();

        public bool GetBoolean(int i) => (bool)_values[i]!;
        public byte GetByte(int i) => (byte)_values[i]!;
        public long GetBytes(int i, long fieldOffset, byte[]? buffer, int bufferoffset, int length) => throw new NotSupportedException();
        public char GetChar(int i) => throw new NotSupportedException();
        public long GetChars(int i, long fieldoffset, char[]? buffer, int bufferoffset, int length) => throw new NotSupportedException();
        public IDataReader GetData(int i) => throw new NotSupportedException();
        public string GetDataTypeName(int i) => _types[i].Name;
        public DateTime GetDateTime(int i) => (DateTime)_values[i]!;
        public decimal GetDecimal(int i) => (decimal)_values[i]!;
        public double GetDouble(int i) => (double)_values[i]!;
        public Type GetFieldType(int i) => _types[i];
        public float GetFloat(int i) => (float)_values[i]!;
        public Guid GetGuid(int i) => (Guid)_values[i]!;
        public short GetInt16(int i) => (short)_values[i]!;

        public int GetInt32(int i)
        {
            if (i == _throwOnOrdinal)
                throw new InvalidOperationException("reader failed mid-read");
            return (int)_values[i]!;
        }

        public long GetInt64(int i) => (long)_values[i]!;
        public string GetName(int i) => $"c{i}";
        public int GetOrdinal(string name) => throw new NotSupportedException();
        public string GetString(int i) => (string)_values[i]!;
        public object GetValue(int i) => _values[i] ?? DBNull.Value;

        public int GetValues(object[] values)
        {
            var count = Math.Min(values.Length, _values.Length);
            for (var i = 0; i < count; i++)
                values[i] = GetValue(i);
            return count;
        }

        public bool IsDBNull(int i) => _values[i] is null;
    }

    // A destination that records bytes, counts Write/Flush calls and can fail on a chosen write call.
    private sealed class DestinationSpy : Stream
    {
        private readonly MemoryStream _inner = new();
        private readonly int _failAtWriteCall;

        public DestinationSpy(int failAtWriteCall = -1) => _failAtWriteCall = failAtWriteCall;

        public int WriteCalls { get; private set; }
        public int FlushCalls { get; private set; }
        public bool IsDisposed { get; private set; }
        public string Text => Encoding.UTF8.GetString(_inner.ToArray());

        public override bool CanRead => false;
        public override bool CanSeek => false;
        public override bool CanWrite => !IsDisposed;
        public override long Length => _inner.Length;
        public override long Position { get => _inner.Position; set => throw new NotSupportedException(); }

        public override void Flush() => FlushCalls++;
        public override Task FlushAsync(CancellationToken cancellationToken) { FlushCalls++; return Task.CompletedTask; }
        public override int Read(byte[] buffer, int offset, int count) => throw new NotSupportedException();
        public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
        public override void SetLength(long value) => throw new NotSupportedException();

        public override void Write(byte[] buffer, int offset, int count)
        {
            WriteCalls++;
            if (WriteCalls == _failAtWriteCall)
                throw new InvalidOperationException("destination failed");
            _inner.Write(buffer, offset, count);
        }

        public override ValueTask WriteAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            WriteCalls++;
            if (WriteCalls == _failAtWriteCall)
                throw new InvalidOperationException("destination failed");
            _inner.Write(buffer.Span);
            return ValueTask.CompletedTask;
        }

        protected override void Dispose(bool disposing)
        {
            IsDisposed = true;
            base.Dispose(disposing);
        }
    }

    // A destination that cancels a token after its first (async) write, then throws from every later
    // write because a well-behaved async Stream observes the cancellation token it is handed.
    private sealed class CancellingDestination : Stream
    {
        private readonly MemoryStream _inner = new();
        private readonly CancellationTokenSource _cts;

        public CancellingDestination(CancellationTokenSource cts) => _cts = cts;

        public bool IsDisposed { get; private set; }
        public string Text => Encoding.UTF8.GetString(_inner.ToArray());

        public override bool CanRead => false;
        public override bool CanSeek => false;
        public override bool CanWrite => !IsDisposed;
        public override long Length => _inner.Length;
        public override long Position { get => _inner.Position; set => throw new NotSupportedException(); }

        public override void Flush() { }
        public override Task FlushAsync(CancellationToken cancellationToken) => Task.CompletedTask;
        public override int Read(byte[] buffer, int offset, int count) => throw new NotSupportedException();
        public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
        public override void SetLength(long value) => throw new NotSupportedException();

        public override void Write(byte[] buffer, int offset, int count)
        {
            _inner.Write(buffer, offset, count);
            _cts.Cancel();
        }

        public override ValueTask WriteAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            _inner.Write(buffer.Span);
            _cts.Cancel();
            return ValueTask.CompletedTask;
        }

        protected override void Dispose(bool disposing)
        {
            IsDisposed = true;
            base.Dispose(disposing);
        }
    }

    private static JsonRowWriter BuildRowWriter(JsonStreamOptions options)
    {
        var plan = JsonShapePlan.Build(
            [new SelectExpression(typeof(int)) { Index = 0, PropertyName = "Id" }],
            oneColumn: false,
            options);
        return JsonRowWriterFactory.Build(plan);
    }

    [Fact]
    public void WriteRow_SyncMidRowReadFailure_ShouldPropagateWithoutRecoveryTail()
    {
        var options = new JsonStreamOptions();
        using var destination = new DestinationSpy();
        using var writer = new JsonStreamWriter(destination, BuildRowWriter(options), options);

        writer.WriteRow(new FakeRecord([1], [typeof(int)]));

        var act = () => writer.WriteRow(new FakeRecord([2], [typeof(int)], throwOnOrdinal: 0));

        act.Should().Throw<InvalidOperationException>().WithMessage("reader failed mid-read");
        // The prefix flushed by the first row stays in place: fail-stop, no rollback and no closing bracket.
        destination.Text.Should().Be("[{\"Id\":1}");
        destination.Text.Should().NotContain("]");
        destination.FlushCalls.Should().Be(0);
        destination.CanWrite.Should().BeTrue();
        destination.IsDisposed.Should().BeFalse();
    }

    [Fact]
    public void WriteRow_NdJsonMidRowReadFailure_ShouldPropagate()
    {
        var options = new JsonStreamOptions { Mode = JsonStreamMode.NdJson };
        using var destination = new DestinationSpy();
        using var writer = new JsonStreamWriter(destination, BuildRowWriter(options), options);

        writer.WriteRow(new FakeRecord([1], [typeof(int)]));

        var act = () => writer.WriteRow(new FakeRecord([2], [typeof(int)], throwOnOrdinal: 0));

        act.Should().Throw<InvalidOperationException>().WithMessage("reader failed mid-read");
        destination.Text.Should().Be("{\"Id\":1}\n");
        destination.FlushCalls.Should().Be(0);
        destination.CanWrite.Should().BeTrue();
    }

    [Fact]
    public void WriteRow_SyncSinkFailure_ShouldKeepDestinationOpenAndPrefix()
    {
        var options = new JsonStreamOptions();
        using var destination = new DestinationSpy(failAtWriteCall: 2);
        using var writer = new JsonStreamWriter(destination, BuildRowWriter(options), options);

        writer.WriteRow(new FakeRecord([1], [typeof(int)]));

        var act = () => writer.WriteRow(new FakeRecord([2], [typeof(int)]));

        act.Should().Throw<InvalidOperationException>().WithMessage("destination failed");
        destination.Text.Should().Be("[{\"Id\":1}");
        destination.FlushCalls.Should().Be(0);
        destination.CanWrite.Should().BeTrue();
        destination.IsDisposed.Should().BeFalse();
    }

    [Fact]
    public async Task WriteRowAsync_MidRowReadFailure_ShouldPropagate()
    {
        var options = new JsonStreamOptions();
        using var destination = new DestinationSpy();
        using var writer = new JsonStreamWriter(destination, BuildRowWriter(options), options);

        await writer.WriteRowAsync(new FakeRecord([1], [typeof(int)]), TestContext.Current.CancellationToken);

        var act = async () => await writer.WriteRowAsync(new FakeRecord([2], [typeof(int)], throwOnOrdinal: 0), TestContext.Current.CancellationToken);

        await act.Should().ThrowAsync<InvalidOperationException>().WithMessage("reader failed mid-read");
        destination.Text.Should().Be("[{\"Id\":1}");
        destination.FlushCalls.Should().Be(0);
        destination.CanWrite.Should().BeTrue();
    }

    [Fact]
    public async Task WriteRowAsync_SinkFailure_ShouldKeepDestinationOpen()
    {
        var options = new JsonStreamOptions();
        using var destination = new DestinationSpy(failAtWriteCall: 2);
        using var writer = new JsonStreamWriter(destination, BuildRowWriter(options), options);

        await writer.WriteRowAsync(new FakeRecord([1], [typeof(int)]), TestContext.Current.CancellationToken);

        var act = async () => await writer.WriteRowAsync(new FakeRecord([2], [typeof(int)]), TestContext.Current.CancellationToken);

        await act.Should().ThrowAsync<InvalidOperationException>().WithMessage("destination failed");
        destination.Text.Should().Be("[{\"Id\":1}");
        destination.FlushCalls.Should().Be(0);
        destination.CanWrite.Should().BeTrue();
        destination.IsDisposed.Should().BeFalse();
    }

    [Fact]
    public async Task WriteRowAsync_CancellationAfterPrefix_ShouldAbortAndKeepPrefix()
    {
        var options = new JsonStreamOptions();
        using var cts = new CancellationTokenSource();
        using var destination = new CancellingDestination(cts);
        using var writer = new JsonStreamWriter(destination, BuildRowWriter(options), options);

        await writer.WriteRowAsync(new FakeRecord([1], [typeof(int)]), cts.Token);

        var act = async () => await writer.WriteRowAsync(new FakeRecord([2], [typeof(int)]), cts.Token);

        var exception = await act.Should().ThrowAsync<OperationCanceledException>();
        exception.Which.CancellationToken.Should().Be(cts.Token);
        destination.Text.Should().Be("[{\"Id\":1}");
        destination.CanWrite.Should().BeTrue();
        destination.IsDisposed.Should().BeFalse();
    }

    [Fact]
    public async Task WriteRowAsync_NdJsonCancellationAfterPrefix_ShouldAbort()
    {
        var options = new JsonStreamOptions { Mode = JsonStreamMode.NdJson };
        using var cts = new CancellationTokenSource();
        using var destination = new CancellingDestination(cts);
        using var writer = new JsonStreamWriter(destination, BuildRowWriter(options), options);

        await writer.WriteRowAsync(new FakeRecord([1], [typeof(int)]), cts.Token);

        var act = async () => await writer.WriteRowAsync(new FakeRecord([2], [typeof(int)]), cts.Token);

        await act.Should().ThrowAsync<OperationCanceledException>();
        destination.Text.Should().Be("{\"Id\":1}\n");
        destination.CanWrite.Should().BeTrue();
    }
}

using System.Collections;
using System.Data.Common;
using System.Text;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// Coverage for the <c>ToDataReader</c>/<c>ToDataReaderAsync</c> terminals and the internal
/// <see cref="LobDataReader"/> wrapper. The in-memory provider rejects the terminals (it cannot
/// stream); the wrapper is exercised over a substituted <see cref="DbDataReader"/> to pin that it
/// is transparent, that disposal is idempotent, and that the opening token still cancels reads. On
/// the dialect gate a provider without sequential access is still rejected before execution (even
/// when it also declares a locator column), while a locator dialect that supports sequential access
/// passes the gate and routes to the locator-free result reader.
/// </summary>
public class LobDataReaderTests
{
    private readonly IDataContext _ctx;

    public LobDataReaderTests(IDataContext ctx)
    {
        _ctx = ctx;
    }

    // --- Terminal gate: the in-memory provider is not relational, so it cannot open a reader. ---

    [Fact]
    public void ToDataReader_InMemory_ShouldThrowNotSupported()
    {
        var command = _ctx.From<LobTestEntity>().Where(it => it.Id == 1).Select(it => new { it.Id, it.Data });

        var act = () => command.ToDataReader();

        act.Should().Throw<NotSupportedException>();
    }

    [Fact]
    public async Task ToDataReaderAsync_InMemory_ShouldThrowNotSupported()
    {
        var command = _ctx.From<LobTestEntity>().Where(it => it.Id == 1).Select(it => new { it.Id, it.Data });

        var act = async () => await command.ToDataReaderAsync();

        await act.Should().ThrowAsync<NotSupportedException>();
    }

    [Fact]
    public void ToDataReader_AfterContextDispose_ShouldThrowObjectDisposed()
    {
        using var ctx = new InMemoryDataContext();
        var command = ctx.From<LobTestEntity>().Where(it => it.Id == 1).Select(it => new { it.Id, it.Data });
        ctx.Dispose();

        var act = () => command.ToDataReader();

        act.Should().Throw<ObjectDisposedException>();
    }

    [Fact]
    public async Task ToDataReaderAsync_AfterContextDispose_ShouldThrowObjectDisposed()
    {
        using var ctx = new InMemoryDataContext();
        var command = ctx.From<LobTestEntity>().Where(it => it.Id == 1).Select(it => new { it.Id, it.Data });
        ctx.Dispose();

        var act = async () => await command.ToDataReaderAsync();

        await act.Should().ThrowAsync<ObjectDisposedException>();
    }

    // --- Dialect gate: a dialect without sequential access is rejected before the provider is
    // touched, even when it also declares a locator column (the non-sequential check wins). The fake
    // context throws InvalidOperationException from its provider seam, so a NotSupportedException
    // proves the terminal never reached execution while reaching that seam proves it passed the gate. ---

    [Fact]
    public void ToDataReader_WithoutSequentialAccess_ShouldThrowNotSupportedBeforeExecution()
        => AssertGate(
            new TestDialect(sequentialAccess: false, locator: null),
            BuildCommand,
            command => command.ToDataReader());

    [Fact]
    public async Task ToDataReaderAsync_WithoutSequentialAccess_ShouldThrowNotSupportedBeforeExecution()
        => await AssertGateAsync(
            new TestDialect(sequentialAccess: false, locator: null),
            BuildCommand,
            command => command.ToDataReaderAsync());

    [Fact]
    public void ToDataReader_WithoutSequentialAccessWithLocator_ShouldStillThrowNotSupportedBeforeExecution()
        => AssertGate(
            new TestDialect(sequentialAccess: false, locator: "rowid"),
            BuildCommand,
            command => command.ToDataReader());

    [Fact]
    public async Task ToDataReaderAsync_WithoutSequentialAccessWithLocator_ShouldStillThrowNotSupportedBeforeExecution()
        => await AssertGateAsync(
            new TestDialect(sequentialAccess: false, locator: "rowid"),
            BuildCommand,
            command => command.ToDataReaderAsync());

    // A locator dialect that supports sequential access is no longer rejected: the terminal routes
    // around the locator (SQLite uses the locator-free result reader), so it proceeds to the provider
    // seam. The fake context throws InvalidOperationException there, which proves the dialect gate was
    // passed; the actual SQLite behaviour is pinned in NextORM.Sqlite.Tests.
    [Fact]
    public void ToDataReader_WithLocatorDialect_ShouldNotBeRejectedBeforeExecution()
        => AssertReachesProvider(
            new TestDialect(sequentialAccess: true, locator: "rowid"),
            BuildCommand,
            command => command.ToDataReader());

    [Fact]
    public async Task ToDataReaderAsync_WithLocatorDialect_ShouldNotBeRejectedBeforeExecution()
        => await AssertReachesProviderAsync(
            new TestDialect(sequentialAccess: true, locator: "rowid"),
            BuildCommand,
            command => command.ToDataReaderAsync());

    // A non-locator sequential dialect (the PostgreSQL/SQL Server shape) reading a lazy
    // temporary-table source must fail closed before execution rather than surface a raw provider
    // error; the guard names the ToDataReader terminal and not CSV.
    [Fact]
    public void ToDataReader_SequentialDialectWithTempTableSource_ShouldThrowNotSupportedBeforeExecution()
    {
        using var ctx = new FakeDialectContext(new TestDialect(sequentialAccess: true, locator: null));
        var source = ctx.From<LobTestEntity>().Select(it => it.Id).AsTempTable();
        var command = ctx.From(source).Select(t => t.GetInt32("id"));

        var act = () => command.ToDataReader();

        var exception = act.Should().Throw<NotSupportedException>().Which;
        exception.Message.Should().Contain("ToDataReader", "the guard names the rejected terminal");
        exception.Message.Should().NotContain("WriteCsv", "the guard must not surface the CSV terminal");
        exception.Message.Should().NotContain("CSV", "the guard must not surface the CSV terminal");
    }

    [Fact]
    public async Task ToDataReaderAsync_SequentialDialectWithTempTableSource_ShouldThrowNotSupportedBeforeExecution()
    {
        using var ctx = new FakeDialectContext(new TestDialect(sequentialAccess: true, locator: null));
        var source = ctx.From<LobTestEntity>().Select(it => it.Id).AsTempTable();
        var command = ctx.From(source).Select(t => t.GetInt32("id"));

        var act = async () => await command.ToDataReaderAsync();

        var exception = (await act.Should().ThrowAsync<NotSupportedException>()).Which;
        exception.Message.Should().Contain("ToDataReader", "the guard names the rejected terminal");
        exception.Message.Should().NotContain("WriteCsv", "the guard must not surface the CSV terminal");
