/// <summary>
/// T212-D1 characterization (reconnaissance only, no production behavior change). Pins the CURRENT tree's
/// observable handling of a nested (level 2+) <c>LoadWith</c> declared on a child query, in both eager
/// modes, and the parent eager-load shape / plan-key identity. Each test prints an <c>OBS</c> line so the
/// runner log is the raw observation record; the assertions encode the observed values.
/// <para>
/// D3/D4 update: the split path (D3) and the expressible single-query path (D4) now orchestrate nested
/// descendants, so the observations that recorded the pre-D3/D4 silent drop were converted to positive
/// assertions. The raw D1 outputs remain in <c>artifacts/pdca/T212/rv1/A/E01.log</c>.
/// </para>
/// </summary>
[Trait("Feature", "T212-D1")]
public sealed class NestedEagerLoadingCharacterizationTests
{
    public sealed class RootEntity
    {
        public int Id { get; set; }
        public ICollection<MiddleEntity> Middles { get; set; } = new List<MiddleEntity>();
    }

    public sealed class MiddleEntity
    {
        public int Id { get; set; }
        public int RootId { get; set; }
        public ICollection<LeafEntity> Leaves { get; set; } = new List<LeafEntity>();
    }

    public sealed class LeafEntity
    {
        public int Id { get; set; }
        public int MiddleId { get; set; }
    }

    private static InMemoryDataContext CreateContext()
    {
        var context = new InMemoryDataContext();
        context.From<RootEntity>().WithData(new[]
        {
            new RootEntity { Id = 1 },
            new RootEntity { Id = 2 },
        });
        context.From<MiddleEntity>().WithData(new[]
        {
            new MiddleEntity { Id = 10, RootId = 1 },
            new MiddleEntity { Id = 11, RootId = 1 },
            new MiddleEntity { Id = 12, RootId = 2 },
        });
        context.From<LeafEntity>().WithData(new[]
        {
            new LeafEntity { Id = 100, MiddleId = 10 },
            new LeafEntity { Id = 101, MiddleId = 10 },
            new LeafEntity { Id = 110, MiddleId = 11 },
            new LeafEntity { Id = 120, MiddleId = 12 },
        });
        return context;
    }

    private static void Observe(string label, InMemoryDataContext context, IReadOnlyList<RootEntity> roots, int nestedFactoryCalls)
    {
        var middles = roots.SelectMany(r => r.Middles).Select(m => m.Id).ToArray();
        var leaves = roots.SelectMany(r => r.Middles).SelectMany(m => m.Leaves).Select(l => l.Id).ToArray();
        Console.WriteLine(
            $"OBS {label}: middles=[{string.Join(",", middles)}] " +
            $"leaves=[{string.Join(",", leaves)}] nestedChildFactoryCalls={nestedFactoryCalls}");
    }

    [Fact]
    public void Split_Depth2_NestedLoadWith_LoadsEveryLevel()
    {
        using var context = CreateContext();
        var nestedFactoryCalls = 0;

        var roots = context.From<RootEntity>()
            .LoadWith(
                r => r.Middles,
                c => c.From<MiddleEntity>().LoadWith(
                    m => m.Leaves,
                    l =>
                    {
                        nestedFactoryCalls++;
                        return l.From<LeafEntity>();
                    },
                    m => m.Id,
                    l => l.MiddleId),
                r => r.Id,
                m => m.RootId)
            .OrderBy(r => r.Id)
            .ToList();

        Observe("split-depth2", context, roots, nestedFactoryCalls);

        roots.SelectMany(r => r.Middles).Select(m => m.Id).Should().Equal(new[] { 10, 11, 12 }, "the level-1 split child load works");
        roots.SelectMany(r => r.Middles).SelectMany(m => m.Leaves).Select(l => l.Id).Should().Equal(
            new[] { 100, 101, 110, 120 },
            "D3: the nested level-2 LoadWith is orchestrated by the split path");
        nestedFactoryCalls.Should().Be(1, "the nested child-query factory is resolved once and reused by execution");
    }

    [Fact]
    public async Task Split_Depth2_NestedLoadWith_Async_LoadsEveryLevel()
    {
        using var context = CreateContext();
        var nestedFactoryCalls = 0;

        var roots = await context.From<RootEntity>()
            .LoadWith(
                r => r.Middles,
                c => c.From<MiddleEntity>().LoadWith(
                    m => m.Leaves,
                    l =>
                    {
                        nestedFactoryCalls++;
                        return l.From<LeafEntity>();
                    },
                    m => m.Id,
                    l => l.MiddleId),
                r => r.Id,
                m => m.RootId)
            .OrderBy(r => r.Id)
            .ToListAsync();

        Observe("split-depth2-async", context, roots, nestedFactoryCalls);

        roots.SelectMany(r => r.Middles).SelectMany(m => m.Leaves).Select(l => l.Id).Should().Equal(
            new[] { 100, 101, 110, 120 },
            "D3: the async split terminal orchestrates the nested level-2 LoadWith");
        nestedFactoryCalls.Should().Be(1, "the nested child-query factory is resolved once and reused by execution");
    }

    [Fact]
    public void SingleQuery_Depth2_NestedLoadWith_LoadsEveryLevel()
    {
        using var context = CreateContext();
        var nestedFactoryCalls = 0;

        var roots = context.From<RootEntity>()
            .LoadWith(
                r => r.Middles,
                c => c.From<MiddleEntity>().LoadWith(
                    m => m.Leaves,
                    l =>
                    {
                        nestedFactoryCalls++;
                        return l.From<LeafEntity>();
                    },
                    m => m.Id,
                    l => l.MiddleId),
                r => r.Id,
                m => m.RootId,
                EagerLoadMode.SingleQuery)
            .OrderBy(r => r.Id)
            .ToList();

        Observe("single-query-depth2", context, roots, nestedFactoryCalls);

        roots.SelectMany(r => r.Middles).Select(m => m.Id).Should().Equal(new[] { 10, 11, 12 }, "the level-1 single-query child load works");
        roots.SelectMany(r => r.Middles).SelectMany(m => m.Leaves).Select(l => l.Id).Should().Equal(
            new[] { 100, 101, 110, 120 },
            "D4: the expressible nested level-2 LoadWith is assembled from the one result set");
        nestedFactoryCalls.Should().Be(1, "the nested child-query factory is resolved once and reused");
    }

    [Fact]
    public void Parent_EagerLoadShape_IgnoresTheNestedGraph()
    {
        using var context = CreateContext();

        var plain = context.From<RootEntity>()
            .LoadWith(r => r.Middles, c => c.From<MiddleEntity>(), r => r.Id, m => m.RootId)
            .ToCommand();
        var nested = context.From<RootEntity>()
            .LoadWith(
                r => r.Middles,
                c => c.From<MiddleEntity>().LoadWith(m => m.Leaves, l => l.From<LeafEntity>(), m => m.Id, l => l.MiddleId),
                r => r.Id,
                m => m.RootId)
            .ToCommand();

        Console.WriteLine(
            $"OBS parent-shape: plain={plain.EagerLoadShape.StructuralHash} nested={nested.EagerLoadShape.StructuralHash} " +
            $"equal={nested.EagerLoadShape.Equals(plain.EagerLoadShape)}");

        nested.EagerLoadShape.Equals(plain.EagerLoadShape).Should().BeTrue(
            "OBSERVED: the nested level-2 graph is invisible to the parent eager-load shape / plan key");
        nested.EagerLoadShape.StructuralHash.Should().Be(plain.EagerLoadShape.StructuralHash);
    }
}

using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// T212-D2 focal coverage for the shared nested eager-load graph contract: node/path metadata,
/// ancestor-composite identity, graph-wide mode/filter context, declaration validation (the deterministic
/// cycle guard and nested-mode conflicts) and frontend normalization. These tests exercise the internal
/// contract directly; they build no command and execute no query.
/// </summary>
[Trait("Feature", "T212-D2")]
public sealed class NestedEagerLoadingGraphContractTests
{
    public sealed class RootEntity
    {
        public int Id { get; set; }
        public ICollection<MiddleEntity> Middles { get; set; } = new List<MiddleEntity>();
        public ICollection<MiddleEntity> AltMiddles { get; set; } = new List<MiddleEntity>();
    }

    public sealed class MiddleEntity
    {
        public int Id { get; set; }
        public int RootId { get; set; }
        public ICollection<LeafEntity> Leaves { get; set; } = new List<LeafEntity>();
    }

    public sealed class LeafEntity
    {
        public int Id { get; set; }
        public int MiddleId { get; set; }
        public ICollection<TipEntity> Tips { get; set; } = new List<TipEntity>();
    }

    public sealed class TipEntity
    {
        public int Id { get; set; }
        public int LeafId { get; set; }
    }

    public sealed class SelfEntity
    {
        public int Id { get; set; }
        public int ParentId { get; set; }
        public ICollection<SelfEntity> Children { get; set; } = new List<SelfEntity>();
    }

    private static InMemoryDataContext CreateContext()
    {
        var context = new InMemoryDataContext();
        context.From<RootEntity>().WithData(new[] { new RootEntity { Id = 1 }, new RootEntity { Id = 2 } });
        context.From<MiddleEntity>().WithData(new[] { new MiddleEntity { Id = 10, RootId = 1 }, new MiddleEntity { Id = 11, RootId = 2 } });
        context.From<LeafEntity>().WithData(new[] { new LeafEntity { Id = 100, MiddleId = 10 } });
        context.From<TipEntity>().WithData(new[] { new TipEntity { Id = 1000, LeafId = 100 } });
        context.From<SelfEntity>().WithData(new[] { new SelfEntity { Id = 1 }, new SelfEntity { Id = 2, ParentId = 1 } });
        return context;
    }

    private static EntityBuilder<RootEntity> NestedBuilder(InMemoryDataContext context, EagerLoadMode mode = EagerLoadMode.Default)
        => context.From<RootEntity>()
            .LoadWith(
                r => r.Middles,
                c => c.From<MiddleEntity>().LoadWith(
                    m => m.Leaves,
                    l => l.From<LeafEntity>(),
                    m => m.Id,
                    l => l.MiddleId),
                r => r.Id,
                m => m.RootId,
                mode);

    [Fact]
    public void Normalize_PlainBuilder_ProducesEmptyGraph()
    {
        using var context = CreateContext();

        var graph = context.From<RootEntity>().NormalizeEagerLoadGraph(context);

        graph.IsEmpty.Should().BeTrue();
        graph.Nodes.Should().BeEmpty();
        graph.MaxDepth.Should().Be(0);
        graph.ToShape().IsEmpty.Should().BeTrue();
    }

    [Fact]
    public void Normalize_NestedGraph_ExposesRootAndChildNodesWithAncestorCompositeIdentity()
    {
        using var context = CreateContext();

        var graph = NestedBuilder(context).NormalizeEagerLoadGraph(context);

        graph.Nodes.Should().HaveCount(2);
        graph.Roots.Should().HaveCount(1);
        graph.MaxDepth.Should().Be(2);

        var root = graph.Roots[0];
        root.IsRoot.Should().BeTrue();
        root.Parent.Should().BeNull();
        root.Depth.Should().Be(1);
        root.Path.Should().Equal(new[] { root.Segment });
        root.CompositeIdentity.Should().Be(root.Segment, "a top-level node's composite identity is its own key");

        var child = graph.Nodes[1];
        child.IsRoot.Should().BeFalse();
        child.Parent.Should().BeSameAs(root);
        child.Depth.Should().Be(2);
        child.Path.Should().Equal(new[] { root.Segment, child.Segment });
        child.CompositeIdentity.Should().Be(root.Segment + "/" + child.Segment, "the identity is L1 key + L2 key");

        graph.Find(root.CompositeIdentity).Should().BeSameAs(root);
        graph.Find(child.CompositeIdentity).Should().BeSameAs(child);
    }

    [Fact]
    public void Normalize_Depth3Graph_ExtendsAncestorCompositeIdentityPerLevel()
    {
        using var context = CreateContext();

        var graph = context.From<RootEntity>()
            .LoadWith(
                r => r.Middles,
                c => c.From<MiddleEntity>().LoadWith(
                    m => m.Leaves,
                    l => l.From<LeafEntity>().LoadWith(
                        t => t.Tips,
                        p => p.From<TipEntity>(),
                        t => t.Id,
                        p => p.LeafId),
                    m => m.Id,
                    l => l.MiddleId),
                r => r.Id,
                m => m.RootId)
            .NormalizeEagerLoadGraph(context);

        graph.Nodes.Should().HaveCount(3);
        graph.MaxDepth.Should().Be(3);
        graph.Roots[0].Depth.Should().Be(1);
        graph.Nodes[1].Depth.Should().Be(2);

        var deepest = graph.Nodes[2];
        deepest.Depth.Should().Be(3);
        deepest.Path.Should().Equal(new[] { graph.Roots[0].Segment, graph.Nodes[1].Segment, deepest.Segment });
        deepest.CompositeIdentity.Should().Be(string.Join("/", deepest.Path));
    }

    [Fact]
    public void Normalize_SingleQueryMode_IsTheGraphWideMode()
    {
        using var context = CreateContext();

        var split = NestedBuilder(context).NormalizeEagerLoadGraph(context);
        var single = NestedBuilder(context, EagerLoadMode.SingleQuery).NormalizeEagerLoadGraph(context);

        split.Context.Mode.Should().Be(EagerLoadMode.SplitQuery);
        single.Context.Mode.Should().Be(EagerLoadMode.SingleQuery);
    }

    [Fact]
    public void Normalize_InheritsTheRootFilterScopeForTheWholeGraph()
    {
        using var context = CreateContext();

        var builder = NestedBuilder(context).IgnoreFilters();
        var graph = builder.NormalizeEagerLoadGraph(context);

        graph.Context.FilterScope.Should().BeSameAs(builder.FilterScope);
        graph.Context.FilterScope.All.Should().BeTrue();
    }

    [Fact]
    public void Normalize_ConflictingNestedMode_IsRejected()
    {
        using var context = CreateContext();

        var builder = context.From<RootEntity>()
            .LoadWith(
                r => r.Middles,
                c => c.From<MiddleEntity>().LoadWith(
                    m => m.Leaves,
                    l => l.From<LeafEntity>(),
                    m => m.Id,
                    l => l.MiddleId,
                    EagerLoadMode.SingleQuery),
                r => r.Id,
                m => m.RootId,
                EagerLoadMode.SplitQuery);

        var act = () => builder.NormalizeEagerLoadGraph(context);

        act.Should().Throw<NotSupportedException>().WithMessage("*mixes modes*");
    }

    [Fact]
    public void Normalize_SelfReferentialCycle_IsRejectedDeterministically()
    {
        using var context = CreateContext();

        Func<IDataContext, EntityBuilder<SelfEntity>> factory = null!;
        factory = ctx => ctx.From<SelfEntity>().LoadWith(n => n.Children, factory, n => n.Id, n => n.ParentId);

        var builder = context.From<SelfEntity>().LoadWith(n => n.Children, factory, n => n.Id, n => n.ParentId);

        var act = () => builder.NormalizeEagerLoadGraph(context);

        act.Should().Throw<NotSupportedException>().WithMessage("*cyclic*");
    }

    [Fact]
    public void Normalize_BuilderReferenceCycle_IsRejected()
    {
        using var context = CreateContext();

        EntityBuilder<SelfEntity> builder = null!;
        builder = context.From<SelfEntity>().LoadWith(n => n.Children, _ => builder, n => n.Id, n => n.ParentId);

        var act = () => builder.NormalizeEagerLoadGraph(context);

        act.Should().Throw<NotSupportedException>().WithMessage("*cyclic*");
    }

    [Fact]
    public void Normalize_SiblingBranchesWithTheSameTypes_AreNotTreatedAsCycles()
    {
        using var context = CreateContext();

        var builder = context.From<RootEntity>()
            .LoadWith(
                r => r.Middles,
                c => c.From<MiddleEntity>().LoadWith(m => m.Leaves, l => l.From<LeafEntity>(), m => m.Id, l => l.MiddleId),
                r => r.Id,
                m => m.RootId)
            .LoadWith(r => r.AltMiddles, c => c.From<MiddleEntity>(), r => r.Id, m => m.RootId);

        var graph = builder.NormalizeEagerLoadGraph(context);

        graph.Roots.Should().HaveCount(2);
        graph.Nodes.Should().HaveCount(3);
        graph.MaxDepth.Should().Be(2);
    }

    [Fact]
    public void ToShape_IncludesNestedIdentity_SoANestedGraphDiffersFromALevelOneGraph()
    {
        using var context = CreateContext();

        var nested = NestedBuilder(context).NormalizeEagerLoadGraph(context).ToShape();
        var flat = context.From<RootEntity>()
            .LoadWith(r => r.Middles, c => c.From<MiddleEntity>(), r => r.Id, m => m.RootId)
            .NormalizeEagerLoadGraph(context)
            .ToShape();

        nested.IsEmpty.Should().BeFalse();
        flat.IsEmpty.Should().BeFalse();
        nested.Equals(flat).Should().BeFalse("the nested graph carries the level-2 identity the flat graph does not");
    }
}

using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// T212-D7 corrective: the mandatory nested eager-load variant-matrix rows the r1 evidence missed.
/// Row A (declaration frontends), row C (identity/state: nullable/composite nested keys, repeated CLR
/// type), the uncovered nested single-query rejection branch, and the deepest-node per-parent paging
/// probe. In-memory rows assert in-memory behavior; the SQL rows live in the dialect projects.
/// </summary>
[Trait("Feature", "T212-D7")]
public sealed class NestedEagerLoadingMatrixTests
{
    // ============================================================================================
    // Row C — same-CLR-type binding (warning: EntityBuilder.ResolveJoinLeftItemNumber latest-match).
    // An acyclic graph repeats a CLR type: a deeper node of the same type precedes a later sibling
    // whose direct parent is the earlier same-typed node. The join must attach to the direct parent.
    // ============================================================================================

    private sealed class RepRoot
    {
        public int Id { get; set; }
        public ICollection<RepT> Ts { get; set; } = new List<RepT>();
    }

    private sealed class RepT
    {
        public int Id { get; set; }
        public int RootId { get; set; }
        public int RefId { get; set; }
        public ICollection<RepU> Us { get; set; } = new List<RepU>();
        public ICollection<RepW> Ws { get; set; } = new List<RepW>();
    }

    private sealed class RepU
    {
        public int Id { get; set; }
        public int TId { get; set; }
        public ICollection<RepT> Ts2 { get; set; } = new List<RepT>();
    }

    private sealed class RepW
    {
        public int Id { get; set; }
        public int TId { get; set; }
    }

    private static EntityBuilder<RepRoot> RepeatedTypeBuilder(InMemoryDataContext context)
        => context.From<RepRoot>()
            .LoadWith(
                r => r.Ts,
                c => c.From<RepT>()
                    .LoadWith(
                        t => t.Us,
                        u => u.From<RepU>().LoadWith(x => x.Ts2, y => y.From<RepT>(), x => x.Id, y => y.RefId),
                        t => t.Id,
                        u => u.TId)
                    .LoadWith(t => t.Ws, w => w.From<RepW>(), t => t.Id, w => w.TId),
                r => r.Id,
                t => t.RootId,
                EagerLoadMode.SingleQuery);

    [Fact]
    public void SingleQuery_RepeatedClrType_SiblingAfterDeeperSameType_AttachesToDirectParent()
    {
        using var context = new InMemoryDataContext();
        context.From<RepRoot>().WithData(new[] { new RepRoot { Id = 1 } });
        context.From<RepT>().WithData(new[]
        {
            new RepT { Id = 10, RootId = 1 },  // RepT attached to RepRoot
            new RepT { Id = 20, RefId = 100 }, // deeper repeated RepT under RepU
        });
        context.From<RepU>().WithData(new[] { new RepU { Id = 100, TId = 10 } });
        context.From<RepW>().WithData(new[] { new RepW { Id = 200, TId = 10 } });

        var roots = RepeatedTypeBuilder(context).ToList();

        var t1 = roots.Single().Ts.Single(t => t.Id == 10);
        var t2 = t1.Us.Single().Ts2.Single(t => t.Id == 20);
        t1.Ws.Select(w => w.Id).Should().Equal(new[] { 200 }, "the sibling attaches to its direct parent, not the deeper same-typed node");
