    [Fact]
    public void Split_SiblingBranches_LoadIndependently()
    {
        using var context = new InMemoryDataContext();
        context.From<Root>().WithData(new[] { new Root { Id = 1 } });
        context.From<Mid>().WithData(new[]
        {
