    [Fact]
    public void Split_RootSelectiveIgnore_PropagatesTheScopeToEveryNestedLevel()
    {
        using var context = CreateFilteredContext();

        var roots = FilteredDepth2Builder(context).IgnoreFilters(["soft"]).OrderBy(r => r.Id).ToList();

        roots.Select(r => r.Id).Should().Equal(1, 2);
        roots.SelectMany(r => r.Mids).Select(m => m.Id).Should().BeEquivalentTo(new[] { 10, 11, 12 });
        roots.SelectMany(r => r.Mids).SelectMany(m => m.Leaves).Select(l => l.Id)
            .Should().BeEquivalentTo(new[] { 100, 101, 110, 120 });
    }

    [Fact]
    public void Split_ChildIgnoreFilters_AtLevel2_PropagatesToLevel3()
    {
        using var context = CreateFilteredContext();

        // The level-2 child disables its own filters (all). Root filters still apply, but level-2 and the
        // level-3 grandchildren inherit the child's all-or-nothing scope.
        var roots = context.From<FilteredRoot>()
            .LoadWith(
                r => r.Mids,
                c => c.From<FilteredMid>().IgnoreFilters().LoadWith(m => m.Leaves, l => l.From<FilteredLeaf>(), m => m.Id, l => l.MidId),
                r => r.Id,
                m => m.RootId)
            .OrderBy(r => r.Id)
            .ToList();

        roots.Select(r => r.Id).Should().Equal(new[] { 1 }, "the parent filter still applies");
        roots.Single().Mids.Select(m => m.Id).Should().Equal(new[] { 10, 11 }, "the level-2 child disables its own filter");
        roots.Single().Mids.SelectMany(m => m.Leaves).Select(l => l.Id)
            .Should().BeEquivalentTo(new[] { 100, 101, 110 }, "the child scope propagates to level 3");
    }

    [Fact]
    public async Task Split_Nested_AsyncParity_MatchesSync()
    {
        using var syncContext = CreateContext();
        using var asyncContext = CreateContext();

        var sync = Depth3Builder(syncContext).OrderBy(r => r.Id).ToList();
        var async = await Depth3Builder(asyncContext).OrderBy(r => r.Id).ToListAsync();

        static string Flatten(IReadOnlyList<Root> roots) => string.Join("|",
            roots.SelectMany(r => r.Mids).SelectMany(m => m.Leaves).SelectMany(l => l.Tips).Select(t => t.Id));

        Flatten(async).Should().Be(Flatten(sync));
    }

    [Fact]
    public void Split_NoPerParentNPlusOne_ExecutionCountsStayStableAsFanOutGrows()
    {
        // The child-query source enumeration count is the execution-count proxy: if the split loader issued
        // one query per parent, the count would scale with the fan-out. It must stay flat.
        static (int MidEnumerations, int LeafEnumerations, int LoadedLeaves) Run(int parentCount)
        {
            var mids = new CountingEnumerable<Mid>(Enumerable.Range(1, parentCount).SelectMany(
                rootId => Enumerable.Range(0, 3).Select(i => new Mid { Id = rootId * 10 + i, RootId = rootId })));
            var leaves = new CountingEnumerable<Leaf>(mids.SelectMany(mid => Enumerable.Range(0, 2).Select(i => new Leaf { Id = mid.Id * 10 + i, MidId = mid.Id })));

            using var context = new InMemoryDataContext();
            context.From<Root>().WithData(Enumerable.Range(1, parentCount).Select(id => new Root { Id = id }));
            context.From<Mid>().WithData(mids);
            context.From<Leaf>().WithData(leaves);

            var roots = context.From<Root>()
                .LoadWith(
                    r => r.Mids,
                    c => c.From<Mid>().LoadWith(m => m.Leaves, l => l.From<Leaf>(), m => m.Id, l => l.MidId),
                    r => r.Id,
                    m => m.RootId)
                .OrderBy(r => r.Id)
                .ToList();

            var loadedLeaves = roots.SelectMany(r => r.Mids).SelectMany(m => m.Leaves).Count();
            return (mids.Enumerations, leaves.Enumerations, loadedLeaves);
        }

        var small = Run(4);
        var large = Run(16);

        small.LoadedLeaves.Should().Be(4 * 3 * 2);
        large.LoadedLeaves.Should().Be(16 * 3 * 2);
        large.MidEnumerations.Should().Be(small.MidEnumerations, "a larger fan-out must not add child queries");
        large.LeafEnumerations.Should().Be(small.LeafEnumerations, "a larger fan-out must not add grandchild queries");
    }

    private sealed class CountingEnumerable<T>(IEnumerable<T> items) : IEnumerable<T>
    {
        private readonly List<T> _items = items.ToList();

        public int Enumerations { get; private set; }

        public IEnumerator<T> GetEnumerator()
        {
            Enumerations++;
            return _items.GetEnumerator();
        }

        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
    }
}

using System.Collections;
using System.Data;
using System.Data.Common;
using System.Diagnostics.CodeAnalysis;
using System.Linq.Expressions;
using System.Text;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// Direct coverage of the immutable guarded parameter-refresh recipe and the planner's fast/mismatch
/// accounting on the cached path. The provider-free <see cref="RecipeTestContext"/> runs the real
/// <c>QueryPlanner</c> (mirroring <c>Iteration14CteLookupTests</c>) so a miss/hit pair exercises the
/// actual <c>TryCreate</c>/<c>TryBind</c>/<c>RefreshParameters</c> path without a database.
/// </summary>
[Collection("Query cache controls")]
public class ParamRefreshRecipeTests
{
    private sealed class RecipeEntity
    {
        public int Id { get; set; }
        public string? Name { get; set; }
    }

    private sealed class NestedProbeHolder
    {
        public CountingProbe Probe { get; set; } = new();
    }

    private sealed class ValueHolder
    {
        public int value;
    }

    private sealed class CountingProbe
    {
        public int Reads;
        public int Value = 5;

        public int Threshold
        {
            get
            {
                Reads++;
                return Value;
            }
        }

        public int Other
        {
            get
            {
                Reads++;
                return Value;
            }
        }

        public string? Text
        {
            get
            {
                Reads++;
                return "text";
            }
        }
    }

    private static DbPreparedQueryCommand<T> Prepare<T>(IDataContext ctx, QueryCommand<T> cmd, bool cache = true)
        => (DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, cache, CancellationToken.None);

    // Same source site, so the captured value (not its shape) changes between calls and the second
    // Prepare is a cache hit with a fresh closure.
    private static QueryCommand<int> WhereCaptured(EntityBuilder<RecipeEntity> e, int value)
        => e.Where(x => x.Id > value).Select(x => x.Id);

    private static QueryCommand<int> WhereProbe(EntityBuilder<RecipeEntity> e, CountingProbe probe)
        => e.Where(x => x.Id > probe.Threshold).Select(x => x.Id);

    private static QueryCommand<string?> WhereText(EntityBuilder<RecipeEntity> e, CountingProbe probe)
        => e.Where(x => x.Name == probe.Text).Select(x => x.Name);

    private static QueryCommand<int> WhereOther(EntityBuilder<RecipeEntity> e, CountingProbe probe)
        => e.Where(x => x.Id > probe.Other).Select(x => x.Id);

    private static QueryCommand<int> WhereTwo(EntityBuilder<RecipeEntity> e, CountingProbe a, CountingProbe b)
        => e.Where(x => x.Id > a.Threshold || x.Id > b.Other).Select(x => x.Id);

    // A capture reached through a member chain on a captured object (not a direct closure field), so the
    // compiled writer walks closure.Probe.Threshold and BuildPath follows the same nested chain.
    private static QueryCommand<int> WhereNestedProbe(EntityBuilder<RecipeEntity> e, NestedProbeHolder holder)
        => e.Where(x => x.Id > holder.Probe.Threshold).Select(x => x.Id);

    // Builds a prepared provider-free command whose only WHERE capture is `captured`, so the shape guard
    // is the sole difference when a shape clause is added through `configure`.
    private static QueryCommand<int> CreateCapturedCommand(
        RecipeTestContext ctx,
        int captured,
        Func<QueryDefinition, QueryDefinition>? configure = null)
    {
        Expression<Func<RecipeEntity, bool>> condition = x => x.Id > captured;
        var definition = new QueryDefinition
        {
            SrcType = typeof(RecipeEntity),
            Exp = (Expression<Func<RecipeEntity, int>>)(x => x.Id),
            Condition = condition,
        };

        if (configure is not null)
            definition = configure(definition);

        var command = ctx.CreateCommand<int>(definition);
        command.PrepareCommand(false, CancellationToken.None);
        return command;
    }

    private static void AssertRecipeNull(QueryCommand<int> command)
    {
        var key = new ExpressionKey(command.PreparedCondition!, command);
        var parameter = new Parameter("captured", 1) { CapturedKey = key };
        ParamRefreshRecipe.TryCreate(command, [parameter]).Should()
            .BeNull("the unsupported shape must keep the original extraction path");
    }

    // The captured scalar lives ONLY in the projection: the WHERE captures nothing. The recipe must
    // therefore navigate the projection root on a hit, not the prepared condition.
    private static QueryCommand<int> ProjectionOnlyCaptured(EntityBuilder<RecipeEntity> e, CountingProbe probe)
        => e.Where(x => x.Id > 0).Select(x => x.Id + probe.Threshold);

