    {
        Action nullName = () => ProcedureParameter.Table(null!, new[] { 1 });
        Action blankName = () => ProcedureParameter.Table("   ", new[] { 1 });

        nullName.Should().Throw<ArgumentException>();
        blankName.Should().Throw<ArgumentException>();
