        Action blankType = () => ProcedureParameter.Table("p", "  ", new[] { 1 });

        nullType.Should().Throw<ArgumentException>();
        blankType.Should().Throw<ArgumentException>();
    }

    [Fact]
    public void Table_NullRowsWithTypeName_ShouldThrow()
    {
