        act.Should().Throw<ArgumentNullException>();
    }
}

using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// Focused unit coverage for the join-slot member parse at
/// <see cref="ProjectionAliasCache"/>: an engine projection member is <c>Item</c> followed by one or
/// more ASCII digits; a generated lexical alias that merely *ends* in a digit (for example
/// <c>Buyer2</c>) must never be misread as a positional slot before its
/// <see cref="JoinSlotAttribute"/> is consulted.
/// </summary>
public class ProjectionAliasCacheTests
{
    [Theory]
    [InlineData("Item1", true, 1)]
    [InlineData("Item2", true, 2)]
    [InlineData("Item8", true, 8)]
    [InlineData("Item9", true, 9)]
    [InlineData("Item10", true, 10)]
    [InlineData("Item0", true, 0)]
    public void TryParseItemPosition_accepts_Item_followed_by_digits(string name, bool expected, int expectedPosition)
    {
        ProjectionAliasCache.TryParseItemPosition(name, out var position).Should().Be(expected);
        position.Should().Be(expectedPosition);
    }

    [Theory]
    [InlineData("Item")]        // exactly the 4-char prefix, no digits
    [InlineData("Items")]       // digit position is a letter
    [InlineData("ItemX")]
    [InlineData("Item2b")]      // trailing non-digit
    [InlineData("Item 2")]      // embedded space
    [InlineData("Item-1")]
    [InlineData("item2")]       // case-sensitive prefix
    [InlineData("buyer2")]      // digit-ending alias
    [InlineData("Buyer2")]
    [InlineData("StoredBuyer2")]
    [InlineData("Approver10")]
    [InlineData("It3m2")]       // 'Item' interrupted by a digit
    [InlineData("I2")]
    [InlineData("")]
    public void TryParseItemPosition_rejects_anything_but_an_exact_ItemN_shape(string name)
    {
        ProjectionAliasCache.TryParseItemPosition(name, out var position).Should().BeFalse();
        position.Should().Be(0);
    }

    [Fact]
    public void GetMemberPosition_maps_a_digit_ending_alias_by_its_JoinSlotAttribute_not_by_the_trailing_digit()
    {
        // 'Buyer2' ends in a digit but is a generated lexical alias in slot 3, not 'Item2'.
        var buyer2 = typeof(DigitEndingAliases).GetProperty(nameof(DigitEndingAliases.Buyer2))!;
        ProjectionAliasCache.GetMemberPosition(buyer2).Should().Be(2);

        var approver10 = typeof(DigitEndingAliases).GetProperty(nameof(DigitEndingAliases.Approver10))!;
        ProjectionAliasCache.GetMemberPosition(approver10).Should().Be(4);

        // A member with neither an ItemN shape nor a JoinSlotAttribute carries no occurrence hint.
        var plain3 = typeof(DigitEndingAliases).GetProperty(nameof(DigitEndingAliases.Plain3))!;
        ProjectionAliasCache.GetMemberPosition(plain3).Should().Be(-1);
    }

    [Fact]
    public void GetMemberPosition_parses_ItemN_before_probing_JoinSlotAttribute()
    {
        // The cheap ItemN parse runs first: 'Item2' resolves to zero-based slot 1 even though the
        // (artificial) attribute on it claims position 5.
        var item2 = typeof(DigitEndingAliases).GetProperty(nameof(DigitEndingAliases.Item2))!;
        ProjectionAliasCache.GetMemberPosition(item2).Should().Be(1);
    }

    private sealed class DigitEndingAliases
    {
        [JoinSlot(3)]
        public int Buyer2 => 0;

        [JoinSlot(5)]
        public int Approver10 => 0;

        [JoinSlot(5)]
        public int Item2 => 0;

        public int Plain3 => 0;
    }
}

using FluentAssertions;

namespace NextORM.Core.Tests;

/// <summary>
/// Serializes the tests that mutate the process-wide <see cref="DataContextCache"/> state (clearing it
/// or changing its sliding expiration) with the rest of the suite.
/// </summary>
[CollectionDefinition("Query cache controls", DisableParallelization = true)]
public sealed class QueryCacheControlsCollection;

/// <summary>
/// Tests for the first-class cache controls: process-wide <see cref="DataContextCache.Clear"/>,
/// context-level disabling through <see cref="DataContextBuilder.UseQueryCache"/> /
/// <see cref="InMemoryDataContext.QueryCacheEnabled"/>, and sliding expiration. The disabling path must
/// never mutate the sticky <see cref="QueryCommand.Cache"/> flag (see AGENTS.md).
/// </summary>
[Collection("Query cache controls")]
public class QueryCacheControlsTests
{
    private sealed class ClearMarker;
    private sealed class SlidingExpirationMarker;
    private sealed class RefreshMarker;

    private static InMemoryDataContext CreateContext()
    {
        var ctx = new InMemoryDataContext();
        ctx.Data[typeof(SimpleEntity)] = new SimpleEntity[] { new() { Id = 1 } };
        return ctx;
    }

    [Fact]
    public void Clear_Should_Empty_ProcessWide_Caches()
    {
        using var ctx = CreateContext();
        ctx.From<SimpleEntity>();

        DataContextCache.SelectListCache[typeof(ClearMarker)] = [];
        DataContextCache.Metadata.ContainsKey(typeof(SimpleEntity)).Should().BeTrue();

        DataContextCache.Clear();

        DataContextCache.SelectListCache.ContainsKey(typeof(ClearMarker)).Should().BeFalse();
        DataContextCache.Metadata.ContainsKey(typeof(SimpleEntity)).Should().BeFalse();
    }

    [Fact]
    public void Enabled_QueryCache_Should_Reuse_Prepared_Command()
    {
        using var ctx = CreateContext();
        var command = ctx.From<SimpleEntity>().Select(x => x.Id);

        var first = ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, TestContext.Current.CancellationToken);
        var second = ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, TestContext.Current.CancellationToken);

        second.Should().BeSameAs(first);
    }

    [Fact]
    public void Disabled_QueryCache_Should_Rebuild_Without_Mutating_Command_Cache_Flag()
    {
        using var ctx = CreateContext();
        ctx.QueryCacheEnabled = false;
        var command = ctx.From<SimpleEntity>().Select(x => x.Id);
        command.Cache.Should().BeTrue();

        var first = ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, TestContext.Current.CancellationToken);
        var second = ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, TestContext.Current.CancellationToken);

        second.Should().NotBeSameAs(first);
        command.Cache.Should().BeTrue();
    }

    [Fact]
    public void StoreInCache_False_Should_Not_Mutate_Command_Cache_Flag()
    {
        using var ctx = CreateContext();
        var command = ctx.From<SimpleEntity>().Select(x => x.Id);

        ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: false, TestContext.Current.CancellationToken);

        command.Cache.Should().BeTrue();
    }

    // A captured scalar Contains must not mutate the persistent command policy when the call is prepared
    // without caching (the InMemory fixture cannot establish the SQL regression; the SQLite D199 suite
    // does that).
    [Fact]
    public void CapturedScalarContains_PrepareWithoutCaching_ShouldPreserveCommandPolicy()
    {
        using var ctx = CreateContext();
        var values = new List<int> { 1 };
        var command = ctx.From<SimpleEntity>().Where(x => values.Contains(x.Id)).Select(x => x.Id);

        ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: false, TestContext.Current.CancellationToken);

        command.Cache.Should().BeTrue(
            "preparing a captured scalar Contains without caching must not mutate the persistent command policy");
    }

    // An explicitly disabled caller policy is authoritative and must not be re-enabled by preparing a
    // captured scalar Contains.
    [Fact]
    public void CapturedScalarContains_ShouldRespectExplicitDisabledPolicy()
    {
        using var ctx = CreateContext();
        var values = new List<int> { 1 };
        var command = ctx.From<SimpleEntity>().Where(x => values.Contains(x.Id)).Select(x => x.Id);
        command.Cache = false;

        ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, TestContext.Current.CancellationToken);

        command.Cache.Should().BeFalse(
            "an explicitly disabled cache policy must not be re-enabled by preparing a captured scalar Contains");
    }

    [Fact]
    public void UseQueryCache_False_Should_Disable_Plan_Cache()
    {
        new DataContextBuilder().UseQueryCache(false).QueryCacheEnabled.Should().BeFalse();
        new DataContextBuilder().UseQueryCache().QueryCacheEnabled.Should().BeTrue();
    }

    [Fact]
    public void UseCacheSlidingExpiration_Should_Set_Global_Window()
    {
        var previous = DataContextCache.CacheSlidingExpiration;
        try
        {
            var ttl = TimeSpan.FromSeconds(5);

            new DataContextBuilder().UseCacheSlidingExpiration(ttl);

            DataContextCache.CacheSlidingExpiration.Should().Be(ttl);
        }
        finally
        {
            DataContextCache.CacheSlidingExpiration = previous;
        }
    }

    [Fact]
    public void UseCacheSlidingExpiration_Negative_ShouldThrow()
    {
        var act = () => new DataContextBuilder().UseCacheSlidingExpiration(TimeSpan.FromMilliseconds(-1));

        act.Should().Throw<ArgumentOutOfRangeException>();
    }

    [Fact]
    public void SlidingExpiration_Should_Evict_After_Ttl()
    {
        DataContextCache.CacheSlidingExpiration = TimeSpan.FromMilliseconds(200);
        try
        {
            var key = typeof(SlidingExpirationMarker);
            DataContextCache.SelectListCache[key] = [];
            DataContextCache.SelectListCache.ContainsKey(key).Should().BeTrue();

            Thread.Sleep(400);

            DataContextCache.SelectListCache.ContainsKey(key).Should().BeFalse();
        }
        finally
        {
            DataContextCache.CacheSlidingExpiration = TimeSpan.Zero;
            DataContextCache.Clear();
        }
    }

    [Fact]
    public void SlidingExpiration_Should_Refresh_On_Read()
    {
        DataContextCache.CacheSlidingExpiration = TimeSpan.FromMilliseconds(400);
        try
        {
            var key = typeof(RefreshMarker);
            DataContextCache.SelectListCache[key] = [];

            Thread.Sleep(250);
            DataContextCache.SelectListCache.ContainsKey(key).Should().BeTrue();
            Thread.Sleep(250);

            DataContextCache.SelectListCache.ContainsKey(key).Should().BeTrue();
        }
        finally
        {
            DataContextCache.CacheSlidingExpiration = TimeSpan.Zero;
            DataContextCache.Clear();
        }
    }
}

using System.Linq.Expressions;
using System.Reflection;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// Pins the exact owner-getter identity contract of the EF Core query-filter bridge: only the method
/// the bridge registers is treated as the owner getter that core parameterises against the live
/// context. Any other static helper over <see cref="QueryFilterContext.Context"/> is a native filter and
/// must keep its own translation path.
/// </summary>
public class QueryFilterOwnerGetterTests
{
    [Fact]
    public void NativeStaticContextHelperIsNotOwnerGetter()
    {
        using var ctx = new InMemoryDataContext();
        var host = new QueryFilterContext(ctx);
        var contextAccess = Expression.Property(Expression.Constant(host), nameof(QueryFilterContext.Context));
        var nativeHelper = typeof(QueryFilterOwnerGetterTests).GetMethod(
            nameof(NativeHelper), BindingFlags.NonPublic | BindingFlags.Static)!;

        var helperCall = Expression.Call(nativeHelper, contextAccess);

        QueryFilterContextAccessor.IsOwnerGetter(helperCall).Should().BeFalse(
            "only the exact owner-getter registered by the EF Core bridge is recognised; a native static helper over Context keeps native semantics");
    }

    [Fact]
    public void BuildSourceName_TruncatedMethodCallChainsCollide()
    {
        var receiver = Expression.Parameter(typeof(Probe), "receiver");
        var getCall = Expression.Call(receiver, typeof(Probe).GetMethod(nameof(Probe.Get))!);
        var id = Expression.Property(getCall, nameof(Probe.Id));
        var other = Expression.Property(getCall, nameof(Probe.Other));

        // The walk stops at the first method call, so two chains over different receivers that share the
        // method and leaf names collapse to one source name; different leaves stay distinct.
        QueryFilterContextAccessor.BuildSourceName(id).Should().Be("Get_Id");
        QueryFilterContextAccessor.BuildSourceName(other).Should().Be("Get_Other");
        QueryFilterContextAccessor.BuildSourceName(id).Should().NotBe(QueryFilterContextAccessor.BuildSourceName(other));
    }

    private sealed class Probe
    {
        public int Id { get; set; }

        public int Other { get; set; }

        public Probe Get() => this;
    }

    private static int NativeHelper(IDataContext context) => context.Properties.Count;
}

