        using var ctx = new InMemoryDataContext();
        var body = ctx.From<BoundEntity>().Where(x => x.Id > 0).Select(x => new { x.Id });
        var source = ctx.FromSql("select 1 as Id");
        source.Ctes = ctx.With("recent", body).Ctes;
