            .HasManyThrough<M2MChild, M2MLink, int, int>(
                p => p.Children, p => p.Id, l => l.ParentId, c => c.Id, l => l.ChildId)
            .Build();

        metadata.Properties.Should().NotContain(p => p.PropertyInfo.Name == nameof(M2MParent.Children));
    }

    [Fact]
    public void HasManyThrough_ParentKeyTypeMismatch_ShouldThrow()
    {
        var builder = new EntityMetadataBuilder<JuncMismatchParent>();

        Action act = () => builder.HasManyThrough<JuncMismatchChild, JuncParentMismatchLink, object, int>(
            p => p.Children, p => p.Id, l => l.ParentId, c => c.Id, l => l.ChildId);

        act.Should().Throw<NotSupportedException>().WithMessage("*does not match the junction*");
    }

    [Fact]
    public void HasManyThrough_ChildKeyTypeMismatch_ShouldThrow()
    {
        var builder = new EntityMetadataBuilder<JuncMismatchParent>();

        Action act = () => builder.HasManyThrough<JuncMismatchChild, JuncChildMismatchLink, int, object>(
            p => p.Children, p => p.Id, l => l.ParentId, c => c.Id, l => l.ChildId);

        act.Should().Throw<NotSupportedException>().WithMessage("*does not match the junction*");
    }

    [Fact]
    public void AllRelationshipKinds_ShouldBeRepresentable()
    {
        var kinds = Enum.GetValues<RelationshipKind>();
        kinds.Should().HaveCount(4);
        kinds.Should().Contain(RelationshipKind.OneToMany);
        kinds.Should().Contain(RelationshipKind.ManyToOne);
        kinds.Should().Contain(RelationshipKind.OneToOne);
        kinds.Should().Contain(RelationshipKind.ManyToMany);

        // Fluent overloads exist for O2M/M2O/O2O; the model can carry M2M as well.
        var oneToOne = new RelationshipMetadata(
            RelationshipKind.OneToOne,
            typeof(InvChild),
            typeof(InvParent),
            typeof(InvChild).GetProperty(nameof(InvChild.Parent)),
            false,
            typeof(InvChild).GetProperty(nameof(InvChild.ParentId))!,
            typeof(InvParent).GetProperty(nameof(InvParent.Id)),
            typeof(InvChild),
            typeof(InvParent));

        var manyToMany = new RelationshipMetadata(
            RelationshipKind.ManyToMany,
            typeof(InvParent),
            typeof(InvChild),
            typeof(InvParent).GetProperty(nameof(InvParent.Children)),
            true,
            typeof(InvChild).GetProperty(nameof(InvChild.ParentId))!,
            typeof(InvParent).GetProperty(nameof(InvParent.Id)),
            typeof(InvChild),
            typeof(InvParent));

        oneToOne.Kind.Should().Be(RelationshipKind.OneToOne);
        oneToOne.IsCollection.Should().BeFalse();
        manyToMany.Kind.Should().Be(RelationshipKind.ManyToMany);
        manyToMany.IsCollection.Should().BeTrue();
    }
}

using System.Collections;
using System.Data;
using System.Data.Common;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// Command ownership of <see cref="ResultSetEnumerator{TResult}"/> (#101 P1). The transient
/// streaming-row command created by the planner is not stored in the plan cache, so the enumerator must
/// release it together with the reader on every disposal path. A cached plan's command, by contrast,
/// must never be disposed by an enumerator.
/// </summary>
public class ResultSetEnumeratorOwnershipTests
{
    private static DbPreparedQueryCommand<int> Prepared(TrackingDbCommand command)
        => new(command, _ => 0, new PreparedCommandOptions());

    [Fact]
    public void OwnedCommand_Dispose_ShouldDisposeOnce()
    {
        var command = new TrackingDbCommand();
        var enumerator = new ResultSetEnumerator<int>(Prepared(command));
        enumerator.OwnCommand();

        enumerator.Dispose();
        enumerator.Dispose();

        command.DisposeCount.Should().Be(1);
    }

    [Fact]
    public async Task OwnedCommand_DisposeAsync_ShouldDisposeOnce()
    {
        var command = new TrackingDbCommand();
        var enumerator = new ResultSetEnumerator<int>(Prepared(command));
        enumerator.OwnCommand();

        await enumerator.DisposeAsync();
        await enumerator.DisposeAsync();

        command.DisposeCount.Should().Be(1);
    }

    [Fact]
    public async Task OwnedCommand_DisposeThenDisposeAsync_ShouldDisposeOnce()
    {
        var command = new TrackingDbCommand();
        var enumerator = new ResultSetEnumerator<int>(Prepared(command));
        enumerator.OwnCommand();

        enumerator.Dispose();
        await enumerator.DisposeAsync();

        command.DisposeCount.Should().Be(1);
    }

    [Fact]
    public void NonOwnedCommand_Dispose_ShouldNotDisposeTheCachedCommand()
    {
        var command = new TrackingDbCommand();
        var enumerator = new ResultSetEnumerator<int>(Prepared(command));

        enumerator.Dispose();

        command.DisposeCount.Should().Be(0);
    }

    private sealed class TrackingDbCommand : DbCommand
    {
        private readonly EmptyDbParameterCollection _parameters = new();

        public int DisposeCount { get; private set; }

        [System.Diagnostics.CodeAnalysis.AllowNull]
        public override string CommandText { get; set; } = string.Empty;
        public override int CommandTimeout { get; set; }
        public override CommandType CommandType { get; set; }
        public override bool DesignTimeVisible { get; set; }
        public override UpdateRowSource UpdatedRowSource { get; set; }
        protected override DbConnection? DbConnection { get; set; }
        protected override DbParameterCollection DbParameterCollection => _parameters;
        protected override DbTransaction? DbTransaction { get; set; }

        public override void Cancel() { }
        public override int ExecuteNonQuery() => throw new NotSupportedException();
        public override object ExecuteScalar() => throw new NotSupportedException();
        public override void Prepare() { }
        protected override DbParameter CreateDbParameter() => throw new NotSupportedException();
        protected override DbDataReader ExecuteDbDataReader(CommandBehavior behavior) => throw new NotSupportedException();

        protected override void Dispose(bool disposing)
        {
            if (disposing)
                DisposeCount++;
            base.Dispose(disposing);
        }
    }

    private sealed class EmptyDbParameterCollection : DbParameterCollection
    {
        public override int Count => 0;
        public override object SyncRoot => this;
        public override int Add(object value) => throw new NotSupportedException();
        public override void AddRange(Array values) => throw new NotSupportedException();
        public override void Clear() { }
        public override bool Contains(object value) => false;
        public override bool Contains(string? value) => false;
        public override void CopyTo(Array array, int index) { }
        public override IEnumerator GetEnumerator() => Array.Empty<object>().GetEnumerator();
        public override int IndexOf(object value) => -1;
        public override int IndexOf(string? parameterName) => -1;
        public override void Insert(int index, object value) => throw new NotSupportedException();
        public override void Remove(object value) => throw new NotSupportedException();
        public override void RemoveAt(int index) => throw new NotSupportedException();
        public override void RemoveAt(string? parameterName) => throw new NotSupportedException();
        protected override DbParameter GetParameter(int index) => throw new NotSupportedException();
        protected override DbParameter GetParameter(string? parameterName) => throw new NotSupportedException();
        protected override void SetParameter(int index, DbParameter value) => throw new NotSupportedException();
        protected override void SetParameter(string? parameterName, DbParameter value) => throw new NotSupportedException();
    }
}

using System.Collections;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using System.Data;
using System.Data.Common;
using System.Diagnostics.CodeAnalysis;
using System.Text;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// Issue #160 Phase 2 core coverage for the root projection: the dim-1 <see cref="Projection{T1}"/>
/// planner path, the <see cref="IExtendableProjection"/> slot chain up to the arity-8 cap, the
/// documented <c>As&lt;TResult&gt;</c> overflow, the runtime root-alias guard (misuse / in-memory
/// fail-closed) and plan reuse. Runs against a provider-free <see cref="TestContext"/> (fake dialect)
/// so the planner and SQL renderer are exercised without a database, plus the core in-memory provider
/// for the fail-closed guard.
/// <para>
/// Runs in the "Query cache controls" collection (serialized, parallelization disabled) because the
/// plan-reuse cases read the process-wide <see cref="DataContextCache"/>.
/// </para>
/// </summary>
[Collection("Query cache controls")]
public class RootProjectionTests
{
    [SqlTable("orders")]
    internal sealed class Order
    {
        [Key]
        public int Id { get; set; }

        [Column("buyer_id")]
        public long BuyerId { get; set; }
    }

    [SqlTable("person")]
    internal sealed class Person
    {
        [Key]
        public long Id { get; set; }
    }

    /// <summary>Hand-written root projection: names slot 1 lexically, like the generated surface.</summary>
    internal sealed class RootProjection<T> : Projection<T>
    {
        [JoinSlot(1)]
        public T Root => throw new NotSupportedException();
    }

    /// <summary>Hand-written root+join projection: root is slot 1, the joined table is slot 2.</summary>
    internal sealed class RootJoinProjection<T1, T2> : Projection<T1, T2>
    {
        [JoinSlot(2)]
        public T2 Buyer => throw new NotSupportedException();
    }

    /// <summary>Parent with a declared collection navigation, used for the JoinInto root guard.</summary>
    private sealed class Parent
    {
        [Key]
        public int Id { get; set; }

        public ICollection<Child> Children { get; } = new List<Child>();
    }

    /// <summary>Child of <see cref="Parent"/>.</summary>
    private sealed class Child
    {
        [Key]
        public int Id { get; set; }

        public int ParentId { get; set; }
    }

    internal static EntityBuilder<RootProjection<Order>> Rooted(TestContext ctx) =>
        ctx.From<Order>().AliasRoot<EntityBuilder<RootProjection<Order>>, RootProjection<Order>>(
            static dc => new EntityBuilder<RootProjection<Order>>(dc));

    // ------------------------------------------------------------------ dimension / Extend --------

    [Fact]
    public void Dim1_projection_reports_dimension_one_and_is_not_directly_extendable()
    {
        IProjection projection = new Projection<Order> { Item1 = new Order { Id = 7 } };

        typeof(Projection<Order>).TryGetProjectionDimension(out var dim).Should().BeTrue();
        dim.Should().Be(1);
        ((Projection<Order>)projection).Item1.Id.Should().Be(7);

        // Dimension 1 is the root-only projection: it is expression-only and the slot-1 -> slot-2
        // transition is supplied by the generated `public new` positional-transition members (exercised
        // by the join tests below), so it deliberately stays a plain IProjection. An accidental
        // projection-level extension fails closed instead of guessing a column mapping.
        projection.Should().BeAssignableTo<IProjection>();
        projection.Should().NotBeAssignableTo<IExtendableProjection>();
        typeof(Projection<Order>).Should().NotBeAssignableTo<IExtendableProjection>();
    }

    [Fact]
    public void Extend_chain_walks_dimension_two_to_eight_and_preserves_every_item()
    {
        // Dimension 1 is root-only and not projection-level extendable; the extendable chain starts at
        // the first joined projection (slot 2) and walks to the arity-8 cap.
        IProjection current = new Projection<int, int> { Item1 = 1, Item2 = 2 };

        current.GetType().TryGetProjectionDimension(out var start).Should().BeTrue();
        start.Should().Be(2);

        for (var next = 3; next <= 8; next++)
        {
            current = ((IExtendableProjection)current).Extend(next);

            current.GetType().TryGetProjectionDimension(out var dim).Should().BeTrue();
            dim.Should().Be(next);
            for (var slot = 1; slot <= next; slot++)
            {
                current.GetType().GetProperty("Item" + slot)!.GetValue(current).Should().Be(slot);
            }
        }

        // The arity-8 projection is the documented cap: it is a projection but no longer extendable.
        current.Should().BeAssignableTo<IProjection>();
        current.Should().NotBeAssignableTo<IExtendableProjection>();
    }

    [Fact]
    public void Max_arity_projection_cannot_absorb_a_ninth_item()
    {
        var capped = new Projection<int, int, int, int, int, int, int, int>();

        (capped is IExtendableProjection).Should().BeFalse();
        typeof(Projection<int, int, int, int, int, int, int, int>)
            .Should().NotBeAssignableTo<IExtendableProjection>();
        typeof(Projection<int, int, int, int, int, int, int, int>)
            .Should().BeAssignableTo<IProjection>();
    }

    [Fact]
    public void As_overflow_escape_is_available_on_the_accumulated_builder()
    {
        // Documented escape: at the cap, project into a named type with EntityBuilder<T>.As<TResult>
        // and continue from the derived table; the generic method is the contract that stays usable.
        var asMethod = typeof(EntityBuilder<Order>).GetMethods()
            .Single(m => m.Name == "As" && m.IsGenericMethodDefinition);

        asMethod.IsGenericMethodDefinition.Should().BeTrue();
        asMethod.GetParameters().Should().HaveCount(1);
        asMethod.GetParameters()[0].ParameterType.IsGenericType.Should().BeTrue();
        asMethod.GetParameters()[0].ParameterType.GetGenericTypeDefinition()
            .Should().Be(typeof(System.Linq.Expressions.Expression<>));
    }

    // ------------------------------------------------------------------ planning ------------------

    [Fact]
    public void Dim1_root_projection_plans_and_maps_the_root_slot_to_t1()
    {
        using var ctx = new TestContext();

        var sql = SqlOf(ctx, Rooted(ctx).Select(p => p.Root.Id));

        // A single-table root needs no alias, but the source must stay the physical table and slot 1
        // must resolve to its column (no nested projection, no flattening).
        sql.Should().Be("select Id from orders");
        sql.Should().NotContain("select * from (");
    }

    [Fact]
    public void Root_projection_with_a_join_maps_root_to_t1_and_join_to_t2()
    {
        using var ctx = new TestContext();
        var people = ctx.From<Person>();

        var joined = Rooted(ctx).JoinAlias<EntityBuilder<RootJoinProjection<Order, Person>>, RootJoinProjection<Order, Person>, Person>(
            static dc => new EntityBuilder<RootJoinProjection<Order, Person>>(dc),
            people,
            (a, b) => a.Root.BuyerId == b.Id);

        var sql = SqlOf(ctx, joined.Select(p => p.Buyer.Id));

        sql.Should().Contain("orders as 't1'");
        sql.Should().Contain("join person as 't2'");
        sql.Should().Contain("on t1.buyer_id = t2.Id");
    }

    [Fact]
    public void Alias_root_is_refused_when_the_receiver_already_has_a_join()
    {
        using var ctx = new TestContext();
        var joined = ctx.From<Order>().Join(ctx.From<Person>(), (o, p) => o.BuyerId == p.Id);

        // Negative: '.WithAlias' is root-only; the runtime seam keeps the same guard as a failsafe.
        Action act = () => joined.AliasRoot<EntityBuilder<RootProjection<Order>>, RootProjection<Order>>(
            static dc => new EntityBuilder<RootProjection<Order>>(dc));

        act.Should().Throw<NotSupportedException>().WithMessage("*before any Join*");
    }

    [Fact]
    public void Alias_root_is_refused_after_a_join_into()
    {
        using var ctx = new TestContext();
        var joinedInto = ctx.From<Parent>(b => b.HasMany(p => p.Children, c => c.ParentId))
            .JoinInto(ctx.From<Child>(), (p, c) => p.Id == c.ParentId, p => p.Children);

        // Finding B: the generated '.WithAlias' only binds on a plain EntityBuilder<T>, but the
        // hand-written seam must keep the same root-only guard (JoinInto is already a join).
        Action act = () => joinedInto.AliasRoot<EntityBuilder<RootProjection<Parent>>, RootProjection<Parent>>(
            static dc => new EntityBuilder<RootProjection<Parent>>(dc));

        act.Should().Throw<NotSupportedException>().WithMessage("*before any Join*");
    }

    [Fact]
    public void Pre_alias_where_is_rebased_onto_the_root_slot_when_a_join_follows()
    {
        using var ctx = new TestContext();
        var people = ctx.From<Person>();

        // Finding D (C2/C4): a Where written before '.WithAlias' is typed over the plain root; after a
        // join it must be rebased onto the root slot t1 (the C1 fix), not dropped and not left bare.
        var rooted = ctx.From<Order>()
            .Where(o => o.BuyerId == o.Id)
            .AliasRoot<EntityBuilder<RootProjection<Order>>, RootProjection<Order>>(
                static dc => new EntityBuilder<RootProjection<Order>>(dc));

        var joined = rooted.JoinAlias<EntityBuilder<RootJoinProjection<Order, Person>>, RootJoinProjection<Order, Person>, Person>(
            static dc => new EntityBuilder<RootJoinProjection<Order, Person>>(dc),
            people,
            (a, b) => a.Root.BuyerId == b.Id);

        var sql = SqlOf(ctx, joined.Select(p => p.Buyer.Id));
        // The predicate is preserved and rebased onto the root slot (`t1`), qualified (not bare
        // `orders`/`buyer_id`); the int→long projection item cast is orthogonal to the rebasing.
        sql.Should().Contain("where t1.buyer_id =");
        sql.Should().Contain("cast(t1.Id as bigint)");
    }

    // ------------------------------------------------------------------ in-memory refusal ---------

    [Fact]
    public void Root_alias_fails_closed_on_the_in_memory_provider()
    {
        using var ctx = new InMemoryDataContext();

        Action act = () => ctx.From<Order>().AliasRoot<EntityBuilder<RootProjection<Order>>, RootProjection<Order>>(
            static dc => new EntityBuilder<RootProjection<Order>>(dc));

        act.Should().Throw<NotSupportedException>().WithMessage("*in-memory provider*");
    }

    [Fact]
    public void Pure_positional_in_memory_query_is_not_refused()
    {
        using var ctx = new InMemoryDataContext();

        Action act = () => ctx.From<Order>().Join(ctx.From<Person>(), (o, p) => o.BuyerId == p.Id).Select(p => p.Item2.Id);

        act.Should().NotThrow();
    }

    // ------------------------------------------------------------------ cache / plan --------------

    [Fact]
    public void Repeated_root_projection_preparation_reuses_the_plan_without_sticky_cache_mutation()
    {
        using var ctx = new TestContext();
        var command = Rooted(ctx).Select(p => p.Root.Id);
        command.Cache.Should().BeTrue();

        var first = ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, CancellationToken.None);
        var second = ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, CancellationToken.None);

        second.Should().BeSameAs(first);
        command.Cache.Should().BeTrue();
    }

    [Fact]
    public void Preparing_a_root_projection_with_storeInCache_false_keeps_the_command_cacheable()
    {
        using var ctx = new TestContext();
        var command = Rooted(ctx).Select(p => p.Root.Id);
        command.Cache.Should().BeTrue();

        // Finding C: the non-caching preparation path must not touch the command's sticky flag.
        _ = ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: false, CancellationToken.None);
        command.Cache.Should().BeTrue("storeInCache:false must not set the sticky _dontCache flag");

        // It must not poison the shared plan cache either: a later cached preparation still stores and
        // reuses the same entry.
        var first = ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, CancellationToken.None);
        var second = ctx.GetPreparedQueryCommand(command, createEnumerator: false, storeInCache: true, CancellationToken.None);
        second.Should().BeSameAs(first);
    }

    [Fact]
    public void Different_root_projection_shapes_do_not_share_a_plan()
    {
        using var ctx = new TestContext();

        var ids = SqlOf(ctx, Rooted(ctx).Select(p => p.Root.Id));
        var buyerIds = SqlOf(ctx, Rooted(ctx).Select(p => p.Root.BuyerId));

        ids.Should().NotBe(buyerIds);
    }

    // ------------------------------------------------------------------ provider-free context -----

    internal static string SqlOf<T>(IDataContext ctx, QueryCommand<T> cmd)
    {
        var prepared = (DbPreparedQueryCommand<T>)ctx.GetPreparedQueryCommand(cmd, false, false, CancellationToken.None);
        return prepared.DbCommand.CommandText.Replace("\r\n", "\n");
    }

