    public void MapStreamingColumn_TextReader_ShouldReadTheSequentialAccessAccessor()
    {
        var column = new SelectExpression(typeof(TextReader)) { Index = 1, PropertyName = "Body", IsLobStreaming = true };
        var param = Expression.Parameter(typeof(IDataRecord));

        var body = RowMapperFactory.MapStreamingColumn(column, param);

        body.ToString().Should().Contain("GetTextReader");
        body.Type.Should().Be(typeof(TextReader));
    }
}

using System.Linq.Expressions;
using FluentAssertions;

namespace NextORM.Core.Tests;

/// <summary>
/// Direct tests of the projection-item materialization path of <see cref="RowMaterializerBuilder"/>.
/// The builder is the shared result-shape -&gt; expression-tree seam, so its constructor-selection
/// contract is pinned here without a database: a projection whose constructor arity does not match the
/// number of projected items must assemble member by member through a parameterless constructor (or be
/// rejected with a preparation error), never invoke a parameterful constructor with no arguments.
/// </summary>
public class RowMaterializerBuilderTests
{
    public sealed class Part
    {
        public int Id { get; set; }
    }

    public sealed class Shape
    {
        public Part? First { get; set; }
        public int Second { get; set; }
        public int Id { get; set; }
        public object? Store { get; set; }

        public Shape()
        {
        }

        public Shape(Part first) => First = first;
    }

    public sealed class CtorOnlyShape
    {
        public Part? First { get; set; }
        public int Second { get; set; }

        public CtorOnlyShape(Part first) => First = first;
    }

    /// <summary>
    /// A class that declares a dynamic-columns store but has no public parameterless constructor: the
    /// store materializes through member-init, which needs one.
    /// </summary>
    public sealed class StoreWithoutParameterlessCtor
    {
        public StoreWithoutParameterlessCtor(int id) => Id = id;

        public int Id { get; set; }

        public Part? Nested { get; set; }

        [DynamicColumns]
        public Dictionary<string, object?> Extra { get; set; } = new();
    }

    // The entity item's own columns are mapped by this delegate through BuildCore; every column it is
    // asked for is a scalar of the entity (int here), so no column is ever of the entity type itself.
    private static Func<SelectExpression, Expression> ConstantMap()
        => column => Expression.Constant(0, column.PropertyType);

    private static SelectExpression[] SelectListFor(Type resultType)
    {
        var item = new ProjectionEntityItem(0, typeof(Part), resultType.GetProperty(nameof(Shape.First)));
        return
        [
            new SelectExpression(typeof(int))
            {
                Index = 0,
                PropertyName = nameof(Part.Id),
                ProjectionItem = item,
            },
            new SelectExpression(typeof(int))
            {
                Index = 1,
                PropertyName = nameof(Shape.Second),
            },
        ];
    }

    [Fact]
    public void ConstructorArityMismatch_ShouldAssembleByMemberThroughTheParameterlessConstructor()
    {
        var param = Expression.Parameter(typeof(object), "row");
        var body = RowMaterializerBuilder.Build(
            typeof(Shape), param, SelectListFor(typeof(Shape)), ignoreColumns: false, ConstantMap());

        var materialize = Expression.Lambda<Func<object, Shape>>(body, param).Compile();
        var shape = materialize(new object());

        shape.First.Should().NotBeNull();
        shape.First!.Id.Should().Be(0);
        shape.Second.Should().Be(0);
    }

    [Fact]
    public void ConstructorArityMismatch_WithoutParameterlessConstructor_ShouldThrowClearPreparationError()
    {
        var param = Expression.Parameter(typeof(object), "row");

        Action act = () => RowMaterializerBuilder.Build(
            typeof(CtorOnlyShape), param, SelectListFor(typeof(CtorOnlyShape)), ignoreColumns: false, ConstantMap());

        act.Should().Throw<QueryPreparationException>()
            .WithMessage("*CtorOnlyShape*1 constructor parameter*2 item*");
    }

    [Fact]
    public void MixedProjection_WithDynamicColumnsStore_ShouldRouteTheStoreThroughTheProviderAccessor()
    {
        var param = Expression.Parameter(typeof(object), "row");
        var item = new ProjectionEntityItem(0, typeof(Part), typeof(Shape).GetProperty(nameof(Shape.First)));
        var store = new SelectExpression(typeof(object))
        {
            Index = 1,
            PropertyName = nameof(Shape.Store),
            PropertyInfo = typeof(Shape).GetProperty(nameof(Shape.Store)),
            IsDynamicColumnsStore = true,
        };
        var selectList = new SelectExpression[]
        {
            new SelectExpression(typeof(int)) { Index = 0, PropertyName = nameof(Part.Id), ProjectionItem = item },
            store,
            new SelectExpression(typeof(int)) { Index = 2, PropertyName = nameof(Shape.Second) },
        };

        var storeCalls = 0;
        Expression MapDynamic(SelectExpression _, int starStart, DynamicColumns __)
        {
            storeCalls++;
            starStart.Should().Be(2);
            return Expression.Constant("store", typeof(object));
        }

        var body = RowMaterializerBuilder.Build(typeof(Shape), param, selectList, ignoreColumns: false, ConstantMap(), MapDynamic);

        var materialize = Expression.Lambda<Func<object, Shape>>(body, param).Compile();
        var shape = materialize(new object());

        storeCalls.Should().Be(1, "a mixed projection must still materialize the dynamic-columns store through the provider accessor");
        shape.Store.Should().Be("store");
        shape.First.Should().NotBeNull();
        shape.Second.Should().Be(0);
    }

    [Fact]
    public void StoreWithoutPublicParameterlessCtor_ThrowsQueryPreparationException()
    {
        var param = Expression.Parameter(typeof(object), "row");
        Expression MapDynamic(SelectExpression _, int __, DynamicColumns ___) =>
            Expression.Constant(new Dictionary<string, object?>(), typeof(object));

        // Ordinary read: BuildCore finds the dynamic-columns store and needs a parameterless
        // constructor to assemble the entity member by member.
        var ordinarySelectList = new SelectExpression[]
        {
            new SelectExpression(typeof(int)) { Index = 0, PropertyName = nameof(StoreWithoutParameterlessCtor.Id) },
            new SelectExpression(typeof(object))
            {
                Index = 1,
                PropertyName = nameof(StoreWithoutParameterlessCtor.Extra),
                PropertyInfo = typeof(StoreWithoutParameterlessCtor).GetProperty(nameof(StoreWithoutParameterlessCtor.Extra)),
                IsDynamicColumnsStore = true,
            },
        };

        Action ordinary = () => RowMaterializerBuilder.Build(
            typeof(StoreWithoutParameterlessCtor), param, ordinarySelectList, ignoreColumns: false, ConstantMap(), MapDynamic);

        ordinary.Should().Throw<QueryPreparationException>()
            .WithMessage("*StoreWithoutParameterlessCtor*no parameterless constructor*");

        // Projection path: the entity is the projection result type, but its constructor arity does not
        // match the projected items, so the member-init fallback also needs a parameterless constructor
        // and rejects the shape with the same exception type.
        var item = new ProjectionEntityItem(
            0, typeof(Part), typeof(StoreWithoutParameterlessCtor).GetProperty(nameof(StoreWithoutParameterlessCtor.Nested)));
        var projectionSelectList = new SelectExpression[]
        {
            new SelectExpression(typeof(int)) { Index = 0, PropertyName = nameof(Part.Id), ProjectionItem = item },
            new SelectExpression(typeof(object))
            {
                Index = 1,
                PropertyName = nameof(StoreWithoutParameterlessCtor.Extra),
                PropertyInfo = typeof(StoreWithoutParameterlessCtor).GetProperty(nameof(StoreWithoutParameterlessCtor.Extra)),
                IsDynamicColumnsStore = true,
            },
        };

        Action projection = () => RowMaterializerBuilder.Build(
            typeof(StoreWithoutParameterlessCtor), param, projectionSelectList, ignoreColumns: false, ConstantMap(), MapDynamic);

        projection.Should().Throw<QueryPreparationException>()
            .WithMessage("*StoreWithoutParameterlessCtor*constructor parameter*item*");
    }

    [Fact]
    public void ConstructorPositionItem_WithoutMatchingCtor_ShouldThrowClearPreparationError()
    {
        // The item addresses a constructor position (Member is null) but the longest constructor takes
        // one argument while the projection materializes two items, so member-init has to bind it. A
        // wrong implementation would fall back to the entity's own property name ("Id", which Shape
        // happens to declare) and fail building the tree with a coercion error instead.
        var param = Expression.Parameter(typeof(object), "row");
        var item = new ProjectionEntityItem(0, typeof(Part), member: null);
        var selectList = new SelectExpression[]
        {
            new SelectExpression(typeof(int)) { Index = 0, PropertyName = nameof(Part.Id), ProjectionItem = item },
            new SelectExpression(typeof(int)) { Index = 1, PropertyName = nameof(Shape.Second) },
        };

        Action act = () => RowMaterializerBuilder.Build(typeof(Shape), param, selectList, ignoreColumns: false, ConstantMap());

        act.Should().Throw<QueryPreparationException>()
            .WithMessage("*constructor position*");
    }

    [Fact]
    public void ConstructorPositionItem_WithMatchingCtor_ShouldMaterializeThroughTheCtorPosition()
    {
        // The item addresses a constructor position (Member is null) and the projection materializes
        // exactly one item, matching CtorOnlyShape's single-parameter constructor. The null member must
        // be bound by constructor position and the projected column value must materialize onto the
        // entity, never be rejected or looked up as a member by the entity's own property name.
        var param = Expression.Parameter(typeof(object), "row");
        var item = new ProjectionEntityItem(0, typeof(Part), member: null);
        var selectList = new SelectExpression[]
        {
            new SelectExpression(typeof(int)) { Index = 0, PropertyName = nameof(Part.Id), ProjectionItem = item },
        };
        Func<SelectExpression, Expression> map = column => Expression.Constant(7, column.PropertyType);

        var body = RowMaterializerBuilder.Build(typeof(CtorOnlyShape), param, selectList, ignoreColumns: false, map);

        var materialize = Expression.Lambda<Func<object, CtorOnlyShape>>(body, param).Compile();
        var shape = materialize(new object());

        shape.First.Should().NotBeNull();
        shape.First!.Id.Should().Be(7, "the projected column value must reach the ctor-position entity item");
    }
}

using System.Linq.Expressions;
using FluentAssertions;
using NextORM.Core;

namespace NextORM.Core.Tests;

/// <summary>
/// Plan-key coverage for <see cref="SelectExpressionPlanEqualityComparer"/>: two projections identical
/// except for their physical column name must compare unequal, so the dynamic-columns store can skip
/// a mapped column by its physical name without sharing a cached plan.
/// </summary>
public class SelectExpressionPlanEqualityComparerTests
{
    [Fact]
    public void Comparer_ShouldDistinguishPhysicalColumnNames()
    {
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var first = new SelectExpression(typeof(string))
        {
            Index = 0,
            PropertyName = "Name",
            PhysicalColumnName = "name",
            ProviderType = typeof(string),
        };
        var second = new SelectExpression(typeof(string))
        {
            Index = 0,
            PropertyName = "Name",
            PhysicalColumnName = "other_name",
            ProviderType = typeof(string),
        };

        comparer.Equals(first, first).Should().BeTrue();
        comparer.Equals(first, second).Should().BeFalse();
    }

    [Fact]
    public void Comparer_ShouldTreatEqualProjectionItemShapesAsEqual()
    {
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());

        // Distinct ProjectionEntityItem instances with the same shape (entity type + slot) must still
        // compare equal, so two separately built identical projections share a cached plan.
        var left = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityEntity), null));
        var right = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityEntity), null));

        comparer.Equals(left, right).Should().BeTrue("an identical projection shape must share a cached plan");
        comparer.GetHashCode(left).Should().Be(comparer.GetHashCode(right));
    }

    [Fact]
    public void Comparer_ShouldDistinguishEntityItemFromScalarColumn()
    {
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var withItem = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityEntity), null));
        var withoutItem = Column(0, null);

        comparer.Equals(withItem, withoutItem).Should()
            .BeFalse("an entity item and a scalar column are different projection shapes");
    }

    [Fact]
    public void Comparer_ShouldTreatEqualScalarColumnsAsEqual()
    {
        // Both scalar columns (ProjectionItem == null), otherwise equal: distinct instances must compare
        // equal and hash alike, closing the "Both scalar columns" matrix row with a two-instance control
        // instead of the reflexive self-equality only.
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var left = Column(0, null);
        var right = Column(0, null);

        left.Should().NotBeSameAs(right);
        comparer.Equals(left, right).Should().BeTrue("equal scalar columns are the same projection shape");
        comparer.GetHashCode(left).Should().Be(comparer.GetHashCode(right));
    }

    [Fact]
    public void Comparer_ShouldDistinguishProjectionItemSlots()
    {
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var first = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityEntity), null));
        var second = Column(0, new ProjectionEntityItem(1, typeof(PlanEqualityEntity), null));

        comparer.Equals(first, second).Should()
            .BeFalse("different projection slots rebuild the row into a different shape");
    }

    [Fact]
    public void Comparer_ShouldDistinguishProjectionItemMembers()
    {
        // #173: two entity items with the same entity type and slot but different target members
        // rebuild the row into different shapes, so they must not share a cached plan.
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var id = typeof(PlanEqualityMemberEntity).GetProperty(nameof(PlanEqualityMemberEntity.Id))!;
        var name = typeof(PlanEqualityMemberEntity).GetProperty(nameof(PlanEqualityMemberEntity.Name))!;
        var first = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityMemberEntity), id));
        var second = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityMemberEntity), name));

        comparer.Equals(first, second).Should()
            .BeFalse("different projection members rebuild the row into a different shape");
        comparer.GetHashCode(first).Should().NotBe(comparer.GetHashCode(second));
    }

    [Fact]
    public void Comparer_ShouldTreatEqualProjectionItemMembersAsEqual()
    {
        // An equal member identity (including a repeated reflection lookup of the same property) must
        // compare equal and hash alike, so a separately built identical projection reuses the plan.
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var left = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityMemberEntity),
            typeof(PlanEqualityMemberEntity).GetProperty(nameof(PlanEqualityMemberEntity.Id))!));
        var right = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityMemberEntity),
            typeof(PlanEqualityMemberEntity).GetProperty(nameof(PlanEqualityMemberEntity.Id))!));

        comparer.Equals(left, right).Should().BeTrue("equal member identities must share a cached plan");
        comparer.GetHashCode(left).Should().Be(comparer.GetHashCode(right));
    }

    [Fact]
    public void Comparer_ShouldDistinguishNullFromNonNullProjectionItemMember()
    {
        // A null member marks a constructor-parameter position; it must not alias a named member.
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var member = typeof(PlanEqualityMemberEntity).GetProperty(nameof(PlanEqualityMemberEntity.Id))!;
        var withMember = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityMemberEntity), member));
        var withoutMember = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityMemberEntity), null));

        comparer.Equals(withMember, withoutMember).Should().BeFalse("a named member and a ctor position differ");
        comparer.Equals(withoutMember, withMember).Should().BeFalse("the result is order independent");
        comparer.GetHashCode(withMember).Should().NotBe(comparer.GetHashCode(withoutMember));
    }

    [Fact]
    public void Comparer_ShouldNotConflateSameMemberNameOnDifferentDeclaringTypes()
    {
        // Member identity is the PropertyInfo, not the name alone: two same-named members on different
        // declaring types must stay distinct even when the entity type and slot are equal.
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var first = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityMemberEntity),
            typeof(PlanEqualityMemberEntity).GetProperty(nameof(PlanEqualityMemberEntity.Id))!));
        var second = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityMemberEntity),
            typeof(PlanEqualityOtherEntity).GetProperty(nameof(PlanEqualityOtherEntity.Id))!));

        comparer.Equals(first, second).Should().BeFalse("same-named members of different types are distinct");
        comparer.GetHashCode(first).Should().NotBe(comparer.GetHashCode(second));
    }

    [Fact]
    public void Comparer_ShouldDistinguishProjectionItemEntityTypes()
    {
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var first = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityEntity), null));
        var second = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityMemberEntity), null));

        comparer.Equals(first, second).Should()
            .BeFalse("different entity types rebuild the row into a different shape");
        comparer.GetHashCode(first).Should().NotBe(comparer.GetHashCode(second));
    }

    [Fact]
    public void Comparer_ShouldDistinguishDirectRootItemSourceExpressions()
    {
        // D190: a direct whole-entity projection expands into columns re-rooted onto the projection
        // source (p.Item1 vs p.Item2). The same entity item and slot reached through a self-join must be
        // separated by the source binding in the column expression, so a cached mapper/SQL built for one
        // alias is never served for the other.
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var parameter = Expression.Parameter(typeof(Projection<PlanEqualityMemberEntity, PlanEqualityMemberEntity>), "p");
        var item = new ProjectionEntityItem(0, typeof(PlanEqualityMemberEntity), null);
        var id = nameof(PlanEqualityMemberEntity.Id);

        var fromFirst = new SelectExpression(typeof(int))
        {
            Index = 0,
            PropertyName = id,
            ProjectionItem = item,
            Expression = Expression.Property(Expression.Property(parameter, nameof(Projection<PlanEqualityMemberEntity, PlanEqualityMemberEntity>.Item1)), id),
        };
        var fromSecond = new SelectExpression(typeof(int))
        {
            Index = 0,
            PropertyName = id,
            ProjectionItem = item,
            Expression = Expression.Property(Expression.Property(parameter, nameof(Projection<PlanEqualityMemberEntity, PlanEqualityMemberEntity>.Item2)), id),
        };

        comparer.Equals(fromFirst, fromSecond).Should()
            .BeFalse("a self-join root item must keep its own source binding");
        comparer.GetHashCode(fromFirst).Should().NotBe(comparer.GetHashCode(fromSecond));
    }

    [Fact]
    public void Comparer_ShouldApplyMemberIdentityToValueTypeEntityItems()
    {
        // #173 variant matrix: a value-type mapped entity follows the same member-identity rule as a
        // reference type — a different target member separates the plan, an equal member shares it.
        var comparer = new SelectExpressionPlanEqualityComparer(new QueryProvider());
        var id = typeof(PlanEqualityValueEntity).GetProperty(nameof(PlanEqualityValueEntity.Id))!;
        var name = typeof(PlanEqualityValueEntity).GetProperty(nameof(PlanEqualityValueEntity.Name))!;
        var first = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityValueEntity), id));
        var second = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityValueEntity), name));

        comparer.Equals(first, second).Should()
            .BeFalse("a different target member on a value-type entity rebuilds a different shape");
        comparer.GetHashCode(first).Should().NotBe(comparer.GetHashCode(second));

        var equalMember = Column(0, new ProjectionEntityItem(0, typeof(PlanEqualityValueEntity), id));
        comparer.Equals(first, equalMember).Should()
            .BeTrue("equal member identities apply to value types like reference types");
        comparer.GetHashCode(first).Should().Be(comparer.GetHashCode(equalMember));
    }

    private static SelectExpression Column(int index, ProjectionEntityItem? item)
        => new(typeof(int))
        {
            Index = index,
            PropertyName = "Id",
            ProjectionItem = item,
        };
}

