        var cmd = ctx.From("typed_cte_entity")
            .Join(bound, (t, b) => t.GetInt64("Id") == b.Id)
            .Select(p => p.Item2.Id);

        // The in-memory test dialect cannot render a raw FROM source, so assert the resolved join source
