        var act = () => ctx.From<ConventionalEntity>()
            .Join(ctx.From<ConventionalEntity>(), (a, b) => a.Id == b.Id)
            .CreateUpdateJoinBuilder()
            .Set(p => p.Item1.Name, "a")
            .ToSql();

        act.Should().Throw<NotSupportedException>();
    }
}

global using Xunit;
using Xunit.Sdk;
